const e={id:"s01",unidad:1,semana:1,kind:"aprendizaje",temaGenerador:"Nuestro lugar en mapas y palabras",title:"Nuestro lugar en mapas y palabras",subtitle:"Ubicamos la comunidad, comprendemos sus condiciones geográficas y compartimos lo que sabemos de ella",icon:"Earth",color:"var(--area-ccss)",contexto:"Esta semana aprenderás a ubicar tu comunidad, reconocer cómo la altitud, el clima y los riesgos naturales influyen en la vida local, y presentar con un mapa y tu propia voz los conocimientos que las familias construyen sobre el lugar que comparten.",ejes:["sostenible","multiculturalidad","vida-ciudadana","seguridad"],media:{id:"s01-portada",kind:"video",title:"Guatemala desde el cielo",aspect:"16:9",duration:60,alt:"Recorrido animado desde la costa de Monterrico, por la bocacosta, hasta Quetzaltenango, con altitudes aproximadas y temperaturas estimadas mediante un modelo educativo.",brief:'Video de 60 s con animación 2D de un recorrido esquemático, sin escala, desde la costa de Monterrico hasta el altiplano de Quetzaltenango. Altitudes aproximadas: referencia del nivel del mar, 800 m y 2,300 m. Compara temperaturas estimadas (30, 25 y 16 °C) mediante un modelo educativo de descenso de 6 °C por cada 1,000 m; indica que no son temperaturas medidas. Usa la paleta actual de Socrates, el Geeky 3D original, narración en español, música de marimba suave original y subtítulos opcionales separados. Cierre: "¿Qué cuentan los mapas sobre el lugar que compartimos?".'},badge:{id:"medalla-s01",name:"Voz del territorio",icon:"Map",desc:"Completaste la semana 1 y superaste su reto"},bank:[{fase:"comprobar",areas:["mat"],cnb:["mat:1.1.2"],prompt:"Un cuadrilátero tiene **exactamente un par de lados paralelos**. ¿Cómo se clasifica?",type:"choice",props:{options:[{id:"a",text:"Trapecio"},{id:"b",text:"Rectángulo"},{id:"c",text:"Rombo"}],correct:["a"]},id:"s01-banco-1"},{fase:"comprobar",areas:["l1"],cnb:["l1:3.4.2"],prompt:"Quieres pedir a la bibliotecaria una entrevista para una tarea. ¿Cuál correo está completo y usa un registro adecuado?",type:"choice",props:{options:[{id:"a",text:"Asunto: Solicitud de entrevista · Saludo: Buenos días, señora bibliotecaria · Petición: ¿Podría concederme una entrevista sobre la historia de la biblioteca? · Firma: Elena López, 6.º grado"},{id:"b",text:"Asunto: Hola · Oiga, necesito hablar con usted. Respóndame rápido."},{id:"c",text:"SIN ASUNTO · QUIERO HACERLE PREGUNTAS PARA MI TAREA"}],correct:["a"]},id:"s01-banco-2"},{fase:"comprobar",areas:["cnt"],cnb:["cnt:1.2.1"],prompt:"Relaciona cada organelo con una tarea cotidiana equivalente.",type:"match",props:{leftTitle:"Organelo",rightTitle:"Tarea equivalente",pairs:[{id:"n",left:"Núcleo",right:"Dirigir y guardar instrucciones"},{id:"m",left:"Mitocondria",right:"Producir energía"},{id:"g",left:"Aparato de Golgi",right:"Empacar y distribuir"}]},id:"s01-banco-3"},{fase:"comprobar",areas:["ccss"],cnb:["ccss:1.2.1"],prompt:"En la costa hay **28 °C**. Si la temperatura baja unos 6 °C por cada 1,000 m, ¿cuál sería la temperatura aproximada a **2,000 m**?",type:"number-input",props:{answer:16,unit:"°C",misconceptions:[{value:22,msg:"A 2,000 m la temperatura baja dos veces 6 °C."}]},id:"s01-banco-4"},{fase:"comprobar",areas:["l2"],cnb:["l2:1.2.6"],prompt:"Clasifica las expresiones como hecho u opinión.",type:"sort",props:{buckets:[{id:"h",label:"Hecho",icon:"BadgeCheck"},{id:"o",label:"Opinión",icon:"MessageCircle"}],items:[{id:"l1",text:"La reunión comenzó a las ocho.",bucket:"h"},{id:"l2",text:"La reunión fue demasiado larga.",bucket:"o"},{id:"l3",text:"Asistieron treinta personas.",bucket:"h"},{id:"l4",text:"El salón era el más bonito del pueblo.",bucket:"o"}]},id:"s01-banco-5"},{fase:"comprobar",areas:["l3"],cnb:["l3:1.1.1"],prompt:"Which sentence means “La biblioteca está detrás de la escuela”?",type:"choice",props:{options:[{id:"a",text:"The library is behind the school."},{id:"b",text:"The library is between the school."},{id:"c",text:"The library is under the school."}],correct:["a"]},id:"s01-banco-6"},{fase:"comprobar",areas:["fc"],cnb:["fc:1.2.1"],prompt:"Una estudiante que usa silla de ruedas no puede entrar a la escuela porque solo hay gradas. ¿Cuál evaluación es más precisa?",type:"choice",props:{options:[{id:"a",text:"El derecho a la educación no se cumple en igualdad de condiciones mientras el edificio siga siendo inaccesible"},{id:"b",text:"El derecho se cumple porque la escuela está abierta para otras personas"},{id:"c",text:"La accesibilidad no tiene relación con los derechos"}],correct:["a"]},id:"s01-banco-7"},{fase:"comprobar",areas:["art"],cnb:["art:1.1.1"],prompt:"Evalúa la ubicación de notas en un pentagrama con clave de sol.",type:"true-false",props:{statements:[{text:"La nota Mi se escribe en la primera línea.",answer:!0},{text:"La nota Sol se escribe en el primer espacio.",answer:!1,why:"Sol se ubica en la segunda línea."},{text:"La nota Do aguda se escribe en el tercer espacio.",answer:!0},{text:"Una nota más arriba en el pentagrama suena más grave.",answer:!1,why:"Una posición más alta representa un sonido más agudo."}]},id:"s01-banco-8"},{fase:"comprobar",areas:["ef"],cnb:["ef:1.2.1","ef:1.2.4"],prompt:"Evalúa estas situaciones de lateralidad y equilibrio.",type:"true-false",props:{statements:[{text:"Caminar sobre una línea sin detenerse requiere equilibrio dinámico.",answer:!0},{text:"La mano dominante siempre es la mano derecha.",answer:!1,why:"Puede ser derecha o izquierda según la persona."},{text:"Mantenerse quieto sobre un pie requiere equilibrio estático.",answer:!0}]},id:"s01-banco-9"},{fase:"comprobar",areas:["pyd"],cnb:["pyd:1.1.1"],prompt:"¿Qué dato muestra una mejora más completa del desarrollo comunitario?",type:"choice",props:{options:[{id:"a",text:"Aumentaron el empleo digno, el acceso a salud y la permanencia escolar"},{id:"b",text:"Se pintó de otro color un solo edificio"},{id:"c",text:"Una familia compró un televisor más grande"}],correct:["a"]},id:"s01-banco-10"}]},a=JSON.parse(`[{"missionId":"s01","version":"cnb-sexto-41af04ec45f4874d","lesson":{"id":"s01-mat-1","title":"Triángulos según sus ángulos","icon":"Triangle","minutes":13,"gancho":"El techo de una casa, una escuadra y una señal de tránsito tienen forma de triángulo. ¿Son todos el mismo tipo de triángulo?","objetivos":["Reconocer ángulos agudos, rectos y obtusos comparándolos con la esquina de una hoja","Clasificar triángulos en acutángulos, rectángulos y obtusángulos"],"resumen":["Un ángulo es la abertura entre dos lados que se unen en un punto llamado vértice. Se mide en grados (°).","Ángulo agudo: menos de 90°. Recto: exactamente 90°. Obtuso: más de 90° y menos de 180°.","Triángulo acutángulo: sus 3 ángulos son agudos. Rectángulo: tiene un ángulo recto. Obtusángulo: tiene un ángulo obtuso.","Para clasificar un triángulo, busca su ángulo más grande y compáralo con 90°."],"media":{"id":"s01-mat-1-familias","kind":"animation","title":"Tres familias de triángulos","aspect":"16:9","duration":40,"alt":"Un triángulo cuyo vértice superior se mueve: cuando un ángulo llega a 90° aparece un cuadradito; si lo pasa, el triángulo se vuelve obtusángulo.","brief":"Animación 2D de 40 s sobre fondo cuadriculado claro. Un triángulo con un vértice arrastrable: su ángulo mayor se colorea verde si es menor de 90°, azul con un cuadradito si mide 90° y naranja si pasa de 90°; la etiqueta cambia entre \\"acutángulo\\", \\"rectángulo\\" y \\"obtusángulo\\". Cierra con los tres tipos lado a lado junto a objetos reales: una señal de tránsito triangular, una escuadra de carpintero y un techo muy abierto. Narración en español neutro, subtítulos."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:1.1.1"],"ambito":"conocer","title":"Tres tipos de ángulo","prompt":"Un **ángulo** es la abertura entre dos lados que se juntan en un punto, el **vértice**. Se mide en **grados (°)**. Toca cada tarjeta.","media":{"id":"s01-mat-1-angulos","kind":"diagram","title":"Agudo, recto y obtuso","aspect":"16:9","alt":"Tres ángulos dibujados con su medida: 45° (agudo, verde), 90° (recto, azul, con un cuadradito) y 130° (obtuso, naranja). Detrás de cada uno, la esquina de una hoja en gris para comparar.","brief":"Diagrama plano con tres ángulos grandes en fila, cada uno con sus dos lados en negro y el arco coloreado: 45° en verde con la palabra \\"agudo\\", 90° en azul con un cuadradito en el vértice y la palabra \\"recto\\", 130° en naranja con la palabra \\"obtuso\\". Detrás de cada ángulo, en gris claro, la silueta de la esquina de una hoja para comparar. Rotular el vértice con un punto. Fondo blanco, trazos gruesos. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"type":"explain","props":{"icon":"Ruler","body":"Compara siempre con la esquina de una hoja: **90°**. Si abres los lados hasta formar una línea recta, el ángulo mide **180°** (ángulo llano).","reveal":[{"icon":"ChevronUp","front":"Agudo","back":"Mide **menos de 90°**: es más cerrado que la esquina de la hoja. Ejemplos: 30°, 60°, 89°."},{"icon":"Square","front":"Recto","back":"Mide **exactamente 90°**. Se marca con un cuadradito en el vértice."},{"icon":"ChevronsLeftRight","front":"Obtuso","back":"Mide **más de 90° y menos de 180°**: es más abierto que la esquina de la hoja. Ejemplos: 100°, 135°, 170°."}]},"id":"s01-mat-1-1"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.1"],"ambito":"conocer","prompt":"Mira las esquinas de estos objetos. ¿Cuál tiene una esquina **igual a la de una hoja de cuaderno**?","explain":"La esquina de una hoja forma un **ángulo recto** (90°). Hoy la usaremos como \\"regla\\" para comparar todos los ángulos.","type":"choice","props":{"layout":"grid","options":[{"id":"a","text":"La punta de un machete","icon":"Sword","feedback":"La punta del machete es más cerrada que la esquina de una hoja."},{"id":"b","text":"La esquina de un pizarrón","icon":"Square"},{"id":"c","text":"Un abanico muy abierto","icon":"Wind","feedback":"Un abanico muy abierto forma una abertura más grande que la esquina de la hoja."}],"correct":["b"]},"id":"s01-mat-1-2"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.1"],"prompt":"Clasifica cada medida en su tipo de ángulo.","hint":"Compara cada número con 90: ¿es menor, igual o mayor?","explain":"Todo se decide comparando con 90°: menos es agudo, igual es recto, más (sin llegar a 180°) es obtuso.","type":"sort","props":{"buckets":[{"id":"ag","label":"Agudo (< 90°)","icon":"ChevronUp","color":"var(--c-ok)"},{"id":"re","label":"Recto (= 90°)","icon":"Square","color":"var(--area-mat)"},{"id":"ob","label":"Obtuso (> 90°)","icon":"ChevronsLeftRight","color":"var(--c-maiz-strong)"}],"items":[{"id":"x1","text":"35°","bucket":"ag"},{"id":"x2","text":"90°","bucket":"re"},{"id":"x3","text":"145°","bucket":"ob"},{"id":"x4","text":"89°","bucket":"ag","feedback":"89 es menor que 90, aunque por poquito: es agudo."},{"id":"x5","text":"91°","bucket":"ob","feedback":"91 ya pasa de 90: es obtuso."},{"id":"x6","text":"12°","bucket":"ag"}]},"id":"s01-mat-1-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.1"],"ambito":"conocer","title":"Los triángulos se nombran por su ángulo mayor","prompt":"Todo triángulo tiene **3 ángulos**. Al menos **dos** de ellos siempre son agudos. Por eso, para clasificarlo, basta con mirar su ángulo **más grande**.","type":"explain","props":{"icon":"Triangle","body":"Un triángulo **nunca** tiene dos ángulos rectos ni dos obtusos: sus lados no alcanzarían a cerrarse.","reveal":[{"icon":"Triangle","front":"Acutángulo","back":"Sus **tres** ángulos son agudos. Ejemplo: 60°, 60°, 60°, como una señal de \\"ceda el paso\\"."},{"icon":"Square","front":"Rectángulo","back":"Tiene **un** ángulo recto. Ejemplo: 90°, 30°, 60°, como la escuadra del carpintero."},{"icon":"Tent","front":"Obtusángulo","back":"Tiene **un** ángulo obtuso. Ejemplo: 120°, 35°, 25°, como algunos techos muy abiertos."}]},"id":"s01-mat-1-4"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.1"],"ambito":"hacer","title":"Ejemplo resuelto","prompt":"Mira cómo se clasifica un triángulo paso a paso.","type":"worked-example","props":{"icon":"Search","problem":"Don Mateo corta una pieza de madera triangular con ángulos de **25°**, **65°** y **90°**. ¿Qué tipo de triángulo es?","steps":[{"text":"Busco el ángulo más grande: **90°**.","why":"Los otros dos siempre serán agudos; el mayor es el que decide."},{"text":"Comparo con 90°: es **exactamente 90°**, un ángulo recto."},{"text":"Un triángulo con un ángulo recto se llama **rectángulo**."}],"answer":"Es un triángulo **rectángulo**.","tip":"Mayor < 90° → acutángulo · Mayor = 90° → rectángulo · Mayor > 90° → obtusángulo."},"id":"s01-mat-1-5"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.1"],"prompt":"Ahora tú, con ayuda: un triángulo tiene ángulos de **30°, 40° y 110°**. ¿Qué tipo es?","hint":"Busca el ángulo mayor. ¿Es menor, igual o mayor que 90°?","explain":"El mayor es 110°, que pasa de 90°: el triángulo es **obtusángulo**.","type":"choice","props":{"options":[{"id":"a","text":"Acutángulo","feedback":"Dos ángulos son agudos, pero 110° no lo es. Basta un ángulo obtuso para cambiar el nombre."},{"id":"r","text":"Rectángulo","feedback":"Ninguno mide exactamente 90°."},{"id":"o","text":"Obtusángulo"}],"correct":["o"]},"id":"s01-mat-1-6"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.1"],"prompt":"Clasifica cada triángulo por sus ángulos.","explain":"Busca primero el ángulo mayor de cada triángulo y compáralo con 90°.","type":"sort","props":{"buckets":[{"id":"ac","label":"Acutángulo","icon":"Triangle","color":"var(--c-ok)"},{"id":"re","label":"Rectángulo","icon":"Square","color":"var(--area-mat)"},{"id":"ob","label":"Obtusángulo","icon":"Tent","color":"var(--c-maiz-strong)"}],"items":[{"id":"t1","text":"90°, 45°, 45°","bucket":"re"},{"id":"t2","text":"70°, 70°, 40°","bucket":"ac"},{"id":"t3","text":"130°, 30°, 20°","bucket":"ob"},{"id":"t4","text":"60°, 30°, 90°","bucket":"re","feedback":"El 90° está al final, pero cuenta igual: es rectángulo."},{"id":"t5","text":"100°, 50°, 30°","bucket":"ob"},{"id":"t6","text":"80°, 55°, 45°","bucket":"ac"}]},"id":"s01-mat-1-7"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.1"],"prompt":"Las señales de \\"ceda el paso\\" tienen forma de triángulo con **tres ángulos iguales de 60°**. ¿Qué tipo de triángulo son?","explain":"60° es menor que 90°, y los tres ángulos son de 60°: es **acutángulo**.","type":"choice","props":{"options":[{"id":"a","text":"Acutángulo","icon":"Triangle"},{"id":"r","text":"Rectángulo","icon":"Square","feedback":"Para ser rectángulo necesita un ángulo de exactamente 90°."},{"id":"o","text":"Obtusángulo","icon":"Tent","feedback":"Ningún ángulo pasa de 90°."}],"correct":["a"]},"id":"s01-mat-1-8"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.1"],"prompt":"Un triángulo es **rectángulo**. ¿Cuántos de sus ángulos son **agudos**?","explain":"Tiene un ángulo recto y los otros **2** son agudos (en todo triángulo, al menos dos ángulos son agudos).","type":"number-input","props":{"answer":2,"misconceptions":[{"value":0,"msg":"Solo uno es recto; los otros dos tienen que ser más pequeños."},{"value":3,"msg":"Si los tres fueran agudos, no habría ángulo recto."}]},"id":"s01-mat-1-9"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.1.1"],"prompt":"Un triángulo tiene ángulos de **95°, 50° y 35°**. ¿Cómo se llama?","type":"choice","props":{"options":[{"id":"a","text":"Acutángulo"},{"id":"r","text":"Rectángulo"},{"id":"o","text":"Obtusángulo"}],"correct":["o"]},"id":"s01-mat-1-10"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.1.1"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Un ángulo de 90° es un ángulo recto.","answer":true},{"text":"Un ángulo de 120° es agudo.","answer":false,"why":"120° es mayor que 90°: es obtuso."},{"text":"Un triángulo puede tener dos ángulos obtusos.","answer":false,"why":"Sus lados no alcanzarían a cerrarse."},{"text":"Un triángulo con ángulos de 50°, 60° y 70° es acutángulo.","answer":true}]},"id":"s01-mat-1-11"}],"kind":"materia","area":"mat","day":1}},{"missionId":"s01","version":"cnb-sexto-4594f2f840d147ad","lesson":{"id":"s01-mat-2","title":"El ángulo que falta: la regla de los 180°","icon":"Scissors","minutes":14,"gancho":"Si recortas un triángulo de papel y juntas sus tres esquinas, pasa algo sorprendente. ¿Qué crees que se forma?","objetivos":["Descubrir que los tres ángulos de cualquier triángulo suman 180°","Calcular el ángulo que falta en un triángulo y luego clasificarlo"],"resumen":["Los tres ángulos de cualquier triángulo suman 180°, sin importar su tamaño ni su forma.","Para hallar el ángulo que falta: suma los dos que conoces y resta ese resultado a 180°.","En un triángulo rectángulo, los dos ángulos agudos suman 90°.","Si tres medidas no suman 180°, no pueden ser los ángulos de un triángulo."],"media":{"id":"s01-mat-2-esquinas","kind":"video","title":"Las tres esquinas forman una línea","aspect":"16:9","duration":50,"alt":"Unas manos recortan un triángulo de papel, arrancan sus tres esquinas y las juntan: forman media vuelta, una línea recta.","brief":"Video de 50 s en mesa de madera, plano cenital. Unas manos de niña o niño dibujan un triángulo cualquiera en papel de color, pintan cada esquina de un color (rojo, azul, amarillo), lo recortan con tijeras de punta redonda, arrancan las tres esquinas con los dedos y las juntan con los vértices en un mismo punto: se forma una línea recta. Aparece el texto \\"180°\\". Se repite rápido con un triángulo muy distinto (largo y delgado) con el mismo resultado. Narración en español: \\"¡Siempre suman 180 grados!\\". Sin marcas. Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:1.1.1"],"ambito":"conocer","title":"La regla de los 180°","prompt":"Los tres ángulos de **cualquier** triángulo suman **180°**. Grande o pequeño, acutángulo u obtusángulo: siempre 180°. Toca cada tarjeta.","type":"explain","props":{"icon":"Triangle","body":"Ángulo 1 + ángulo 2 + ángulo 3 = **180°**","reveal":[{"icon":"Scissors","front":"Compruébalo en casa","back":"Dibuja un triángulo, colorea sus esquinas, recórtalo y junta las tres esquinas: formarán una línea recta (180°)."},{"icon":"Calculator","front":"El ángulo que falta","back":"Si conoces dos ángulos, súmalos y **resta** el resultado a 180°."},{"icon":"Lightbulb","front":"¿Por qué solo un ángulo grande?","back":"Dos ángulos rectos ya suman 90° + 90° = 180° y no quedaría nada para el tercero. Por eso un triángulo tiene como máximo un ángulo recto u obtuso."}]},"id":"s01-mat-2-1"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.1"],"ambito":"conocer","prompt":"Recortas un triángulo de papel, arrancas sus **tres esquinas** y las juntas con las puntas en un mismo lugar. ¿Qué crees que se forma?","explain":"¡Se forma una **línea recta**! Una línea recta es un ángulo llano: **180°**. Eso pasa con cualquier triángulo.","type":"choice","props":{"options":[{"id":"a","text":"Un círculo completo","icon":"Circle","feedback":"Un círculo completo serían 360°. Las tres esquinas juntas alcanzan solo la mitad."},{"id":"b","text":"Una línea recta (media vuelta)","icon":"Minus"},{"id":"c","text":"Una esquina de hoja (90°)","icon":"Square","feedback":"Juntas son más abiertas que la esquina de una hoja: llegan a formar una línea recta."}],"correct":["b"]},"id":"s01-mat-2-2"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.1"],"ambito":"hacer","title":"Ejemplo resuelto","prompt":"Así se calcula el ángulo que falta.","type":"worked-example","props":{"icon":"Calculator","problem":"Un banderín triangular para la feria tiene dos ángulos de **48°** y **75°**. ¿Cuánto mide el tercero? ¿Qué tipo de triángulo es?","steps":[{"text":"Sumo los ángulos que conozco: 48° + 75° = **123°**."},{"text":"Resto a 180°: 180° − 123° = **57°**.","why":"Los tres juntos deben sumar 180°; lo que falta para llegar es el tercer ángulo."},{"text":"Compruebo: 48 + 75 + 57 = 180. ✔"},{"text":"El mayor es 75°, menor que 90°: los tres son agudos."}],"answer":"El tercer ángulo mide **57°** y el banderín es un triángulo **acutángulo**.","tip":"Suma, resta a 180 y comprueba sumando los tres."},"id":"s01-mat-2-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.1"],"prompt":"Ahora tú, con ayuda: un triángulo tiene ángulos de **90°** y **35°**. ¿Cuánto mide el tercero?","hint":"Primero suma 90 + 35. Luego resta ese resultado a 180.","explain":"90 + 35 = 125 y 180 − 125 = 55. El tercer ángulo mide 55°.","type":"number-input","props":{"answer":55,"unit":"°","stimulus":"90° + 35° + ? = 180°","misconceptions":[{"value":125,"msg":"125 es la suma de los dos ángulos que conoces. Falta restarla a 180."},{"value":305,"msg":"Sumaste todo. Recuerda: el total debe ser 180°, así que hay que restar."}]},"id":"s01-mat-2-4"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.1"],"ambito":"conocer","title":"Atajos que salen de la regla","prompt":"Con la regla de los 180° descubres datos útiles sin medir. Toca cada tarjeta.","type":"explain","props":{"icon":"Sparkles","body":"Estos atajos te ahorran pasos.","reveal":[{"icon":"Square","front":"Triángulo rectángulo","back":"El recto ya ocupa 90°. Los otros dos suman **90°**. Si uno mide 30°, el otro mide 60°."},{"icon":"Triangle","front":"Tres ángulos iguales","back":"180° ÷ 3 = **60°** cada uno."},{"icon":"Tent","front":"Dos ángulos iguales","back":"Resta el ángulo distinto a 180° y divide lo que queda entre 2. Si el distinto mide 100°: (180 − 100) ÷ 2 = **40°** cada uno."}]},"id":"s01-mat-2-5"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.1"],"prompt":"Una escuadra es un triángulo rectángulo. Uno de sus ángulos agudos mide **27°**. ¿Cuánto mide el otro ángulo agudo?","hint":"En un triángulo rectángulo, los dos ángulos agudos suman 90°.","explain":"90 − 27 = 63. El otro ángulo mide 63°. (Compruebo: 90 + 27 + 63 = 180.)","type":"number-input","props":{"answer":63,"unit":"°","misconceptions":[{"value":153,"msg":"Restaste 27 a 180, pero olvidaste que el ángulo recto ya ocupa 90°."},{"value":117,"msg":"Sumaste 90 + 27. Ahora resta ese resultado a 180."}]},"id":"s01-mat-2-6"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.1"],"prompt":"El techo de un rancho forma un triángulo. El ángulo de arriba mide **120°** y los dos ángulos de abajo son **iguales**. ¿Cuánto mide cada ángulo de abajo?","explain":"180 − 120 = 60 y 60 ÷ 2 = 30. Cada ángulo de abajo mide 30°.","type":"number-input","props":{"answer":30,"unit":"°","misconceptions":[{"value":60,"msg":"60° es lo que miden los dos juntos. Divide entre 2."},{"value":20,"msg":"Ten cuidado: no se divide 60 entre 3. El ángulo de arriba ya está contado."}]},"id":"s01-mat-2-7"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.1"],"prompt":"¿Pueden ser estos los ángulos de un triángulo? Suma y decide.","explain":"Solo son posibles si la suma da exactamente 180°.","type":"true-false","props":{"statements":[{"text":"60°, 60° y 60°","answer":true,"why":"60 + 60 + 60 = 180."},{"text":"100°, 50° y 40°","answer":false,"why":"100 + 50 + 40 = 190: se pasa de 180."},{"text":"90°, 45° y 45°","answer":true,"why":"90 + 45 + 45 = 180."},{"text":"90°, 90° y 10°","answer":false,"why":"Suma 190 y además tendría dos ángulos rectos."}]},"id":"s01-mat-2-8"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.1"],"prompt":"Doña Rosa corta una servilleta por su diagonal y obtiene un triángulo con dos ángulos de **45°**. ¿Cuánto mide el tercer ángulo y qué tipo de triángulo es?","explain":"45 + 45 = 90 y 180 − 90 = 90. El tercer ángulo es recto: triángulo **rectángulo**.","type":"choice","props":{"options":[{"id":"a","text":"90°, rectángulo"},{"id":"b","text":"45°, acutángulo","feedback":"Si los tres midieran 45°, sumarían solo 135°."},{"id":"c","text":"100°, obtusángulo","feedback":"Revisa la resta: 180 − 90 = 90."}],"correct":["a"]},"id":"s01-mat-2-9"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.1.1"],"prompt":"Un triángulo tiene ángulos de **65°** y **70°**. ¿Cuánto mide el tercero?","type":"number-input","props":{"answer":45,"unit":"°"},"id":"s01-mat-2-10"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.1.1"],"prompt":"Dos ángulos de un triángulo miden **30°** y **50°**. ¿Qué tipo de triángulo es?","type":"choice","props":{"options":[{"id":"a","text":"Acutángulo"},{"id":"r","text":"Rectángulo"},{"id":"o","text":"Obtusángulo"}],"correct":["o"]},"id":"s01-mat-2-11"}],"kind":"materia","area":"mat","day":2}},{"missionId":"s01","version":"cnb-sexto-410aa2a66467a368","lesson":{"id":"s01-mat-5","title":"Figuras congruentes: iguales en forma y tamaño","icon":"Copy","minutes":15,"gancho":"Para que un piso quede parejo, todas las baldosas deben encajar igualito. ¿Cómo sabes si dos figuras son exactamente iguales?","objetivos":["Identificar figuras congruentes comparando lados y ángulos","Trazar una figura congruente a otra en papel cuadriculado"],"resumen":["Dos figuras son congruentes si tienen la misma forma y el mismo tamaño: sus lados correspondientes miden lo mismo y sus ángulos correspondientes también.","No importa la posición, el color ni si una está girada o reflejada: si encajan exactamente una sobre otra, son congruentes.","Dos figuras con la misma forma pero distinto tamaño NO son congruentes.","Para trazar una figura congruente, copia cada lado con el mismo número de cuadritos y en la misma dirección."],"media":{"id":"s01-mat-5-baldosas","kind":"image","title":"Un piso de baldosas congruentes","aspect":"4:3","alt":"Piso de un corredor colonial con baldosas cuadradas de dos colores; dos baldosas se levantan y se superponen para mostrar que encajan exactamente.","brief":"Ilustración de un corredor de casa antigua de Antigua Guatemala con piso de baldosas cuadradas en dos colores (rojo barro y crema). En primer plano, una baldosa aparece levantada y colocada encima de otra, con una línea punteada mostrando que coinciden en todos sus bordes; texto pequeño: \\"congruentes\\". A un lado, una baldosa más pequeña con el mismo dibujo, con una X suave y la etiqueta \\"misma forma, otro tamaño\\". Estilo plano cálido, sin personas. Dimensiones: 1200x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:1.1.4"],"ambito":"conocer","title":"¿Qué significa congruente?","prompt":"Dos figuras son **congruentes** cuando tienen **la misma forma y el mismo tamaño**. Toca cada tarjeta.","type":"explain","props":{"icon":"Copy","body":"Para comprobarlo, compara **lados correspondientes** (los que ocupan el mismo lugar) y **ángulos correspondientes**.","reveal":[{"icon":"Ruler","front":"Lados","back":"Cada lado de una figura mide lo mismo que su lado correspondiente en la otra."},{"icon":"Triangle","front":"Ángulos","back":"Cada ángulo de una figura mide lo mismo que su ángulo correspondiente en la otra."},{"icon":"RotateCw","front":"Posición","back":"No importa si una está **girada**, **volteada** o en otro lugar, ni de qué color es."},{"icon":"X","front":"Contraejemplo","back":"Un cuadrado de 3 cm y uno de 5 cm tienen la misma forma, pero **no** son congruentes: su tamaño es distinto."}]},"id":"s01-mat-5-1"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.4"],"ambito":"conocer","prompt":"Tienes dos tortillas hechas con el mismo molde y una tortillita pequeña. ¿Cuáles **encajarían exactamente** una sobre otra?","explain":"Las dos del mismo molde tienen la misma forma **y** el mismo tamaño. La pequeña tiene la misma forma, pero no el mismo tamaño.","type":"choice","props":{"options":[{"id":"a","text":"Las dos tortillas del mismo molde","icon":"Pizza"},{"id":"b","text":"Una tortilla del molde y la tortillita","icon":"CircleDot","feedback":"Son redondas las dos, pero de distinto tamaño: no encajan exactamente."},{"id":"c","text":"Todas, porque todas son redondas","icon":"Layers","feedback":"Ser redondas no basta: también deben ser del mismo tamaño."}],"correct":["a"]},"id":"s01-mat-5-2"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.4"],"prompt":"El triángulo A tiene lados de **3, 4 y 5 cm**. ¿Cuál de estos triángulos es **congruente** con A?","hint":"Busca uno con exactamente las mismas tres medidas, aunque estén en otro orden.","explain":"El triángulo con lados de 5, 3 y 4 cm tiene las mismas medidas en otro orden: está girado, pero es congruente.","type":"choice","props":{"options":[{"id":"a","text":"Lados de 6, 8 y 10 cm","feedback":"Tiene la misma forma, pero es el doble de grande: no es congruente."},{"id":"b","text":"Lados de 5, 3 y 4 cm"},{"id":"c","text":"Lados de 3, 4 y 6 cm","feedback":"Un lado es distinto (6 en lugar de 5)."}],"correct":["b"]},"id":"s01-mat-5-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.5"],"ambito":"hacer","title":"Trazar una figura congruente","prompt":"En papel cuadriculado, copiar una figura es como seguir un camino. Observa.","type":"worked-example","props":{"icon":"PenTool","problem":"Copia en otro lugar de la hoja el romboide que tiene: base de **4 cuadritos**, lado inclinado que sube **2** y se corre **1** a la derecha.","steps":[{"text":"Elige un punto de inicio nuevo en la hoja."},{"text":"Traza la base: **4 cuadritos** a la derecha.","why":"El mismo número de cuadritos asegura la misma longitud."},{"text":"Desde el inicio, sube **2** y córrete **1** a la derecha; marca ese punto. Haz lo mismo desde el final de la base.","why":"Así el lado inclinado tiene la misma longitud y el mismo ángulo."},{"text":"Une los dos puntos de arriba (otra línea de 4) y los lados inclinados."}],"answer":"Tu romboide es **congruente** con el original: mismos lados y mismos ángulos.","tip":"Sin cuadrícula, usa regla para los lados y transportador para los ángulos."},"id":"s01-mat-5-4"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.4","mat:1.1.5"],"prompt":"¿Verdadero o falso?","hint":"Congruente = misma forma y mismo tamaño. La posición no importa.","explain":"Girar, voltear o mover una figura no cambia sus lados ni sus ángulos.","type":"true-false","props":{"statements":[{"text":"Si giro un triángulo, el triángulo girado es congruente con el original.","answer":true},{"text":"Un rectángulo de 4 × 2 cuadritos y uno de 8 × 4 cuadritos son congruentes.","answer":false,"why":"El segundo es el doble de grande."},{"text":"Para copiar una figura congruente en cuadrícula, cada lado debe medir los mismos cuadritos.","answer":true}]},"id":"s01-mat-5-5"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.4"],"prompt":"¿Son congruentes estos pares de figuras?","explain":"Compara lado por lado y ángulo por ángulo.","type":"sort","props":{"buckets":[{"id":"si","label":"Congruentes","icon":"Check","color":"var(--c-ok)"},{"id":"no","label":"No congruentes","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"a","text":"Dos cuadrados de 5 cm de lado","bucket":"si"},{"id":"b","text":"Un cuadrado de 4 cm y un rombo de 4 cm de lado con ángulos de 60° y 120°","bucket":"no","feedback":"Los lados miden igual, pero los ángulos no: 90° no es igual a 60°."},{"id":"c","text":"Dos rectángulos de 7 × 3 cm, uno acostado y otro parado","bucket":"si","feedback":"Solo cambió la posición."},{"id":"d","text":"Dos triángulos de 60°, 60° y 60°, uno con lados de 2 cm y otro de 3 cm","bucket":"no","feedback":"Misma forma, distinto tamaño."},{"id":"e","text":"Un triángulo y su reflejo en un espejo","bucket":"si"}]},"id":"s01-mat-5-6"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.5","mat:1.1.1"],"prompt":"Trazaste un triángulo congruente con otro que tiene ángulos de **50°** y **70°**. ¿Cuánto mide el **tercer** ángulo de tu copia?","explain":"El original mide 180 − 50 − 70 = 60°. Como tu copia es congruente, su tercer ángulo también mide 60°.","type":"number-input","props":{"answer":60,"unit":"°","misconceptions":[{"value":120,"msg":"120 es la suma de los dos ángulos conocidos. Réstala a 180."}]},"id":"s01-mat-5-7"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.4"],"prompt":"Un albañil va a cubrir un piso sin dejar huecos ni encimar piezas. ¿Por qué pide que todas las baldosas sean **congruentes**?","explain":"Si todas son congruentes, cada baldosa encaja exactamente junto a las demás y el piso queda parejo.","type":"choice","props":{"options":[{"id":"a","text":"Para que todas encajen igual y el piso quede parejo","icon":"Blocks"},{"id":"b","text":"Para que sean todas del mismo color","icon":"Palette","feedback":"El color no tiene que ver con la congruencia."},{"id":"c","text":"Para que pesen menos","icon":"Scale","feedback":"Lo importante es la forma y el tamaño, no el peso."}],"correct":["a"]},"id":"s01-mat-5-8"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.1.4"],"prompt":"El rectángulo R mide **6 cm × 2 cm**. ¿Cuál es congruente con R?","type":"choice","props":{"options":[{"id":"a","text":"Un rectángulo de 3 cm × 1 cm"},{"id":"b","text":"Un rectángulo de 2 cm × 6 cm, parado"},{"id":"c","text":"Un romboide de lados 6 cm y 2 cm"}],"correct":["b"]},"id":"s01-mat-5-9"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.1.4","mat:1.1.2","mat:1.1.1"],"prompt":"Repaso de la semana. ¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Dos figuras congruentes tienen la misma forma y el mismo tamaño.","answer":true},{"text":"Un cuadrado de 3 cm y otro de 6 cm son congruentes.","answer":false},{"text":"Un rombo tiene 4 lados iguales.","answer":true},{"text":"Un triángulo con ángulos de 90°, 60° y 30° es obtusángulo.","answer":false}]},"id":"s01-mat-5-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["mat"],"cnb":[],"type":"reflection","props":{"statements":["Clasifico triángulos por sus ángulos y calculo el ángulo que falta","Distingo rectángulo, cuadrado, rombo y romboide","Reconozco y trazo figuras congruentes"],"commitments":["Buscaré paralelogramos en mi casa y en el mercado","Haré el experimento de las tres esquinas con mi familia","Revisaré mis trazos contando cuadritos con cuidado"]},"id":"s01-mat-5-11"}],"kind":"materia","area":"mat","day":5}},{"missionId":"s01","version":"cnb-sexto-ff4c4b7d707f5bf5","lesson":{"id":"s01-cnt-3","title":"Células, cromosomas y genes","icon":"Leaf","minutes":15,"gancho":"Una hoja de lechuga fresca cruje y se mantiene firme; tu mejilla es suave y flexible. ¿Tendrá algo que ver con sus células?","objetivos":["Comparar células animales y vegetales y relacionar sus cromosomas con las funciones de los genes"],"resumen":["Ambas células tienen membrana, citoplasma, núcleo, mitocondrias, ribosomas, retículo endoplasmático y aparato de Golgi.","Solo la célula vegetal tiene pared celular (da forma y firmeza), cloroplastos (hacen la fotosíntesis) y una vacuola central grande (guarda agua).","La célula animal tiene centriolos, vacuolas pequeñas y forma redondeada o irregular; la vegetal suele tener forma regular, como un ladrillo.","En ambos tipos de célula, los cromosomas organizan el ADN; los genes son segmentos de ADN con instrucciones para funciones y características."],"media":{"id":"s01-cnt-3-comparacion","kind":"diagram","title":"Célula animal y célula vegetal lado a lado","aspect":"16:9","alt":"A la izquierda una célula animal redondeada; a la derecha una célula vegetal rectangular con pared gruesa verde, cloroplastos y una gran vacuola central. Las estructuras compartidas tienen el mismo color en ambas.","brief":"Diagrama escolar comparativo en colores planos. Izquierda: célula animal redondeada (membrana, citoplasma, núcleo, mitocondrias, ribosomas, retículo, Golgi, lisosomas, centriolos). Derecha: célula vegetal con forma de ladrillo: pared celular gruesa verde oscuro por fuera de la membrana, varios cloroplastos verdes ovalados, vacuola central grande celeste que empuja el núcleo hacia un lado, mitocondrias. Estructuras compartidas con el mismo color en ambas células; las exclusivas con un borde de estrella y rótulo en negrita (\\"solo vegetal\\", \\"solo animal\\"). Letra grande, fondo blanco. Dimensiones: 1600x900."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:1.3.1"],"ambito":"conocer","title":"Lo que comparten","prompt":"Las células de plantas y de animales son **parecidas por dentro**. Toca las tarjetas.","type":"explain","props":{"icon":"Copy","body":"Ambas tienen **núcleo** con ADN y los organelos que aprendiste en la lección anterior.","reveal":[{"icon":"Shield","front":"Membrana y citoplasma","back":"Las dos tienen **membrana celular** que controla el paso de sustancias y **citoplasma** donde flotan los organelos."},{"icon":"Brain","front":"Núcleo","back":"Las dos guardan su ADN en un **núcleo** que dirige la célula."},{"icon":"Zap","front":"Mitocondrias","back":"¡Ojo! Las plantas **también** tienen mitocondrias: necesitan energía para crecer, igual que tú."},{"icon":"Package","front":"Ribosomas, retículo y Golgi","back":"Ambas fabrican, transportan y empacan sustancias con los mismos organelos."}]},"id":"s01-cnt-3-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.4.1"],"ambito":"conocer","title":"Del núcleo al gen","prompt":"Sigue un ejemplo para relacionar núcleo, cromosoma y gen sin confundirlos.","type":"worked-example","props":{"icon":"Dna","problem":"Una célula de una hoja necesita una instrucción para producir una proteína. ¿Cómo se organiza esa información?","steps":[{"text":"El **núcleo** guarda el ADN de la célula."},{"text":"El **ADN** se empaqueta y organiza en **cromosomas**."},{"text":"Un **gen** es un segmento de ADN ubicado en un cromosoma; contiene una instrucción funcional."}],"answer":"La instrucción está en un gen, dentro del ADN organizado en un cromosoma del núcleo. Cromosoma y gen no son sinónimos.","tip":"Piensa en la relación de mayor a menor: núcleo, cromosoma, gen."},"id":"s01-cnt-3-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.3.1"],"ambito":"conocer","title":"Lo que las hace diferentes","prompt":"Observa el esquema de la lección. La célula vegetal tiene **tres estructuras** que la animal no tiene, y la animal tiene una que la vegetal no. Toca cada tarjeta.","type":"explain","props":{"icon":"Leaf","body":"Las plantas **no se mueven** de un lugar a otro y **fabrican su propio alimento** con la luz del Sol. Sus células están preparadas para eso.","reveal":[{"icon":"Square","front":"Pared celular (solo vegetal)","back":"Capa **rígida** de **celulosa** por fuera de la membrana. Da **forma y firmeza**: por eso un tronco se sostiene de pie. La madera y el papel están hechos de paredes celulares."},{"icon":"Sun","front":"Cloroplastos (solo vegetal)","back":"Organelos verdes con **clorofila**. Capturan la luz del Sol y hacen la **fotosíntesis**: fabrican alimento (azúcar) y liberan oxígeno."},{"icon":"Droplet","front":"Vacuola central (solo vegetal)","back":"Una bolsa **grande** llena de agua que ocupa casi toda la célula y la mantiene **firme**. En la célula animal las vacuolas son pequeñas."},{"icon":"Circle","front":"Centriolos y forma (solo animal)","back":"La célula animal tiene **centriolos** y, sin pared, tiene forma **redondeada o irregular**. La vegetal suele verse como un **ladrillo**."}]},"id":"s01-cnt-3-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.3.1"],"ambito":"conocer","prompt":"Usa lo aprendido: ¿por qué una hoja de lechuga fresca se mantiene **firme** y cruje?","explain":"La **pared celular** rígida y la **vacuola** llena de agua ayudan a que la hoja se mantenga firme.","type":"choice","props":{"options":[{"id":"a","text":"Porque sus células tienen una cubierta rígida y mucha agua adentro","icon":"Droplets"},{"id":"b","text":"Porque tiene huesos muy pequeños","icon":"Bone","feedback":"Las plantas no tienen huesos. La firmeza viene de sus células."},{"id":"c","text":"Porque está fría","icon":"Snowflake","feedback":"El frío ayuda a conservarla, pero la firmeza viene de la estructura de sus células."}],"correct":["a"]},"id":"s01-cnt-3-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.3.1"],"ambito":"conocer","prompt":"Clasifica cada estructura: ¿solo en la célula animal, solo en la vegetal o en ambas?","hint":"Solo la vegetal: pared, cloroplastos, vacuola central grande. Solo la animal: centriolos. Lo demás lo comparten.","explain":"Compartidas: membrana, núcleo, mitocondrias, ribosomas. Solo vegetal: pared celular, cloroplastos, vacuola central. Solo animal: centriolos.","type":"sort","props":{"buckets":[{"id":"an","label":"Solo animal","icon":"Circle","color":"var(--area-l1)"},{"id":"ve","label":"Solo vegetal","icon":"Leaf","color":"var(--c-ok)"},{"id":"am","label":"Ambas","icon":"Copy","color":"var(--area-cnt)"}],"items":[{"id":"s1","text":"Pared celular","bucket":"ve"},{"id":"s2","text":"Cloroplastos","bucket":"ve"},{"id":"s3","text":"Núcleo","bucket":"am"},{"id":"s4","text":"Centriolos","bucket":"an"},{"id":"s5","text":"Mitocondrias","bucket":"am","feedback":"Las plantas también necesitan energía: tienen mitocondrias."},{"id":"s6","text":"Vacuola central grande","bucket":"ve"},{"id":"s7","text":"Membrana celular","bucket":"am","feedback":"La célula vegetal también tiene membrana, justo por dentro de la pared."},{"id":"s8","text":"Ribosomas","bucket":"am"}]},"id":"s01-cnt-3-5"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.3.1"],"ambito":"hacer","title":"Ejemplo: la lechuga marchita","prompt":"Usa lo que sabes de la célula vegetal para explicar algo que pasa en la cocina.","media":{"id":"s01-cnt-3-lechuga","kind":"image","title":"Antes y después: la hoja en agua","aspect":"4:3","alt":"Dos fotos de una hoja de lechuga: a la izquierda marchita y doblada; a la derecha firme después de estar en un vaso con agua. Debajo, dos células vegetales: una con la vacuola pequeña y otra con la vacuola llena.","brief":"Composición de dos fotografías reales, fondo de mesa de cocina sencilla: (1) hoja de lechuga marchita, caída; (2) la misma hoja firme dentro de un vaso de agua, rótulo \\"1 hora después\\". Debajo de cada foto, un dibujo simple de una célula vegetal: vacuola encogida y membrana separada de la pared (marchita) / vacuola grande que empuja contra la pared (firme). Flechas azules de agua entrando. Sin marcas comerciales. Dimensiones: 1200x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"type":"worked-example","props":{"icon":"Salad","problem":"Una hoja de lechuga se quedó fuera del refrigerador y se **marchitó**. La mamá de Rosa la pone en un vaso con agua fresca y, una hora después, está **firme** otra vez. ¿Por qué?","steps":[{"text":"La hoja marchita **perdió agua**: las **vacuolas** de sus células se encogieron.","why":"La vacuola central guarda el agua de la célula vegetal."},{"text":"Sin agua que empuje, las células ya no presionan contra la **pared celular**, y la hoja se dobla."},{"text":"En el vaso, el agua **entra** a las células a través de la pared y de la membrana, y las vacuolas se llenan de nuevo."},{"text":"Las vacuolas llenas empujan contra la pared rígida: la célula se pone **firme**, como un globo inflado dentro de una caja.","why":"La pared no deja que la célula se estire de más."}],"answer":"La firmeza de la hoja depende de la **vacuola llena de agua** que empuja contra la **pared celular**.","tip":"Pruébalo en casa, con permiso: pon una rama de apio o una hoja marchita en un vaso de agua y obsérvala después de una hora."},"id":"s01-cnt-3-6"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.3.1"],"ambito":"conocer","prompt":"Rodrigo dice: \\"Las plantas no tienen mitocondrias porque ya tienen cloroplastos\\". ¿Tiene razón?","hint":"Recuerda: ¿qué hace cada organelo? Uno fabrica alimento; el otro saca energía del alimento.","explain":"El **cloroplasto** fabrica el alimento (azúcar) con la luz; la **mitocondria** saca energía de ese alimento. Las plantas necesitan los dos.","type":"choice","props":{"options":[{"id":"a","text":"Sí, los cloroplastos hacen el trabajo de las mitocondrias","feedback":"Hacen trabajos distintos: fabricar alimento no es lo mismo que obtener energía de él."},{"id":"b","text":"No: las plantas tienen cloroplastos **y** mitocondrias"},{"id":"c","text":"No: las plantas no tienen ninguno de los dos","feedback":"Las células de las hojas tienen cloroplastos, y todas las células vegetales tienen mitocondrias."}],"correct":["b"]},"id":"s01-cnt-3-7"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.3.1"],"ambito":"hacer","prompt":"Una científica describe lo que vio en el microscopio. ¿Es una célula **animal** o **vegetal**?","explain":"Pared gruesa, forma de ladrillo, granos verdes o una gran vacuola indican célula vegetal. Forma redondeada sin pared indica célula animal.","type":"sort","props":{"layout":"grid2","buckets":[{"id":"an","label":"Célula animal","icon":"Circle","color":"var(--area-l1)"},{"id":"ve","label":"Célula vegetal","icon":"Leaf","color":"var(--c-ok)"}],"items":[{"id":"m1","text":"Forma de ladrillo, con muchos granos verdes","bucket":"ve"},{"id":"m2","text":"Redondeada, flexible, sin pared","bucket":"an"},{"id":"m3","text":"Tiene una bolsa de agua que ocupa casi toda la célula","bucket":"ve"},{"id":"m4","text":"De la mejilla por dentro, con forma irregular","bucket":"an"},{"id":"m5","text":"De una hoja de milpa, con cloroplastos","bucket":"ve"},{"id":"m6","text":"Tiene centriolos cerca del núcleo","bucket":"an"}]},"id":"s01-cnt-3-8"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.3.1","cnt:1.4.1"],"ambito":"conocer","prompt":"Una científica observa una célula vegetal con núcleo. Dentro identifica cromosomas y, en ellos, genes. ¿Qué relación entre sus funciones es correcta?","type":"choice","props":{"options":[{"id":"a","text":"Los cromosomas organizan ADN y cada gen es un segmento con una instrucción"},{"id":"b","text":"Cada gen contiene todos los cromosomas de la célula"},{"id":"c","text":"Los cromosomas fabrican luz y los genes almacenan agua"}],"correct":["a"]},"id":"s01-cnt-3-9"},{"fase":"aplicar","areas":["cnt","art"],"cnb":["cnt:1.3.1","cnt:1.4.1"],"ambito":"hacer","title":"Modelo breve en papel","prompt":"En una hoja o cuaderno, representa una célula vegetal y amplía su núcleo hasta mostrar cromosoma, ADN y gen.","type":"project","props":{"goal":"Dibujar una comparación celular y un acercamiento que relacione cromosomas y genes.","steps":[{"title":"Célula","detail":"Con lápiz, dibuja pared, membrana, vacuola, cloroplastos y núcleo; marca dos diferencias con una célula animal."},{"title":"Acercamiento","detail":"Traza una flecha desde el núcleo a un cromosoma, dibuja su ADN y señala un segmento como gen."}],"evidence":"El dibujo en papel queda como evidencia física; la lista solo verifica que se completaron sus partes.","rubric":["Diferencié célula vegetal y animal","Relacioné núcleo, cromosoma, ADN y gen","Rotulé la función de cromosoma y gen"]},"id":"s01-cnt-3-10"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:1.3.1","cnt:1.4.1"],"prompt":"Una célula vegetal tiene cloroplastos y núcleo. ¿Qué opción relaciona correctamente una diferencia celular y las funciones de cromosomas y genes?","type":"choice","props":{"options":[{"id":"a","text":"El cloroplasto distingue a la célula vegetal; los cromosomas organizan ADN y los genes son segmentos con instrucciones"},{"id":"b","text":"El cloroplasto contiene todos los genes y cada gen organiza varios núcleos"},{"id":"c","text":"La pared celular es un cromosoma y el núcleo es un gen"}],"correct":["a"]},"id":"s01-cnt-3-11"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:1.3.1","cnt:1.4.1"],"prompt":"Comprueba diferencias celulares y la relación funcional entre cromosomas y genes.","type":"true-false","props":{"statements":[{"text":"Las células animales y vegetales pueden tener cromosomas en el núcleo.","answer":true},{"text":"Un gen es un segmento de ADN situado en un cromosoma y aporta una instrucción.","answer":true},{"text":"La pared celular y los cloroplastos son propios de la célula animal.","answer":false,"why":"Son estructuras características de la célula vegetal."}]},"id":"s01-cnt-3-12"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["cnt"],"cnb":[],"type":"reflection","props":{"statements":["Diferencio una célula animal de una vegetal","Relaciono núcleo, cromosomas, ADN y genes","Explico que un gen es un segmento de ADN con una instrucción"],"commitments":["Revisaré que mi modelo distinga ambos tipos de célula","Explicaré cómo un cromosoma organiza ADN y contiene genes"]},"id":"s01-cnt-3-13"}],"kind":"materia","area":"cnt","day":5}},{"missionId":"s01","version":"cnb-sexto-8c1624b61fb68479","lesson":{"id":"s01-l2-1","title":"Tres mensajes para orientar","icon":"MessagesSquare","minutes":14,"gancho":"Un mismo mapa puede servir para informar, explicar o defender una propuesta.","objetivos":["Producir mensajes informativos, expositivos y argumentativos breves sobre el lugar local y su mapa"],"resumen":["El informativo comunica datos verificables.","El expositivo explica como o por que.","El argumentativo presenta una postura con una razon."],"media":{"id":"s01-l2-1-mensajes","kind":"diagram","title":"Tres propositos en un mapa local","aspect":"16:9","alt":"Mapa local con tres globos rotulados informar, explicar y argumentar.","brief":"Diagrama 1600x900 de un mapa local ficticio con escuela, parque, mercado y puente. Tres globos: dato verificable, explicacion de una ruta y postura con razon. Texto grande, alto contraste, iconos ademas de color y lectura lineal accesible."},"steps":[{"fase":"explorar","areas":["l2"],"cnb":["l2:1.2.2"],"prompt":"Produce mensajes informativos, expositivos y argumentativos sobre un lugar o mapa segun el proposito.","type":"explain","props":{"icon":"Goal","body":"**Informativo:** da un dato. **Expositivo:** explica como o por que. **Argumentativo:** propone una postura y la apoya con una razon."},"id":"s01-l2-1-1"},{"fase":"construir","areas":["l2"],"cnb":["l2:1.2.2"],"title":"Proposito y forma","prompt":"Para redactar cada mensaje sobre la comunidad, elige primero su proposito.","type":"explain","props":{"icon":"ListTree","body":"Informar: \\"La biblioteca esta al norte del parque\\". Exponer: \\"La flecha norte permite orientar la ruta\\". Argumentar: \\"Conviene senalar el cruce porque ayuda a caminar con seguridad\\"."},"id":"s01-l2-1-2"},{"fase":"construir","areas":["l2"],"cnb":["l2:1.2.2"],"title":"Modelo de produccion","prompt":"Observa como se producen tres mensajes distintos sobre el mismo mapa local.","type":"worked-example","props":{"icon":"Map","problem":"El mapa muestra una escuela, un puente y un sendero.","steps":[{"text":"Informativo: La escuela esta al este del puente."},{"text":"Expositivo: El sendero llega a la escuela porque conecta con el puente."},{"text":"Argumentativo: Debemos marcar el puente, pues es una referencia util."}],"answer":"Cada mensaje mantiene el tema y cambia su forma segun el proposito."},"id":"s01-l2-1-3"},{"fase":"construir","areas":["l2"],"cnb":["l2:1.2.2"],"prompt":"Con ayuda, produce mensajes informativos, expositivos y argumentativos sobre el mapa de una comunidad: escuela al norte, parque al centro y mercado al sur.","hint":"Usa dato; como o por que; postura mas razon.","explain":"Los tres mensajes tratan el mapa, pero cumplen propositos diferentes.","type":"short-answer","props":{"minWords":21,"placeholder":"Informativo: ... Expositivo: ... Argumentativo: ...","model":"Informativo: la escuela esta al norte. Expositivo: el parque orienta porque queda al centro. Argumentativo: conviene marcar el mercado porque guia la ruta.","rubric":["Produje los tres mensajes","Ajuste cada forma al proposito","Mantuve el tema local"]},"id":"s01-l2-1-4"},{"fase":"construir","areas":["l2"],"cnb":["l2:1.2.2"],"prompt":"Para producir un mensaje informativo, otro expositivo y otro argumentativo sobre una ruta local, ¿que plan sirve mejor?","hint":"Busca dato, explicacion y postura con razon.","explain":"El plan A distingue los tres propositos y conserva el tema del mapa.","type":"choice","props":{"options":[{"id":"a","text":"Dato de ubicacion; explicacion del recorrido; propuesta con una razon"},{"id":"b","text":"Tres opiniones sin evidencia"},{"id":"c","text":"Tres listas de nombres sin proposito"}],"correct":["a"]},"id":"s01-l2-1-5"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:1.2.2"],"prompt":"Produce de forma independiente un mensaje informativo, uno expositivo y uno argumentativo sobre una plaza, una parada y una calle representadas en un mapa local.","type":"short-answer","props":{"minWords":24,"placeholder":"Informativo: ... Expositivo: ... Argumentativo: ...","model":"Informativo: la parada esta junto a la plaza. Expositivo: la calle une ambos puntos. Argumentativo: conviene marcar el cruce porque aclara el recorrido para quienes visitan.","rubric":["Inclui un dato","Explique una relacion","Defendi una propuesta con razon"]},"id":"s01-l2-1-6"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:1.2.2"],"prompt":"Al producir mensajes informativos, expositivos y argumentativos sobre el mapa del barrio, ¿cual inicio corresponde al proposito argumentativo?","type":"choice","props":{"options":[{"id":"a","text":"Propongo marcar la fuente porque ayuda a reconocer la plaza."},{"id":"b","text":"La fuente esta frente al edificio municipal."},{"id":"c","text":"La fuente orienta la ruta al funcionar como referencia."}],"correct":["a"]},"id":"s01-l2-1-7"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:1.2.2"],"prompt":"Salida: produce dos mensajes nuevos sobre un mapa local que muestra una cancha al oeste de la biblioteca: uno informativo y otro expositivo.","type":"short-answer","props":{"minWords":12,"placeholder":"Informativo: ... Expositivo: ...","model":"Informativo: la cancha esta al oeste. Expositivo: la biblioteca ayuda a orientar la ruta porque queda al este.","rubric":["Produje ambos mensajes","Ajuste cada mensaje a su proposito","Use la ubicacion suministrada"]},"id":"s01-l2-1-8"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:1.2.2"],"prompt":"Salida nueva: produce un mensaje argumentativo breve sobre si conviene marcar un paso peatonal en el mapa de la comunidad. Incluye una postura y una razon propia.","type":"short-answer","props":{"minWords":8,"placeholder":"Propongo... porque...","model":"Conviene marcar el paso peatonal porque permite reconocer un cruce previsto para caminar.","rubric":["Exprese una postura","Inclui una razon","Mantuve el tema del mapa comunitario"]},"id":"s01-l2-1-9"}],"kind":"materia","area":"l2","day":2}},{"missionId":"s01","version":"cnb-sexto-17648fd188f8cc33","lesson":{"id":"s01-ccss-2","title":"Clima, ecosistemas, recursos y desarrollo","icon":"MountainSnow","minutes":15,"gancho":"Quetzaltenango y Puerto San José están casi a la misma latitud. ¿Por qué en uno usas chumpa y en el otro buscas sombra?","objetivos":["Relacionar clima y ecosistemas con recursos de distintos continentes y reflexionar por qué los recursos no determinan por sí solos el desarrollo"],"resumen":["Por la latitud, la Tierra tiene tres grandes zonas climáticas: cálida o tropical (entre los trópicos), templadas y frías o polares.","La altitud es la altura sobre el nivel del mar. Mientras más alto, más frío: la temperatura baja unos 6 °C por cada 1,000 metros.","En Guatemala hay pisos térmicos: tierras cálidas (costas y Petén), templadas (como la capital) y frías (como Quetzaltenango y el altiplano).","El clima decide qué ecosistema hay en cada lugar: selva tropical, sabana, desierto, bosque templado, taiga, tundra, arrecife y otros.","Los ecosistemas ofrecen recursos distintos: agua, suelos, flora, fauna, minerales y fuentes de energía; América se compara con otros continentes sin suponer que uno tiene de todo.","Tener muchos recursos no garantiza desarrollo: también influyen educación, salud, tecnología, instituciones, distribución y conservación."],"media":{"id":"s01-ccss-2-zonas","kind":"diagram","title":"Zonas climáticas de la Tierra","aspect":"4:3","alt":"Globo terráqueo con franjas de colores: roja entre los trópicos, verde en las zonas templadas y azul en los polos, con las líneas y latitudes rotuladas.","brief":"Diagrama de un globo terráqueo de frente con franjas horizontales coloreadas: zona cálida o tropical (naranja) entre el Trópico de Cáncer (23.5° N) y el Trópico de Capricornio (23.5° S); zonas templadas (verde) entre los trópicos y los círculos polares (66.5°); zonas frías o polares (azul claro) más allá de los círculos polares. Rotular cada línea con su nombre y latitud. Rayos de Sol entrando casi verticales en el ecuador y muy inclinados en los polos. Un punto marca Guatemala dentro de la zona cálida. Dimensiones: 1200x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:1.2.1"],"ambito":"conocer","title":"La latitud y las zonas climáticas","prompt":"La Tierra es redonda, así que los rayos del Sol **no llegan igual** a todas partes. Cerca del ecuador llegan casi directos y calientan más; cerca de los polos llegan inclinados y calientan menos. Toca cada tarjeta.","type":"explain","props":{"icon":"Sun","body":"Dos paralelos marcan la zona más cálida: el **Trópico de Cáncer** (unos 23.5° N) y el **Trópico de Capricornio** (unos 23.5° S).","reveal":[{"icon":"Sun","front":"Zona cálida o tropical","back":"Entre los dos trópicos. Hace calor casi todo el año. Guatemala está aquí, por eso no tenemos invierno con nieve: tenemos **época seca** y **época lluviosa**."},{"icon":"Leaf","front":"Zonas templadas","back":"Entre los trópicos y los círculos polares. Tienen **cuatro estaciones**: primavera, verano, otoño e invierno. Ejemplo: gran parte de Europa."},{"icon":"Snowflake","front":"Zonas frías o polares","back":"Más allá de los círculos polares (unos 66.5°). Muy frías casi todo el año. Ejemplo: la Antártida."}]},"id":"s01-ccss-2-1"},{"fase":"explorar","areas":["ccss"],"cnb":["ccss:1.2.1"],"ambito":"conocer","title":"La altitud: más alto, más frío","prompt":"La **altitud** es la altura de un lugar **sobre el nivel del mar** (msnm). Al subir una montaña, el aire es más delgado y guarda menos calor: la temperatura baja, en promedio, **unos 6 °C por cada 1,000 metros**.","media":{"id":"s01-ccss-2-pisos","kind":"diagram","title":"Pisos térmicos de Guatemala","aspect":"16:9","alt":"Corte de una montaña de Guatemala desde la costa del Pacífico hasta un volcán, con tres franjas: cálida abajo, templada en medio y fría arriba, con lugares de ejemplo.","brief":"Perfil lateral de Guatemala de sur a norte: costa del Pacífico al nivel del mar, bocacosta, altiplano y un volcán. Tres franjas de color: tierra cálida (0 a 1,000 m aprox., naranja) con Puerto San José y una palmera; tierra templada (1,000 a 2,000 m aprox., verde) con la Ciudad de Guatemala (unos 1,500 m) y un cafetal; tierra fría (más de 2,000 m, azul) con Quetzaltenango (unos 2,330 m) y pinos. Un termómetro al lado muestra que la temperatura baja al subir. Rótulos grandes; alturas con \\"aprox.\\". Dimensiones: 1600x900."},"type":"explain","props":{"icon":"Mountain","body":"Por eso en un mismo país tropical, como Guatemala, hay **pisos térmicos**: franjas de clima según la altura (los límites son aproximados).","reveal":[{"icon":"Sun","front":"Tierra cálida (0 a 1,000 m)","back":"Costa del Pacífico, Izabal y Petén. Ejemplos: Puerto San José, Puerto Barrios, Flores. Cultivos: caña de azúcar, banano, palma."},{"icon":"CloudSun","front":"Tierra templada (1,000 a 2,000 m)","back":"Ejemplos: Ciudad de Guatemala (unos 1,500 m), Cobán. Clima agradable; buen lugar para el café."},{"icon":"Snowflake","front":"Tierra fría (más de 2,000 m)","back":"Altiplano occidental. Ejemplos: Quetzaltenango (unos 2,330 m), Totonicapán. Puede haber heladas en diciembre y enero. Cultivos: trigo, papa, hortalizas."}]},"id":"s01-ccss-2-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:1.2.1"],"ambito":"conocer","prompt":"Dos lugares de Guatemala están a una latitud parecida: **Puerto San José** (a la orilla del mar) y **Quetzaltenango** (en las montañas, a más de 2,300 m). ¿Cuál crees que es más frío?","explain":"¡Quetzaltenango! Aunque estén a una latitud parecida, **la altitud** ayuda a explicar la diferencia de temperatura.","type":"choice","props":{"options":[{"id":"a","text":"Quetzaltenango, porque está más alto","icon":"Mountain"},{"id":"b","text":"Puerto San José, porque está junto al mar","icon":"Waves","feedback":"Puerto San José está al nivel del mar. Recuerda: al aumentar la altitud, la temperatura suele bajar."},{"id":"c","text":"Los dos tienen el mismo clima","icon":"Equal","feedback":"Tienen latitud parecida, pero la diferencia de altitud influye mucho en la temperatura."}],"correct":["a"]},"id":"s01-ccss-2-3"},{"fase":"construir","areas":["ccss","mat"],"cnb":["ccss:1.2.1"],"ambito":"hacer","title":"Ejemplo resuelto: estimar la temperatura","prompt":"Supongamos que usamos la regla aproximada: **la temperatura baja 6 °C por cada 1,000 m que subes**.","type":"worked-example","props":{"icon":"Thermometer","problem":"En una playa del Pacífico (nivel del mar) hace **30 °C**. ¿Qué temperatura aproximada habría a la misma hora en un pueblo a **2,000 m** de altitud?","steps":[{"text":"Calculo cuántos \\"miles de metros\\" subo: 2,000 ÷ 1,000 = **2**."},{"text":"Cada 1,000 m baja 6 °C, así que baja 2 × 6 = **12 °C**.","why":"Es una regla de promedio: el valor real cambia con el viento, las nubes y la hora."},{"text":"Resto: 30 − 12 = **18 °C**."}],"answer":"Arriba haría aproximadamente **18 °C**: fresco, aunque en la playa haga calor.","tip":"Por eso las personas de tierra fría cultivan papa y trigo, y en la costa se cultiva caña de azúcar."},"id":"s01-ccss-2-4"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:1.2.1"],"prompt":"Une cada lugar con su **piso térmico** según su altitud aproximada.","hint":"Recuerda: menos de 1,000 m es cálido; entre 1,000 y 2,000 m, templado; más de 2,000 m, frío.","explain":"La altitud explica por qué en un país pequeño como Guatemala hay climas tan distintos.","type":"match","props":{"leftTitle":"Lugar","rightTitle":"Piso térmico","pairs":[{"id":"fl","left":"Flores, Petén (unos 130 m)","leftIcon":"TreePine","right":"Tierra cálida"},{"id":"gc","left":"Ciudad de Guatemala (unos 1,500 m)","leftIcon":"Building2","right":"Tierra templada"},{"id":"xe","left":"Quetzaltenango (unos 2,330 m)","leftIcon":"MountainSnow","right":"Tierra fría"}]},"id":"s01-ccss-2-5"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:2.2.1","ccss:2.1.1","ccss:2.3.1"],"ambito":"conocer","title":"Del clima a los recursos y al desarrollo","prompt":"Compara ecosistemas y recursos naturales de América con otros continentes, y distingue esos recursos del nivel de desarrollo. Toca cada tarjeta.","type":"explain","props":{"icon":"Trees","body":"Clima, suelo y agua influyen en los ecosistemas y recursos disponibles. Sin embargo, **tener recursos no garantiza desarrollo**: tambien importan educación, salud, tecnología, instituciones, distribución y conservación.","reveal":[{"icon":"Trees","front":"América","back":"Amazonía y otros bosques, grandes ríos, suelos agrícolas, pesca y minerales como cobre. Hay países con niveles de desarrollo diferentes."},{"icon":"Sun","front":"África","back":"Sabanas, cuenca del Congo, minerales y zonas petroleras. Sus países también presentan condiciones sociales y económicas diversas."},{"icon":"Wheat","front":"Asia y Europa","back":"Asia reúne arrozales, bosques, minerales y petróleo; Europa cuenta con suelos agrícolas y bosques, y compra recursos que no posee en cantidad suficiente."},{"icon":"Mountain","front":"Oceanía","back":"Australia posee minerales y zonas ganaderas; las islas del Pacífico dependen mucho de recursos marinos. Un continente no tiene una sola realidad."}]},"id":"s01-ccss-2-6"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:2.2.1","ccss:2.1.1","ccss:2.3.1"],"prompt":"Con ayuda, relaciona ecosistema o recurso de América y otros continentes con una comparación cuidadosa del desarrollo.","hint":"Distingue lo que ofrece la naturaleza de las decisiones sociales sobre su uso.","explain":"Los recursos varían por clima y geografía; el desarrollo depende además de cómo se transforman, distribuyen y conservan.","type":"match","props":{"leftTitle":"Evidencia","rightTitle":"Relación","pairs":[{"id":"se","left":"Selvas y grandes ríos en América y África","leftIcon":"Trees","right":"Climas parecidos pueden sostener recursos semejantes"},{"id":"mi","left":"Cobre americano y minerales australianos","leftIcon":"Pickaxe","right":"Continentes distintos aportan minerales al intercambio"},{"id":"de","left":"País con muchos recursos y servicios insuficientes","leftIcon":"Scale","right":"Los recursos por sí solos no garantizan desarrollo"}]},"id":"s01-ccss-2-7"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:1.2.1","ccss:2.2.1","ccss:2.1.1","ccss:2.3.1"],"ambito":"hacer","prompt":"Aplicación independiente. América tiene bosques, agua, suelos y minerales; Asia, África, Europa y Oceanía poseen combinaciones distintas. ¿Qué explicación relaciona clima, recursos y nivel de desarrollo sin confundirlos?","type":"choice","props":{"options":[{"id":"a","text":"El clima influye en ecosistemas y recursos, pero educación, salud, tecnología, distribución y conservación también influyen en el desarrollo"},{"id":"b","text":"El continente con más minerales es automáticamente el más desarrollado"},{"id":"c","text":"Todos los continentes poseen exactamente los mismos recursos"}],"correct":["a"]},"id":"s01-ccss-2-8"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:1.2.1","ccss:2.2.1","ccss:2.1.1","ccss:2.3.1"],"prompt":"Salida: compara clima, ecosistemas, recursos de América y otros continentes, y su relación con el desarrollo.","type":"true-false","props":{"statements":[{"text":"América y África pueden compartir selvas tropicales porque algunas regiones tienen climas parecidos.","answer":true},{"text":"La cantidad de recursos naturales determina por sí sola el nivel de desarrollo de un continente.","answer":false},{"text":"Educación, salud, tecnología, distribución y conservación también influyen en el desarrollo.","answer":true}]},"id":"s01-ccss-2-9"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:1.2.1","ccss:2.2.1","ccss:2.1.1","ccss:2.3.1"],"prompt":"Salida nueva. América tiene agua y cobre; otra región posee petróleo y arrozales. ¿Qué conclusión compara recursos continentales y niveles de desarrollo con cuidado?","type":"choice","props":{"options":[{"id":"a","text":"Los recursos difieren, y su aprovechamiento, distribución y conservación se relacionan con el desarrollo sin garantizarlo"},{"id":"b","text":"Un solo recurso permite conocer toda la calidad de vida de un continente"},{"id":"c","text":"Los ecosistemas y el clima no se relacionan con ningún recurso"}],"correct":["a"]},"id":"s01-ccss-2-10"}],"kind":"materia","area":"ccss","day":3}},{"missionId":"s01","version":"cnb-sexto-ca5de0ee39569fef","lesson":{"id":"s01-pyd-1","title":"Necesidades y perfiles para emprender","icon":"BriefcaseBusiness","minutes":15,"gancho":"Un mapa muestra que varias familias recorren lejos para comprar alimentos frescos. ¿Basta con tener una idea o también importa quién puede llevarla adelante?","objetivos":["Relacionar una necesidad de desarrollo con el perfil emprendedor requerido para una respuesta productiva"],"resumen":["El desarrollo mejora condiciones como alimentación, salud, educación, agua, ambiente y trabajo digno para toda la población.","Un perfil emprendedor reúne saberes, habilidades y actitudes pertinentes para implementar una actividad productiva.","Una respuesta responsable parte de evidencia sobre una necesidad y selecciona un perfil capaz de organizar recursos."],"media":{"id":"s01-pyd-1-necesidad-perfil","kind":"diagram","title":"De la necesidad al perfil","aspect":"16:9","alt":"Mapa didáctico con un mercado lejano y una tabla que organiza saberes, habilidades y actitudes para una respuesta productiva.","brief":"Diagrama horizontal 1600×900. A la izquierda, mapa ficticio rotulado CASO SIMULADO con viviendas, camino y mercado distante; a la derecha, tres columnas: SABERES, HABILIDADES y ACTITUDES. Incluir iconos descriptivos de libro, herramientas y manos colaborando. Sin respuestas completas, texto grande, contraste alto y patrones además de color."},"steps":[{"fase":"explorar","areas":["pyd"],"cnb":["pyd:1.1.1"],"title":"Necesidades y desarrollo","prompt":"El desarrollo se observa en condiciones de vida compartidas, no en la riqueza de unas pocas personas.","type":"explain","props":{"icon":"TrendingUp","body":"Alimentación, salud, educación, agua y saneamiento, vivienda, ambiente sano y trabajo digno son elementos relacionados. La pobreza aparece cuando varias necesidades básicas no pueden cubrirse; no es culpa de las personas."},"id":"s01-pyd-1-1"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:1.1.1"],"prompt":"Lee el caso simulado y reconoce la necesidad respaldada por datos.","hint":"Distingue el dato de una suposición.","explain":"Los datos describen una necesidad de acceso e ingresos; no explican por sí solos todas sus causas.","type":"reading","props":{"genre":"Caso simulado","heading":"Aldea El Encuentro","passage":"En un registro didáctico de 30 familias, 18 recorren más de una hora para comprar hortalizas y 12 reportan ingresos inestables. Ocho personas saben cultivar y cuatro conocen ventas en el mercado. No se ha medido la disponibilidad de tierra ni de agua.","questions":[{"q":"¿Qué necesidad está respaldada?","options":[{"id":"a","text":"Acceso cercano a alimentos frescos e ingresos más estables"},{"id":"b","text":"Construir un aeropuerto"},{"id":"c","text":"Afirmar que todas las familias poseen terreno"}],"correct":"a"}]},"id":"s01-pyd-1-2"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:1.2.1"],"title":"Perfil emprendedor","prompt":"Para implementar una respuesta productiva se determina qué perfil emprendedor hace falta.","type":"explain","props":{"icon":"UserRoundCog","body":"El perfil combina **saberes** (qué conoce), **habilidades** (qué sabe hacer) y **actitudes** (cómo trabaja). Debe corresponder a la necesidad y a los recursos comprobados.","reveal":[{"icon":"Brain","front":"Saberes","back":"Conocer cultivo, costos, higiene o necesidades de clientes."},{"icon":"Wrench","front":"Habilidades","back":"Sembrar, calcular, registrar, comunicar y organizar tareas."},{"icon":"Handshake","front":"Actitudes","back":"Responsabilidad, honestidad, perseverancia y cooperación."}]},"id":"s01-pyd-1-3"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:1.1.1","pyd:1.2.1"],"title":"Modelo: necesidad y perfil","prompt":"Observa cómo la evidencia orienta el perfil emprendedor de un proyecto productivo.","type":"worked-example","props":{"icon":"ListChecks","problem":"El caso muestra dificultad para conseguir hortalizas y personas con saberes de cultivo.","steps":[{"text":"Necesidad respaldada: acceso cercano a hortalizas e ingresos más estables."},{"text":"Respuesta posible: venta semanal de hortalizas, sujeta a comprobar recursos."},{"text":"Saberes: cultivo y precios; habilidades: sembrar y vender; actitudes: responsabilidad y cooperación."},{"text":"Dato pendiente: disponibilidad de tierra, agua y demanda."}],"answer":"El perfil se elige por la necesidad y las tareas reales del proyecto, no por estereotipos."},"id":"s01-pyd-1-4"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:1.2.1"],"prompt":"Clasifica el perfil emprendedor para responder a la necesidad del caso con un proyecto productivo.","hint":"Conocer es saber; una habilidad se demuestra al hacer; una actitud orienta la conducta.","explain":"Un perfil útil combina las tres dimensiones.","type":"sort","props":{"buckets":[{"id":"s","label":"Saberes","icon":"Brain"},{"id":"h","label":"Habilidades","icon":"Wrench"},{"id":"a","label":"Actitudes","icon":"Handshake"}],"items":[{"id":"1","text":"Conocer épocas de siembra","bucket":"s"},{"id":"2","text":"Calcular costos","bucket":"h"},{"id":"3","text":"Cumplir turnos acordados","bucket":"a"},{"id":"4","text":"Conocer normas de higiene","bucket":"s"}]},"id":"s01-pyd-1-5"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:1.1.1"],"prompt":"¿Qué conclusión usa los datos sin culpar a las familias?","hint":"Describe condiciones y límites.","explain":"La necesidad se analiza con evidencia y causas posibles, no como defecto personal.","type":"choice","props":{"options":[{"id":"a","text":"Hay barreras de acceso e ingresos; faltan datos de recursos antes de decidir"},{"id":"b","text":"Las familias son pobres porque no se esfuerzan"},{"id":"c","text":"Todas tienen tierra y agua disponibles"}],"correct":["a"]},"id":"s01-pyd-1-6"},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:1.1.1","pyd:1.2.1"],"prompt":"Relaciona cada necesidad de desarrollo con el perfil emprendedor pertinente para una respuesta productiva.","type":"match","props":{"pairs":[{"id":"a","left":"Alimentos frescos lejanos","right":"Saber cultivar, organizar entregas y trabajar con responsabilidad"},{"id":"b","left":"Bicicletas sin reparación cercana","right":"Conocer mecanismos, usar herramientas y atender con honestidad"},{"id":"c","left":"Fruta de temporada se desperdicia","right":"Conocer conservación, calcular costos y cooperar en higiene"}]},"id":"s01-pyd-1-7"},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:1.1.1","pyd:1.2.1"],"prompt":"Un caso simulado muestra poco acceso a reparación de bicicletas. ¿Qué proyecto y perfil emprendedor responden mejor a esa necesidad de desarrollo?","type":"choice","props":{"options":[{"id":"a","text":"Taller básico: saber mecánica, reparar con seguridad y cumplir acuerdos"},{"id":"b","text":"Venta de adornos: saber colores y no revisar la necesidad"},{"id":"c","text":"Prometer una fábrica sin recursos ni habilidades"}],"correct":["a"]},"id":"s01-pyd-1-8"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:1.1.1","pyd:1.2.1"],"prompt":"Una población necesita empleo digno y tiene demanda de pan. ¿Qué opción relaciona la necesidad con un perfil emprendedor completo para un proyecto productivo?","type":"choice","props":{"options":[{"id":"a","text":"Conocer recetas y costos, saber hornear y vender, actuar con higiene y responsabilidad"},{"id":"b","text":"Tener entusiasmo sin saberes ni habilidades"},{"id":"c","text":"Culpar a las familias por sus ingresos"}],"correct":["a"]},"id":"s01-pyd-1-9"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:1.1.1","pyd:1.2.1"],"prompt":"Comprueba qué elementos pertenecen al perfil emprendedor de un proyecto productivo que atiende una necesidad de desarrollo.","type":"sort","props":{"buckets":[{"id":"perfil","label":"Perfil pertinente"},{"id":"no","label":"No demuestra pertinencia"}],"items":[{"id":"a","text":"Saber relacionado con el producto","bucket":"perfil"},{"id":"b","text":"Habilidad para una tarea necesaria","bucket":"perfil"},{"id":"c","text":"Actitud responsable y cooperativa","bucket":"perfil"},{"id":"d","text":"Promesa sin datos ni recursos","bucket":"no"}]},"id":"s01-pyd-1-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["pyd"],"cnb":["pyd:1.1.1","pyd:1.2.1"],"type":"reflection","props":{"statements":["Relacioné una necesidad respaldada con saberes, habilidades y actitudes pertinentes"],"commitments":["Revisaré qué datos faltan antes de proponer un proyecto"]},"id":"s01-pyd-1-11"}],"kind":"materia","area":"pyd","day":3}},{"missionId":"s01","version":"cnb-sexto-e34e49fbad3b17ce","lesson":{"id":"s01-ccss-3","title":"Fenómenos naturales: conocer para prevenir","icon":"CloudRain","minutes":15,"gancho":"En Guatemala tiembla con frecuencia y cada año llegan lluvias fuertes. ¿Por qué nos pasa tan seguido? ¿Qué podemos hacer para estar a salvo?","objetivos":["Describir terremotos, erupciones, huracanes y depresiones tropicales","Distinguir entre fenómeno natural, amenaza, vulnerabilidad y desastre","Reconocer los riesgos de vivir en zonas vulnerables y cómo prevenirlos"],"resumen":["Los fenómenos geológicos nacen dentro de la Tierra: terremotos, erupciones volcánicas y tsunamis. Los hidrometeorológicos nacen en la atmósfera y el agua: huracanes, depresiones y tormentas tropicales, inundaciones y sequías.","Guatemala está donde se juntan tres placas tectónicas (Norteamérica, Caribe y Cocos) y entre dos océanos: por eso tiene temblores, volcanes activos y temporales de lluvia.","Un fenómeno natural se vuelve desastre cuando encuentra a una población vulnerable: casas en laderas, orillas de ríos, construcciones débiles o falta de preparación.","Prevenir salva vidas: plan familiar de emergencia, mochila de emergencia, rutas de evacuación y seguir las indicaciones de la CONRED."],"media":{"id":"s01-ccss-3-placas","kind":"animation","title":"¿Por qué tiembla en Guatemala?","aspect":"16:9","duration":50,"alt":"Mapa de Centroamérica con tres placas tectónicas de colores que se empujan; aparecen los volcanes de la cadena volcánica y la falla del Motagua.","brief":"Animación 2D de 50 s. Mapa de Centroamérica visto desde arriba. Tres placas con colores suaves y rotuladas: Placa de Norteamérica, Placa del Caribe y Placa de Cocos. Flechas muestran que la placa de Cocos se mete debajo de la del Caribe frente a la costa del Pacífico; aparecen triángulos de volcanes a lo largo del altiplano. Luego se resalta la falla del Motagua entre Norteamérica y Caribe. Un sismógrafo dibuja una línea que tiembla. Narración en español: \\"Guatemala está donde se juntan tres placas: por eso tenemos temblores y volcanes.\\" Sin escenas de destrucción ni personas heridas. Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:1.3.1"],"ambito":"conocer","title":"Fenómenos que nacen dentro de la Tierra","prompt":"La capa exterior de la Tierra está partida en enormes piezas llamadas **placas tectónicas**, que se mueven muy despacio. Cuando chocan o se rozan, liberan energía. Toca cada tarjeta.","type":"explain","props":{"icon":"Mountain","body":"Guatemala está donde se juntan **tres placas**: Norteamérica, Caribe y Cocos. También forma parte del **Cinturón de Fuego del Pacífico**, una franja con muchos volcanes y sismos alrededor del océano Pacífico.","reveal":[{"icon":"Activity","front":"Terremoto o sismo","back":"Movimiento brusco del suelo cuando las placas liberan energía. El 4 de febrero de **1976** un fuerte terremoto, originado en la **falla del Motagua**, causó grandes daños en Guatemala."},{"icon":"Flame","front":"Erupción volcánica","back":"Salida de lava, ceniza y gases por un volcán. En Guatemala hay volcanes activos como el de **Fuego**, el **Pacaya** y el **Santiaguito**."},{"icon":"Waves","front":"Tsunami","back":"Olas gigantes causadas por un terremoto bajo el mar. En 2004, un tsunami en el océano Índico afectó a varios países de Asia."}]},"id":"s01-ccss-3-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:1.3.1"],"ambito":"conocer","title":"Fenómenos del agua y el aire","prompt":"Sobre los mares cálidos se forman **ciclones tropicales**: grandes remolinos de nubes, viento y lluvia. Se nombran según la **fuerza de sus vientos**. Toca cada tarjeta.","media":{"id":"s01-ccss-3-ciclon","kind":"animation","title":"De depresión a huracán","aspect":"16:9","duration":40,"alt":"Vista satelital animada de un remolino de nubes sobre el mar que crece y gira más rápido; la etiqueta cambia de depresión tropical a tormenta tropical y a huracán.","brief":"Animación 2D estilo imagen de satélite, 40 s. Sobre un mar azul cálido se forma un remolino de nubes. Un velocímetro en la esquina muestra la velocidad del viento. Etiquetas que cambian: \\"Depresión tropical: vientos de menos de 63 km/h\\", \\"Tormenta tropical: de 63 a 118 km/h\\", \\"Huracán: 119 km/h o más\\" (en este momento se ve el ojo del huracán). Al final, el remolino toca tierra y se debilita. Narración en español con subtítulos. Sin imágenes de daños."},"type":"explain","props":{"icon":"CloudRain","body":"No solo el viento es peligroso: la **lluvia de muchos días** provoca **inundaciones** y **deslizamientos** de tierra en laderas.","reveal":[{"icon":"Cloud","front":"Depresión tropical","back":"La etapa más débil (vientos de **menos de 63 km/h**), pero puede traer lluvia durante días."},{"icon":"CloudRain","front":"Tormenta tropical","back":"Vientos de **63 a 118 km/h**. Desde esta etapa recibe un nombre propio. La tormenta tropical **Agatha** (2010) causó graves inundaciones y deslaves en Guatemala."},{"icon":"Wind","front":"Huracán","back":"Vientos de **119 km/h o más**. En 1998, el huracán **Mitch** causó enormes inundaciones en Centroamérica."},{"icon":"Sun","front":"Sequía","back":"Falta de lluvia por mucho tiempo. Afecta las cosechas; en Guatemala ocurre con más frecuencia en el llamado **Corredor Seco**."}]},"id":"s01-ccss-3-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:1.3.1"],"ambito":"conocer","prompt":"Usa lo aprendido para clasificar: ¿este fenómeno viene **de dentro de la Tierra** o **del agua y el aire**?","explain":"Los fenómenos **geológicos** nacen dentro de la Tierra; los **hidrometeorológicos** se relacionan con el agua y el aire.","type":"sort","props":{"buckets":[{"id":"geo","label":"De dentro de la Tierra","icon":"Mountain","color":"var(--c-maiz-strong)"},{"id":"hid","label":"Del agua y el aire","icon":"CloudRain","color":"var(--area-ccss)"}],"items":[{"id":"f1","text":"Terremoto","bucket":"geo"},{"id":"f2","text":"Huracán","bucket":"hid"},{"id":"f3","text":"Erupción volcánica","bucket":"geo"},{"id":"f4","text":"Depresión tropical","bucket":"hid"},{"id":"f5","text":"Sequía","bucket":"hid"}]},"id":"s01-ccss-3-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:1.3.1"],"prompt":"Une cada fenómeno natural con su descripción.","hint":"Fíjate en la fuerza del viento para los ciclones: menos de 63 km/h, de 63 a 118 km/h o 119 km/h y más. El terremoto viene de las placas.","explain":"Los ciclones tropicales se nombran por la fuerza de su viento; el terremoto nace del movimiento de las placas tectónicas.","type":"match","props":{"leftTitle":"Fenómeno","rightTitle":"Descripción","pairs":[{"id":"dt","left":"Depresión tropical","leftIcon":"Cloud","right":"Remolino con vientos de menos de 63 km/h y lluvia de varios días"},{"id":"tt","left":"Tormenta tropical","leftIcon":"CloudRain","right":"Vientos de 63 a 118 km/h; desde aquí recibe nombre propio"},{"id":"hu","left":"Huracán","leftIcon":"Wind","right":"Vientos de 119 km/h o más, con un \\"ojo\\" en el centro"},{"id":"te","left":"Terremoto","leftIcon":"Activity","right":"Movimiento brusco del suelo cuando las placas liberan energía"}]},"id":"s01-ccss-3-4"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:1.3.1"],"ambito":"conocer","title":"Fenómeno no es lo mismo que desastre","prompt":"Un temblor en un desierto vacío no hace daño a nadie. El mismo temblor en una ciudad con casas débiles puede ser un **desastre**. La diferencia está en la **vulnerabilidad**. Toca cada tarjeta.","type":"explain","props":{"icon":"ShieldCheck","body":"No podemos evitar los fenómenos naturales, pero **sí podemos reducir la vulnerabilidad**. Eso se llama **prevención**.","reveal":[{"icon":"Zap","front":"Amenaza","back":"El fenómeno que **podría** ocurrir: un sismo, una crecida del río, una erupción."},{"icon":"Home","front":"Vulnerabilidad","back":"Lo que hace que una población salga más dañada: vivir en **laderas inestables** o a la **orilla de ríos**, casas mal construidas, no tener plan de emergencia."},{"icon":"TriangleAlert","front":"Riesgo","back":"La posibilidad de sufrir daño. **Más amenaza y más vulnerabilidad = más riesgo.**"},{"icon":"Shield","front":"Prevención","back":"Plan familiar, **mochila de emergencia**, rutas de evacuación, no construir en zonas peligrosas y atender los avisos de la **CONRED** (Coordinadora Nacional para la Reducción de Desastres)."}]},"id":"s01-ccss-3-5"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:1.3.1"],"prompt":"Clasifica cada situación: ¿**aumenta** la vulnerabilidad o la **reduce**?","hint":"Pregúntate: si llega un sismo o un temporal, ¿esta situación protege a la familia o la pone en peligro?","explain":"La vulnerabilidad se reduce con buenas decisiones: dónde y cómo construir, y estar preparados.","type":"sort","props":{"buckets":[{"id":"mas","label":"Aumenta la vulnerabilidad","icon":"TriangleAlert","color":"var(--c-bad)"},{"id":"menos","label":"Reduce la vulnerabilidad","icon":"ShieldCheck","color":"var(--c-ok)"}],"items":[{"id":"v1","text":"Construir una casa a la orilla de un río que se desborda","bucket":"mas"},{"id":"v2","text":"Tener una mochila de emergencia lista","bucket":"menos"},{"id":"v3","text":"Practicar simulacros de sismo en la escuela","bucket":"menos"},{"id":"v4","text":"Cortar los árboles de una ladera donde hay casas","bucket":"mas","feedback":"Las raíces sostienen el suelo. Sin árboles, la lluvia provoca deslizamientos."},{"id":"v5","text":"Tirar basura en los tragantes de la calle","bucket":"mas","feedback":"Los tragantes tapados hacen que el agua de lluvia inunde las calles."},{"id":"v6","text":"Acordar en familia un punto de reunión","bucket":"menos"}]},"id":"s01-ccss-3-6"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:1.3.1"],"ambito":"hacer","prompt":"Está temblando fuerte y estás en el aula. Ordena lo que debes hacer.","explain":"Durante el sismo: **agáchate, cúbrete y sujétate** lejos de ventanas. Cuando pare, sal con calma por la ruta de evacuación, sin correr, y espera en el punto de reunión.","type":"order","props":{"items":[{"id":"o1","text":"Mantener la calma y alejarte de ventanas y objetos que puedan caer"},{"id":"o2","text":"Agacharte, cubrirte la cabeza y sujetarte (por ejemplo, bajo un escritorio firme)"},{"id":"o3","text":"Cuando deje de temblar, salir en orden por la ruta de evacuación, sin correr"},{"id":"o4","text":"Esperar en el punto de reunión y seguir las indicaciones de tu maestra o maestro"}],"labels":{"start":"Primero","end":"Al final"}},"id":"s01-ccss-3-7"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:1.3.1"],"ambito":"conocer","prompt":"Escuchas en la radio: _\\"Una depresión tropical se acerca a la costa del Pacífico; se espera lluvia fuerte durante tres días.\\"_ ¿Qué familia está en **mayor riesgo**?","explain":"Una depresión tropical tiene vientos débiles, pero su **lluvia prolongada** hace crecer los ríos y afloja las laderas. Las familias en esas zonas deben estar atentas a la evacuación.","type":"choice","props":{"options":[{"id":"a","text":"Una familia cuya casa está a la orilla de un río, al pie de un cerro","icon":"Home"},{"id":"b","text":"Una familia con casa firme en terreno plano, lejos de ríos","icon":"ShieldCheck","feedback":"Esa familia también debe estar atenta, pero su vulnerabilidad es mucho menor."},{"id":"c","text":"Nadie: una depresión es muy débil y no causa daños","icon":"X","feedback":"Sus vientos son débiles, pero la lluvia de varios días puede causar inundaciones y deslaves."}],"correct":["a"]},"id":"s01-ccss-3-8"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:1.3.1"],"prompt":"¿Por qué en Guatemala hay tantos temblores y volcanes?","type":"choice","props":{"options":[{"id":"a","text":"Porque está donde se juntan tres placas tectónicas"},{"id":"b","text":"Porque está en la zona tropical y hace calor"},{"id":"c","text":"Porque llueve mucho en la época lluviosa"}],"correct":["a"]},"id":"s01-ccss-3-9"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:1.3.1"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Un huracán tiene vientos más fuertes que una depresión tropical.","answer":true},{"text":"Vivir en una ladera sin árboles reduce el riesgo de deslizamientos.","answer":false,"why":"Sin raíces que sostengan el suelo, la lluvia provoca más deslizamientos."},{"text":"Un fenómeno natural se vuelve desastre cuando afecta a una población vulnerable.","answer":true}]},"id":"s01-ccss-3-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["ccss"],"cnb":[],"type":"reflection","props":{"statements":["Ubico lugares con latitud y longitud","Explico por qué la altitud cambia el clima","Sé qué hacer para reducir el riesgo ante un fenómeno natural"],"commitments":["Revisaré con mi familia si tenemos un punto de reunión y una mochila de emergencia","Buscaré en un mapa las coordenadas aproximadas de mi municipio"]},"id":"s01-ccss-3-11"}],"kind":"materia","area":"ccss","day":4}},{"missionId":"s01","version":"cnb-sexto-b150f2a7f98c7b40","lesson":{"id":"s01-art-2","title":"El pentagrama y las siete notas","icon":"Music2","minutes":15,"gancho":"La marimba tiene teclas grandes a un lado y pequeñitas al otro. ¿Por qué crees que suenan distinto, y cómo se escribe si una nota es grave o aguda?","objetivos":["Distinguir sonidos graves y agudos y ordenar las siete notas musicales","Reconocer las líneas y los espacios del pentagrama","Leer las notas en clave de sol"],"resumen":["Las siete notas musicales son Do, Re, Mi, Fa, Sol, La y Si. Después de Si vuelve Do, pero más agudo: esa distancia se llama octava.","El pentagrama tiene 5 líneas y 4 espacios que se cuentan de abajo hacia arriba. Mientras más arriba está una nota, más aguda suena.","La clave de sol se enrolla en la 2.ª línea e indica que ahí está la nota Sol.","En clave de sol, las líneas son Mi, Sol, Si, Re, Fa y los espacios Fa, La, Do, Mi. El Do grave se escribe en una línea adicional debajo del pentagrama."],"media":{"id":"s01-art-2-escala","kind":"video","title":"La escala de Do en la marimba","aspect":"16:9","duration":45,"alt":"Unas baquetas tocan en una marimba ocho teclas seguidas, de la más grande a la más pequeña, mientras en un pentagrama se ilumina cada nota de Do a Do.","brief":"Video de 45 s. Pantalla dividida: arriba, plano cenital de una marimba de madera (sin marcas) donde unas baquetas tocan Do, Re, Mi, Fa, Sol, La, Si, Do (una nota por segundo) de la tecla larga a la corta; abajo, un pentagrama en clave de sol donde cada nota se ilumina al sonar, con su nombre debajo. Luego la escala descendente. Cierre: rótulo \\"Más arriba en el pentagrama = más agudo\\". Narración breve en español, subtítulos."},"steps":[{"fase":"explorar","areas":["art"],"cnb":["art:1.1.1"],"ambito":"conocer","title":"Las siete notas","prompt":"Para nombrar la altura de los sonidos usamos **siete notas**. Se cantan en orden, de la más grave a la más aguda.","type":"explain","props":{"icon":"Music","body":"**Do · Re · Mi · Fa · Sol · La · Si** … y otra vez **Do**, pero más agudo. Ese nuevo Do está a una **octava** del primero (ocho notas contando las dos puntas). Esta serie ordenada se llama **escala de Do**.","reveal":[{"icon":"ArrowUpRight","front":"Escala ascendente","back":"Do, Re, Mi, Fa, Sol, La, Si, Do: cada nota es **un poco más aguda** que la anterior."},{"icon":"Repeat","front":"La octava","back":"El Do agudo \\"se parece\\" al Do grave: suenan como la misma nota en una voz más delgada. Por eso la escala vuelve a empezar."},{"icon":"Piano","front":"En los instrumentos","back":"En la marimba y el piano, hacia la **derecha** las notas se vuelven más agudas (teclas más cortas o más a la derecha)."}]},"id":"s01-art-2-1"},{"fase":"construir","areas":["art"],"cnb":["art:1.1.1"],"ambito":"conocer","prompt":"Antes de leer notas, entrena tu oído. Clasifica cada sonido como **grave** (grueso) o **agudo** (delgado).","explain":"La **altura** del sonido es lo que dice si es grave o agudo. En el pentagrama, los agudos se escriben arriba y los graves abajo.","type":"sort","props":{"buckets":[{"id":"g","label":"Grave","icon":"ArrowDown","color":"var(--area-art)"},{"id":"a","label":"Agudo","icon":"ArrowUp","color":"var(--c-maiz-strong)"}],"items":[{"id":"x1","text":"El tun (tambor de madera) grande","icon":"Drum","bucket":"g"},{"id":"x2","text":"El canto de un canario","icon":"Bird","bucket":"a"},{"id":"x3","text":"Las teclas más largas de la marimba","bucket":"g","feedback":"Las teclas largas vibran más lento y suenan más graves."},{"id":"x4","text":"Un silbato","bucket":"a"},{"id":"x5","text":"El trueno a lo lejos","icon":"CloudRain","bucket":"g"},{"id":"x6","text":"Las teclas más cortas de la marimba","bucket":"a"}]},"id":"s01-art-2-2"},{"fase":"construir","areas":["art"],"cnb":["art:1.1.1"],"ambito":"conocer","prompt":"Ordena las notas de la escala, de la **más grave** a la **más aguda**.","hint":"Canta despacio \\"Do, Re, Mi…\\" hasta llegar al Do agudo.","type":"order","props":{"items":[{"id":"do","text":"Do"},{"id":"re","text":"Re"},{"id":"mi","text":"Mi"},{"id":"fa","text":"Fa"},{"id":"sol","text":"Sol"},{"id":"la","text":"La"},{"id":"si","text":"Si"},{"id":"do2","text":"Do (agudo)"}],"labels":{"start":"Más grave","end":"Más aguda"}},"id":"s01-art-2-3"},{"fase":"construir","areas":["art"],"cnb":["art:1.1.1"],"ambito":"conocer","title":"El pentagrama y la clave de sol","prompt":"Las notas se escriben sobre el **pentagrama**: cinco líneas horizontales con cuatro espacios entre ellas.","media":{"id":"s01-art-2-pentagrama","kind":"diagram","title":"Las notas en clave de sol","aspect":"16:9","alt":"Pentagrama con la clave de sol al inicio. Las líneas están numeradas del 1 al 5 de abajo hacia arriba y los espacios del 1 al 4. Sobre él, las notas de Do grave a Do agudo con su nombre debajo.","brief":"Diagrama horizontal sobre fondo blanco. Pentagrama grande con clave de sol dibujada con claridad: su espiral termina rodeando la 2.ª línea, marcada en color. A la izquierda, números 1-5 junto a las líneas (de abajo hacia arriba) y 1-4 en los espacios, en gris. Sobre el pentagrama, 8 negras en escalera: Do (con línea adicional debajo), Re (bajo la 1.ª línea), Mi (1.ª línea), Fa (1.er espacio), Sol (2.ª línea, resaltada), La (2.º espacio), Si (3.ª línea), Do (3.er espacio). Nombre debajo de cada nota. Flecha a la derecha \\"más agudo ↑\\". Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"type":"explain","props":{"icon":"Music2","body":"Las líneas y los espacios se cuentan **de abajo hacia arriba**. Una nota puede ir **en una línea** (la línea la cruza por la mitad) o **en un espacio** (entre dos líneas). **Mientras más arriba, más aguda.**","reveal":[{"icon":"AlignJustify","front":"5 líneas y 4 espacios","back":"La 1.ª línea es la de abajo. El 1.er espacio está entre la 1.ª y la 2.ª línea."},{"icon":"Music","front":"La clave de sol","back":"Es el símbolo del inicio. Su espiral se enrolla en la **2.ª línea**: ahí está la nota **Sol**. A partir de Sol se leen las demás."},{"icon":"Minus","front":"Líneas adicionales","back":"Para notas más graves o más agudas se dibujan rayitas cortas fuera del pentagrama. El **Do grave** va en una línea adicional **debajo**."}]},"id":"s01-art-2-4"},{"fase":"construir","areas":["art"],"cnb":["art:1.1.1"],"ambito":"hacer","title":"Ejemplo resuelto: leer notas desde Sol","prompt":"Si sabes dónde está Sol, puedes encontrar cualquier nota subiendo o bajando **un escalón** (de línea a espacio o de espacio a línea).","type":"worked-example","props":{"icon":"Search","problem":"Una nota está en la **3.ª línea** y otra en el **1.er espacio**. ¿Qué notas son?","steps":[{"text":"Parto de la clave de sol: la **2.ª línea es Sol**."},{"text":"Subo un escalón: el **2.º espacio es La**. Subo otro: la **3.ª línea es Si**.","why":"Cada escalón (línea → espacio → línea) es la nota siguiente de la escala."},{"text":"Ahora bajo desde Sol: un escalón abajo está el **1.er espacio**, que es **Fa**.","why":"Al bajar, las notas van hacia atrás: Sol, Fa, Mi…"}],"answer":"La nota de la 3.ª línea es **Si** y la del 1.er espacio es **Fa**.","tip":"Truco para memorizar: líneas = **Mi, Sol, Si, Re, Fa**; espacios = **Fa, La, Do, Mi**."},"id":"s01-art-2-5"},{"fase":"construir","areas":["art"],"cnb":["art:1.1.1"],"ambito":"conocer","prompt":"Completa con el nombre de la nota (clave de sol).","hint":"Empieza en Sol (2.ª línea) y sube o baja un escalón a la vez.","explain":"Líneas de abajo arriba: Mi, Sol, Si, Re, Fa. Espacios: Fa, La, Do, Mi.","type":"fill-blank","props":{"text":"La 1.ª línea es [[Mi]]. La 2.ª línea es [[Sol]]. El 2.º espacio es [[La]]. El 3.er espacio es [[Do]].","distractors":["Re","Si"]},"id":"s01-art-2-6"},{"fase":"aplicar","areas":["art"],"cnb":["art:1.1.1"],"ambito":"hacer","prompt":"Une cada lugar del pentagrama (clave de sol) con su nota.","explain":"3.ª línea = Si, 4.ª línea = Re, 5.ª línea = Fa, 4.º espacio = Mi, línea adicional abajo = Do.","type":"match","props":{"leftTitle":"Lugar","rightTitle":"Nota","pairs":[{"id":"l3","left":"3.ª línea","right":"Si"},{"id":"l4","left":"4.ª línea","right":"Re"},{"id":"l5","left":"5.ª línea","right":"Fa"},{"id":"e4","left":"4.º espacio","right":"Mi"},{"id":"ad","left":"Línea adicional debajo","right":"Do"}]},"id":"s01-art-2-7"},{"fase":"aplicar","areas":["art"],"cnb":["art:1.1.1"],"ambito":"conocer","prompt":"Una melodía empieza en la **1.ª línea** y termina en el **4.º espacio**. ¿Qué pasa con el sonido?","explain":"Terminar más arriba en el pentagrama significa que el sonido se vuelve **más agudo**.","type":"choice","props":{"options":[{"id":"a","text":"Se vuelve más agudo","icon":"ArrowUp"},{"id":"b","text":"Se vuelve más grave","icon":"ArrowDown","feedback":"En el pentagrama, subir es ir hacia lo agudo."},{"id":"c","text":"Se vuelve más fuerte","icon":"Volume2","feedback":"La posición en el pentagrama indica altura, no intensidad."}],"correct":["a"]},"id":"s01-art-2-8"},{"fase":"aplicar","areas":["art"],"cnb":["art:1.1.1"],"ambito":"hacer","prompt":"**En casa:** arma un **pentagrama de mesa** para practicar la lectura de notas.","type":"project","props":{"goal":"Construir un pentagrama con materiales sencillos y escribir en él la escala de Do.","steps":[{"title":"Dibuja el pentagrama","detail":"En una hoja o cartón, traza con regla 5 líneas paralelas separadas por un dedo de ancho. Dibuja la clave de sol enrollada en la 2.ª línea."},{"title":"Prepara tus notas","detail":"Usa 8 frijoles, botones o tapitas como cabezas de nota."},{"title":"Coloca la escala","detail":"Pon Do en una rayita debajo del pentagrama y sube escalón por escalón hasta el Do del 3.er espacio."},{"title":"Juega con alguien","detail":"Una persona coloca un frijol y la otra dice el nombre de la nota. Luego canten la escala subiendo y bajando."}],"evidence":"Una foto o dibujo de tu pentagrama con la escala completa y los nombres de las notas.","rubric":["Mi pentagrama tiene 5 líneas y la clave de sol en la 2.ª línea","Coloqué las notas en el orden correcto","Leo las notas sin contar desde el principio"]},"id":"s01-art-2-9"},{"fase":"comprobar","areas":["art"],"cnb":["art:1.1.1"],"prompt":"En clave de sol, ¿qué nota está en la **2.ª línea**?","type":"choice","props":{"options":[{"id":"a","text":"Mi"},{"id":"b","text":"Sol"},{"id":"c","text":"Do"},{"id":"d","text":"La"}],"correct":["b"]},"id":"s01-art-2-10"},{"fase":"comprobar","areas":["art"],"cnb":["art:1.1.1"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"El pentagrama tiene 4 líneas y 5 espacios.","answer":false,"why":"Tiene 5 líneas y 4 espacios."},{"text":"Una nota escrita más arriba en el pentagrama suena más aguda.","answer":true},{"text":"Después de Si, la escala vuelve a empezar con un Do más agudo.","answer":true},{"text":"Las líneas del pentagrama se cuentan de arriba hacia abajo.","answer":false,"why":"Se cuentan de abajo hacia arriba."}]},"id":"s01-art-2-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["art"],"cnb":["art:1.1.1"],"type":"reflection","props":{"statements":["Reconozco la duración de la redonda, la blanca, la negra y la corchea","Ordeno las siete notas de grave a agudo","Leo notas en el pentagrama con clave de sol"],"commitments":["Practicaré ritmos con mi sonaja","Leeré una nota nueva cada día en mi pentagrama","Escucharé una canción marcando su pulso con el pie"]},"id":"s01-art-2-12"}],"kind":"materia","area":"art","day":4}},{"missionId":"s01","version":"cnb-sexto-e8aa9ea44169633a","lesson":{"id":"s01-l2-2","title":"Escucho, anticipo e identifico la intencion","icon":"Ear","minutes":15,"gancho":"Las primeras palabras y el tono pueden anunciar que viene y para que se dice.","objetivos":["Anticipar el contenido de un mensaje oral e identificar su intencion como hecho u opinion"],"resumen":["Anticipar usa las primeras palabras, el tono y el tema.","Un hecho comunica algo comprobable; una opinion expresa una valoracion.","Despues de anticipar, se escucha el final para confirmar o corregir."],"media":{"id":"s01-l2-2-ruta-escucha","kind":"diagram","title":"Ruta para escuchar con intencion","aspect":"16:9","alt":"Tres pasos: anticipar con pistas, escuchar el cierre e identificar hecho u opinion.","brief":"Diagrama educativo 1600x900 con tres pasos numerados: pistas iniciales para anticipar, escucha completa para confirmar o corregir, e intencion de hecho comprobable u opinion valorativa. Usar ondas de audio e iconos descriptivos, texto grande, alto contraste, patrones ademas de color y orden de lectura accesible."},"steps":[{"fase":"explorar","areas":["l2"],"cnb":["l2:1.2.4","l2:1.2.6"],"prompt":"Al escuchar un mensaje oral, anticipa que seguira e identifica si su intencion comunica un hecho o una opinion.","type":"explain","props":{"icon":"Ear","body":"Usa inicio, tono y tema para **anticipar**. Luego pregunta: ¿la intencion es informar un **hecho comprobable** o expresar una **opinion**? Escucha el final para verificar."},"id":"s01-l2-2-1"},{"fase":"construir","areas":["l2"],"cnb":["l2:1.2.4","l2:1.2.6"],"title":"Dos decisiones al escuchar","prompt":"Anticipa el contenido del mensaje oral y reconoce su intencion como hecho u opinion.","type":"explain","props":{"icon":"GitCompare","body":"\\"El mapa registra...\\" suele continuar con un dato: hecho. \\"Me parece que este camino...\\" anuncia una valoracion: opinion. La anticipacion es provisional y puede corregirse."},"id":"s01-l2-2-2"},{"fase":"construir","areas":["l2"],"cnb":["l2:1.2.4","l2:1.2.6"],"title":"Modelo auditivo","prompt":"Observa como anticipar un mensaje oral e identificar su intencion de comunicar hecho u opinion.","type":"worked-example","props":{"icon":"Radio","problem":"Se oye: \\"Segun el mapa, la clinica queda...\\"","steps":[{"text":"\\"Segun el mapa\\" permite anticipar una ubicacion."},{"text":"El cierre \\"al oeste de la plaza\\" confirma el dato."},{"text":"Su intencion es informar un hecho comprobable, no una opinion."}],"answer":"Anticipacion: ubicacion. Intencion: hecho."},"id":"s01-l2-2-3"},{"fase":"construir","areas":["l2"],"cnb":["l2:1.2.4","l2:1.2.6"],"prompt":"Escucha, anticipa que completara el mensaje oral e identifica si su intencion es comunicar un hecho o una opinion.","hint":"Atiende al inicio y decide si el cierre puede comprobarse.","explain":"El inicio anuncia una ubicacion verificable en el mapa.","media":{"id":"s01-l2-2-guia","kind":"audio","title":"Ubicacion en San Lucas","duration":12,"alt":"Audio breve de un mensaje oral sobre un lugar de la comunidad; la transcripcion se ofrece despues de responder.","brief":"Audio MP3 de una voz adulta, acento guatemalteco y ritmo pausado. Texto exacto: \\"En el mapa de San Lucas, el puesto de salud aparece... al norte del mercado.\\" Dejar una pausa de 3 segundos despues de la primera oracion para anticipar y 2 segundos de silencio final. Duracion: 12 s. Transcripcion disponible despues de responder o por mediacion docente para accesibilidad. Reemplazo: public/media/s01-l2-2-guia.mp3."},"type":"choice","props":{"options":[{"id":"a","text":"Una ubicacion; intencion de comunicar un hecho"},{"id":"b","text":"Un gusto; intencion de expresar una opinion"},{"id":"c","text":"Una receta; intencion de ordenar pasos"}],"correct":["a"]},"id":"s01-l2-2-4"},{"fase":"construir","areas":["l2"],"cnb":["l2:1.2.4","l2:1.2.6"],"prompt":"Escucha otro mensaje oral, anticipa su cierre e identifica la intencion como hecho u opinion.","hint":"Una expresion de preferencia anuncia una valoracion.","explain":"\\"Para mi\\" orienta hacia una opinion, aunque el lugar exista.","media":{"id":"s01-l2-2-guia-opinion","kind":"audio","title":"Opinion sobre una ruta","duration":12,"alt":"Audio breve de un mensaje oral sobre un lugar de la comunidad; la transcripcion se ofrece despues de responder.","brief":"Audio MP3 de una voz adulta, acento guatemalteco y ritmo pausado. Texto exacto: \\"Para mi, la ruta junto al parque es... la mas agradable del pueblo.\\" Dejar una pausa de 3 segundos despues de la primera oracion para anticipar y 2 segundos de silencio final. Duracion: 12 s. Transcripcion disponible despues de responder o por mediacion docente para accesibilidad. Reemplazo: public/media/s01-l2-2-guia-opinion.mp3."},"type":"true-false","props":{"statements":[{"text":"Se anticipa una valoracion.","answer":true},{"text":"La intencion es expresar una opinion.","answer":true},{"text":"El cierre comunica una medida comprobable.","answer":false}]},"id":"s01-l2-2-5"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:1.2.4","l2:1.2.6"],"prompt":"Sin pista, escucha el mensaje oral, anticipa la informacion final e identifica su intencion como hecho u opinion.","media":{"id":"s01-l2-2-aplica","kind":"audio","title":"Dato sobre un puente","duration":12,"alt":"Audio breve de un mensaje oral sobre un lugar de la comunidad; la transcripcion se ofrece despues de responder.","brief":"Audio MP3 de una voz adulta, acento guatemalteco y ritmo pausado. Texto exacto: \\"El registro de la alcaldia indica que el puente mide... doce metros de largo.\\" Dejar una pausa de 3 segundos despues de la primera oracion para anticipar y 2 segundos de silencio final. Duracion: 12 s. Transcripcion disponible despues de responder o por mediacion docente para accesibilidad. Reemplazo: public/media/s01-l2-2-aplica.mp3."},"type":"choice","props":{"options":[{"id":"a","text":"Una medida comprobable; hecho"},{"id":"b","text":"Un gusto personal; opinion"},{"id":"c","text":"Una invitacion; opinion"}],"correct":["a"]},"id":"s01-l2-2-6"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:1.2.4","l2:1.2.6"],"prompt":"Escucha de forma independiente, anticipa el cierre del mensaje oral e identifica su intencion como hecho u opinion.","media":{"id":"s01-l2-2-aplica-opinion","kind":"audio","title":"Valoracion sobre la plaza","duration":12,"alt":"Audio breve de un mensaje oral sobre un lugar de la comunidad; la transcripcion se ofrece despues de responder.","brief":"Audio MP3 de una voz adulta, acento guatemalteco y ritmo pausado. Texto exacto: \\"Creo que la plaza central es... el sitio mas acogedor para reunirse.\\" Dejar una pausa de 3 segundos despues de la primera oracion para anticipar y 2 segundos de silencio final. Duracion: 12 s. Transcripcion disponible despues de responder o por mediacion docente para accesibilidad. Reemplazo: public/media/s01-l2-2-aplica-opinion.mp3."},"type":"true-false","props":{"statements":[{"text":"El inicio permite anticipar una valoracion.","answer":true},{"text":"La intencion es expresar una opinion.","answer":true},{"text":"El cierre es una coordenada comprobable.","answer":false}]},"id":"s01-l2-2-7"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:1.2.4","l2:1.2.6"],"prompt":"Salida: escucha, anticipa el final del mensaje oral e identifica su intencion como hecho u opinion.","media":{"id":"s01-l2-2-salida-a","kind":"audio","title":"Simbolo de un mapa","duration":12,"alt":"Audio breve de un mensaje oral sobre un lugar de la comunidad; la transcripcion se ofrece despues de responder.","brief":"Audio MP3 de una voz adulta, acento guatemalteco y ritmo pausado. Texto exacto: \\"La clave del mapa usa una cruz para representar... el centro de salud.\\" Dejar una pausa de 3 segundos despues de la primera oracion para anticipar y 2 segundos de silencio final. Duracion: 12 s. Transcripcion disponible despues de responder o por mediacion docente para accesibilidad. Reemplazo: public/media/s01-l2-2-salida-a.mp3."},"type":"choice","props":{"options":[{"id":"a","text":"El significado de un simbolo; hecho"},{"id":"b","text":"El lugar mas bonito; opinion"},{"id":"c","text":"Una preferencia de color; opinion"}],"correct":["a"]},"id":"s01-l2-2-8"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:1.2.4","l2:1.2.6"],"prompt":"Salida nueva: escucha, anticipa el cierre del mensaje oral e identifica su intencion como hecho u opinion.","media":{"id":"s01-l2-2-salida-b","kind":"audio","title":"Valoracion sobre un mirador","duration":12,"alt":"Audio breve de un mensaje oral sobre un lugar de la comunidad; la transcripcion se ofrece despues de responder.","brief":"Audio MP3 de una voz adulta, acento guatemalteco y ritmo pausado. Texto exacto: \\"En mi opinion, el mirador del cerro es... la mejor parada del recorrido.\\" Dejar una pausa de 3 segundos despues de la primera oracion para anticipar y 2 segundos de silencio final. Duracion: 12 s. Transcripcion disponible despues de responder o por mediacion docente para accesibilidad. Reemplazo: public/media/s01-l2-2-salida-b.mp3."},"type":"true-false","props":{"statements":[{"text":"Se anticipa una valoracion del mirador.","answer":true},{"text":"La intencion es expresar una opinion.","answer":true},{"text":"El cierre aporta una cantidad medible.","answer":false}]},"id":"s01-l2-2-9"}],"kind":"materia","area":"l2","day":4}},{"missionId":"s01","version":"cnb-sexto-64ec7306d91c6706","lesson":{"id":"s01-fc-2","title":"Los derechos humanos en los lugares donde vivimos","icon":"Scale","minutes":15,"gancho":"Agua, comida, escuela, un nombre… ¿Son solo cosas que necesitas o son también tus derechos?","objetivos":["Explicar qué son los derechos humanos y sus características","Relacionar las condiciones de un lugar (agua, escuela, salud) con los derechos que se cumplen o no","Proponer qué se puede hacer cuando un derecho no se cumple"],"resumen":["Los derechos humanos son lo que toda persona necesita y merece para vivir con dignidad, solo por ser persona.","Son universales (de todas las personas), inalienables (nadie te los puede quitar) e interdependientes (si falla uno, se afectan otros).","La Declaración Universal de los Derechos Humanos fue aprobada por las Naciones Unidas el 10 de diciembre de 1948. En Guatemala, la Constitución Política de la República también los protege.","Las condiciones de un lugar concreto (agua potable, escuela, centro de salud, trabajo, seguridad) muestran si los derechos se cumplen. El Estado es el principal responsable de garantizarlos; familias y comunidades también participan."],"media":{"id":"s01-fc-2-derechos-lugar","kind":"animation","title":"Un derecho, un lugar","aspect":"16:9","duration":50,"alt":"Un mapa ilustrado de una aldea donde se encienden íconos: un chorro de agua, una escuela, un centro de salud y una casa, cada uno con el derecho que representa.","brief":"Animación 2D de 50 s. Vista aérea ilustrada de una aldea guatemalteca con milpas, casas de block y lámina, un río y una carretera de terracería. Aparecen, uno a uno, íconos sobre lugares concretos: chorro de agua → \\"Derecho al agua y a la salud\\", escuela → \\"Derecho a la educación\\", centro de salud → \\"Derecho a la salud\\", mercado y parcela → \\"Derecho a la alimentación y al trabajo\\". Luego un lugar sin chorro se marca con un signo de pregunta: \\"¿Se cumple este derecho aquí?\\". Narración: \\"Los derechos humanos se viven en lugares concretos\\". Subtítulos. Colores planos, sin textos largos."},"steps":[{"fase":"explorar","areas":["fc"],"cnb":["fc:1.2.1"],"ambito":"conocer","title":"¿Qué son los derechos humanos?","prompt":"Los **derechos humanos** son lo que toda persona necesita y merece para vivir con **dignidad**, solo por ser persona. Toca cada tarjeta.","type":"explain","props":{"icon":"Scale","body":"No son favores ni premios: **te pertenecen desde que naces**, igual que a cualquier otra persona del mundo.","reveal":[{"icon":"Globe","front":"Universales","back":"Son de **todas** las personas, sin importar su pueblo, idioma, sexo, religión, edad o si tienen dinero o no."},{"icon":"Lock","front":"Inalienables","back":"**Nadie te los puede quitar**, ni tú los puedes vender o regalar."},{"icon":"Link","front":"Interdependientes","back":"Están conectados: si falla uno, se afectan otros. Sin alimentación, por ejemplo, cuesta aprender."},{"icon":"ScrollText","front":"Declaración Universal","back":"Las **Naciones Unidas** la aprobaron el **10 de diciembre de 1948**. Por eso ese día es el Día de los Derechos Humanos."},{"icon":"Landmark","front":"En Guatemala","back":"La **Constitución Política de la República** (1985) reconoce derechos como la vida, la libertad, la igualdad, la educación y la salud."}]},"id":"s01-fc-2-1"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.1"],"ambito":"conocer","prompt":"Supongamos que en una aldea las niñas y los niños caminan **dos horas** cada mañana para traer agua del río. ¿A qué más crees que afecta esa situación, además de la sed?","explain":"¡Muy bien pensado! La falta de agua afecta la salud, el tiempo para estudiar y hasta el juego. Hoy verás que detrás de cada condición de un lugar hay **derechos humanos**.","type":"choice","props":{"options":[{"id":"a","text":"A la salud, al tiempo para estudiar y al descanso","icon":"Droplets"},{"id":"b","text":"A nada más: solo es un poco de cansancio","icon":"X","feedback":"Piensa: si pasas dos horas acarreando agua, ¿a qué hora estudias o juegas? ¿Y si el agua del río no es limpia?"}],"correct":["a"]},"id":"s01-fc-2-2"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.1"],"prompt":"Comprueba lo que aprendiste. ¿Verdadero o falso?","hint":"Recuerda las tres características: universales, inalienables e interdependientes.","type":"true-false","props":{"statements":[{"text":"Los derechos humanos son solo para las personas adultas.","answer":false,"why":"Son universales: también son de las niñas y los niños."},{"text":"Una persona no pierde sus derechos por ser pobre o por hablar otro idioma.","answer":true},{"text":"Si alguien no tiene agua limpia, también puede verse afectada su salud.","answer":true,"why":"Los derechos son interdependientes: uno afecta a otro."},{"text":"Los derechos humanos se pueden vender.","answer":false,"why":"Son inalienables: no se venden, no se regalan, no se quitan."}]},"id":"s01-fc-2-3"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.1"],"ambito":"conocer","prompt":"Lee con atención. Este texto explica cómo se relacionan los derechos con los **lugares concretos** donde vive la gente.","type":"reading","props":{"genre":"Texto informativo","heading":"Los derechos se viven en un lugar","passage":"Los derechos humanos no se quedan en un papel: se viven, o no se viven, en lugares concretos. En la casa, en la escuela, en la calle, en el centro de salud y en el mercado podemos ver si se cumplen.\\n\\nPor ejemplo, el derecho a la **salud** se cumple mejor cuando hay agua potable, un **ambiente sano** (sin basura ni aguas contaminadas), un centro de salud cercano y alimentos suficientes. El derecho a la **educación** se cumple cuando hay una escuela a una distancia razonable, con maestros, materiales y un ambiente seguro. A esas cosas las llamamos **condiciones sociales**.\\n\\nCuando en un lugar faltan esas condiciones, las personas no pueden disfrutar plenamente de sus derechos, aunque estén escritos en la ley. El **Estado** es el principal responsable de garantizarlos: debe construir escuelas, llevar servicios de salud y proteger a la población. Las familias y las comunidades también ayudan: organizándose, cuidando lo que tienen y exigiendo con respeto lo que les corresponde.","questions":[{"q":"Según el texto, ¿qué son las \\"condiciones sociales\\"?","options":[{"id":"a","text":"Las cosas que hay en un lugar para que los derechos se cumplan, como agua, escuela o centro de salud"},{"id":"b","text":"Las reglas de un juego"},{"id":"c","text":"El clima de una región"}],"correct":"a"},{"q":"¿Quién es el principal responsable de garantizar los derechos?","options":[{"id":"a","text":"Cada niño por su cuenta"},{"id":"b","text":"El Estado"},{"id":"c","text":"Nadie"}],"correct":"b","why":"El texto dice que el Estado es el principal responsable; familias y comunidades también participan."},{"q":"Si un derecho está escrito en la ley pero en tu aldea no hay escuela, ¿qué puedes concluir?","options":[{"id":"a","text":"Que el derecho a la educación no se cumple plenamente en ese lugar"},{"id":"b","text":"Que ese derecho no existe"},{"id":"c","text":"Que no importa, porque ya está escrito"}],"correct":"a","why":"El derecho existe para todos; lo que falta son las condiciones para vivirlo."}]},"id":"s01-fc-2-4"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.1"],"prompt":"Une cada **condición** de un lugar con el **derecho** que ayuda a cumplir.","hint":"Pregúntate: si esa condición faltara, ¿qué necesidad de la persona quedaría sin atender?","explain":"Cada condición social concreta hace posible un derecho: el agua a la salud, la escuela a la educación, la inscripción a la identidad…","type":"match","props":{"leftTitle":"Condición","rightTitle":"Derecho","pairs":[{"id":"c1","left":"Agua potable en casa","leftIcon":"Droplets","right":"Derecho a la salud"},{"id":"c2","left":"Escuela con maestros y libros","leftIcon":"School","right":"Derecho a la educación"},{"id":"c3","left":"Inscripción en el RENAP al nacer","leftIcon":"FileText","right":"Derecho a un nombre y una identidad"},{"id":"c4","left":"Tortillas, frijol y verduras suficientes","leftIcon":"Wheat","right":"Derecho a la alimentación"},{"id":"c5","left":"Calles alumbradas y seguras","leftIcon":"Lightbulb","right":"Derecho a la seguridad"}]},"id":"s01-fc-2-5"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.1"],"ambito":"hacer","title":"Ejemplo resuelto: de la condición al derecho","prompt":"Así se analiza un **lugar concreto** para saber qué derechos se cumplen. Revela cada paso.","type":"worked-example","props":{"icon":"MapPin","problem":"Supongamos que en la Escuela de la aldea Los Pinos **no hay agua en los baños** desde hace tres meses. Las niñas y los niños no pueden lavarse las manos y varios se han enfermado del estómago.","steps":[{"text":"**Describo la condición:** no hay agua en los baños de la escuela."},{"text":"**Busco el derecho relacionado:** derecho a la **salud** (se enferman) y, de paso, a la **educación** (faltan a clases por enfermedad).","why":"Los derechos son interdependientes: uno arrastra a otro."},{"text":"**Identifico a los responsables:** el Estado, por medio del Ministerio de Educación y la municipalidad, debe resolver el servicio; la comunidad educativa puede organizarse para pedirlo."},{"text":"**Propongo una acción:** el gobierno escolar y la junta de padres escriben una carta respetuosa a la municipalidad, con fotos y fechas, pidiendo la reparación."}],"answer":"En ese lugar el derecho a la salud **no se cumple plenamente**. La comunidad puede **exigirlo con respeto y con datos**.","tip":"Condición → derecho → responsable → acción. Esas cuatro preguntas sirven para analizar cualquier lugar."},"id":"s01-fc-2-6"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.1"],"prompt":"En una colonia no pasa el camión de la basura y la gente la tira al río. Los niños que juegan en la orilla se enferman de la piel. ¿Qué **dos** derechos se ven afectados?","explain":"La basura en el río afecta la **salud** de las personas y su derecho a un **ambiente sano**. Votar o tener un nombre no dependen de la basura del río.","type":"choice","props":{"multiple":true,"options":[{"id":"a","text":"Derecho a la salud","icon":"HeartPulse"},{"id":"b","text":"Derecho a un ambiente sano","icon":"Leaf"},{"id":"c","text":"Derecho a votar","icon":"Vote","feedback":"Votar es un derecho de las personas adultas y no tiene relación directa con esta situación."},{"id":"d","text":"Derecho a tener un nombre","icon":"FileText","feedback":"El nombre y la identidad no dependen de la basura del río."}],"correct":["a","b"]},"id":"s01-fc-2-7"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.1"],"prompt":"Observa cada lugar. ¿El derecho **se cumple** o **no se cumple** plenamente?","explain":"Mira siempre la condición concreta: si falta lo necesario para vivir el derecho, no se cumple plenamente, aunque esté escrito en la ley.","type":"sort","props":{"buckets":[{"id":"si","label":"Se cumple","icon":"Check","color":"var(--c-ok)"},{"id":"no","label":"No se cumple plenamente","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"l1","text":"Un centro de salud abierto, con medicinas, a 15 minutos a pie","bucket":"si"},{"id":"l2","text":"Una escuela con una sola maestra para seis grados y sin libros","bucket":"no"},{"id":"l3","text":"Un niño de 11 años que trabaja todo el día y no va a la escuela","bucket":"no","feedback":"Se afecta su derecho a la educación, al descanso y al juego."},{"id":"l4","text":"Una familia inscribe a su bebé en el RENAP y recibe su certificado","bucket":"si"},{"id":"l5","text":"Un barrio sin alumbrado donde da miedo caminar de noche","bucket":"no"}]},"id":"s01-fc-2-8"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.1"],"ambito":"hacer","prompt":"Piensa en **un lugar de tu comunidad** (tu escuela, tu calle, el mercado, el centro de salud). Escribe: ¿qué condición observas?, ¿qué derecho se relaciona?, ¿se cumple o no? y ¿qué se podría hacer?","type":"short-answer","props":{"minWords":35,"placeholder":"En … observo que… Esto se relaciona con el derecho a…","model":"En mi escuela observo que el techo del aula de cuarto grado gotea cuando llueve y los niños tienen que moverse a una esquina. Esto se relaciona con el derecho a la educación en un ambiente seguro. No se cumple plenamente, porque se pierden clases. Podríamos contar las veces que pasa y pedir, con una carta del gobierno escolar, que la municipalidad repare el techo.","rubric":["Describí una condición concreta de un lugar real","Nombré el derecho relacionado","Dije si se cumple o no y por qué","Propuse una acción respetuosa y posible"]},"id":"s01-fc-2-9"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:1.2.1"],"prompt":"Una comunidad tiene escuela, pero no tiene centro de salud en 30 kilómetros. ¿Qué derecho **no** se cumple plenamente allí?","type":"choice","props":{"options":[{"id":"a","text":"El derecho a la educación"},{"id":"b","text":"El derecho a la salud"},{"id":"c","text":"El derecho a tener un nombre"}],"correct":["b"]},"id":"s01-fc-2-10"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:1.2.1"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"La Declaración Universal de los Derechos Humanos se aprobó en 1948.","answer":true},{"text":"Si un derecho está escrito en la ley, siempre se cumple en todos los lugares.","answer":false,"why":"Depende de que existan las condiciones: escuela, agua, salud, seguridad…"},{"text":"El Estado es el principal responsable de garantizar los derechos humanos.","answer":true}]},"id":"s01-fc-2-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["fc"],"cnb":["fc:1.1.2","fc:1.2.1"],"type":"reflection","props":{"statements":["Explico qué son la solidaridad y la tolerancia","Explico qué son los derechos humanos","Relaciono las condiciones de un lugar con los derechos que se cumplen o no"],"commitments":["Incluiré a alguien que esté solo en el recreo","Observaré un lugar de mi comunidad y pensaré qué derecho se cumple allí","Preguntaré en casa si conocen la Declaración de los Derechos Humanos"]},"id":"s01-fc-2-12"}],"kind":"materia","area":"fc","day":5}},{"missionId":"s01","version":"cnb-sexto-563c990f583c1b82","lesson":{"id":"s01-ef-2","title":"Mi lado dominante y mi equilibrio","icon":"Hand","minutes":15,"gancho":"¿Con qué mano escribes, lanzas una pelota o te cepillas los dientes? ¿Y podrías hacerlo igual de bien con la otra?","objetivos":["Identificar tu mano dominante y ejercitarla, sin olvidar la otra mano","Diferenciar el equilibrio estático del dinámico","Mejorar tu equilibrio con una base amplia, el centro de gravedad bajo y la mirada fija"],"resumen":["La lateralidad es la preferencia por usar un lado del cuerpo. El lado dominante es el que usamos con más fuerza y precisión: la mayoría de personas son diestras; otras son zurdas. Ambas son normales.","Ejercitar la mano dominante mejora la precisión; practicar también con la otra mano da más habilidad y equilibrio al cuerpo.","Equilibrio estático: mantener una postura sin moverse (pararse en un pie). Equilibrio dinámico: mantenerlo mientras te mueves (caminar sobre una línea).","Para tener más equilibrio: base de apoyo amplia, centro de gravedad bajo (rodillas un poco dobladas), brazos abiertos y la mirada fija en un punto."],"media":{"id":"s01-ef-2-equilibrio","kind":"video","title":"Equilibrio quieto y en movimiento","aspect":"9:16","duration":45,"alt":"Una niña se para en un pie con los brazos abiertos y la mirada fija; luego camina sobre una línea en el suelo con un libro en la cabeza.","brief":"Video vertical de 45 s en un patio o salón. Parte 1 \\"Equilibrio estático\\": una niña (ropa deportiva, rostro no protagonista) se para en un pie, primero con brazos pegados (se tambalea) y luego con brazos abiertos y mirada fija en un punto (se estabiliza); rótulos \\"brazos abiertos\\", \\"mira un punto\\". Parte 2 \\"Equilibrio dinámico\\": camina sobre una línea de yeso o cinta, de talón a punta, con un cuaderno sobre la cabeza. Parte 3: un niño en silla de ruedas hace equilibrio del tronco con una pelota sobre las piernas. Aviso \\"Hazlo en suelo plano y despejado\\". Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:1.2.1"],"ambito":"conocer","title":"La lateralidad","prompt":"Nuestro cuerpo tiene dos lados, pero casi siempre **preferimos uno**. Toca cada tarjeta.","type":"explain","props":{"icon":"Hand","body":"La **lateralidad** es la preferencia por usar un lado del cuerpo: mano, pie, ojo y oído.","reveal":[{"icon":"Hand","front":"Lado dominante","back":"Es el que usas con **más fuerza y precisión**. Si es la derecha eres **diestro/a**; si es la izquierda, **zurdo/a**."},{"icon":"Users","front":"Todos somos distintos","back":"La mayoría de las personas son diestras, pero ser zurdo es **igual de normal**. Nadie debe obligarte a cambiar de mano."},{"icon":"Target","front":"Reforzar la dominante","back":"Practicar lanzamientos, botes y agarres con tu mano dominante mejora tu **precisión** en juegos y deportes."},{"icon":"RefreshCw","front":"Entrenar la otra","back":"Practicar también con la mano no dominante te da **más opciones** en el juego y equilibra tu cuerpo."}]},"id":"s01-ef-2-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.2.1"],"ambito":"conocer","prompt":"Haz una prueba rápida: **lanza una bolita de papel** a un bote con una mano y luego con la otra, 3 veces cada una. Casi todas las personas aciertan más con una mano. ¿Por qué crees que pasa?","explain":"Acertamos más con la mano **dominante**: la que el cerebro prefiere y ha entrenado más. Hoy vas a ejercitarla y también a darle práctica a la otra.","type":"choice","props":{"options":[{"id":"a","text":"Porque es la mano que preferimos y más hemos practicado","icon":"Target"},{"id":"b","text":"Porque esa mano tiene más huesos","icon":"Bone","feedback":"Las dos manos tienen los mismos huesos. La diferencia está en la práctica y en la preferencia del cerebro."},{"id":"c","text":"Por pura suerte","icon":"Sparkles","feedback":"Si repites la prueba muchas veces, casi siempre gana la misma mano: no es suerte."}],"correct":["a"]},"id":"s01-ef-2-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.2.4"],"ambito":"conocer","title":"Dos tipos de equilibrio","prompt":"El **equilibrio** es la capacidad de mantener el cuerpo estable sin caerse. Mira el video y toca cada tarjeta.","type":"explain","props":{"icon":"Scale","body":"Tu cuerpo tiene un **centro de gravedad** (un punto cerca del ombligo) que debe quedar **encima de tu base de apoyo** (los pies).","reveal":[{"icon":"PersonStanding","front":"Equilibrio estático","back":"Mantener una postura **sin desplazarte**: pararte en un pie, hacer \\"el avión\\", quedarte en cuclillas."},{"icon":"Footprints","front":"Equilibrio dinámico","back":"Mantener el equilibrio **mientras te mueves**: caminar sobre una línea o un tronco, saltar y caer firme, andar en bicicleta."},{"icon":"Maximize2","front":"Base amplia","back":"Con los pies **separados** tienes más base y más equilibrio que con los pies juntos o en un pie."},{"icon":"ArrowDown","front":"Centro bajo y mirada fija","back":"**Dobla un poco las rodillas**, **abre los brazos** y **mira un punto fijo**: te tambaleas menos."}]},"id":"s01-ef-2-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.2.4"],"ambito":"hacer","title":"Ejemplo resuelto: cruzar el tronco sobre el río","prompt":"Mira cómo Kevin aplica lo aprendido para no caerse.","type":"worked-example","props":{"icon":"Footprints","problem":"En un paseo, Kevin debe cruzar caminando sobre un tronco ancho y bajo, puesto como puente sobre un riachuelo poco profundo. ¿Qué hace para mantener el equilibrio?","steps":[{"text":"Revisa que el tronco esté **firme** y pide que una persona adulta esté cerca.","why":"La seguridad va primero."},{"text":"Abre los **brazos** hacia los lados.","why":"Los brazos abiertos ayudan a corregir el tambaleo."},{"text":"Dobla un poco las **rodillas**.","why":"Baja su centro de gravedad y queda más estable."},{"text":"Mira un **punto fijo** al final del tronco, no el agua.","why":"Mirar el agua que corre confunde al cerebro y hace tambalear."},{"text":"Avanza con **pasos cortos**, apoyando bien cada pie antes de mover el otro."}],"answer":"Kevin usa **equilibrio dinámico**: brazos abiertos, centro bajo, mirada fija y pasos cortos.","tip":"Si sientes que te caes, agáchate y apoya las manos: bajar el cuerpo te devuelve el equilibrio."},"id":"s01-ef-2-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.2.4"],"ambito":"conocer","prompt":"Clasifica cada actividad: ¿equilibrio **estático** o **dinámico**?","hint":"Pregúntate: ¿la persona se desplaza o se queda en su lugar?","explain":"Si te quedas quieto en una postura es estático; si te desplazas manteniendo el equilibrio, es dinámico.","type":"sort","props":{"buckets":[{"id":"e","label":"Estático (quieto)","icon":"PersonStanding","color":"var(--area-ef)"},{"id":"d","label":"Dinámico (en movimiento)","icon":"Footprints","color":"var(--c-maiz-strong)"}],"items":[{"id":"x1","text":"Pararme en un pie 20 segundos","bucket":"e"},{"id":"x2","text":"Caminar sobre la orilla de la banqueta con cuidado","bucket":"d"},{"id":"x3","text":"Hacer \\"el avión\\" sin moverme","bucket":"e"},{"id":"x4","text":"Andar en bicicleta","bucket":"d"},{"id":"x5","text":"Saltar la cuerda","bucket":"d"},{"id":"x6","text":"Quedarme en cuclillas con los brazos al frente","bucket":"e"}]},"id":"s01-ef-2-5"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.2.1","ef:1.2.4"],"ambito":"hacer","prompt":"¡Circuito de mano y equilibrio! **Calentamiento:** rota muñecas, hombros y tobillos. **Estación 1 (mano):** lanza y atrapa una bolita de papel o un calcetín enrollado, 10 veces con la mano dominante y 10 con la otra; luego bota una pelota 10 veces con cada mano. **Estación 2 (equilibrio):** párate en un pie 20 s con cada pierna (estático) y camina 10 pasos sobre una línea de talón a punta, ida y vuelta (dinámico). **Poco espacio:** usa una línea de cinta de 2 m. **Adaptación:** puedes apoyarte en una pared o en una silla; en silla de ruedas, haz el equilibrio con el tronco sosteniendo un cuaderno sobre la cabeza.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después de la estación de la mano","exercise":{"name":"Lanzar, atrapar y botar con cada mano","icon":"Hand","seconds":60}},{"label":"Después de la estación de equilibrio","exercise":{"name":"Un pie y caminar sobre la línea","icon":"Footprints","seconds":60}}]},"id":"s01-ef-2-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.2.4"],"ambito":"hacer","prompt":"Ana se tambalea al pararse en un pie. Tiene los brazos pegados al cuerpo, las rodillas rígidas y mira hacia todos lados. ¿Qué le aconsejas?","explain":"Abrir los brazos, doblar un poco la rodilla de apoyo y fijar la mirada en un punto aumenta la estabilidad.","type":"choice","props":{"options":[{"id":"a","text":"Que abra los brazos, doble un poco la rodilla y mire un punto fijo"},{"id":"b","text":"Que cierre los ojos para concentrarse","feedback":"Con los ojos cerrados el equilibrio es mucho más difícil: la vista ayuda a estabilizarse."},{"id":"c","text":"Que se pare de puntillas para estar más alta","feedback":"De puntillas la base es más pequeña y el equilibrio es más difícil."}],"correct":["a"]},"id":"s01-ef-2-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.2.1"],"ambito":"convivir","prompt":"Luis es zurdo. En el recreo, un compañero le dice que \\"está mal\\" lanzar con la izquierda. ¿Qué es correcto?","explain":"Ser zurdo es una forma normal de lateralidad. Lo importante es ejercitar el lado dominante y, además, practicar con el otro.","type":"choice","props":{"options":[{"id":"a","text":"Luis debe cambiar a la mano derecha","feedback":"No: forzar a alguien a cambiar su mano dominante no tiene sentido y le quita precisión."},{"id":"b","text":"Ser zurdo es normal; Luis puede reforzar su mano izquierda y practicar también con la derecha"},{"id":"c","text":"Luis no debería jugar a lanzar","feedback":"Todas las personas pueden jugar, sin importar su mano dominante."}],"correct":["b"]},"id":"s01-ef-2-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.2.4"],"prompt":"Clasifica cada actividad: ¿equilibrio **estático** o **dinámico**?","type":"sort","props":{"buckets":[{"id":"e","label":"Estático (quieto)","icon":"PersonStanding","color":"var(--area-ef)"},{"id":"d","label":"Dinámico (en movimiento)","icon":"Footprints","color":"var(--c-maiz-strong)"}],"items":[{"id":"y1","text":"Caminar sobre una línea recta sin salirte","bucket":"d"},{"id":"y2","text":"Sostenerte en un pie con la otra rodilla arriba, sin moverte","bucket":"e"},{"id":"y3","text":"Cruzar un puente angosto caminando","bucket":"d"},{"id":"y4","text":"Quedarte de puntillas 10 segundos en tu lugar","bucket":"e"}]},"id":"s01-ef-2-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.2.1","ef:1.2.4"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"La mano dominante es la que usamos con más fuerza y precisión.","answer":true},{"text":"Con los pies juntos tienes más equilibrio que con los pies separados.","answer":false,"why":"Con los pies separados la base de apoyo es más amplia y hay más equilibrio."},{"text":"Doblar un poco las rodillas baja el centro de gravedad y ayuda al equilibrio.","answer":true}]},"id":"s01-ef-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["ef"],"cnb":["ef:1.2.4"],"type":"reflection","props":{"statements":["Explico qué hacen huesos, músculos, tendones y ligamentos","Hago flexión, extensión y rotación con control","Reconozco mi mano dominante y mejoro mi equilibrio"],"commitments":["Haré mi rutina de calentamiento antes de jugar","Practicaré lanzar y botar con las dos manos","Me pararé en un pie mientras me lavo los dientes"]},"id":"s01-ef-2-11"}],"kind":"materia","area":"ef","day":5}},{"missionId":"s01","version":"cnb-sexto-ce0de0bc29e2c7b9","lesson":{"id":"s01-d5-taller","kind":"taller","day":5,"title":"Mapa y voz de nuestro lugar","icon":"Presentation","minutes":20,"gancho":"Si tuvieras menos de un minuto para presentar tu lugar ante personas de todo el país, ¿qué evidencia mostrarías en un mapa?","objetivos":["Representar en un mapa condiciones geográficas y evidencia local","Relacionar una condición del lugar con un derecho y una respuesta solidaria","Realizar una presentación oral breve apoyada en el mapa"],"resumen":["Los datos de ubicación, altitud, clima y riesgo ayudan a interpretar un lugar.","Las condiciones locales permiten analizar el cumplimiento de derechos sin afirmar más de lo que muestra la evidencia.","La orientación, los símbolos, la clave y las anotaciones hacen legible un mapa.","Una presentación breve selecciona una evidencia, un juicio y una respuesta solidaria."],"media":{"id":"s01-d5-taller-ficha","kind":"image","title":"Ficha de la aldea Loma Linda","aspect":"4:3","alt":"Ilustración de una aldea del altiplano en una ladera, con una escuela en terreno firme, un barranco, un nacimiento de agua y una flecha verde de ruta de evacuación.","brief":"Ilustración plana, colores cálidos, de una aldea ficticia del altiplano guatemalteco: casas de adobe y block en una ladera, un barranco a un lado, milpas, un nacimiento de agua con familias acarreando agua en tinajas, una escuela en una parte plana y firme, y señales verdes de ruta de evacuación que llevan a la escuela. Recuadro: \\"Loma Linda · 14.9° N · 91.4° O · 2,000 m\\". Sin rostros identificables ni texto adicional. Dimensiones: 1200x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["ccss","l1"],"cnb":["ccss:1.2.1","l1:2.1.6"],"ambito":"conocer","title":"Misión y tiempo","prompt":"En unos **18 minutos** analizarás la ficha de Loma Linda, recuperarás aprendizajes de la semana y elaborarás dos productos breves: un mapa anotado y una presentación de 45 segundos.","type":"explain","props":{"icon":"Timer","body":"Usa solo la evidencia disponible. El mapa recibe siete minutos y la preparación y presentación oral, tres.","reveal":[{"icon":"Globe","front":"Sociales","back":"Recupera ubicación, condiciones geográficas y prevención."},{"icon":"Map","front":"Comunicación y Lenguaje","back":"Aplica orientación, símbolos, clave y anotaciones como aprendiste en L1."},{"icon":"Scale","front":"Formación Ciudadana","back":"Formula un juicio cuidadoso sobre un derecho y una respuesta solidaria."}]},"id":"s01-d5-taller-1"},{"fase":"construir","areas":["ccss","fc"],"cnb":["ccss:1.2.1","ccss:1.3.1","fc:1.2.1"],"ambito":"conocer","prompt":"Lee la ficha breve. Elige únicamente conclusiones respaldadas por la evidencia.","type":"reading","props":{"genre":"Ficha informativa","heading":"Aldea Loma Linda","passage":"Loma Linda está en el altiplano occidental, a unos **2,000 metros** de altitud. Es tierra fría. **Seis de cada diez casas** tienen agua entubada; las demás familias acarrean agua de un nacimiento. Varias viviendas están en una ladera junto a un barranco. Después de un deslave, el COCODE marcó una ruta de evacuación hacia la escuela, ubicada en terreno firme.","questions":[{"q":"¿Qué conclusión sobre el acceso al agua sí está respaldada?","options":[{"id":"a","text":"El acceso domiciliario es desigual: cuatro de cada diez familias deben acarrear agua"},{"id":"b","text":"Toda el agua entubada es potable"},{"id":"c","text":"El agua del nacimiento es necesariamente insegura"}],"correct":"a","why":"La ficha informa cómo llega el agua y el esfuerzo para obtenerla; no informa su calidad."},{"q":"¿Qué evidencia muestra un riesgo localizado?","options":[{"id":"a","text":"Varias viviendas están en la ladera junto al barranco"},{"id":"b","text":"La aldea está en el altiplano occidental"},{"id":"c","text":"La escuela está en terreno firme"}],"correct":"a","why":"La cercanía al barranco expone esas viviendas a deslaves."}]},"id":"s01-d5-taller-2"},{"fase":"construir","areas":["l1"],"cnb":["l1:3.4.2"],"ambito":"hacer","prompt":"Recupera lo aprendido en **Comunicación y Lenguaje**: relaciona cada convención con su función.","type":"match","props":{"leftTitle":"Convención","rightTitle":"Función","pairs":[{"id":"o","left":"Orientación","right":"La flecha N permite reconocer el norte"},{"id":"s","left":"Símbolo","right":"Representa un lugar con un signo sencillo"},{"id":"c","left":"Clave","right":"Explica los símbolos usados"},{"id":"a","left":"Anotación","right":"Vincula evidencia con un lugar"}]},"id":"s01-d5-taller-3"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.1","fc:1.1.2"],"ambito":"convivir","prompt":"¿Qué juicio y respuesta respetan la evidencia de la ficha?","explain":"La ficha permite evaluar la accesibilidad domiciliaria, pero no la potabilidad ni la continuidad del agua.","type":"choice","props":{"options":[{"id":"a","text":"La accesibilidad domiciliaria al agua es desigual; se pueden registrar recorridos y organizar acompañamiento"},{"id":"b","text":"Toda el agua entubada es potable; no hace falta investigar"},{"id":"c","text":"El nacimiento siempre es inseguro; las familias tienen la culpa"}],"correct":["a"]},"id":"s01-d5-taller-4"},{"fase":"aplicar","areas":["l1","ccss","fc"],"cnb":["l1:3.4.2","ccss:1.2.1","ccss:1.3.1","fc:1.2.1","fc:1.1.2"],"ambito":"hacer","prompt":"Selecciona las **cuatro anotaciones** que colocarás: una por categoría.","type":"match","props":{"leftTitle":"Categoría","rightTitle":"Anotación","pairs":[{"id":"u","left":"Ubicación o condición geográfica","right":"A unos 2,000 m, Loma Linda es tierra fría"},{"id":"r","left":"Riesgo y prevención","right":"Las viviendas junto al barranco están expuestas; la ruta lleva a terreno firme"},{"id":"d","left":"Condición, derecho y juicio","right":"Cuatro de cada diez familias acarrean agua: el acceso domiciliario es desigual"},{"id":"s","left":"Respuesta solidaria","right":"Registrar recorridos con el COCODE y acompañar a quienes acarrean agua"}]},"id":"s01-d5-taller-5"},{"fase":"aplicar","areas":["l1","ccss","fc"],"cnb":["l1:3.4.2","ccss:1.2.1","ccss:1.3.1","fc:1.2.1","fc:1.1.2"],"ambito":"hacer","title":"Producto 1: mapa anotado · 7 min","prompt":"Usa Loma Linda o datos equivalentes y comprobables de tu comunidad.","type":"project","props":{"goal":"Crear un mapa local legible que conecte cuatro evidencias con lugares.","steps":[{"title":"Base mínima · 3 min","detail":"Traza un camino, marca el norte y coloca dos lugares rotulados con dos símbolos explicados en una clave."},{"title":"Cuatro anotaciones · 4 min","detail":"Añade exactamente una anotación de cada categoría recuperada y une cada una con una línea al lugar correspondiente."}],"evidence":"Un mapa con norte, dos lugares rotulados, clave de dos símbolos y exactamente cuatro anotaciones vinculadas.","rubric":["El mapa incluye norte, dos lugares y una clave de dos símbolos","Hay exactamente cuatro anotaciones, una por categoría","Cada anotación usa evidencia y señala el lugar correspondiente"]},"id":"s01-d5-taller-6"},{"fase":"aplicar","areas":["l1","fc"],"cnb":["l1:3.4.2","fc:1.2.1"],"ambito":"hacer","prompt":"Haz una revisión rápida del mapa antes de presentarlo.","explain":"Corrige afirmaciones no respaldadas y verifica que las cuatro anotaciones estén vinculadas.","type":"sort","props":{"buckets":[{"id":"listo","label":"Listo para presentar","icon":"BadgeCheck"},{"id":"corregir","label":"Corregir","icon":"Pencil"}],"items":[{"id":"v1","text":"La clave explica los dos símbolos del mapa","bucket":"listo"},{"id":"v2","text":"Las cuatro anotaciones señalan lugares concretos","bucket":"listo"},{"id":"v3","text":"Una nota afirma que toda el agua entubada es potable","bucket":"corregir"},{"id":"v4","text":"La respuesta solidaria culpa a las familias","bucket":"corregir"}]},"id":"s01-d5-taller-7"},{"fase":"aplicar","areas":["l1","fc"],"cnb":["l1:2.1.6","fc:1.2.1"],"ambito":"hacer","prompt":"Ordena los **tres apoyos** de una presentación de 45 segundos.","type":"order","props":{"items":[{"id":"i","text":"Abrir con una pregunta sobre el acceso al agua","icon":"CircleHelp"},{"id":"e","text":"Señalar una evidencia y explicar el juicio sobre el derecho","icon":"MapPin"},{"id":"c","text":"Cerrar con la respuesta solidaria","icon":"HandHeart"}],"labels":{"start":"Primero","end":"Al final"}},"id":"s01-d5-taller-8"},{"fase":"aplicar","areas":["l1","fc"],"cnb":["l1:2.1.6","fc:1.2.1","fc:1.1.2"],"ambito":"hacer","title":"Producto 2: presentación oral · 2 min","prompt":"Apóyate en el mapa y en los tres momentos que acabas de ordenar.","type":"project","props":{"goal":"Comunicar una evidencia, un juicio cuidadoso y una respuesta solidaria en 45 segundos.","steps":[{"title":"Ensaya · 1 min","detail":"Practica una vez: pregunta inicial, evidencia y juicio, cierre solidario."},{"title":"Presenta · 1 min","detail":"Habla durante 45 segundos, señala el lugar de la evidencia y marca una pausa."}],"evidence":"Una presentación breve que usa el mapa como apoyo.","rubric":["La evidencia señalada respalda el juicio","El cierre propone una respuesta solidaria realizable","La voz es clara y contiene una pausa"]},"id":"s01-d5-taller-9"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["l1","ccss","fc"],"cnb":["l1:2.1.6","l1:3.4.2","fc:1.2.1","fc:1.1.2"],"type":"reflection","props":{"statements":["Construí un mapa legible con cuatro evidencias vinculadas","Juzgué una condición local sin afirmar más de lo que muestran los datos","Presenté una respuesta solidaria en 45 segundos"],"commitments":["Preguntaré antes de afirmar algo que el mapa no demuestra","Escucharé cómo otras familias viven las condiciones del lugar","Participaré en una acción solidaria realizable"]},"id":"s01-d5-taller-10"}]}},{"missionId":"s01","version":"cnb-sexto-1f870d9e743a5d12","lesson":{"id":"s01-mat-5","title":"Figuras congruentes: iguales en forma y tamaño","icon":"Copy","minutes":15,"gancho":"Para que un piso quede parejo, todas las baldosas deben encajar igualito. ¿Cómo sabes si dos figuras son exactamente iguales?","objetivos":["Identificar figuras congruentes comparando lados y ángulos","Trazar una figura congruente a otra en papel cuadriculado"],"resumen":["Dos figuras son congruentes si tienen la misma forma y el mismo tamaño: sus lados correspondientes miden lo mismo y sus ángulos correspondientes también.","No importa la posición, el color ni si una está girada o reflejada: si encajan exactamente una sobre otra, son congruentes.","Dos figuras con la misma forma pero distinto tamaño NO son congruentes.","Para trazar una figura congruente, copia cada lado con el mismo número de cuadritos y en la misma dirección."],"media":{"id":"s01-mat-5-baldosas","kind":"image","title":"Un piso de baldosas congruentes","aspect":"4:3","alt":"Piso de un corredor colonial con baldosas cuadradas de dos colores; dos baldosas se levantan y se superponen para mostrar que encajan exactamente.","brief":"Ilustración de un corredor de casa antigua de Antigua Guatemala con piso de baldosas cuadradas en dos colores (rojo barro y crema). En primer plano, una baldosa aparece levantada y colocada encima de otra, con una línea punteada mostrando que coinciden en todos sus bordes; texto pequeño: \\"congruentes\\". A un lado, una baldosa más pequeña con el mismo dibujo, con una X suave y la etiqueta \\"misma forma, otro tamaño\\". Estilo plano cálido, sin personas. Dimensiones: 1200x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:1.1.4"],"ambito":"conocer","title":"¿Qué significa congruente?","prompt":"Dos figuras son **congruentes** cuando tienen **la misma forma y el mismo tamaño**. Toca cada tarjeta.","type":"explain","props":{"icon":"Copy","body":"Para comprobarlo, compara **lados correspondientes** (los que ocupan el mismo lugar) y **ángulos correspondientes**.","reveal":[{"icon":"Ruler","front":"Lados","back":"Cada lado de una figura mide lo mismo que su lado correspondiente en la otra."},{"icon":"Triangle","front":"Ángulos","back":"Cada ángulo de una figura mide lo mismo que su ángulo correspondiente en la otra."},{"icon":"RotateCw","front":"Posición","back":"No importa si una está **girada**, **volteada** o en otro lugar, ni de qué color es."},{"icon":"X","front":"Contraejemplo","back":"Un cuadrado de 3 cm y uno de 5 cm tienen la misma forma, pero **no** son congruentes: su tamaño es distinto."}]},"id":"s01-mat-5-1"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.4"],"ambito":"conocer","prompt":"Tienes dos tortillas hechas con el mismo molde y una tortillita pequeña. ¿Cuáles **encajarían exactamente** una sobre otra?","explain":"Las dos del mismo molde tienen la misma forma **y** el mismo tamaño. La pequeña tiene la misma forma, pero no el mismo tamaño.","type":"choice","props":{"options":[{"id":"a","text":"Las dos tortillas del mismo molde","icon":"Cookie"},{"id":"b","text":"Una tortilla del molde y la tortillita","icon":"CircleDot","feedback":"Son redondas las dos, pero de distinto tamaño: no encajan exactamente."},{"id":"c","text":"Todas, porque todas son redondas","icon":"Layers","feedback":"Ser redondas no basta: también deben ser del mismo tamaño."}],"correct":["a"]},"id":"s01-mat-5-2"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.4"],"prompt":"El triángulo A tiene lados de **3, 4 y 5 cm**. ¿Cuál de estos triángulos es **congruente** con A?","hint":"Busca uno con exactamente las mismas tres medidas, aunque estén en otro orden.","explain":"El triángulo con lados de 5, 3 y 4 cm tiene las mismas medidas en otro orden: está girado, pero es congruente.","type":"choice","props":{"options":[{"id":"a","text":"Lados de 6, 8 y 10 cm","feedback":"Tiene la misma forma, pero es el doble de grande: no es congruente."},{"id":"b","text":"Lados de 5, 3 y 4 cm"},{"id":"c","text":"Lados de 3, 4 y 6 cm","feedback":"Un lado es distinto (6 en lugar de 5)."}],"correct":["b"]},"id":"s01-mat-5-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.5"],"ambito":"hacer","title":"Trazar una figura congruente","prompt":"En papel cuadriculado, copiar una figura es como seguir un camino. Observa.","type":"worked-example","props":{"icon":"PenTool","problem":"Copia en otro lugar de la hoja el romboide que tiene: base de **4 cuadritos**, lado inclinado que sube **2** y se corre **1** a la derecha.","steps":[{"text":"Elige un punto de inicio nuevo en la hoja."},{"text":"Traza la base: **4 cuadritos** a la derecha.","why":"El mismo número de cuadritos asegura la misma longitud."},{"text":"Desde el inicio, sube **2** y córrete **1** a la derecha; marca ese punto. Haz lo mismo desde el final de la base.","why":"Así el lado inclinado tiene la misma longitud y el mismo ángulo."},{"text":"Une los dos puntos de arriba (otra línea de 4) y los lados inclinados."}],"answer":"Tu romboide es **congruente** con el original: mismos lados y mismos ángulos.","tip":"Sin cuadrícula, usa regla para los lados y transportador para los ángulos."},"id":"s01-mat-5-4"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.4","mat:1.1.5"],"prompt":"¿Verdadero o falso?","hint":"Congruente = misma forma y mismo tamaño. La posición no importa.","explain":"Girar, voltear o mover una figura no cambia sus lados ni sus ángulos.","type":"true-false","props":{"statements":[{"text":"Si giro un triángulo, el triángulo girado es congruente con el original.","answer":true},{"text":"Un rectángulo de 4 × 2 cuadritos y uno de 8 × 4 cuadritos son congruentes.","answer":false,"why":"El segundo es el doble de grande."},{"text":"Para copiar una figura congruente en cuadrícula, cada lado debe medir los mismos cuadritos.","answer":true}]},"id":"s01-mat-5-5"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.4"],"prompt":"¿Son congruentes estos pares de figuras?","explain":"Compara lado por lado y ángulo por ángulo.","type":"sort","props":{"buckets":[{"id":"si","label":"Congruentes","icon":"Check","color":"var(--c-ok)"},{"id":"no","label":"No congruentes","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"a","text":"Dos cuadrados de 5 cm de lado","bucket":"si"},{"id":"b","text":"Un cuadrado de 4 cm y un rombo de 4 cm de lado con ángulos de 60° y 120°","bucket":"no","feedback":"Los lados miden igual, pero los ángulos no: 90° no es igual a 60°."},{"id":"c","text":"Dos rectángulos de 7 × 3 cm, uno acostado y otro parado","bucket":"si","feedback":"Solo cambió la posición."},{"id":"d","text":"Dos triángulos de 60°, 60° y 60°, uno con lados de 2 cm y otro de 3 cm","bucket":"no","feedback":"Misma forma, distinto tamaño."},{"id":"e","text":"Un triángulo y su reflejo en un espejo","bucket":"si"}]},"id":"s01-mat-5-6"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.5","mat:1.1.1"],"prompt":"Trazaste un triángulo congruente con otro que tiene ángulos de **50°** y **70°**. ¿Cuánto mide el **tercer** ángulo de tu copia?","explain":"El original mide 180 − 50 − 70 = 60°. Como tu copia es congruente, su tercer ángulo también mide 60°.","type":"number-input","props":{"answer":60,"unit":"°","misconceptions":[{"value":120,"msg":"120 es la suma de los dos ángulos conocidos. Réstala a 180."}]},"id":"s01-mat-5-7"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.4"],"prompt":"Un albañil va a cubrir un piso sin dejar huecos ni encimar piezas. ¿Por qué pide que todas las baldosas sean **congruentes**?","explain":"Si todas son congruentes, cada baldosa encaja exactamente junto a las demás y el piso queda parejo.","type":"choice","props":{"options":[{"id":"a","text":"Para que todas encajen igual y el piso quede parejo","icon":"Blocks"},{"id":"b","text":"Para que sean todas del mismo color","icon":"Palette","feedback":"El color no tiene que ver con la congruencia."},{"id":"c","text":"Para que pesen menos","icon":"Scale","feedback":"Lo importante es la forma y el tamaño, no el peso."}],"correct":["a"]},"id":"s01-mat-5-8"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.1.4"],"prompt":"El rectángulo R mide **6 cm × 2 cm**. ¿Cuál es congruente con R?","type":"choice","props":{"options":[{"id":"a","text":"Un rectángulo de 3 cm × 1 cm"},{"id":"b","text":"Un rectángulo de 2 cm × 6 cm, parado"},{"id":"c","text":"Un romboide de lados 6 cm y 2 cm"}],"correct":["b"]},"id":"s01-mat-5-9"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.1.4","mat:1.1.2","mat:1.1.1"],"prompt":"Repaso de la semana. ¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Dos figuras congruentes tienen la misma forma y el mismo tamaño.","answer":true},{"text":"Un cuadrado de 3 cm y otro de 6 cm son congruentes.","answer":false},{"text":"Un rombo tiene 4 lados iguales.","answer":true},{"text":"Un triángulo con ángulos de 90°, 60° y 30° es obtusángulo.","answer":false}]},"id":"s01-mat-5-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["mat"],"cnb":[],"type":"reflection","props":{"statements":["Clasifico triángulos por sus ángulos y calculo el ángulo que falta","Distingo rectángulo, cuadrado, rombo y romboide","Reconozco y trazo figuras congruentes"],"commitments":["Buscaré paralelogramos en mi casa y en el mercado","Haré el experimento de las tres esquinas con mi familia","Revisaré mis trazos contando cuadritos con cuidado"]},"id":"s01-mat-5-11"}],"kind":"materia","area":"mat","day":5}},{"missionId":"s01","version":"cnb-sexto-986dddf321ad9c02","lesson":{"id":"s01-cnt-3","title":"Células, cromosomas y genes","icon":"Leaf","minutes":15,"gancho":"Una hoja de lechuga fresca cruje y se mantiene firme; tu mejilla es suave y flexible. ¿Tendrá algo que ver con sus células?","objetivos":["Comparar células animales y vegetales y relacionar sus cromosomas con las funciones de los genes"],"resumen":["Ambas células tienen membrana, citoplasma, núcleo, mitocondrias, ribosomas, retículo endoplasmático y aparato de Golgi.","Solo la célula vegetal tiene pared celular (da forma y firmeza), cloroplastos (hacen la fotosíntesis) y una vacuola central grande (guarda agua).","La célula animal tiene centriolos, vacuolas pequeñas y forma redondeada o irregular; la vegetal suele tener forma regular, como un ladrillo.","En ambos tipos de célula, los cromosomas organizan el ADN; los genes son segmentos de ADN con instrucciones para funciones y características."],"media":{"id":"s01-cnt-3-comparacion","kind":"diagram","title":"Célula animal y célula vegetal lado a lado","aspect":"16:9","alt":"A la izquierda una célula animal redondeada; a la derecha una célula vegetal rectangular con pared gruesa verde, cloroplastos y una gran vacuola central. Las estructuras compartidas tienen el mismo color en ambas.","brief":"Diagrama escolar comparativo en colores planos. Izquierda: célula animal redondeada (membrana, citoplasma, núcleo, mitocondrias, ribosomas, retículo, Golgi, lisosomas, centriolos). Derecha: célula vegetal con forma de ladrillo: pared celular gruesa verde oscuro por fuera de la membrana, varios cloroplastos verdes ovalados, vacuola central grande celeste que empuja el núcleo hacia un lado, mitocondrias. Estructuras compartidas con el mismo color en ambas células; las exclusivas con un borde de estrella y rótulo en negrita (\\"solo vegetal\\", \\"solo animal\\"). Letra grande, fondo blanco. Dimensiones: 1600x900."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:1.3.1"],"ambito":"conocer","title":"Lo que comparten","prompt":"Las células de plantas y de animales son **parecidas por dentro**. Toca las tarjetas.","type":"explain","props":{"icon":"Copy","body":"Ambas tienen **núcleo** con ADN y los organelos que aprendiste en la lección anterior.","reveal":[{"icon":"Shield","front":"Membrana y citoplasma","back":"Las dos tienen **membrana celular** que controla el paso de sustancias y **citoplasma** donde flotan los organelos."},{"icon":"Brain","front":"Núcleo","back":"Las dos guardan su ADN en un **núcleo** que dirige la célula."},{"icon":"Zap","front":"Mitocondrias","back":"¡Ojo! Las plantas **también** tienen mitocondrias: necesitan energía para crecer, igual que tú."},{"icon":"Package","front":"Ribosomas, retículo y Golgi","back":"Ambas fabrican, transportan y empacan sustancias con los mismos organelos."}]},"id":"s01-cnt-3-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.4.1"],"ambito":"conocer","title":"Del núcleo al gen","prompt":"Sigue un ejemplo para relacionar núcleo, cromosoma y gen sin confundirlos.","type":"worked-example","props":{"icon":"Dna","problem":"Una célula de una hoja necesita una instrucción para producir una proteína. ¿Cómo se organiza esa información?","steps":[{"text":"El **núcleo** guarda el ADN de la célula."},{"text":"El **ADN** se empaqueta y organiza en **cromosomas**."},{"text":"Un **gen** es un segmento de ADN ubicado en un cromosoma; contiene una instrucción funcional."}],"answer":"La instrucción está en un gen, dentro del ADN organizado en un cromosoma del núcleo. Cromosoma y gen no son sinónimos.","tip":"Piensa en la relación de mayor a menor: núcleo, cromosoma, gen."},"id":"s01-cnt-3-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.3.1"],"ambito":"conocer","title":"Lo que las hace diferentes","prompt":"Observa el esquema de la lección. La célula vegetal tiene **tres estructuras** que la animal no tiene, y la animal tiene una que la vegetal no. Toca cada tarjeta.","type":"explain","props":{"icon":"Leaf","body":"Las plantas **no se mueven** de un lugar a otro y **fabrican su propio alimento** con la luz del Sol. Sus células están preparadas para eso.","reveal":[{"icon":"BrickWall","front":"Pared celular (solo vegetal)","back":"Capa **rígida** de **celulosa** por fuera de la membrana. Da **forma y firmeza**: por eso un tronco se sostiene de pie. La madera y el papel están hechos de paredes celulares."},{"icon":"Sun","front":"Cloroplastos (solo vegetal)","back":"Organelos verdes con **clorofila**. Capturan la luz del Sol y hacen la **fotosíntesis**: fabrican alimento (azúcar) y liberan oxígeno."},{"icon":"Droplet","front":"Vacuola central (solo vegetal)","back":"Una bolsa **grande** llena de agua que ocupa casi toda la célula y la mantiene **firme**. En la célula animal las vacuolas son pequeñas."},{"icon":"Circle","front":"Centriolos y forma (solo animal)","back":"La célula animal tiene **centriolos** y, sin pared, tiene forma **redondeada o irregular**. La vegetal suele verse como un **ladrillo**."}]},"id":"s01-cnt-3-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.3.1"],"ambito":"conocer","prompt":"Usa lo aprendido: ¿por qué una hoja de lechuga fresca se mantiene **firme** y cruje?","explain":"La **pared celular** rígida y la **vacuola** llena de agua ayudan a que la hoja se mantenga firme.","type":"choice","props":{"options":[{"id":"a","text":"Porque sus células tienen una cubierta rígida y mucha agua adentro","icon":"Droplets"},{"id":"b","text":"Porque tiene huesos muy pequeños","icon":"Bone","feedback":"Las plantas no tienen huesos. La firmeza viene de sus células."},{"id":"c","text":"Porque está fría","icon":"Snowflake","feedback":"El frío ayuda a conservarla, pero la firmeza viene de la estructura de sus células."}],"correct":["a"]},"id":"s01-cnt-3-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.3.1"],"ambito":"conocer","prompt":"Clasifica cada estructura: ¿solo en la célula animal, solo en la vegetal o en ambas?","hint":"Solo la vegetal: pared, cloroplastos, vacuola central grande. Solo la animal: centriolos. Lo demás lo comparten.","explain":"Compartidas: membrana, núcleo, mitocondrias, ribosomas. Solo vegetal: pared celular, cloroplastos, vacuola central. Solo animal: centriolos.","type":"sort","props":{"buckets":[{"id":"an","label":"Solo animal","icon":"Circle","color":"var(--area-l1)"},{"id":"ve","label":"Solo vegetal","icon":"Leaf","color":"var(--c-ok)"},{"id":"am","label":"Ambas","icon":"Copy","color":"var(--area-cnt)"}],"items":[{"id":"s1","text":"Pared celular","bucket":"ve"},{"id":"s2","text":"Cloroplastos","bucket":"ve"},{"id":"s3","text":"Núcleo","bucket":"am"},{"id":"s4","text":"Centriolos","bucket":"an"},{"id":"s5","text":"Mitocondrias","bucket":"am","feedback":"Las plantas también necesitan energía: tienen mitocondrias."},{"id":"s6","text":"Vacuola central grande","bucket":"ve"},{"id":"s7","text":"Membrana celular","bucket":"am","feedback":"La célula vegetal también tiene membrana, justo por dentro de la pared."},{"id":"s8","text":"Ribosomas","bucket":"am"}]},"id":"s01-cnt-3-5"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.3.1"],"ambito":"hacer","title":"Ejemplo: la lechuga marchita","prompt":"Usa lo que sabes de la célula vegetal para explicar algo que pasa en la cocina.","media":{"id":"s01-cnt-3-lechuga","kind":"image","title":"Antes y después: la hoja en agua","aspect":"4:3","alt":"Dos fotos de una hoja de lechuga: a la izquierda marchita y doblada; a la derecha firme después de estar en un vaso con agua. Debajo, dos células vegetales: una con la vacuola pequeña y otra con la vacuola llena.","brief":"Composición de dos fotografías reales, fondo de mesa de cocina sencilla: (1) hoja de lechuga marchita, caída; (2) la misma hoja firme dentro de un vaso de agua, rótulo \\"1 hora después\\". Debajo de cada foto, un dibujo simple de una célula vegetal: vacuola encogida y membrana separada de la pared (marchita) / vacuola grande que empuja contra la pared (firme). Flechas azules de agua entrando. Sin marcas comerciales. Dimensiones: 1200x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"type":"worked-example","props":{"icon":"Salad","problem":"Una hoja de lechuga se quedó fuera del refrigerador y se **marchitó**. La mamá de Rosa la pone en un vaso con agua fresca y, una hora después, está **firme** otra vez. ¿Por qué?","steps":[{"text":"La hoja marchita **perdió agua**: las **vacuolas** de sus células se encogieron.","why":"La vacuola central guarda el agua de la célula vegetal."},{"text":"Sin agua que empuje, las células ya no presionan contra la **pared celular**, y la hoja se dobla."},{"text":"En el vaso, el agua **entra** a las células a través de la pared y de la membrana, y las vacuolas se llenan de nuevo."},{"text":"Las vacuolas llenas empujan contra la pared rígida: la célula se pone **firme**, como un globo inflado dentro de una caja.","why":"La pared no deja que la célula se estire de más."}],"answer":"La firmeza de la hoja depende de la **vacuola llena de agua** que empuja contra la **pared celular**.","tip":"Pruébalo en casa, con permiso: pon una rama de apio o una hoja marchita en un vaso de agua y obsérvala después de una hora."},"id":"s01-cnt-3-6"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.3.1"],"ambito":"conocer","prompt":"Rodrigo dice: \\"Las plantas no tienen mitocondrias porque ya tienen cloroplastos\\". ¿Tiene razón?","hint":"Recuerda: ¿qué hace cada organelo? Uno fabrica alimento; el otro saca energía del alimento.","explain":"El **cloroplasto** fabrica el alimento (azúcar) con la luz; la **mitocondria** saca energía de ese alimento. Las plantas necesitan los dos.","type":"choice","props":{"options":[{"id":"a","text":"Sí, los cloroplastos hacen el trabajo de las mitocondrias","feedback":"Hacen trabajos distintos: fabricar alimento no es lo mismo que obtener energía de él."},{"id":"b","text":"No: las plantas tienen cloroplastos **y** mitocondrias"},{"id":"c","text":"No: las plantas no tienen ninguno de los dos","feedback":"Las células de las hojas tienen cloroplastos, y todas las células vegetales tienen mitocondrias."}],"correct":["b"]},"id":"s01-cnt-3-7"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.3.1"],"ambito":"hacer","prompt":"Una científica describe lo que vio en el microscopio. ¿Es una célula **animal** o **vegetal**?","explain":"Pared gruesa, forma de ladrillo, granos verdes o una gran vacuola indican célula vegetal. Forma redondeada sin pared indica célula animal.","type":"sort","props":{"layout":"grid2","buckets":[{"id":"an","label":"Célula animal","icon":"Circle","color":"var(--area-l1)"},{"id":"ve","label":"Célula vegetal","icon":"Leaf","color":"var(--c-ok)"}],"items":[{"id":"m1","text":"Forma de ladrillo, con muchos granos verdes","bucket":"ve"},{"id":"m2","text":"Redondeada, flexible, sin pared","bucket":"an"},{"id":"m3","text":"Tiene una bolsa de agua que ocupa casi toda la célula","bucket":"ve"},{"id":"m4","text":"De la mejilla por dentro, con forma irregular","bucket":"an"},{"id":"m5","text":"De una hoja de milpa, con cloroplastos","bucket":"ve"},{"id":"m6","text":"Tiene centriolos cerca del núcleo","bucket":"an"}]},"id":"s01-cnt-3-8"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.3.1","cnt:1.4.1"],"ambito":"conocer","prompt":"Una científica observa una célula vegetal con núcleo. Dentro identifica cromosomas y, en ellos, genes. ¿Qué relación entre sus funciones es correcta?","type":"choice","props":{"options":[{"id":"a","text":"Los cromosomas organizan ADN y cada gen es un segmento con una instrucción"},{"id":"b","text":"Cada gen contiene todos los cromosomas de la célula"},{"id":"c","text":"Los cromosomas fabrican luz y los genes almacenan agua"}],"correct":["a"]},"id":"s01-cnt-3-9"},{"fase":"aplicar","areas":["cnt","art"],"cnb":["cnt:1.3.1","cnt:1.4.1"],"ambito":"hacer","title":"Modelo breve en papel","prompt":"En una hoja o cuaderno, representa una célula vegetal y amplía su núcleo hasta mostrar cromosoma, ADN y gen.","type":"project","props":{"goal":"Dibujar una comparación celular y un acercamiento que relacione cromosomas y genes.","steps":[{"title":"Célula","detail":"Con lápiz, dibuja pared, membrana, vacuola, cloroplastos y núcleo; marca dos diferencias con una célula animal."},{"title":"Acercamiento","detail":"Traza una flecha desde el núcleo a un cromosoma, dibuja su ADN y señala un segmento como gen."}],"evidence":"El dibujo en papel queda como evidencia física; la lista solo verifica que se completaron sus partes.","rubric":["Diferencié célula vegetal y animal","Relacioné núcleo, cromosoma, ADN y gen","Rotulé la función de cromosoma y gen"]},"id":"s01-cnt-3-10"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:1.3.1","cnt:1.4.1"],"prompt":"Una célula vegetal tiene cloroplastos y núcleo. ¿Qué opción relaciona correctamente una diferencia celular y las funciones de cromosomas y genes?","type":"choice","props":{"options":[{"id":"a","text":"El cloroplasto distingue a la célula vegetal; los cromosomas organizan ADN y los genes son segmentos con instrucciones"},{"id":"b","text":"El cloroplasto contiene todos los genes y cada gen organiza varios núcleos"},{"id":"c","text":"La pared celular es un cromosoma y el núcleo es un gen"}],"correct":["a"]},"id":"s01-cnt-3-11"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:1.3.1","cnt:1.4.1"],"prompt":"Comprueba diferencias celulares y la relación funcional entre cromosomas y genes.","type":"true-false","props":{"statements":[{"text":"Las células animales y vegetales pueden tener cromosomas en el núcleo.","answer":true},{"text":"Un gen es un segmento de ADN situado en un cromosoma y aporta una instrucción.","answer":true},{"text":"La pared celular y los cloroplastos son propios de la célula animal.","answer":false,"why":"Son estructuras características de la célula vegetal."}]},"id":"s01-cnt-3-12"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["cnt"],"cnb":[],"type":"reflection","props":{"statements":["Diferencio una célula animal de una vegetal","Relaciono núcleo, cromosomas, ADN y genes","Explico que un gen es un segmento de ADN con una instrucción"],"commitments":["Revisaré que mi modelo distinga ambos tipos de célula","Explicaré cómo un cromosoma organiza ADN y contiene genes"]},"id":"s01-cnt-3-13"}],"kind":"materia","area":"cnt","day":5}},{"missionId":"s01","version":"cnb-sexto-11d3bdb488df0bd2","lesson":{"id":"s01-d5-reto","kind":"reto","day":5,"title":"Reto de la semana 1","icon":"Trophy","minutes":14,"objetivos":["Demostrar lo que aprendiste esta semana en todas tus materias","Obtener la medalla \\"Voz del territorio\\" (70 % o más)"],"resumen":["Superé el reto de la semana 1: geometría, comunicación, células, territorio, idiomas, música, movimiento, derechos y desarrollo."],"media":{"id":"s01-d5-reto","kind":"image","title":"Medalla Voz del territorio","aspect":"1:1","alt":"Medalla dorada con un mapa de Guatemala, una rosa de los vientos y un quetzal.","brief":"Ilustración de medalla circular dorada con relieve de un mapa de Guatemala, una rosa de los vientos y un quetzal estilizado. Cinta con los colores de las áreas del CNB. Fondo transparente, 1024×1024. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.1.1"],"prompt":"Dos ángulos de un triángulo miden **38°** y **67°**. ¿Cuánto mide el tercer ángulo?","type":"number-input","props":{"answer":75,"unit":"°","misconceptions":[{"value":105,"msg":"105° es la suma de los dos datos; falta restarla de 180°."}]},"id":"s01-d5-reto-1"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:2.1.6"],"prompt":"Ordena un inicio oral que usa la voz para crear curiosidad.","type":"order","props":{"labels":{"start":"Primero","end":"Después"},"items":[{"id":"a","text":"Mirar al público y preguntar: “¿Han visto un río cambiar de color?”"},{"id":"b","text":"Hacer una pausa breve"},{"id":"c","text":"Presentar el dato que explica el cambio"}]},"id":"s01-d5-reto-2"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:1.3.1"],"prompt":"Clasifica estas estructuras celulares.","type":"sort","props":{"buckets":[{"id":"v","label":"Solo vegetal","icon":"Leaf","color":"var(--c-ok)"},{"id":"a","label":"Solo animal","icon":"PawPrint","color":"var(--c-hint)"},{"id":"b","label":"Ambas","icon":"Copy","color":"var(--area-cnt)"}],"items":[{"id":"c1","text":"Estructura rígida de celulosa que da firmeza","bucket":"v"},{"id":"c2","text":"Organelo con clorofila que capta luz","bucket":"v"},{"id":"c3","text":"Vacuolas pequeñas en vez de una central grande","bucket":"a"},{"id":"c4","text":"Organelo que produce energía","bucket":"b"},{"id":"c5","text":"Organelo que empaca y distribuye sustancias","bucket":"b"}]},"id":"s01-d5-reto-3"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:1.2.1","ccss:1.3.1"],"prompt":"Evalúa estas afirmaciones sobre ubicación, clima y prevención.","type":"true-false","props":{"statements":[{"text":"Un punto marcado 15° N y 90° O está al norte del ecuador y al oeste de Greenwich.","answer":true},{"text":"Si dos lugares tienen latitud parecida, el de mayor altitud suele ser más cálido.","answer":false,"why":"A mayor altitud, la temperatura suele disminuir."},{"text":"Practicar una ruta de evacuación antes de las lluvias puede reducir la vulnerabilidad.","answer":true}]},"id":"s01-d5-reto-4"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:1.2.4","l2:1.2.6"],"prompt":"Escucha el aviso, anticipa qué información seguirá e identifica si la intención comunica un hecho o una opinión.","media":{"id":"s01-reto-l2-aviso","kind":"audio","title":"Aviso sobre un desvío local","duration":12,"alt":"Audio breve de un aviso comunitario sobre una ruta; la transcripción se ofrece después de responder.","brief":"Audio MP3 de una voz adulta, acento guatemalteco y ritmo pausado. Texto exacto: \\"Según el mapa municipal, la calle del puente estará cerrada mañana... use la ruta junto al mercado.\\" Dejar una pausa de 3 segundos después de \\"mañana\\" para anticipar y 2 segundos de silencio final. Duración: 12 s. Transcripción disponible después de responder o por mediación docente para accesibilidad. Reemplazo: public/media/s01-reto-l2-aviso.mp3."},"type":"choice","props":{"options":[{"id":"a","text":"Seguirá una ruta alternativa; la intención es comunicar un hecho"},{"id":"b","text":"Seguirá un gusto sobre el puente; la intención es opinar"},{"id":"c","text":"Seguirá una receta; la intención es explicar una preferencia"}],"correct":["a"]},"id":"s01-d5-reto-5"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:1.1.1"],"prompt":"Complete in English.","type":"fill-blank","props":{"text":"The clinic is [[next to]] the school. The bus is [[in front of]] the market.","distractors":["under","in"]},"id":"s01-d5-reto-6"},{"fase":"comprobar","areas":["art"],"cnb":["art:1.1.1"],"prompt":"Une cada figura musical con su duración.","type":"match","props":{"leftTitle":"Figura","rightTitle":"Duración","pairs":[{"id":"a1","left":"Dos corcheas","right":"Un tiempo"},{"id":"a2","left":"Una blanca y una negra","right":"Tres tiempos"},{"id":"a3","left":"Una redonda y una corchea","right":"Cuatro tiempos y medio"},{"id":"a4","left":"Dos blancas y una negra","right":"Cinco tiempos"}]},"id":"s01-d5-reto-7"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.1.2"],"prompt":"Clasifica cada movimiento del cuerpo.","type":"sort","props":{"buckets":[{"id":"f","label":"Flexión","icon":"FoldHorizontal"},{"id":"e","label":"Extensión","icon":"MoveHorizontal"},{"id":"r","label":"Rotación","icon":"RotateCw"}],"items":[{"id":"e1","text":"Doblar el codo para acercar la mano al hombro","bucket":"f"},{"id":"e2","text":"Enderezar la rodilla","bucket":"e"},{"id":"e3","text":"Girar el tronco para mirar atrás","bucket":"r"}]},"id":"s01-d5-reto-8"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:1.2.1"],"prompt":"En una comunidad hay escuela primaria, pero el instituto más cercano queda a tres horas a pie. ¿Cuál juicio usa la evidencia correctamente?","type":"choice","props":{"options":[{"id":"a","text":"El acceso a la educación básica existe, pero continuar los estudios no está garantizado en igualdad de condiciones"},{"id":"b","text":"El derecho a la educación se cumple por completo porque hay primaria"},{"id":"c","text":"La distancia demuestra que nadie de la comunidad estudia"}],"correct":["a"]},"id":"s01-d5-reto-9"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:1.1.1"],"prompt":"¿Qué muestran estos datos sobre desarrollo y pobreza?","type":"true-false","props":{"statements":[{"text":"Tener empleo digno, servicios de salud y acceso confiable al agua favorece el desarrollo.","answer":true},{"text":"La pobreza depende solamente del dinero que una persona lleva en el bolsillo hoy.","answer":false,"why":"También influyen empleo, educación, salud, vivienda, servicios y oportunidades."},{"text":"Dos comunidades con distinta disponibilidad de servicios pueden ofrecer oportunidades diferentes a sus habitantes.","answer":true}]},"id":"s01-d5-reto-10"}]}},{"missionId":"s01","version":"cnb-sexto-4c0eb6a31881abcc","lesson":{"id":"s01-ccss-1","title":"Latitud y longitud: la dirección de cada lugar","icon":"Globe","minutes":14,"gancho":"Tu casa tiene una dirección para que el cartero la encuentre. ¿Cómo le darías la \\"dirección\\" de Guatemala a alguien que está al otro lado del mundo?","objetivos":["Reconocer el ecuador, el meridiano de Greenwich, los paralelos y los meridianos","Explicar qué miden la latitud y la longitud","Ubicar un punto en un mapa cuadriculado con sus coordenadas geográficas"],"resumen":["Los paralelos son líneas imaginarias horizontales; el más importante es el ecuador (0°), que divide la Tierra en hemisferio norte y hemisferio sur.","Los meridianos son líneas imaginarias que van de polo a polo; el meridiano de Greenwich (0°) divide la Tierra en hemisferio este (oriente) y hemisferio oeste (occidente).","La latitud es la distancia en grados desde el ecuador hacia el norte o el sur (de 0° a 90°). La longitud es la distancia en grados desde Greenwich hacia el este o el oeste (de 0° a 180°).","Guatemala está aproximadamente entre los 13° y 18° de latitud norte y entre los 88° y 92° de longitud oeste."],"media":{"id":"s01-ccss-1-red","kind":"animation","title":"La red de líneas imaginarias","aspect":"16:9","duration":45,"alt":"Un globo terráqueo gira; aparecen el ecuador y los paralelos en azul, luego Greenwich y los meridianos en naranja, y finalmente un punto se ubica sobre Guatemala.","brief":"Animación 2D de 45 s. Un globo terráqueo gira despacio. (1) Aparece el ecuador en azul con la etiqueta \\"Ecuador 0°\\" y luego otros paralelos cada 30° (30° N, 60° N, 30° S, 60° S). (2) Aparece el meridiano de Greenwich en naranja \\"0°\\" y meridianos cada 30° hacia el este y el oeste. (3) Una lupa se acerca a Centroamérica y un punto marca Guatemala con la leyenda \\"aprox. 15° N, 90° O\\". Narración en español: \\"Latitud: cuánto al norte o al sur. Longitud: cuánto al este o al oeste.\\" Subtítulos. Colores planos, sin banderas."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:1.2.1"],"ambito":"conocer","title":"Líneas que no se ven, pero sirven","prompt":"Para ubicar lugares, los geógrafos dibujan sobre la Tierra una **red de líneas imaginarias**. No existen en el suelo: están en mapas y globos. Toca cada tarjeta.","media":{"id":"s01-ccss-1-hemisferios","kind":"diagram","title":"Cuatro hemisferios","aspect":"16:9","alt":"Dos globos: el primero cortado por el ecuador en norte y sur; el segundo cortado por el meridiano de Greenwich en este y oeste. Guatemala marcada en norte y oeste.","brief":"Diagrama con dos globos terráqueos lado a lado. Globo 1: el ecuador en azul grueso; mitad superior rotulada \\"Hemisferio norte\\" y mitad inferior \\"Hemisferio sur\\". Globo 2: el meridiano de Greenwich en naranja grueso; mitad izquierda \\"Hemisferio oeste (occidente)\\" y mitad derecha \\"Hemisferio este (oriente)\\". En ambos, un punto rojo pequeño sobre Guatemala con la etiqueta \\"Guatemala\\". Fondo blanco, textos grandes. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"type":"explain","props":{"icon":"Globe","body":"Guatemala está en el hemisferio **norte** (arriba del ecuador) y en el hemisferio **oeste** (a la izquierda de Greenwich).","reveal":[{"icon":"Minus","front":"Paralelos","back":"Círculos **horizontales** que rodean la Tierra. El más largo es el **ecuador (0°)**. Los paralelos llegan hasta 90° en cada polo."},{"icon":"Circle","front":"Ecuador","back":"Divide la Tierra en **hemisferio norte** y **hemisferio sur**. Pasa por países como Ecuador, Colombia y Brasil."},{"icon":"Slash","front":"Meridianos","back":"Semicírculos que van **de polo a polo**. Todos se juntan en el Polo Norte y en el Polo Sur."},{"icon":"MapPin","front":"Meridiano de Greenwich","back":"Es el meridiano **0°**. Pasa por Greenwich, en Londres (Inglaterra), y divide la Tierra en **este** y **oeste**."}]},"id":"s01-ccss-1-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:1.2.1"],"ambito":"conocer","prompt":"En una sala de cine, tu boleto dice **\\"Fila F, asiento 12\\"**. ¿Por qué necesitas **dos** datos para encontrar tu lugar?","explain":"Con un solo dato habría muchos lugares posibles. Con **dos datos que se cruzan** hay un solo lugar. La Tierra funciona igual: usamos **latitud** y **longitud**.","type":"choice","props":{"options":[{"id":"a","text":"Porque la fila dice qué tan adelante y el asiento dice qué tan a un lado: juntos marcan un solo lugar","icon":"Target"},{"id":"b","text":"Porque así el boleto se ve más bonito","icon":"Sparkles","feedback":"No es por adorno: con solo \\"fila F\\" habría muchos asientos posibles."},{"id":"c","text":"No hace falta: con la fila es suficiente","icon":"X","feedback":"En la fila F hay muchos asientos. Necesitas el número para saber cuál es el tuyo."}],"correct":["a"]},"id":"s01-ccss-1-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:1.2.1"],"prompt":"Clasifica cada descripción: ¿habla de un **paralelo** o de un **meridiano**?","hint":"Los paralelos son horizontales y nunca se tocan. Los meridianos van de un polo al otro y se juntan en los polos.","explain":"Paralelos: horizontales, miden la latitud, el principal es el ecuador. Meridianos: de polo a polo, miden la longitud, el principal es Greenwich.","type":"sort","props":{"buckets":[{"id":"par","label":"Paralelo","icon":"Minus","color":"var(--area-ccss)"},{"id":"mer","label":"Meridiano","icon":"Slash","color":"var(--c-maiz-strong)"}],"items":[{"id":"p1","text":"El ecuador","bucket":"par"},{"id":"p2","text":"Greenwich","bucket":"mer"},{"id":"p3","text":"Línea que va del Polo Norte al Polo Sur","bucket":"mer"},{"id":"p4","text":"Círculo horizontal que rodea la Tierra","bucket":"par"},{"id":"p5","text":"Se usa para medir la latitud","bucket":"par","feedback":"La latitud se cuenta desde el ecuador, recorriendo los paralelos hacia el norte o el sur."},{"id":"p6","text":"Se usa para medir la longitud","bucket":"mer"}]},"id":"s01-ccss-1-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:1.2.1"],"ambito":"conocer","title":"Latitud y longitud","prompt":"Las **coordenadas geográficas** son dos números en **grados (°)** que dicen dónde está un lugar. Toca cada tarjeta.","type":"explain","props":{"icon":"Compass","body":"Se escriben así: **15° N, 90° O**. Primero la latitud (con N o S) y luego la longitud (con E u O).","reveal":[{"icon":"ArrowUpDown","front":"Latitud","back":"Cuántos grados está un lugar **al norte (N) o al sur (S) del ecuador**. Va de 0° (ecuador) a 90° (polos)."},{"icon":"ArrowLeftRight","front":"Longitud","back":"Cuántos grados está un lugar **al este (E) o al oeste (O) de Greenwich**. Va de 0° a 180°."},{"icon":"MapPin","front":"Guatemala","back":"Está aproximadamente entre **13° y 18° N** y entre **88° y 92° O**. La capital queda cerca de **15° N, 90° O**."},{"icon":"AlertTriangle","front":"Error frecuente","back":"Escribir solo \\"15°\\" no basta: **15° N** y **15° S** son lugares muy lejanos. Siempre di la dirección."}]},"id":"s01-ccss-1-4"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:1.2.1"],"ambito":"hacer","title":"Ejemplo resuelto: leer un mapa cuadriculado","prompt":"En los mapas escolares a veces se usa una **cuadrícula**. Supongamos que en este mapa **cada cuadro mide 10°**: el eje horizontal es el ecuador y el vertical es Greenwich.","type":"worked-example","props":{"icon":"Map","problem":"Un barco está **3 cuadros a la izquierda** de Greenwich y **2 cuadros arriba** del ecuador. ¿Cuáles son sus coordenadas?","steps":[{"text":"Arriba del ecuador es **norte**. 2 cuadros × 10° = **20° N**.","why":"La latitud se cuenta hacia arriba (N) o hacia abajo (S) desde el ecuador."},{"text":"A la izquierda de Greenwich es **oeste**. 3 cuadros × 10° = **30° O**.","why":"La longitud se cuenta hacia la derecha (E) o la izquierda (O) desde Greenwich."},{"text":"Se escribe primero la latitud y luego la longitud: **20° N, 30° O**."},{"text":"En la cuadrícula del plano, ese punto es **(−3, 2)**: x negativa porque va al oeste, y positiva porque va al norte."}],"answer":"El barco está en **20° N, 30° O**.","tip":"Truco: norte y este son como los números positivos del plano; sur y oeste, como los negativos."},"id":"s01-ccss-1-5"},{"fase":"construir","areas":["ccss","mat"],"cnb":["ccss:1.2.1"],"ambito":"hacer","prompt":"Ahora tú, con ayuda. En este mapa cuadriculado **cada cuadro = 10°**. Coloca la lancha en **30° N, 20° E**.","hint":"Este = a la derecha (x positiva): 20° son 2 cuadros. Norte = arriba (y positiva): 30° son 3 cuadros.","explain":"20° E → x = 2; 30° N → y = 3. El punto es (2, 3).","type":"coordinate-map","props":{"range":{"xmin":-5,"xmax":5,"ymin":-4,"ymax":4},"task":{"kind":"place","x":2,"y":3,"emoji":"🚤","label":"la lancha"}},"id":"s01-ccss-1-6"},{"fase":"aplicar","areas":["ccss","mat"],"cnb":["ccss:1.2.1"],"ambito":"hacer","prompt":"Mismo mapa (cada cuadro = 10°). Una estación científica está en **20° S, 40° O**. Colócala.","explain":"40° O → 4 cuadros a la izquierda (x = −4). 20° S → 2 cuadros abajo (y = −2). El punto es (−4, −2).","type":"coordinate-map","props":{"range":{"xmin":-5,"xmax":5,"ymin":-4,"ymax":4},"task":{"kind":"place","x":-4,"y":-2,"emoji":"🏕️","label":"la estación"}},"id":"s01-ccss-1-7"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:1.2.1"],"ambito":"conocer","prompt":"Un lugar está en **0° de latitud**. ¿Qué sabemos seguro de él?","explain":"Latitud 0° significa que está **sobre el ecuador**. Su longitud puede ser cualquiera: por eso hay muchos lugares con latitud 0°.","type":"choice","props":{"options":[{"id":"a","text":"Está sobre el ecuador"},{"id":"b","text":"Está en el Polo Norte","feedback":"El Polo Norte está a 90° N, lo más lejos posible del ecuador."},{"id":"c","text":"Está en Greenwich","feedback":"Greenwich es la longitud 0°, no la latitud 0°."}],"correct":["a"]},"id":"s01-ccss-1-8"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:1.2.1"],"prompt":"¿Verdadero o falso? Piensa en dónde está Guatemala.","explain":"Guatemala está al norte del ecuador y al oeste de Greenwich; por eso sus coordenadas llevan N y O.","type":"true-false","props":{"statements":[{"text":"Guatemala está en el hemisferio norte.","answer":true},{"text":"Guatemala está en el hemisferio este.","answer":false,"why":"Está a la izquierda (al oeste) del meridiano de Greenwich."},{"text":"La longitud de Guatemala se escribe con la letra O (oeste).","answer":true},{"text":"Si un lugar está en 15° S, está al norte del ecuador.","answer":false,"why":"La S significa sur: está debajo del ecuador."}]},"id":"s01-ccss-1-9"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:1.2.1"],"prompt":"¿Qué mide la **longitud**?","type":"choice","props":{"options":[{"id":"a","text":"La distancia en grados al este o al oeste del meridiano de Greenwich"},{"id":"b","text":"La distancia en grados al norte o al sur del ecuador"},{"id":"c","text":"La altura de un lugar sobre el nivel del mar"}],"correct":["a"]},"id":"s01-ccss-1-10"},{"fase":"comprobar","areas":["ccss","mat"],"cnb":["ccss:1.2.1"],"prompt":"Cada cuadro = 10°. Coloca el avión en **10° N, 30° O**.","type":"coordinate-map","props":{"range":{"xmin":-5,"xmax":5,"ymin":-4,"ymax":4},"task":{"kind":"place","x":-3,"y":1,"emoji":"✈️","label":"el avión"}},"id":"s01-ccss-1-11"}],"kind":"materia","area":"ccss","day":1}},{"missionId":"s01","version":"cnb-sexto-bb7cc782fd451cf7","lesson":{"id":"s01-ef-1","title":"Huesos, músculos y articulaciones en movimiento","icon":"PersonStanding","minutes":15,"gancho":"Para patear una pelota, subir un cerro o levantar un canasto trabajan juntos huesos, músculos, tendones y ligamentos. ¿Sabes qué hace cada uno?","objetivos":["Explicar la función de huesos, músculos, tendones y ligamentos","Realizar movimientos de flexión, extensión y rotación con control","Hacer una rutina de calentamiento y estiramiento de forma segura"],"resumen":["Los huesos forman el esqueleto: sostienen el cuerpo y protegen órganos. Una persona adulta tiene 206 huesos.","Los músculos se contraen (se acortan) y jalan de los huesos para moverlos. Trabajan en parejas: cuando uno se contrae, el otro se relaja.","Los tendones unen los músculos con los huesos. Los ligamentos unen un hueso con otro en las articulaciones (rodilla, codo, tobillo).","Flexión: doblar una articulación (cerrar el ángulo). Extensión: estirarla (abrir el ángulo). Rotación: girar una parte del cuerpo sobre su eje.","Antes de una actividad intensa se calienta el cuerpo; al final se estira suave, sin rebotes ni dolor, y se toma agua."],"media":{"id":"s01-ef-1-sistema","kind":"animation","title":"Cómo se mueve tu brazo","aspect":"16:9","duration":50,"alt":"Un brazo transparente muestra el hueso, el bíceps y el tríceps. Al doblar el codo, el bíceps se acorta y el tríceps se estira; al estirar el brazo, ocurre lo contrario. Se resaltan los tendones y un ligamento del codo.","brief":"Animación 2D anatómica sencilla, estilo libro escolar, 50 s. (1) Brazo de una niña levantando un canasto pequeño; vista transparente con húmero, radio y cúbito en beige, bíceps rojo delante y tríceps rojo detrás. (2) Flexión del codo: el bíceps se engrosa y acorta (rótulo \\"se contrae\\"), el tríceps se alarga (\\"se relaja\\"); flecha \\"flexión\\". (3) Extensión: al revés; flecha \\"extensión\\". (4) Zoom al codo: tendones en blanco uniendo músculo-hueso (rótulo \\"tendón\\"), bandas que unen hueso-hueso (rótulo \\"ligamento\\"). (5) Giro de la muñeca: \\"rotación\\". Narración en español, subtítulos. Sin sangre ni detalles gráficos."},"steps":[{"fase":"explorar","areas":["ef","cnt"],"cnb":["ef:1.1.6"],"ambito":"conocer","title":"El equipo del movimiento","prompt":"Cada movimiento que haces es trabajo en equipo. Toca cada tarjeta para conocer a los integrantes.","type":"explain","props":{"icon":"PersonStanding","body":"El **aparato locomotor** está formado por **huesos**, **articulaciones** y **músculos**, unidos por **tendones** y **ligamentos**.","reveal":[{"icon":"Bone","front":"Huesos","back":"Forman el **esqueleto**: sostienen el cuerpo y protegen órganos (el cráneo protege el cerebro; las costillas, el corazón y los pulmones). Una persona adulta tiene **206**."},{"icon":"Dumbbell","front":"Músculos","back":"Se **contraen** (se acortan) y **jalan** de los huesos. Trabajan en **parejas**: el bíceps dobla el codo y el tríceps lo estira."},{"icon":"Link","front":"Tendones","back":"Cordones fuertes que **unen el músculo con el hueso**. El más grueso es el tendón de Aquiles, en el talón."},{"icon":"Link2","front":"Ligamentos","back":"Bandas que **unen un hueso con otro** en las **articulaciones** (rodilla, tobillo, codo) y las mantienen firmes."}]},"id":"s01-ef-1-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.1.6"],"ambito":"conocer","prompt":"Dobla tu brazo como mostrando tu \\"fuerza\\" y toca con la otra mano la parte de adelante del brazo. ¿Qué sientes?","explain":"Sientes el **bíceps** endurecerse y abultarse: se **contrae** (se acorta) y jala el hueso del antebrazo hacia arriba. Así funcionan todos los músculos que mueven el esqueleto.","type":"choice","props":{"options":[{"id":"a","text":"Se pone duro y abultado","icon":"Dumbbell"},{"id":"b","text":"Se queda igual de blando","icon":"Minus","feedback":"Prueba de nuevo apretando el puño: el músculo de adelante se endurece al doblar el codo."},{"id":"c","text":"Se siente el hueso moviéndose solo","icon":"Bone","feedback":"Los huesos no se mueven solos: los músculos los jalan."}],"correct":["a"]},"id":"s01-ef-1-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.1.2"],"ambito":"hacer","title":"Tres movimientos básicos","prompt":"Las **articulaciones** son los lugares donde se unen los huesos y donde el cuerpo se dobla o gira. Toca cada tarjeta y **haz el movimiento**.","media":{"id":"s01-ef-1-movimientos","kind":"video","title":"Flexión, extensión y rotación","aspect":"9:16","duration":40,"alt":"Un niño en el patio muestra en cámara lenta: dobla y estira el codo y la rodilla, y gira los hombros, el cuello y la cintura.","brief":"Video vertical de 40 s, patio de escuela, fondo despejado. Un niño con ropa deportiva sencilla (rostro no protagonista) demuestra en cámara lenta: flexión y extensión de codo, flexión y extensión de rodilla (sentado en una silla), rotación de hombros hacia atrás, rotación suave de cuello (medio círculo, sin echar la cabeza atrás), rotación de cintura con manos en la cadera. Rótulos grandes \\"flexión\\", \\"extensión\\", \\"rotación\\" y un arco que muestra el ángulo que se cierra o se abre."},"type":"explain","props":{"icon":"RotateCw","body":"Muévete **despacio y con control**. Si algo duele, detente.","reveal":[{"icon":"CornerDownRight","front":"Flexión","back":"**Doblar** una articulación: el ángulo se **cierra**. Ejemplo: doblar el codo para llevar una tortilla a la boca."},{"icon":"MoveHorizontal","front":"Extensión","back":"**Estirar** una articulación: el ángulo se **abre**. Ejemplo: estirar la pierna al patear."},{"icon":"RotateCw","front":"Rotación","back":"**Girar** una parte del cuerpo sobre su eje. Ejemplo: girar los hombros, la muñeca o la cintura."}]},"id":"s01-ef-1-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.1.2","ef:1.1.6"],"ambito":"conocer","title":"Ejemplo resuelto: analizar un movimiento","prompt":"Mira cómo se analiza un movimiento de la vida diaria.","type":"worked-example","props":{"icon":"Search","problem":"Doña Rosa saca agua del pozo: **jala la cuerda** doblando los brazos y luego **vuelve a estirarlos** para agarrar más abajo. ¿Qué pasa en su codo?","steps":[{"text":"Al jalar, el codo se **dobla**: es una **flexión**. El **bíceps** se contrae y jala el antebrazo."},{"text":"Los **tendones** transmiten la fuerza del bíceps al hueso.","why":"Sin tendones, el músculo se contraería pero no movería el hueso."},{"text":"Al estirar el brazo, el codo se abre: es una **extensión**. Ahora trabaja el **tríceps** y el bíceps se relaja."},{"text":"Mientras tanto, los **ligamentos** del codo mantienen unidos los huesos para que la articulación no se salga de lugar."}],"answer":"Jalar = **flexión** (bíceps); estirar = **extensión** (tríceps). Tendones transmiten la fuerza y ligamentos dan firmeza.","tip":"Para saber si es flexión o extensión, fíjate si el ángulo de la articulación se cierra o se abre."},"id":"s01-ef-1-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.1.6"],"ambito":"conocer","prompt":"Une cada parte con su función.","hint":"Tendón: músculo-hueso. Ligamento: hueso-hueso.","explain":"Huesos sostienen, músculos mueven, tendones unen músculo con hueso y ligamentos unen hueso con hueso.","type":"match","props":{"leftTitle":"Parte","rightTitle":"Función","pairs":[{"id":"h","left":"Hueso","leftIcon":"Bone","right":"Sostiene el cuerpo y protege órganos"},{"id":"m","left":"Músculo","leftIcon":"Dumbbell","right":"Se contrae y jala para mover"},{"id":"t","left":"Tendón","leftIcon":"Link","right":"Une el músculo con el hueso"},{"id":"l","left":"Ligamento","leftIcon":"Link2","right":"Une un hueso con otro"}]},"id":"s01-ef-1-5"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.1.2","ef:1.1.6"],"ambito":"hacer","prompt":"¡A moverte! Mide tu pulso en reposo y luego haz la rutina en tres partes. **Calentamiento (1 min):** trote suave en tu lugar y rotación de hombros, muñecas y tobillos. **Parte principal (1 min):** 10 sentadillas (flexión y extensión de rodillas), 10 flexiones de codo levantando dos botellas con agua y 10 rotaciones de cintura. **Estiramiento (1 min):** estira brazos y piernas, 15 s cada uno, suave y sin rebotes. **Poco espacio:** todo se hace en tu lugar. **Adaptación:** si usas silla de ruedas o no puedes estar de pie, haz la rutina sentado con brazos, tronco y cuello.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después del calentamiento","exercise":{"name":"Trote suave y rotaciones","icon":"RotateCw","seconds":60}},{"label":"Después de la parte principal","exercise":{"name":"Sentadillas, flexiones de codo y rotación de cintura","icon":"Dumbbell","seconds":60}},{"label":"Después del estiramiento","exercise":{"name":"Estiramiento suave de brazos y piernas","icon":"PersonStanding","seconds":60}}]},"id":"s01-ef-1-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.1.2"],"ambito":"hacer","prompt":"Clasifica cada movimiento de la rutina: ¿flexión, extensión o rotación?","explain":"Si el ángulo se cierra es flexión; si se abre, extensión; si la parte gira, rotación.","type":"sort","props":{"buckets":[{"id":"f","label":"Flexión","icon":"CornerDownRight","color":"var(--area-ef)"},{"id":"e","label":"Extensión","icon":"MoveHorizontal","color":"var(--c-ok)"},{"id":"r","label":"Rotación","icon":"RotateCw","color":"var(--c-maiz-strong)"}],"items":[{"id":"x1","text":"Bajar en una sentadilla (doblar las rodillas)","bucket":"f"},{"id":"x2","text":"Subir de la sentadilla (estirar las rodillas)","bucket":"e"},{"id":"x3","text":"Girar los hombros hacia atrás","bucket":"r"},{"id":"x4","text":"Levantar la botella doblando el codo","bucket":"f"},{"id":"x5","text":"Girar la cintura con las manos en la cadera","bucket":"r"},{"id":"x6","text":"Estirar la pierna para patear","bucket":"e"}]},"id":"s01-ef-1-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.1.6"],"ambito":"ser","prompt":"Cuida tu cuerpo. ¿Verdadero o falso?","explain":"Calentar prepara músculos y articulaciones; estirar suave al final ayuda a relajarlos; el agua repone lo que pierdes al sudar.","type":"true-false","props":{"statements":[{"text":"El calentamiento prepara los músculos y articulaciones para el esfuerzo.","answer":true},{"text":"Al estirar hay que rebotar fuerte para llegar más lejos.","answer":false,"why":"Los rebotes pueden lastimar músculos y tendones. Se estira suave y se sostiene."},{"text":"Si una articulación duele durante el ejercicio, es mejor detenerse y avisar a una persona adulta.","answer":true},{"text":"Después de hacer ejercicio conviene tomar agua.","answer":true}]},"id":"s01-ef-1-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.1.6"],"prompt":"¿Qué une los **músculos** con los **huesos**?","type":"choice","props":{"options":[{"id":"a","text":"Los ligamentos"},{"id":"b","text":"Los tendones"},{"id":"c","text":"Las articulaciones"}],"correct":["b"]},"id":"s01-ef-1-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.1.2"],"prompt":"Al **estirar la rodilla** para levantarte de una silla, haces una…","type":"choice","props":{"options":[{"id":"a","text":"Flexión"},{"id":"b","text":"Extensión"},{"id":"c","text":"Rotación"}],"correct":["b"]},"id":"s01-ef-1-10"}],"kind":"materia","area":"ef","day":2}},{"missionId":"s01","version":"cnb-sexto-c32deeb24010d5ff","lesson":{"id":"s01-l2-2","title":"Escucho, anticipo e identifico la intención","icon":"Ear","minutes":15,"gancho":"Las primeras palabras y el tono pueden anunciar que viene y para que se dice.","objetivos":["Anticipar el contenido de un mensaje oral e identificar su intención como hecho u opinión"],"resumen":["Anticipar usa las primeras palabras, el tono y el tema.","Un hecho comunica algo comprobable; una opinión expresa una valoración.","Después de anticipar, se escucha el final para confirmar o corregir."],"media":{"id":"s01-l2-2-ruta-escucha","kind":"diagram","title":"Ruta para escuchar con intención","aspect":"16:9","alt":"Tres pasos: anticipar con pistas, escuchar el cierre e identificar hecho u opinión.","brief":"Diagrama educativo 1600x900 con tres pasos numerados: pistas iniciales para anticipar, escucha completa para confirmar o corregir, e intención de hecho comprobable u opinión valorativa. Usar ondas de audio e iconos descriptivos, texto grande, alto contraste, patrones además de color y orden de lectura accesible."},"steps":[{"fase":"explorar","areas":["l2"],"cnb":["l2:1.2.4","l2:1.2.6"],"prompt":"Cuando escuchas un mensaje oral, puedes anticipar lo que seguirá. También puedes reconocer su intención: ¿comunica un hecho o una opinión?","type":"explain","props":{"icon":"Ear","body":"Usa inicio, tono y tema para **anticipar**. Luego pregunta: ¿la intención es informar un **hecho comprobable** o expresar una **opinión**? Escucha el final para verificar."},"id":"s01-l2-2-1"},{"fase":"construir","areas":["l2"],"cnb":["l2:1.2.4","l2:1.2.6"],"title":"Dos decisiones al escuchar","prompt":"Lee las dos decisiones que tomas al escuchar: anticipar el contenido del mensaje oral y reconocer su intención (hecho u opinión).","type":"explain","props":{"icon":"GitCompare","body":"\\"El mapa registra...\\" suele continuar con un dato: hecho. \\"Me parece que este camino...\\" anuncia una valoración: opinión. La anticipación es provisional y puede corregirse."},"id":"s01-l2-2-2"},{"fase":"construir","areas":["l2"],"cnb":["l2:1.2.4","l2:1.2.6"],"title":"Escucha un ejemplo","prompt":"Mira cómo se anticipa un mensaje oral y cómo se reconoce si su intención es comunicar un hecho o una opinión.","type":"worked-example","props":{"icon":"Radio","problem":"Se oye: \\"Según el mapa, la clínica queda...\\"","steps":[{"text":"\\"Según el mapa\\" permite anticipar una ubicación."},{"text":"El cierre \\"al oeste de la plaza\\" confirma el dato."},{"text":"Su intención es informar un hecho comprobable, no una opinión."}],"answer":"Anticipación: ubicación. Intención: hecho."},"id":"s01-l2-2-3"},{"fase":"construir","areas":["l2"],"cnb":["l2:1.2.4","l2:1.2.6"],"prompt":"Escucha el mensaje oral. Anticipa cómo terminará y decide si su intención es comunicar un hecho o una opinión.","hint":"Atiende al inicio y decide si el cierre puede comprobarse.","explain":"El inicio anuncia una ubicación verificable en el mapa.","media":{"id":"s01-l2-2-guia","kind":"audio","title":"Ubicación en San Lucas","duration":12,"alt":"Audio breve de un mensaje oral sobre un lugar de la comunidad; la transcripcion se ofrece después de responder.","brief":"Audio MP3 de una voz adulta, acento guatemalteco y ritmo pausado. Texto exacto: \\"En el mapa de San Lucas, el puesto de salud aparece... al norte del mercado.\\" Dejar una pausa de 3 segundos despues de la primera oracion para anticipar y 2 segundos de silencio final. Duracion: 12 s. Transcripcion disponible despues de responder o por mediacion docente para accesibilidad. Reemplazo: public/media/s01-l2-2-guia.mp3."},"type":"choice","props":{"options":[{"id":"a","text":"Una ubicación; intención de comunicar un hecho"},{"id":"b","text":"Un gusto; intención de expresar una opinión"},{"id":"c","text":"Una receta; intención de ordenar pasos"}],"correct":["a"]},"id":"s01-l2-2-4"},{"fase":"construir","areas":["l2"],"cnb":["l2:1.2.4","l2:1.2.6"],"prompt":"Escucha otro mensaje oral. Anticipa su cierre y reconoce su intención: ¿hecho u opinión?","hint":"Una expresión de preferencia anuncia una valoración.","explain":"\\"Para mi\\" orienta hacia una opinión, aunque el lugar exista.","media":{"id":"s01-l2-2-guia-opinion","kind":"audio","title":"Opinión sobre una ruta","duration":12,"alt":"Audio breve de un mensaje oral sobre un lugar de la comunidad; la transcripcion se ofrece después de responder.","brief":"Audio MP3 de una voz adulta, acento guatemalteco y ritmo pausado. Texto exacto: \\"Para mi, la ruta junto al parque es... la más agradable del pueblo.\\" Dejar una pausa de 3 segundos despues de la primera oracion para anticipar y 2 segundos de silencio final. Duracion: 12 s. Transcripcion disponible despues de responder o por mediacion docente para accesibilidad. Reemplazo: public/media/s01-l2-2-guia-opinion.mp3."},"type":"true-false","props":{"statements":[{"text":"Se anticipa una valoración.","answer":true},{"text":"La intención es expresar una opinión.","answer":true},{"text":"El cierre comunica una medida comprobable.","answer":false}]},"id":"s01-l2-2-5"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:1.2.4","l2:1.2.6"],"prompt":"Escucha el mensaje oral, anticipa la información final y reconoce su intención: ¿hecho u opinión?","media":{"id":"s01-l2-2-aplica","kind":"audio","title":"Dato sobre un puente","duration":12,"alt":"Audio breve de un mensaje oral sobre un lugar de la comunidad; la transcripcion se ofrece después de responder.","brief":"Audio MP3 de una voz adulta, acento guatemalteco y ritmo pausado. Texto exacto: \\"El registro de la alcaldia indica que el puente mide... doce metros de largo.\\" Dejar una pausa de 3 segundos despues de la primera oracion para anticipar y 2 segundos de silencio final. Duracion: 12 s. Transcripcion disponible despues de responder o por mediacion docente para accesibilidad. Reemplazo: public/media/s01-l2-2-aplica.mp3."},"type":"choice","props":{"options":[{"id":"a","text":"Una medida comprobable; hecho"},{"id":"b","text":"Un gusto personal; opinión"},{"id":"c","text":"Una invitación; opinión"}],"correct":["a"]},"id":"s01-l2-2-6"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:1.2.4","l2:1.2.6"],"prompt":"Ahora sin ayuda: escucha, anticipa el cierre del mensaje oral y reconoce su intención: ¿hecho u opinión?","media":{"id":"s01-l2-2-aplica-opinion","kind":"audio","title":"Valoración sobre la plaza","duration":12,"alt":"Audio breve de un mensaje oral sobre un lugar de la comunidad; la transcripcion se ofrece después de responder.","brief":"Audio MP3 de una voz adulta, acento guatemalteco y ritmo pausado. Texto exacto: \\"Creo que la plaza central es... el sitio más acogedor para reunirse.\\" Dejar una pausa de 3 segundos despues de la primera oracion para anticipar y 2 segundos de silencio final. Duracion: 12 s. Transcripcion disponible despues de responder o por mediacion docente para accesibilidad. Reemplazo: public/media/s01-l2-2-aplica-opinion.mp3."},"type":"true-false","props":{"statements":[{"text":"El inicio permite anticipar una valoración.","answer":true},{"text":"La intención es expresar una opinión.","answer":true},{"text":"El cierre es una coordenada comprobable.","answer":false}]},"id":"s01-l2-2-7"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:1.2.4","l2:1.2.6"],"prompt":"Escucha, anticipa el final del mensaje oral y reconoce su intención: ¿hecho u opinión?","media":{"id":"s01-l2-2-salida-a","kind":"audio","title":"Símbolo de un mapa","duration":12,"alt":"Audio breve de un mensaje oral sobre un lugar de la comunidad; la transcripcion se ofrece después de responder.","brief":"Audio MP3 de una voz adulta, acento guatemalteco y ritmo pausado. Texto exacto: \\"La clave del mapa usa una cruz para representar... el centro de salud.\\" Dejar una pausa de 3 segundos despues de la primera oracion para anticipar y 2 segundos de silencio final. Duracion: 12 s. Transcripcion disponible despues de responder o por mediacion docente para accesibilidad. Reemplazo: public/media/s01-l2-2-salida-a.mp3."},"type":"choice","props":{"options":[{"id":"a","text":"El significado de un símbolo; hecho"},{"id":"b","text":"El lugar más bonito; opinión"},{"id":"c","text":"Una preferencia de color; opinión"}],"correct":["a"]},"id":"s01-l2-2-8"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:1.2.4","l2:1.2.6"],"prompt":"Escucha un mensaje oral nuevo, anticipa su cierre y reconoce su intención: ¿hecho u opinión?","media":{"id":"s01-l2-2-salida-b","kind":"audio","title":"Valoración sobre un mirador","duration":12,"alt":"Audio breve de un mensaje oral sobre un lugar de la comunidad; la transcripcion se ofrece después de responder.","brief":"Audio MP3 de una voz adulta, acento guatemalteco y ritmo pausado. Texto exacto: \\"En mi opinión, el mirador del cerro es... la mejor parada del recorrido.\\" Dejar una pausa de 3 segundos despues de la primera oracion para anticipar y 2 segundos de silencio final. Duracion: 12 s. Transcripcion disponible despues de responder o por mediacion docente para accesibilidad. Reemplazo: public/media/s01-l2-2-salida-b.mp3."},"type":"true-false","props":{"statements":[{"text":"Se anticipa una valoración del mirador.","answer":true},{"text":"La intención es expresar una opinión.","answer":true},{"text":"El cierre aporta una cantidad medible.","answer":false}]},"id":"s01-l2-2-9"}],"kind":"materia","area":"l2","day":4}},{"missionId":"s01","version":"cnb-sexto-3f73e7ccd35c2d25","lesson":{"id":"s01-l1-5","title":"Escribir un correo electrónico claro y respetuoso","icon":"Mail","minutes":14,"gancho":"Antes, para comunicarse con alguien lejos, las personas escribían cartas que tardaban semanas en llegar. Hoy un correo llega en segundos. ¿Se escribe igual?","objetivos":["Reconocer las partes de un correo electrónico","Escribir un asunto claro y un mensaje completo y cortés","Cuidar tus datos personales al usar el correo"],"resumen":["Partes de un correo: destinatario (Para), asunto, saludo, cuerpo del mensaje, despedida y firma. Se puede adjuntar un archivo con el ícono del clip.","El asunto dice en pocas palabras de qué trata el correo: \\"Solicitud de información sobre la biblioteca\\".","El cuerpo explica quién escribe, qué necesita y para qué, con palabras completas y cortesía.","Nunca compartas contraseñas ni datos personales con personas que no conoces. Si algo te incomoda, cuéntaselo a un adulto de confianza."],"media":{"id":"s01-l1-5-correo","kind":"diagram","title":"Las partes de un correo","aspect":"4:3","alt":"Ventana de correo electrónico con flechas que señalan: Para, Asunto, saludo, cuerpo, despedida, firma y el ícono del clip para adjuntar.","brief":"Diagrama de una ventana de correo genérica (sin marca real). Campos rotulados con flechas de colores: \\"Para\\" (correo inventado biblioteca@ejemplo.org), \\"Asunto: Solicitud de libros sobre volcanes\\", saludo \\"Buenos días:\\", cuerpo de tres líneas, despedida \\"Atentamente,\\", firma \\"Julio Tzoc, 6.º grado, Escuela Oficial Rural Mixta\\" y el ícono de clip con la etiqueta \\"Adjuntar\\". Estilo plano, colores suaves, letra grande legible en teléfono. Dimensiones: 1200x900."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":["l1:3.4.2"],"ambito":"conocer","title":"Las partes de un correo","prompt":"Observa el diagrama y toca cada tarjeta para conocer las partes de un correo electrónico.","type":"explain","props":{"icon":"Mail","body":"Un correo electrónico es parecido a una carta, pero viaja por internet. Tiene partes que ayudan a que llegue a la persona correcta y se entienda.","reveal":[{"icon":"AtSign","front":"Para (destinatario)","back":"La **dirección de correo** de quien lo recibe. Revísala letra por letra: un error y el correo no llega."},{"icon":"Tag","front":"Asunto","back":"El **tema** en pocas palabras. Ejemplo: \\"Consulta sobre la tarea de Ciencias\\"."},{"icon":"Hand","front":"Saludo","back":"Formal: \\"Buenos días, señora directora:\\" / \\"Estimado señor Pérez:\\". Informal (familia): \\"¡Hola, tía Rosa!\\"."},{"icon":"AlignJustify","front":"Cuerpo","back":"El mensaje: **quién eres**, **qué necesitas o quieres contar** y **para qué**. Párrafos cortos y palabras completas."},{"icon":"PenLine","front":"Despedida y firma","back":"Despedida: \\"Atentamente,\\" / \\"Muchas gracias,\\" / \\"Un abrazo,\\". Firma: tu nombre y, si es formal, tu grado y escuela."}]},"id":"s01-l1-5-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:3.4.2"],"ambito":"conocer","prompt":"La directora recibe muchos correos al día. ¿Cuál de estos **asuntos** le ayuda a saber de qué trata el mensaje antes de abrirlo?","explain":"Un buen asunto es corto y dice exactamente de qué trata el correo. Así la persona sabe si es urgente y lo encuentra fácilmente después.","type":"choice","props":{"options":[{"id":"a","text":"\\"Hola\\"","icon":"Mail","feedback":"\\"Hola\\" no dice nada sobre el tema del correo."},{"id":"b","text":"\\"Solicitud de permiso para la feria de ciencias\\"","icon":"MailCheck"},{"id":"c","text":"\\"URGENTE!!!!!\\"","icon":"Megaphone","feedback":"Las mayúsculas y los signos repetidos parecen gritos, y no dicen el tema."}],"correct":["b"]},"id":"s01-l1-5-2"},{"fase":"construir","areas":["l1"],"cnb":["l1:3.4.2"],"ambito":"hacer","prompt":"Ordena las partes del correo de Julio, de arriba hacia abajo.","hint":"Primero va a quién y sobre qué; luego el saludo, el mensaje y, al final, la despedida y la firma.","explain":"Este orden es el mismo en casi todos los correos: te ayuda a no olvidar ninguna parte.","type":"order","props":{"labels":{"start":"Arriba","end":"Abajo"},"items":[{"id":"p1","text":"Para: biblioteca.municipal@ejemplo.org"},{"id":"p2","text":"Asunto: Solicitud de libros sobre volcanes"},{"id":"p3","text":"Buenos días:"},{"id":"p4","text":"Soy estudiante de sexto grado y estoy preparando una exposición sobre los volcanes de Guatemala. ¿Tienen libros sobre el tema que pueda consultar?"},{"id":"p5","text":"Atentamente,"},{"id":"p6","text":"Julio Tzoc, 6.º grado"}]},"id":"s01-l1-5-3"},{"fase":"construir","areas":["l1"],"cnb":["l1:3.4.2"],"ambito":"hacer","title":"Ejemplo resuelto: de mensaje apurado a correo claro","prompt":"Mira cómo Andrea mejora su correo paso a paso.","type":"worked-example","props":{"icon":"MailCheck","problem":"Primer intento de Andrea al comité de la feria: Asunto: \\"hola\\". Cuerpo: \\"q dia es la feria y si puedo llevar mi proyecto de plantas\\".","steps":[{"text":"Escribe un **asunto** que diga el tema: \\"Consulta sobre la feria escolar\\"."},{"text":"Agrega un **saludo** formal: \\"Buenas tardes, estimado comité:\\".","why":"El comité no es su amigo cercano: el saludo formal muestra respeto."},{"text":"Se **presenta**: \\"Soy Andrea López, de sexto grado sección A.\\"","why":"Quien lee necesita saber quién escribe."},{"text":"Escribe su **pregunta completa** y con signos: \\"¿Qué día será la feria? ¿Puedo participar con mi proyecto sobre el cuidado de las plantas?\\"","why":"Palabras completas y signos de interrogación de apertura y cierre."},{"text":"Cierra con **despedida y firma**: \\"Muchas gracias. Atentamente, Andrea López.\\""}],"answer":"Un correo con asunto claro, saludo, presentación, preguntas completas, despedida y firma.","tip":"Antes de enviar, léelo como si fueras quien lo recibe: ¿se entiende sin que tengas que explicar nada más?"},"id":"s01-l1-5-4"},{"fase":"construir","areas":["l1"],"cnb":["l1:3.4.2"],"ambito":"hacer","prompt":"Este correo va dirigido a la señora alcaldesa auxiliar, pero tiene palabras **demasiado informales**. Tócalas.","hint":"Busca abreviaturas y expresiones que usarías solo con amigos.","explain":"\\"Q onda\\", \\"xq\\", \\"porfa\\" y \\"bye\\" son informales. En un correo formal se escribe: \\"Buenos días\\", \\"porque\\", \\"por favor\\" y \\"Atentamente\\".","type":"highlight","props":{"target":"palabras informales","text":"{Q onda}, señora alcaldesa auxiliar. Le escribimos {xq} queremos limpiar el parque de la aldea el sábado. ¿Nos podría prestar escobas y bolsas, {porfa}? {Bye}. Estudiantes de sexto grado."},"id":"s01-l1-5-5"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:3.4.2"],"ambito":"hacer","prompt":"Vas a mandar por correo tu tarea de Ciencias Sociales a tu maestro. ¿Qué **asunto** y qué **ícono** usas para enviar el archivo?","explain":"El asunto dice qué es y de quién; el clip sirve para adjuntar el archivo.","type":"choice","props":{"options":[{"id":"a","text":"Asunto: \\"Tarea de Ciencias Sociales – Luis Chávez, 6.º B\\" + ícono del clip","icon":"Paperclip"},{"id":"b","text":"Asunto: \\"aquí está\\" + ícono de la lupa","icon":"Search","feedback":"El asunto no dice qué es, y la lupa sirve para buscar, no para adjuntar."},{"id":"c","text":"Asunto: vacío + ícono del bote de basura","icon":"Trash2","feedback":"¡El bote de basura elimina! Y un asunto vacío confunde."}],"correct":["a"]},"id":"s01-l1-5-6"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:3.4.2"],"ambito":"ser","prompt":"Sobre el uso seguro del correo, ¿verdadero o falso?","explain":"Usar la tecnología también implica cuidarnos: nuestros datos son valiosos.","type":"true-false","props":{"statements":[{"text":"Si un desconocido te pide tu contraseña por correo, debes dársela para que no se enoje.","answer":false,"why":"Tu contraseña es solo tuya. Nadie que te quiera ayudar te la pedirá por correo."},{"text":"Si recibes un mensaje que te incomoda, es bueno contárselo a un adulto de confianza.","answer":true},{"text":"Revisar la dirección del destinatario antes de enviar evita que el correo llegue a otra persona.","answer":true}]},"id":"s01-l1-5-7"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:3.4.2"],"ambito":"hacer","prompt":"Escribe un correo a un familiar que viva en otro lugar (otro municipio, departamento o país). Invítalo a contarte **cómo es el lugar donde vive** para comparar con tu exposición \\"Nuestro lugar en mapas y palabras\\". Incluye asunto, saludo, cuerpo, despedida y firma.","type":"short-answer","props":{"minWords":45,"placeholder":"Asunto: …\\n\\nSaludo…\\n\\nCuerpo…\\n\\nDespedida y firma…","model":"Asunto: Quiero conocer tu lugar\\n\\n¡Hola, tío Mario!\\n\\nEstoy preparando una exposición en la escuela llamada \\"Nuestro lugar en mapas y palabras\\". Yo voy a hablar de Quetzaltenango, pero me gustaría compararlo con Petén, donde vives tú. ¿Me podrías contar cómo es el clima, qué se cultiva y qué te gusta más de ahí? Si tienes una foto, me ayudaría mucho.\\n\\nMuchas gracias. Un abrazo,\\nValeria","rubric":["Escribí un asunto que dice el tema","Tiene saludo, cuerpo, despedida y firma","Expliqué qué necesito y para qué","Escribí palabras completas, sin abreviaturas","Usé signos de interrogación de apertura y cierre (¿…?)"]},"id":"s01-l1-5-8"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:3.4.2"],"prompt":"Ordena las partes de un correo electrónico, de arriba hacia abajo.","type":"order","props":{"labels":{"start":"Arriba","end":"Abajo"},"items":[{"id":"q1","text":"Asunto"},{"id":"q2","text":"Saludo"},{"id":"q3","text":"Cuerpo del mensaje"},{"id":"q4","text":"Despedida y firma"}]},"id":"s01-l1-5-9"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:2.1.6"],"prompt":"Repaso de la semana: para empezar una exposición y **atrapar la atención**, ¿qué conviene más?","type":"choice","props":{"options":[{"id":"a","text":"Una pregunta o un dato curioso sobre el tema"},{"id":"b","text":"Pedir disculpas por estar nervioso"},{"id":"c","text":"Leer el título de la hoja"}],"correct":["a"]},"id":"s01-l1-5-10"},{"fase":"reflexionar","areas":["l1"],"cnb":[],"ambito":"ser","prompt":"Mira hacia atrás en tu semana de Comunicación y Lenguaje.","type":"reflection","props":{"statements":["Uso mi voz (volumen, pausas, cambios) para que me escuchen","Uso gestos y mirada que acompañan lo que digo","Interpreto íconos y elijo un lenguaje formal o informal según a quién escribo","Escribo un correo con todas sus partes"],"commitments":["Presentaré mi exposición \\"Nuestro lugar en mapas y palabras\\" a mi familia","Revisaré a quién escribo antes de enviar un mensaje","Evitaré escribir en mayúsculas para no \\"gritar\\" en los chats"]},"id":"s01-l1-5-11"}],"kind":"materia","area":"l1","day":5}},{"missionId":"s01","version":"cnb-sexto-1cbb79687ea2c18c","lesson":{"id":"s01-ef-2","title":"Mi lado dominante y mi equilibrio","icon":"Hand","minutes":15,"gancho":"¿Con qué mano escribes, lanzas una pelota o te cepillas los dientes? ¿Y podrías hacerlo igual de bien con la otra?","objetivos":["Identificar tu mano dominante y ejercitarla, sin olvidar la otra mano","Diferenciar el equilibrio estático del dinámico","Mejorar tu equilibrio con una base amplia, el centro de gravedad bajo y la mirada fija"],"resumen":["La lateralidad es la preferencia por usar un lado del cuerpo. El lado dominante es el que usamos con más fuerza y precisión: la mayoría de personas son diestras; otras son zurdas. Ambas son normales.","Ejercitar la mano dominante mejora la precisión; practicar también con la otra mano da más habilidad y equilibrio al cuerpo.","Equilibrio estático: mantener una postura sin moverse (pararse en un pie). Equilibrio dinámico: mantenerlo mientras te mueves (caminar sobre una línea).","Para tener más equilibrio: base de apoyo amplia, centro de gravedad bajo (rodillas un poco dobladas), brazos abiertos y la mirada fija en un punto."],"media":{"id":"s01-ef-2-equilibrio","kind":"video","title":"Equilibrio quieto y en movimiento","aspect":"9:16","duration":45,"alt":"Una niña se para en un pie con los brazos abiertos y la mirada fija; luego camina sobre una línea en el suelo con un libro en la cabeza.","brief":"Video vertical de 45 s en un patio o salón. Parte 1 \\"Equilibrio estático\\": una niña (ropa deportiva, rostro no protagonista) se para en un pie, primero con brazos pegados (se tambalea) y luego con brazos abiertos y mirada fija en un punto (se estabiliza); rótulos \\"brazos abiertos\\", \\"mira un punto\\". Parte 2 \\"Equilibrio dinámico\\": camina sobre una línea de yeso o cinta, de talón a punta, con un cuaderno sobre la cabeza. Parte 3: un niño en silla de ruedas hace equilibrio del tronco con una pelota sobre las piernas. Aviso \\"Hazlo en suelo plano y despejado\\". Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:1.2.1"],"ambito":"conocer","title":"La lateralidad","prompt":"Nuestro cuerpo tiene dos lados, pero casi siempre **preferimos uno**. Toca cada tarjeta.","type":"explain","props":{"icon":"Hand","body":"La **lateralidad** es la preferencia por usar un lado del cuerpo: mano, pie, ojo y oído.","reveal":[{"icon":"Hand","front":"Lado dominante","back":"Es el que usas con **más fuerza y precisión**. Si es la derecha eres **diestro/a**; si es la izquierda, **zurdo/a**."},{"icon":"Users","front":"Todos somos distintos","back":"La mayoría de las personas son diestras, pero ser zurdo es **igual de normal**. Nadie debe obligarte a cambiar de mano."},{"icon":"Target","front":"Reforzar la dominante","back":"Practicar lanzamientos, botes y agarres con tu mano dominante mejora tu **precisión** en juegos y deportes."},{"icon":"RefreshCw","front":"Entrenar la otra","back":"Practicar también con la mano no dominante te da **más opciones** en el juego y equilibra tu cuerpo."}]},"id":"s01-ef-2-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.2.1"],"ambito":"conocer","prompt":"Haz una prueba rápida: **lanza una bolita de papel** a un bote con una mano y luego con la otra, 3 veces cada una. Casi todas las personas aciertan más con una mano. ¿Por qué crees que pasa?","explain":"Acertamos más con la mano **dominante**: la que el cerebro prefiere y ha entrenado más. Hoy vas a ejercitarla y también a darle práctica a la otra.","type":"choice","props":{"options":[{"id":"a","text":"Porque es la mano que preferimos y más hemos practicado","icon":"Target"},{"id":"b","text":"Porque esa mano tiene más huesos","icon":"Bone","feedback":"Las dos manos tienen los mismos huesos. La diferencia está en la práctica y en la preferencia del cerebro."},{"id":"c","text":"Por pura suerte","icon":"Sparkles","feedback":"Si repites la prueba muchas veces, casi siempre gana la misma mano: no es suerte."}],"correct":["a"]},"id":"s01-ef-2-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.2.4"],"ambito":"conocer","title":"Dos tipos de equilibrio","prompt":"El **equilibrio** es la capacidad de mantener el cuerpo estable sin caerse. Mira el video y toca cada tarjeta.","type":"explain","props":{"icon":"Scale","body":"Tu cuerpo tiene un **centro de gravedad** (un punto cerca del ombligo) que debe quedar **encima de tu base de apoyo** (los pies).","reveal":[{"icon":"PersonStanding","front":"Equilibrio estático","back":"Mantener una postura **sin desplazarte**: pararte en un pie, hacer \\"el avión\\", quedarte en cuclillas."},{"icon":"Footprints","front":"Equilibrio dinámico","back":"Mantener el equilibrio **mientras te mueves**: caminar sobre una línea o un tronco, saltar y caer firme, andar en bicicleta."},{"icon":"Maximize2","front":"Base amplia","back":"Con los pies **separados** tienes más base y más equilibrio que con los pies juntos o en un pie."},{"icon":"ArrowDown","front":"Centro bajo y mirada fija","back":"**Dobla un poco las rodillas**, **abre los brazos** y **mira un punto fijo**: te tambaleas menos."}]},"id":"s01-ef-2-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.2.4"],"ambito":"hacer","title":"Ejemplo resuelto: cruzar el tronco sobre el río","prompt":"Mira cómo Kevin aplica lo aprendido para no caerse.","type":"worked-example","props":{"icon":"Footprints","problem":"En un paseo, Kevin debe cruzar caminando sobre un tronco ancho y bajo, puesto como puente sobre un riachuelo poco profundo. ¿Qué hace para mantener el equilibrio?","steps":[{"text":"Revisa que el tronco esté **firme** y pide que una persona adulta esté cerca.","why":"La seguridad va primero."},{"text":"Abre los **brazos** hacia los lados.","why":"Los brazos abiertos ayudan a corregir el tambaleo."},{"text":"Dobla un poco las **rodillas**.","why":"Baja su centro de gravedad y queda más estable."},{"text":"Mira un **punto fijo** al final del tronco, no el agua.","why":"Mirar el agua que corre confunde al cerebro y hace tambalear."},{"text":"Avanza con **pasos cortos**, apoyando bien cada pie antes de mover el otro."}],"answer":"Kevin usa **equilibrio dinámico**: brazos abiertos, centro bajo, mirada fija y pasos cortos.","tip":"Si sientes que te caes, agáchate y apoya las manos: bajar el cuerpo te devuelve el equilibrio."},"id":"s01-ef-2-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.2.4"],"ambito":"conocer","prompt":"Clasifica cada actividad: ¿equilibrio **estático** o **dinámico**?","hint":"Pregúntate: ¿la persona se desplaza o se queda en su lugar?","explain":"Si te quedas quieto en una postura es estático; si te desplazas manteniendo el equilibrio, es dinámico.","type":"sort","props":{"buckets":[{"id":"e","label":"Estático (quieto)","icon":"PersonStanding","color":"var(--area-ef)"},{"id":"d","label":"Dinámico (en movimiento)","icon":"Footprints","color":"var(--c-maiz-strong)"}],"items":[{"id":"x1","text":"Pararme en un pie 20 segundos","bucket":"e"},{"id":"x2","text":"Caminar sobre la orilla de la banqueta con cuidado","bucket":"d"},{"id":"x3","text":"Hacer \\"el avión\\" sin moverme","bucket":"e"},{"id":"x4","text":"Andar en bicicleta","bucket":"d"},{"id":"x5","text":"Saltar la cuerda","bucket":"d"},{"id":"x6","text":"Quedarme en cuclillas con los brazos al frente","bucket":"e"}]},"id":"s01-ef-2-5"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.2.1","ef:1.2.4"],"ambito":"hacer","prompt":"¡Circuito de mano y equilibrio! **Calentamiento:** rota muñecas, hombros y tobillos. **Estación 1 (mano):** lanza y atrapa una bolita de papel o un calcetín enrollado, 10 veces con la mano dominante y 10 con la otra; luego bota una pelota 10 veces con cada mano. **Estación 2 (equilibrio):** párate en un pie 20 s con cada pierna (estático) y camina 10 pasos sobre una línea de talón a punta, ida y vuelta (dinámico). **Poco espacio:** usa una línea de cinta de 2 m. **Adaptación:** puedes apoyarte en una pared o en una silla; en silla de ruedas, haz el equilibrio con el tronco sosteniendo un cuaderno sobre la cabeza.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después de la estación de la mano","exercise":{"name":"Lanzar, atrapar y botar con cada mano","icon":"Hand","seconds":60}},{"label":"Después de la estación de equilibrio","exercise":{"name":"Un pie y caminar sobre la línea","icon":"Footprints","seconds":60}}]},"id":"s01-ef-2-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.2.4"],"ambito":"hacer","prompt":"Ana se tambalea al pararse en un pie. Tiene los brazos pegados al cuerpo, las rodillas rígidas y mira hacia todos lados. ¿Qué le aconsejas?","explain":"Abrir los brazos, doblar un poco la rodilla de apoyo y fijar la mirada en un punto aumenta la estabilidad.","type":"choice","props":{"options":[{"id":"a","text":"Que abra los brazos, doble un poco la rodilla y mire un punto fijo"},{"id":"b","text":"Que cierre los ojos para concentrarse","feedback":"Con los ojos cerrados el equilibrio es mucho más difícil: la vista ayuda a estabilizarse."},{"id":"c","text":"Que se pare de puntillas para estar más alta","feedback":"De puntillas la base es más pequeña y el equilibrio es más difícil."}],"correct":["a"]},"id":"s01-ef-2-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.2.1"],"ambito":"convivir","prompt":"Luis es zurdo. En el recreo, un compañero le dice que \\"está mal\\" lanzar con la izquierda. ¿Qué es correcto?","explain":"Ser zurdo es una forma normal de lateralidad. Lo importante es ejercitar el lado dominante y, además, practicar con el otro.","type":"choice","props":{"options":[{"id":"a","text":"Luis debe cambiar a la mano derecha","feedback":"No: forzar a alguien a cambiar su mano dominante no tiene sentido y le quita precisión."},{"id":"b","text":"Ser zurdo es normal; Luis puede reforzar su mano izquierda y practicar también con la derecha"},{"id":"c","text":"Luis no debería jugar a lanzar","feedback":"Todas las personas pueden jugar, sin importar su mano dominante."}],"correct":["b"]},"id":"s01-ef-2-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.2.4"],"prompt":"Clasifica cada actividad: ¿equilibrio **estático** o **dinámico**?","type":"sort","props":{"buckets":[{"id":"e","label":"Estático (quieto)","icon":"PersonStanding","color":"var(--area-ef)"},{"id":"d","label":"Dinámico (en movimiento)","icon":"Footprints","color":"var(--c-maiz-strong)"}],"items":[{"id":"y1","text":"Caminar sobre una línea recta sin salirte","bucket":"d"},{"id":"y2","text":"Sostenerte en un pie con la otra rodilla arriba, sin moverte","bucket":"e"},{"id":"y3","text":"Cruzar un puente angosto caminando","bucket":"d"},{"id":"y4","text":"Quedarte de puntillas 10 segundos en tu lugar","bucket":"e"}]},"id":"s01-ef-2-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.2.1","ef:1.2.4"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"La mano dominante es la que usamos con más fuerza y precisión.","answer":true},{"text":"Con los pies juntos tienes más equilibrio que con los pies separados.","answer":false,"why":"Con los pies separados la base de apoyo es más amplia y hay más equilibrio."},{"text":"Doblar un poco las rodillas baja el centro de gravedad y ayuda al equilibrio.","answer":true}]},"id":"s01-ef-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["ef"],"cnb":["ef:1.2.4"],"type":"reflection","props":{"statements":["Explico qué hacen huesos, músculos, tendones y ligamentos","Hago flexión, extensión y rotación con control","Reconozco mi mano dominante y mejoro mi equilibrio"],"commitments":["Haré mi rutina de calentamiento antes de jugar","Practicaré lanzar y botar con las dos manos","Me pararé en un pie mientras me lavo los dientes"]},"id":"s01-ef-2-11"}],"kind":"materia","area":"ef","day":5}},{"missionId":"s01","version":"cnb-sexto-f7d805d2898c9368","lesson":{"id":"s01-l1-3","title":"El cuerpo también habla: gestos, mirada y movimiento","icon":"PersonStanding","minutes":14,"gancho":"Sin decir una palabra, ¿puedes saber si alguien está nervioso, contento o aburrido? ¿Cómo lo sabes?","objetivos":["Preparar un guion breve que coordine palabras, voz, gestos y mirada"],"resumen":["Los gestos (manos y cara), la mirada, la postura y los movimientos también comunican.","Reparte la mirada entre todas las personas; párate firme; mueve las manos para mostrar tamaños, cantidades o direcciones.","El cuerpo y las palabras deben decir lo mismo: si dices \\"¡qué emoción!\\" con cara seria, el público se confunde.","Una exposición corta tiene inicio (atrapa), desarrollo (2 o 3 ideas) y cierre (una frase para recordar)."],"media":{"id":"s01-l1-3-cuerpo","kind":"image","title":"Lo que dice el cuerpo","aspect":"16:9","alt":"Dos ilustraciones de la misma niña exponiendo: a la izquierda, con los brazos cruzados, mirando al piso y balanceándose; a la derecha, parada firme, mirando al grupo y señalando un mapa.","brief":"Ilustración plana en dos paneles. Panel izquierdo con etiqueta \\"Distrae\\": niña de 12 años con brazos cruzados, vista al suelo, un pie cruzado detrás del otro, flechas que indican balanceo. Panel derecho con etiqueta \\"Comunica\\": la misma niña con postura erguida, pies separados al ancho de los hombros, mano abierta señalando un mapa de su municipio, mirada hacia el público; líneas punteadas desde sus ojos hacia distintos compañeros. Fondo de aula guatemalteca sencilla. Colores cálidos, sin texto adicional. Dimensiones: 1600x900."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":["l1:2.1.6"],"ambito":"conocer","title":"Cuatro formas en que habla tu cuerpo","prompt":"Toca cada tarjeta y descubre cómo usar tu cuerpo al exponer.","type":"explain","props":{"icon":"PersonStanding","body":"El lenguaje del cuerpo se llama **comunicación no verbal**: todo lo que comunicamos sin palabras. Después de la lección, compartir el guion con un familiar es opcional.","reveal":[{"icon":"Hand","front":"Gestos","back":"Con las **manos** puedes mostrar tamaños (\\"así de grande\\"), cantidades (tres dedos), direcciones (señalar el mapa). Con la **cara** muestras emociones: sorpresa, alegría, preocupación."},{"icon":"Eye","front":"Mirada","back":"**Reparte la mirada**: mira un momento a una persona de la izquierda, otra del centro y otra de la derecha. Así todos sienten que les hablas a ellos."},{"icon":"PersonStanding","front":"Postura","back":"Párate **firme**, con los pies separados al ancho de los hombros y la espalda recta. Evita balancearte o esconder las manos en los bolsillos."},{"icon":"Footprints","front":"Movimientos","back":"Muévete **con intención**: da un paso hacia el público para decir algo importante o acércate al cartel para señalarlo. No camines de un lado a otro sin razón."}]},"id":"s01-l1-3-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:2.1.6"],"ambito":"conocer","prompt":"Observa la imagen. La niña de la izquierda dice exactamente las mismas palabras que la de la derecha. ¿Qué **te comunica** su cuerpo?","explain":"Aunque las palabras sean iguales, los brazos cruzados, la vista al suelo y el balanceo transmiten nervios o desinterés. El cuerpo habla, ¡aunque no queramos!","type":"choice","props":{"options":[{"id":"a","text":"Que está segura y entusiasmada con su tema","feedback":"Fíjate en los brazos y en hacia dónde mira: dicen otra cosa."},{"id":"b","text":"Que está nerviosa o que no le interesa mucho su tema"},{"id":"c","text":"Nada: el cuerpo no comunica","feedback":"Siempre comunica. Por eso conviene usarlo a nuestro favor."}],"correct":["b"]},"id":"s01-l1-3-2"},{"fase":"construir","areas":["l1"],"cnb":["l1:2.1.6"],"ambito":"hacer","prompt":"¿Esto **ayuda** a comunicar o **distrae** al público?","hint":"Pregúntate si el gesto o movimiento acompaña lo que se está diciendo.","explain":"Lo que ayuda tiene una intención clara. Lo que distrae son hábitos de nervios que podemos corregir con práctica.","type":"sort","props":{"buckets":[{"id":"ay","label":"Ayuda","icon":"ThumbsUp","color":"var(--c-ok)"},{"id":"di","label":"Distrae","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"c1","text":"Abrir los brazos al decir \\"un lago enorme\\"","bucket":"ay"},{"id":"c2","text":"Jugar con el lapicero todo el tiempo","bucket":"di"},{"id":"c3","text":"Mirar a personas de distintos lados del salón","bucket":"ay"},{"id":"c4","text":"Mirar solo a la maestra","bucket":"di","feedback":"El resto del grupo siente que no le hablas. Reparte la mirada."},{"id":"c5","text":"Dar un paso al frente antes del dato más importante","bucket":"ay"},{"id":"c6","text":"Balancearse de un pie al otro","bucket":"di"}]},"id":"s01-l1-3-3"},{"id":"s01-l1-3-5","fase":"construir","areas":["l1"],"cnb":["l1:2.1.6"],"ambito":"hacer","title":"Ejemplo resuelto: el guion de una exposición de un minuto","prompt":"Ana preparó su exposición **\\"Nuestro lugar en mapas y palabras\\"**. Mira cómo organizó su guion y dónde decidió usar cada recurso.","type":"worked-example","props":{"icon":"ClipboardList","problem":"Ana vive en Livingston, Izabal. Tiene un minuto para presentar su lugar.","steps":[{"text":"**Inicio (atrapa):** \\"¿Se imaginan ir a la escuela… en lancha?\\" (Pausa. Sonríe. Mira a todo el grupo.)","why":"Pregunta + pausa + mirada: tres recursos en diez segundos."},{"text":"**Idea 1:** \\"Livingston está donde el río Dulce llega al mar Caribe.\\" (Señala el lugar en un mapa.)","why":"El gesto de señalar ayuda a ubicar."},{"text":"**Idea 2:** \\"Ahí vivimos familias garífunas, q'eqchi' y ladinas; por eso se oyen varios idiomas.\\" (Cuenta con los dedos: uno, dos, tres.)"},{"text":"**Idea 3:** \\"Mi comida favorita es el tapado, una sopa de mariscos con coco.\\" (Cara de \\"¡qué rico!\\".)"},{"text":"**Cierre (para recordar):** \\"Si algún día llegan en lancha, los espero con un tapado.\\" (Da un paso al frente y sonríe.)","why":"Un cierre amable y concreto se queda en la memoria."}],"answer":"Un guion claro: inicio que atrapa, tres ideas cortas y un cierre, cada parte con su recurso de voz o de cuerpo anotado entre paréntesis.","tip":"Escribe tus recursos entre paréntesis en el guion, como si fueras actor o actriz."}},{"id":"s01-l1-3-6","fase":"aplicar","areas":["l1"],"cnb":["l1:2.1.6"],"ambito":"hacer","prompt":"Ordena las partes de la exposición de Pedro sobre San Juan Comalapa.","explain":"Primero se atrapa la atención, luego se desarrollan las ideas y al final se cierra con algo memorable.","type":"order","props":{"labels":{"start":"Empieza","end":"Termina"},"items":[{"id":"o1","text":"\\"¿Sabían que en mi pueblo hay un muro pintado de colores que cuenta nuestra historia?\\" (Pausa.)"},{"id":"o2","text":"\\"Comalapa está en Chimaltenango y es conocida por sus pintores.\\" (Señala el mapa.)"},{"id":"o3","text":"\\"Mi tío pinta la cosecha del maíz; a veces yo le ayudo a mezclar colores.\\" (Muestra un dibujo.)"},{"id":"o4","text":"\\"Cuando vayan, busquen el muro: una parte de nuestra historia está pintada ahí.\\" (Paso al frente, sonrisa.)"}]}},{"id":"s01-l1-3-8","fase":"aplicar","areas":["l1"],"cnb":["l1:2.1.6"],"ambito":"hacer","prompt":"Dentro de los 6 minutos, **completa el inicio que ya escribiste en la lección 1** hasta formar un guion de al menos 50 palabras para **\\"Nuestro lugar en mapas y palabras\\"**: inicio, dos ideas y cierre. No copies de nuevo el inicio. Reserva los últimos **20 a 30 segundos** para un **autoensayo individual en solitario** del inicio: usa un recurso de voz, un gesto, una mirada intencional y un movimiento breve.","explain":"La representación breve es parte de esta misma tarea: no requiere otra persona, materiales ni grabación.","type":"short-answer","props":{"minWords":50,"placeholder":"Inicio: … (recurso)\\nIdea 1: … (recurso)\\nIdea 2: …\\nCierre: …","model":"Inicio: \\"¿Sabían que desde mi casa se ven tres volcanes?\\" (Pausa, señalo la ventana.)\\nIdea 1: \\"Vivo en Antigua Guatemala, una ciudad de calles empedradas.\\" (Muestro una foto.)\\nIdea 2: \\"Cada mañana miro el Volcán de Agua: si tiene nubes, mi abuela dice que va a llover.\\" (Cara de duda, sonrío.)\\nIdea 3: \\"En Semana Santa las calles se llenan de alfombras de aserrín de colores.\\" (Abro los brazos.)\\nCierre: \\"Mi lugar es pequeño, pero desde él se ven gigantes.\\" (Paso al frente, voz más lenta.)","rubric":["Tiene inicio, 2 o 3 ideas y cierre","Anoté al menos un recurso de voz (pausa, cambio de volumen)","Anoté al menos dos recursos de cuerpo (gesto, mirada, movimiento)","Los gestos acompañan lo que digo","Reutilicé el inicio previo sin copiarlo de nuevo","Representé en solitario el inicio durante 20 a 30 segundos usando voz, un gesto, una mirada intencional y un movimiento breve"]}},{"id":"s01-l1-3-9","fase":"comprobar","areas":["l1"],"cnb":["l1:2.1.6"],"prompt":"¿Qué es **repartir la mirada**?","type":"choice","props":{"options":[{"id":"a","text":"Mirar un momento a personas de distintos lados del grupo"},{"id":"b","text":"Mirar fijamente a una sola persona"},{"id":"c","text":"Cerrar los ojos para concentrarse"}],"correct":["a"]}},{"id":"s01-l1-3-10","fase":"comprobar","areas":["l1"],"cnb":["l1:2.1.6"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Mostrar tres dedos al decir \\"tres ríos\\" es un gesto que acompaña el mensaje.","answer":true},{"text":"Caminar de un lado a otro sin parar ayuda a mantener la atención.","answer":false,"why":"Los movimientos deben tener intención; si no, distraen."},{"text":"Si tus palabras dicen alegría, tu cara también debería mostrarla.","answer":true}]}}],"kind":"materia","area":"l1","day":3}},{"missionId":"s01","version":"cnb-sexto-f4175d7c16cfa98f","lesson":{"id":"s01-cnt-2","title":"La célula animal y sus organelos","icon":"Microscope","minutes":15,"gancho":"Un jaguar, una hormiga y tú parecen muy distintos. Si los miraras con un microscopio muy potente, ¿qué encontrarías en los tres?","objetivos":["Explicar qué es la célula y por qué es la unidad de la vida","Nombrar las partes de la célula animal y describir la función de cada organelo"],"resumen":["La célula es la unidad más pequeña con vida. Todos los seres vivos están formados por células, y toda célula proviene de otra célula.","Partes principales: membrana celular (controla lo que entra y sale), citoplasma (medio donde están los organelos) y núcleo (guarda el ADN y dirige la célula).","Organelos: mitocondrias (producen energía), ribosomas (fabrican proteínas), retículo endoplasmático (transporta), aparato de Golgi (empaca y envía), lisosomas (digieren desechos), vacuolas (almacenan) y centriolos (ayudan a dividir la célula)."],"media":{"id":"s01-cnt-2-celula-animal","kind":"diagram","title":"La célula animal por dentro","aspect":"4:3","alt":"Esquema de una célula animal redondeada, cortada por la mitad, con el núcleo en el centro y los organelos rotulados en el citoplasma.","brief":"Diagrama escolar en colores planos de una célula animal de forma redondeada e irregular, vista en corte. Rotular con líneas guía y letra grande: membrana celular (borde fino azul), citoplasma (celeste claro), núcleo (morado, con nucléolo y ADN como hilos), mitocondrias (naranja, forma de frijol con pliegues), ribosomas (puntitos negros), retículo endoplasmático (pliegues rosados junto al núcleo), aparato de Golgi (sacos amarillos apilados), lisosomas (círculos verdes pequeños), vacuolas pequeñas y par de centriolos. Fondo blanco. Estilo de libro de texto de primaria, sin exceso de detalle. Dimensiones: 1200x900."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","title":"¿Qué es una célula?","prompt":"La **célula** es la unidad más pequeña que tiene vida: se alimenta, crece, responde y se reproduce. Toca cada tarjeta.","type":"explain","props":{"icon":"Microscope","body":"La mayoría de las células mide **menos de una décima de milímetro**: por eso necesitamos un **microscopio** para verlas. Tu cuerpo tiene **billones** de ellas (millones de millones).","reveal":[{"icon":"Blocks","front":"Unidad de la vida","back":"**Todos** los seres vivos están formados por células: algunos por una sola, otros, como tú, por billones."},{"icon":"Copy","front":"Viene de otra célula","back":"Toda célula nace de **otra célula** que se divide en dos. Así creces y así se reparan tus heridas."},{"icon":"Layers","front":"Tres partes principales","back":"**Membrana** (el borde), **citoplasma** (el interior) y **núcleo** (el centro de mando)."}]},"id":"s01-cnt-2-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","prompt":"¿Qué tienen en común un **jaguar**, una **hormiga** y **tú**?","explain":"Los tres están formados por **células**. La hormiga no tiene huesos y solo el jaguar tiene pelo, pero todos los seres vivos están hechos de células.","type":"choice","props":{"layout":"grid","options":[{"id":"a","text":"Todos tienen huesos","icon":"Bone","feedback":"La hormiga no tiene huesos: tiene un esqueleto externo, duro, por fuera del cuerpo."},{"id":"b","text":"Todos están formados por células","icon":"Microscope"},{"id":"c","text":"Todos tienen pelo","icon":"Cat","feedback":"Ni la hormiga ni tú tienen el cuerpo cubierto de pelo como el jaguar."}],"correct":["b"]},"id":"s01-cnt-2-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","title":"Las partes principales","prompt":"Imagina la célula como una **comunidad pequeña**: tiene un cerco con portón, un espacio donde se trabaja y una oficina que da las órdenes. Toca las tarjetas.","type":"explain","props":{"icon":"Home","body":"Cada parte tiene una **función** (un trabajo). Si una parte falla, toda la célula sufre.","reveal":[{"icon":"Shield","front":"Membrana celular","back":"Capa delgada y flexible que rodea la célula. **Controla qué entra y qué sale**: deja pasar agua y nutrientes y saca desechos. Es como el cerco con portón."},{"icon":"Droplets","front":"Citoplasma","back":"Sustancia parecida a una **gelatina** que llena la célula. En ella flotan los organelos y ocurren muchas reacciones."},{"icon":"Brain","front":"Núcleo","back":"Guarda el **ADN**, la información para construir y hacer funcionar la célula. **Dirige** todas sus actividades, como una oficina central."}]},"id":"s01-cnt-2-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","prompt":"Completa la descripción de la célula animal.","hint":"El borde controla el paso; la \\"gelatina\\" es el citoplasma; el centro de mando es el núcleo.","explain":"Membrana = controla el paso; citoplasma = medio interno; núcleo = guarda el ADN y dirige.","type":"fill-blank","props":{"text":"La [[membrana celular]] rodea la célula y controla lo que entra y sale. Adentro está el [[citoplasma]], una sustancia parecida a la gelatina donde flotan los organelos. El [[núcleo]] guarda el [[ADN]] y dirige las actividades de la célula.","distractors":["cloroplasto","pared celular"]},"id":"s01-cnt-2-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","title":"Los organelos: trabajadores de la célula","prompt":"En el citoplasma hay **organelos**: pequeñas estructuras, cada una con un trabajo. Observa el esquema de la lección y toca cada tarjeta.","type":"explain","props":{"icon":"Factory","body":"Los organelos trabajan en equipo, como las personas de una panadería: unas hacen la masa, otras hornean, otras empacan y otras limpian.","reveal":[{"icon":"Zap","front":"Mitocondrias","back":"Transforman los nutrientes de los alimentos en **energía** que la célula usa. Son su \\"planta de energía\\"."},{"icon":"CircleDot","front":"Ribosomas","back":"Puntitos que **fabrican proteínas**, siguiendo las instrucciones del núcleo."},{"icon":"Route","front":"Retículo endoplasmático","back":"Red de canales y pliegues que **transporta** sustancias dentro de la célula."},{"icon":"Package","front":"Aparato de Golgi","back":"Sacos apilados que **empacan y envían** las sustancias adonde se necesitan, dentro o fuera de la célula."},{"icon":"Recycle","front":"Lisosomas","back":"Bolsitas con jugos que **digieren** desechos y partes viejas. Son el \\"equipo de limpieza\\"."},{"icon":"Archive","front":"Vacuolas y centriolos","back":"Las **vacuolas** (pequeñas en la célula animal) **almacenan** agua y sustancias. Los **centriolos** ayudan a la célula a **dividirse** en dos."}]},"id":"s01-cnt-2-5"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","prompt":"Une cada organelo con su función.","hint":"Piensa en la comparación con la panadería: energía, fabricar, transportar, empacar, limpiar.","explain":"Mitocondria = energía; ribosoma = proteínas; retículo = transporte; Golgi = empaque y envío; lisosoma = digestión de desechos; centriolos = división.","type":"match","props":{"leftTitle":"Organelo","rightTitle":"Función","pairs":[{"id":"mi","left":"Mitocondria","leftIcon":"Zap","right":"Produce energía a partir de los nutrientes"},{"id":"ri","left":"Ribosoma","leftIcon":"CircleDot","right":"Fabrica proteínas"},{"id":"re","left":"Retículo endoplasmático","leftIcon":"Route","right":"Transporta sustancias por la célula"},{"id":"go","left":"Aparato de Golgi","leftIcon":"Package","right":"Empaca y envía sustancias"},{"id":"li","left":"Lisosoma","leftIcon":"Recycle","right":"Digiere desechos y partes viejas"},{"id":"ce","left":"Centriolos","leftIcon":"Copy","right":"Ayudan a la célula a dividirse"}]},"id":"s01-cnt-2-6"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","title":"Ejemplo: los organelos en equipo","prompt":"Mira cómo varios organelos trabajan juntos para que una célula fabrique y envíe una sustancia.","media":{"id":"s01-cnt-2-proteina","kind":"animation","title":"El viaje de una proteína","aspect":"16:9","duration":40,"alt":"Animación dentro de una célula animal: una instrucción sale del núcleo, un ribosoma arma una proteína, esta viaja por el retículo, el aparato de Golgi la empaca y una bolsita la saca por la membrana.","brief":"Animación 2D de 40 s con el mismo estilo del esquema de la célula animal. Un \\"mensaje\\" (cinta morada) sale del núcleo; un ribosoma sobre el retículo endoplasmático arma una cadena de cuentas (proteína); la cadena viaja por los canales del retículo hasta el aparato de Golgi, que la envuelve en una burbuja; la burbuja llega a la membrana y la proteína sale de la célula. Las mitocondrias brillan cada vez que dan energía. Rótulos grandes en cada organelo; narración en español con subtítulos."},"type":"worked-example","props":{"icon":"Factory","problem":"Las células del estómago fabrican **enzimas digestivas**: proteínas que salen de la célula y ayudan a deshacer la comida. ¿Qué organelos participan y en qué orden?","steps":[{"text":"El **núcleo** tiene en su ADN la instrucción para fabricar la sustancia y la envía al citoplasma.","why":"El núcleo dirige: sin su instrucción, no se fabrica nada."},{"text":"Los **ribosomas** fabrican la proteína siguiendo esa instrucción."},{"text":"El **retículo endoplasmático** la transporta por sus canales."},{"text":"El **aparato de Golgi** la empaca en una bolsita y la envía hacia la **membrana**, que la deja salir."},{"text":"Durante todo el proceso, las **mitocondrias** aportan la **energía** necesaria.","why":"Fabricar, transportar y empacar requiere energía."}],"answer":"Núcleo → ribosomas → retículo endoplasmático → aparato de Golgi → membrana, con energía de las mitocondrias.","tip":"Los organelos no trabajan solos: la célula funciona como un equipo."},"id":"s01-cnt-2-7"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","prompt":"Las células de los **músculos de las piernas** de una corredora de maratón necesitan muchísima energía. ¿Qué organelo tendrán en gran cantidad?","explain":"Las células que gastan mucha energía, como las musculares, tienen **muchas mitocondrias**.","type":"choice","props":{"options":[{"id":"a","text":"Mitocondrias","icon":"Zap"},{"id":"b","text":"Lisosomas","icon":"Recycle","feedback":"Los lisosomas digieren desechos; no producen energía."},{"id":"c","text":"Aparato de Golgi","icon":"Package","feedback":"El Golgi empaca y envía sustancias; la energía viene de otro organelo."}],"correct":["a"]},"id":"s01-cnt-2-8"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","prompt":"Una célula de tu piel fabrica una proteína que la protege. Ordena el recorrido, desde la instrucción hasta que la proteína sale.","explain":"La instrucción sale del núcleo, el ribosoma fabrica, el retículo transporta, el Golgi empaca y la membrana deja salir.","type":"order","props":{"labels":{"start":"Inicio","end":"Final"},"items":[{"id":"p1","text":"El núcleo envía la instrucción","icon":"Brain"},{"id":"p2","text":"Un ribosoma fabrica la proteína","icon":"CircleDot"},{"id":"p3","text":"El retículo endoplasmático la transporta","icon":"Route"},{"id":"p4","text":"El aparato de Golgi la empaca","icon":"Package"},{"id":"p5","text":"La membrana la deja salir de la célula","icon":"Shield"}]},"id":"s01-cnt-2-9"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","prompt":"Supongamos que en una célula los **lisosomas** dejaran de funcionar. ¿Qué pasaría con más probabilidad?","explain":"Sin su \\"equipo de limpieza\\", los desechos y las partes viejas se acumularían y la célula se dañaría.","type":"choice","props":{"options":[{"id":"a","text":"Se acumularían desechos dentro de la célula","icon":"Trash2"},{"id":"b","text":"La célula dejaría de tener membrana","icon":"Shield","feedback":"La membrana no depende de los lisosomas."},{"id":"c","text":"La célula tendría más energía","icon":"Zap","feedback":"La energía la producen las mitocondrias."}],"correct":["a"]},"id":"s01-cnt-2-10"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:1.2.1"],"prompt":"¿Qué parte de la célula **guarda el ADN y dirige** sus actividades?","type":"choice","props":{"options":[{"id":"a","text":"La membrana celular"},{"id":"b","text":"El núcleo"},{"id":"c","text":"El citoplasma"},{"id":"d","text":"Los ribosomas"}],"correct":["b"]},"id":"s01-cnt-2-11"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:1.2.1"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"La membrana celular controla qué sustancias entran y salen de la célula.","answer":true},{"text":"Los ribosomas se encargan de digerir los desechos de la célula.","answer":false,"why":"Los ribosomas fabrican proteínas; los lisosomas digieren desechos."},{"text":"El aparato de Golgi empaca y envía sustancias.","answer":true},{"text":"Una célula puede aparecer de la nada, sin venir de otra célula.","answer":false,"why":"Toda célula proviene de otra célula que se divide."}]},"id":"s01-cnt-2-12"}],"kind":"materia","area":"cnt","day":3}},{"missionId":"s01","version":"cnb-sexto-aba29bf5a084fc94","lesson":{"id":"s01-l3-2","title":"Next to, behind, in front of: my town","icon":"Map","minutes":14,"gancho":"Un turista te pregunta en el parque: \\"Where is the market?\\" ¿Podrías explicarle en inglés dónde queda?","objetivos":["Nombrar en inglés lugares de la comunidad","Usar next to, behind, in front of y between","Describir dónde están los lugares en un mapa sencillo"],"resumen":["Lugares: school (escuela), park (parque), market (mercado), church (iglesia), store (tienda), house (casa), bus stop (parada de bus).","next to = a la par de · behind = detrás de · in front of = enfrente de · between = entre (dos cosas).","Between siempre une dos lugares con and: The store is between the school and the park.","Seguimos usando in, on y under para objetos: The map is on the wall."],"media":{"id":"s01-l3-2-town","kind":"diagram","title":"Map of San Pedro","aspect":"16:9","alt":"Mapa sencillo de un pueblo con rótulos en inglés: church, park, school, store, market, bus stop y una casa.","brief":"Mapa ilustrado, vista desde arriba con edificios en perspectiva ligera, estilo amable. Una calle principal horizontal. Arriba de la calle, de izquierda a derecha: \\"school\\", \\"store\\", \\"park\\". El \\"park\\" tiene árboles y una fuente. Frente al parque, al otro lado de la calle (abajo): \\"church\\". Detrás de la escuela (más arriba): \\"market\\" con toldos de colores. A la par de la iglesia, a su derecha: \\"bus stop\\" con una camioneta. Una \\"house\\" pequeña a la izquierda de la iglesia. Rótulos grandes en inglés, en minúscula. Sin marcas comerciales. Dimensiones: 1600x900."},"steps":[{"fase":"explorar","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"conocer","title":"More prepositions of place","prompt":"Estas preposiciones sirven para ubicar lugares y personas. Toca cada tarjeta y compara con el mapa.","type":"explain","props":{"icon":"MapPin","body":"Fíjate: **in front of** y **next to** tienen varias palabras, pero funcionan como una sola.","reveal":[{"icon":"ArrowLeftRight","front":"next to","back":"**A la par de, al lado de.** _The bus stop is **next to** the church._"},{"icon":"ArrowUpFromLine","front":"behind","back":"**Detrás de.** _The market is **behind** the school._"},{"icon":"ArrowDownToLine","front":"in front of","back":"**Enfrente de.** _The church is **in front of** the park._"},{"icon":"Columns","front":"between","back":"**Entre** dos cosas, unidas con **and**. _The store is **between** the school **and** the park._"}]},"id":"s01-l3-2-1"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"conocer","prompt":"Mira el mapa de la lección. Lee: _\\"The store is **between** the school and the park.\\"_ ¿Qué crees que significa **between**?","explain":"La tienda está en medio de la escuela y el parque: **between** = entre. Con las pistas del mapa pudiste deducirlo. Hoy aprenderás más palabras para ubicar lugares.","type":"choice","props":{"options":[{"id":"a","text":"Entre (en medio de dos lugares)","icon":"ArrowLeftRight"},{"id":"b","text":"Dentro de","icon":"Package","feedback":"Dentro de es \\"in\\". Mira el mapa: la tienda está en medio de dos lugares."},{"id":"c","text":"Muy lejos de","icon":"Route","feedback":"En el mapa la tienda está justo en medio de la escuela y el parque, no lejos."}],"correct":["a"]},"id":"s01-l3-2-2"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"conocer","title":"Places in town","prompt":"Escucha y repite cada lugar en voz alta. Voltea la tarjeta para ver su significado.","media":{"id":"s01-l3-2-places","kind":"audio","title":"Places in town","duration":30,"alt":"Una voz en inglés dice nombres de lugares del pueblo.","brief":"Audio de 30 s. Voz adulta, inglés claro y pausado, sin música. Cada palabra dos veces con 1 s de pausa: \\"school\\", \\"park\\", \\"market\\", \\"church\\", \\"store\\", \\"house\\", \\"bus stop\\". Al final: \\"The store is between the school and the park.\\""},"type":"flashcards","props":{"cards":[{"icon":"School","front":"school","back":"escuela · \\"skul\\""},{"icon":"Trees","front":"park","back":"parque · \\"park\\""},{"icon":"Store","front":"market","back":"mercado · \\"már-ket\\""},{"icon":"Church","front":"church","back":"iglesia · \\"cherch\\""},{"icon":"ShoppingBasket","front":"store","back":"tienda · \\"stor\\""},{"icon":"Bus","front":"bus stop","back":"parada de bus · \\"bas stop\\""}]},"id":"s01-l3-2-3"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"hacer","title":"Worked example","prompt":"Mira cómo Carlos le explica a un turista dónde está la parada de bus.","type":"worked-example","props":{"icon":"Bus","problem":"A tourist asks: _\\"Excuse me, where is the bus stop?\\"_ En el mapa, la parada está **a la par de la iglesia**. ¿Qué responde Carlos?","steps":[{"text":"Empieza con **It's** (Está)."},{"text":"A la par de = **next to**.","why":"Se escriben dos palabras, pero es una sola idea."},{"text":"Agrega el lugar de referencia: **the church**."},{"text":"Junta todo en orden: It's + next to + the church. Carlos además señala la iglesia con la mano para ayudar más.","why":"Un gesto acompaña la respuesta y la hace más clara."}],"answer":"**It's next to the church.** (Está a la par de la iglesia.)","tip":"Siempre necesitas un lugar de referencia: next to the…, behind the…, between the… and the…"},"id":"s01-l3-2-4"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"hacer","prompt":"Ahora tú, con ayuda: en este mapa hay tres casas sin nombre (A, B y C). Lee y toca la correcta: _\\"The **store** is **between** the school and the park.\\"_","hint":"Between = entre. Busca la casa que está en medio de la escuela y el parque.","explain":"La casa B está justo entre la escuela y el parque: esa es la tienda (store).","type":"coordinate-map","props":{"range":{"xmin":0,"xmax":10,"ymin":0,"ymax":6},"markers":[{"id":"school","label":"school","emoji":"🏫","x":2,"y":4},{"id":"b","label":"B","emoji":"🏠","x":5,"y":4},{"id":"park","label":"park","emoji":"🌳","x":8,"y":4},{"id":"a","label":"A","emoji":"🏠","x":2,"y":1},{"id":"c","label":"C","emoji":"🏠","x":8,"y":1}],"task":{"kind":"identify","markerId":"b"}},"id":"s01-l3-2-5"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"hacer","prompt":"Mira el mapa de la lección y completa las oraciones.","explain":"El mercado está detrás de la escuela (behind), la iglesia enfrente del parque (in front of) y la parada de bus a la par de la iglesia (next to).","type":"fill-blank","props":{"text":"The market is [[behind]] the school. The church is [[in front of]] the park. The bus stop is [[next to]] the church.","distractors":["under","between"]},"id":"s01-l3-2-6"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"hacer","prompt":"Mira el mapa de la lección. True or false?","type":"true-false","props":{"statements":[{"text":"The store is between the school and the park.","answer":true},{"text":"The market is in front of the church.","answer":false,"why":"The market is behind the school."},{"text":"The bus stop is next to the church.","answer":true},{"text":"The park is under the school.","answer":false,"why":"\\"Under\\" es debajo de. Un parque no puede estar debajo de una escuela: the park is next to the store."}]},"id":"s01-l3-2-7"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"hacer","title":"Reading","prompt":"Lee lo que escribió Ana sobre su comunidad y responde. Pistas: _my_ = mi, _near_ = cerca, _big_ = grande, _small_ = pequeño, _I like_ = me gusta.","type":"reading","props":{"genre":"Description","heading":"My town","passage":"Hello! My name is Ana. I live in San Pedro. My house is small. It is next to the bus stop.\\n\\nMy school is big. The store is between my school and the park. The market is behind my school.\\n\\nI like the park. It has many trees. On Sundays, I play in the park with my brother.","questions":[{"q":"Where is Ana's house?","options":[{"id":"a","text":"Next to the bus stop"},{"id":"b","text":"Behind the park"},{"id":"c","text":"In the market"}],"correct":"a"},{"q":"What is between the school and the park?","options":[{"id":"a","text":"The store"},{"id":"b","text":"The church"},{"id":"c","text":"Ana's house"}],"correct":"a"},{"q":"¿Qué hace Ana los domingos?","options":[{"id":"a","text":"Juega en el parque con su hermano"},{"id":"b","text":"Va al mercado con su mamá"},{"id":"c","text":"Estudia en la escuela"}],"correct":"a","why":"\\"On Sundays, I play in the park with my brother.\\" Play = jugar, brother = hermano."}]},"id":"s01-l3-2-8"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"hacer","prompt":"Escribe **dos oraciones en inglés** sobre tu comunidad o tu casa. Usa dos preposiciones distintas (next to, behind, in front of, between, in, on, under).","type":"short-answer","props":{"minWords":10,"placeholder":"My school is next to…","model":"My house is behind the church. The store is next to my school.","rubric":["Escribí dos oraciones en inglés","Usé dos preposiciones de lugar distintas","Cada oración tiene un lugar de referencia (the church, my school…)"]},"id":"s01-l3-2-9"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:1.1.1"],"prompt":"Boleto de salida: ¿qué significa _\\"The park is **in front of** the church\\"_?","type":"choice","props":{"options":[{"id":"a","text":"El parque está enfrente de la iglesia."},{"id":"b","text":"El parque está detrás de la iglesia."},{"id":"c","text":"El parque está dentro de la iglesia."}],"correct":["a"]},"id":"s01-l3-2-10"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:1.1.1"],"prompt":"Completa en inglés: \\"La tienda está **entre** la escuela y el mercado. El perro está **detrás de** la casa.\\"","type":"fill-blank","props":{"text":"The store is [[between]] the school and the market. The dog is [[behind]] the house.","distractors":["next to","on"]},"id":"s01-l3-2-11"},{"fase":"reflexionar","areas":["l3"],"cnb":[],"ambito":"ser","prompt":"How are you? ¿Cómo te fue esta semana?","type":"reflection","props":{"statements":["Nombro objetos del aula y lugares del pueblo en inglés","Uso in, on y under correctamente","Uso next to, behind, in front of y between para ubicar lugares"],"commitments":["Diré en inglés dónde están tres cosas de mi casa","Enseñaré a alguien de mi familia la diferencia entre \\"in\\" y \\"on\\"","Dibujaré un mapa de mi comunidad con rótulos en inglés"]},"id":"s01-l3-2-12"}],"kind":"materia","area":"l3","day":4}},{"missionId":"s01","version":"cnb-sexto-9811e60eac57b0cd","lesson":{"id":"s01-d0-diagnostico","title":"¿Desde dónde empiezo?","icon":"Compass","minutes":25,"kind":"diagnostico","day":0,"gancho":"Diez desafíos para descubrir cómo razonas y qué apoyos te ayudarán a empezar sexto.","objetivos":["Resolver situaciones y justificar decisiones","Reconocer fortalezas y temas por explorar","Compartir cómo aprendes y cuándo necesitas ayuda"],"resumen":["Mi punto de partida ayuda a planificar mis primeros apoyos del año.","Una respuesta es una pista para conversar con mi docente; puedo seguir aprendiendo."],"media":{"id":"s01-d0-bienvenida","kind":"video","title":"Bienvenida a Sexto","aspect":"16:9","duration":50,"alt":"Geeky, tu compañero de aprendizaje, da la bienvenida al año escolar y explica cómo funciona la plataforma.","brief":"Video de bienvenida de 50 s basado en la interfaz actual de Socrates: tema claro blanco con coral, cielo y ciruela de los tokens vigentes. Usa el Geeky 3D original de GuateGeeks mediante el mismo ThreeRenderer de la app: montura índigo, ojos blancos y pupilas negras con dos brillos. Muestra pantallas reales del recorrido del año (4 unidades, 40 semanas), las fases Explorar, Construir, Reto, Comprobar y Reflexionar, el Repaso inteligente y el Cuaderno. Tono cálido y voz juvenil en español; subtítulos opcionales separados del video y transcripción audiovisual."},"questionGroups":[{"id":"operaciones","label":"Problemas de varios pasos","stepIds":["s01-d0-diagnostico-q01","s01-d0-diagnostico-q11"],"count":1,"nextStep":"Pedir que represente los datos y explique el orden de las operaciones; practicar compras y repartos con material concreto."},{"id":"fracciones","label":"Fracciones y equivalencias","stepIds":["s01-d0-diagnostico-q02","s01-d0-diagnostico-q12"],"count":1,"nextStep":"Representar la misma cantidad con tiras divididas en partes distintas y explicar por qué son equivalentes."},{"id":"medidas","label":"Decimales y medidas","stepIds":["s01-d0-diagnostico-q03","s01-d0-diagnostico-q13"],"count":1,"nextStep":"Usar una recta numérica y medidas reales para comparar decimales y justificar sumas o restas."},{"id":"inferencias","label":"Inferencias al leer","stepIds":["s01-d0-diagnostico-q04","s01-d0-diagnostico-q14"],"count":1,"nextStep":"Leer un texto breve y pedir una inferencia junto con la frase que la sostiene; contrastar con una lectura acompañada."},{"id":"argumentos","label":"Ideas y argumentos","stepIds":["s01-d0-diagnostico-q05","s01-d0-diagnostico-q15"],"count":1,"nextStep":"Pedir una opinión, una razón pertinente y un ejemplo, primero oralmente y luego por escrito."},{"id":"experimentos","label":"Investigación científica","stepIds":["s01-d0-diagnostico-q06","s01-d0-diagnostico-q16"],"count":1,"nextStep":"Diseñar una comparación sencilla: cambiar una condición, mantener las demás y registrar observaciones."},{"id":"datos","label":"Interpretación de evidencia","stepIds":["s01-d0-diagnostico-q07","s01-d0-diagnostico-q17"],"count":1,"nextStep":"Leer una tabla, distinguir lo observado de lo supuesto y explicar qué datos faltan para una conclusión."},{"id":"fuentes","label":"Fuentes y comunidad","stepIds":["s01-d0-diagnostico-q08","s01-d0-diagnostico-q18"],"count":1,"nextStep":"Comparar dos fuentes sobre un problema comunitario: autoría, fecha, datos y voces que faltan."},{"id":"ingles","label":"Inglés en contexto","stepIds":["s01-d0-diagnostico-q09","s01-d0-diagnostico-q19"],"count":1,"nextStep":"Comprobar la exposición previa al inglés; acompañar instrucciones con acciones e imágenes antes de retirar el apoyo."},{"id":"convivencia","label":"Cooperación y diálogo","stepIds":["s01-d0-diagnostico-q10","s01-d0-diagnostico-q20"],"count":1,"nextStep":"Observar una tarea cooperativa real y conversar sobre turnos, escucha y desacuerdos; contrastar con la autoevaluación."}],"steps":[{"id":"s01-d0-diagnostico-bienvenida-v2","fase":"explorar","areas":["fc","l1"],"cnb":[],"prompt":"¡Bienvenida y bienvenido a **Sexto Primaria**! Queremos conocer cómo piensas.","type":"explain","props":{"icon":"Compass","body":"Resolverás **10 preguntas**, elegidas de un banco de 20, y una reflexión final. Puedes usar papel y lápiz. Trabaja sin ayuda para responder; si necesitas apoyo para leer o usar la pantalla, cuéntaselo a tu docente. Tómate tu tiempo: no hay cronómetro ni nota para aprobar."}},{"id":"s01-d0-diagnostico-q01","fase":"comprobar","areas":["mat"],"cnb":["mat:4.2.4"],"title":"Organiza una compra","prompt":"La clase tiene **Q200**. Compra **6 cuadernos de Q18** y reparte el dinero restante por igual entre **4 equipos**. ¿Cuántos quetzales recibe cada equipo?","explain":"6 × 18 = 108; 200 − 108 = 92; 92 ÷ 4 = 23.","type":"number-input","props":{"answer":23,"unit":"Q","misconceptions":[{"value":92,"msg":"Ese es el dinero que queda antes de repartirlo."},{"value":50,"msg":"Antes de repartir, descuenta el costo de los cuadernos."}]}},{"id":"s01-d0-diagnostico-q02","fase":"comprobar","areas":["mat"],"cnb":["mat:4.4.1"],"title":"Una cantidad, otras partes","prompt":"Se usaron **2 de 4 partes iguales** de un litro de pintura. El nuevo recipiente está dividido en mitades. Representa la **misma cantidad usada**.","explain":"Dos cuartos y una mitad representan la misma cantidad: 2/4 = 1/2.","type":"fraction-model","props":{"sourceNumerator":2,"sourceDenominator":4,"targetDenominator":2}},{"id":"s01-d0-diagnostico-q03","fase":"comprobar","areas":["mat"],"cnb":["mat:4.5.1"],"title":"Mide lo que queda","prompt":"Una cinta mide **2.5 m**. Cortas **0.75 m** y después **0.6 m**. ¿Cuántos metros quedan?","explain":"2.50 − 0.75 − 0.60 = 1.15 m. Alinea las posiciones decimales.","type":"number-input","props":{"answer":1.15,"allowDecimal":true,"unit":"m","misconceptions":[{"value":1.75,"msg":"Falta descontar el segundo corte."}]}},{"id":"s01-d0-diagnostico-q04","fase":"comprobar","areas":["l1"],"cnb":["l1:4.1"],"title":"Lee entre líneas","prompt":"Lee la situación con atención y responde.","explain":"Las nubes y los charcos permiten inferir que anticipó la lluvia y protegió sus cuadernos.","type":"reading","props":{"passage":"Antes de salir, Lucía vio nubes oscuras y guardó sus cuadernos en una bolsa. Al volver, los charcos cubrían el patio, pero sus cuadernos estaban secos. **¿Por qué usó la bolsa?**","questions":[{"q":"Elige tu respuesta.","options":[{"id":"0","text":"Quería regalar sus cuadernos."},{"id":"1","text":"Previó lluvia y quiso protegerlos."},{"id":"2","text":"El texto dice que estaban mojados."},{"id":"3","text":"La bolsa impide que se formen charcos."}],"correct":"1"}]}},{"id":"s01-d0-diagnostico-q05","fase":"comprobar","areas":["l1"],"cnb":["l1:2.3"],"title":"Elige una razón pertinente","prompt":"El grupo propone abrir la biblioteca durante el recreo. **¿Qué razón sostiene mejor esa propuesta?**","explain":"La razón relaciona la propuesta con una necesidad concreta: disponer de tiempo para leer.","type":"choice","props":{"options":[{"id":"0","text":"Los libros tienen muchas páginas."},{"id":"1","text":"El recreo es más divertido que la clase."},{"id":"2","text":"Permitiría leer a quienes no tienen otro momento para usarla."},{"id":"3","text":"Las bibliotecas siempre deben ser grandes."}],"correct":["2"]}},{"id":"s01-d0-diagnostico-q06","fase":"comprobar","areas":["cnt"],"cnb":["cnt:8.2"],"title":"Diseña una comparación justa","prompt":"Quieres investigar si la **cantidad de luz** afecta el crecimiento de frijoles. **¿Qué comparación permite estudiar esa pregunta?**","explain":"Solo debe variar la luz; el tipo de planta, el agua, el suelo y el tiempo deben ser comparables.","type":"choice","props":{"options":[{"id":"0","text":"Frijoles similares con igual suelo y agua, pero distinta luz."},{"id":"1","text":"Un frijol al sol con agua y un maíz a oscuras sin agua."},{"id":"2","text":"Un frijol al sol hoy y otro a la sombra durante un mes."},{"id":"3","text":"Frijoles con distinta luz, distinto suelo y distinta agua."}],"correct":["0"]}},{"id":"s01-d0-diagnostico-q07","fase":"comprobar","areas":["cnt"],"cnb":["cnt:8.1"],"title":"Concluye a partir de datos","prompt":"Lee la situación con atención y responde.","explain":"Creció 3 cm en total. Los aumentos fueron 2 cm y 1 cm; no podemos afirmar que siempre crecerá igual.","type":"reading","props":{"passage":"Una planta midió **día 1: 4 cm; día 4: 6 cm; día 7: 7 cm**. **¿Qué conclusión está respaldada por esos datos?**","questions":[{"q":"Elige tu respuesta.","options":[{"id":"0","text":"Creció exactamente 1 cm cada día."},{"id":"1","text":"Creció 3 cm entre el primer y el último registro."},{"id":"2","text":"Medirá 20 cm el día 10."},{"id":"3","text":"La luz fue la única causa de su crecimiento."}],"correct":"1"}]}},{"id":"s01-d0-diagnostico-q08","fase":"comprobar","areas":["ccss"],"cnb":["ccss:5.2"],"title":"Comprueba una afirmación","prompt":"Un mensaje sin fecha afirma: «El río de la comunidad ya está limpio». **¿Cómo investigarías esa afirmación antes de compartirla?**","explain":"El origen, la fecha y los datos recientes permiten contrastar la afirmación; repetirla no la verifica.","type":"choice","props":{"options":[{"id":"0","text":"Contaría cuántas personas lo reenviaron."},{"id":"1","text":"Miraría únicamente una foto antigua del río."},{"id":"2","text":"Lo compartiría porque habla de mi comunidad."},{"id":"3","text":"Buscaría autoría, fecha y datos recientes de una fuente identificable."}],"correct":["3"]}},{"id":"s01-d0-diagnostico-q09","fase":"comprobar","areas":["l3"],"cnb":["l3:3.3"],"title":"Sigue instrucciones en inglés","prompt":"Lee la situación con atención y responde.","explain":"“Before” indica que escribir tu nombre ocurre antes de dibujar; “then” introduce la acción posterior.","type":"reading","props":{"passage":"Read: **“Before you draw a circle, write your name. Then put the pencil on the table.”** What do you do **first**?","questions":[{"q":"Elige tu respuesta.","options":[{"id":"0","text":"Put the pencil on the table."},{"id":"1","text":"Draw a circle."},{"id":"2","text":"Write your name."},{"id":"3","text":"Read a book."}],"correct":"2"}]}},{"id":"s01-d0-diagnostico-q10","fase":"comprobar","areas":["fc"],"cnb":["fc:4.3"],"title":"Resuelve un desacuerdo","prompt":"Dos integrantes proponen ideas distintas y el proyecto está detenido. **¿Qué acuerdo permite avanzar y escuchar a ambos?**","explain":"Comparar ambas ideas con el objetivo permite decidir con razones y revisar la decisión.","type":"choice","props":{"options":[{"id":"0","text":"Explicar ambas ideas, compararlas con el objetivo y acordar cuál probar."},{"id":"1","text":"Dividir el tiempo entre ambas ideas aunque ninguna cumpla el objetivo."},{"id":"2","text":"Votar de inmediato sin escuchar argumentos para ahorrar tiempo."},{"id":"3","text":"Pedir al docente que elija sin explicarle las propuestas."}],"correct":["0"]}},{"id":"s01-d0-diagnostico-q11","fase":"comprobar","areas":["mat"],"cnb":["mat:4.2.4"],"title":"Reparte con una condición","prompt":"Hay **8 cajas de 24 lápices**. Se reservan **36 lápices** y se reparten los demás entre **6 equipos**. ¿Cuántos lápices recibe cada equipo?","explain":"8 × 24 = 192; 192 − 36 = 156; 156 ÷ 6 = 26.","type":"number-input","props":{"answer":26,"unit":"lápices","misconceptions":[{"value":32,"msg":"Falta descontar los lápices reservados."},{"value":156,"msg":"Falta repartir entre los seis equipos."}]}},{"id":"s01-d0-diagnostico-q12","fase":"comprobar","areas":["mat"],"cnb":["mat:4.4.1"],"title":"Cambia la partición","prompt":"Una receta usa **3/4 de litro**. La jarra nueva está dividida en **8 partes iguales**. Representa la cantidad que necesitas sin cambiar el total.","explain":"Cada cuarto equivale a dos octavos: 3/4 = 6/8.","type":"fraction-model","props":{"sourceNumerator":3,"sourceDenominator":4,"targetDenominator":8}},{"id":"s01-d0-diagnostico-q13","fase":"comprobar","areas":["mat"],"cnb":["mat:4.5.1"],"title":"Completa una medida","prompt":"Necesitas **3 m** de cuerda. Tienes un trozo de **1.25 m** y otro de **0.8 m**. ¿Cuántos metros te faltan?","explain":"1.25 + 0.80 = 2.05 m disponibles; 3.00 − 2.05 = 0.95 m faltantes.","type":"number-input","props":{"answer":0.95,"allowDecimal":true,"unit":"m","misconceptions":[{"value":2.05,"msg":"Esa es la cuerda disponible; calcula cuánto falta."}]}},{"id":"s01-d0-diagnostico-q14","fase":"comprobar","areas":["l1"],"cnb":["l1:4.1"],"title":"Infiere con evidencia","prompt":"Lee la situación con atención y responde.","explain":"Cambió la forma de encontrar y conocer los libros; no se compraron más.","type":"reading","props":{"passage":"Nadie tomaba libros del rincón de lectura. El grupo puso rótulos por tema y recomendaciones. La semana siguiente se prestaron más libros, sin comprar ninguno nuevo. **¿Qué explicación encaja mejor?**","questions":[{"q":"Elige tu respuesta.","options":[{"id":"0","text":"Los libros nuevos atrajeron a todos."},{"id":"1","text":"Los rótulos hicieron innecesario leer."},{"id":"2","text":"Los rótulos ayudaron a encontrar libros de interés."},{"id":"3","text":"El rincón cerró durante toda la semana."}],"correct":"2"}]}},{"id":"s01-d0-diagnostico-q15","fase":"comprobar","areas":["l1"],"cnb":["l1:2.3"],"title":"Sostén una propuesta","prompt":"¿Qué oración combina una **propuesta y una razón que la apoya**?","explain":"La propuesta se apoya en una observación relacionada con los residuos.","type":"choice","props":{"options":[{"id":"0","text":"Separemos residuos porque observamos papel mezclado con restos de comida."},{"id":"1","text":"Separemos residuos porque ayer fue martes."},{"id":"2","text":"Los residuos están en el patio y el patio tiene una puerta."},{"id":"3","text":"Separemos residuos porque es la mejor idea y punto."}],"correct":["0"]}},{"id":"s01-d0-diagnostico-q16","fase":"comprobar","areas":["cnt"],"cnb":["cnt:8.2"],"title":"Detecta un experimento confuso","prompt":"Para probar qué suelo retiene más agua, un equipo vierte **100 ml en arena** y **200 ml en tierra**, usando recipientes distintos. **¿Qué debería cambiar?**","explain":"Hay que usar iguales cantidades de agua y suelo, recipientes equivalentes y el mismo tiempo de observación.","type":"choice","props":{"options":[{"id":"0","text":"Agregar todavía más agua a la tierra."},{"id":"1","text":"Medir solo el color de cada suelo."},{"id":"2","text":"Usar solo arena y decir que representa todos los suelos."},{"id":"3","text":"Usar igual agua y cantidad de suelo, recipientes equivalentes y el mismo tiempo."}],"correct":["3"]}},{"id":"s01-d0-diagnostico-q17","fase":"comprobar","areas":["cnt"],"cnb":["cnt:8.1"],"title":"Distingue datos y suposiciones","prompt":"Lee la situación con atención y responde.","explain":"Se recogieron menos envolturas, pero los registros no dicen quién las tiró ni prueban la causa del cambio.","type":"reading","props":{"passage":"En tres días se recogieron **12, 9 y 6 envolturas** del patio, a la misma hora. **¿Qué afirmación sostienen esos registros?**","questions":[{"q":"Elige tu respuesta.","options":[{"id":"0","text":"Ya nadie tira basura en la escuela."},{"id":"1","text":"El tercer día se recogieron la mitad que el primero."},{"id":"2","text":"Cada estudiante dejó exactamente una envoltura."},{"id":"3","text":"La reducción se debe con certeza a un cartel nuevo."}],"correct":"1"}]}},{"id":"s01-d0-diagnostico-q18","fase":"comprobar","areas":["ccss"],"cnb":["ccss:5.2"],"title":"Contrasta perspectivas","prompt":"Una entrevista afirma que el mercado comenzó en **1980**; una fotografía fechada en **1975** ya muestra puestos allí. **¿Qué conviene hacer antes de escribir su historia?**","explain":"Contrastar las fuentes ayuda a distinguir un mercado anterior de su posible inauguración formal.","type":"choice","props":{"options":[{"id":"0","text":"Descartar la fotografía por ser antigua."},{"id":"1","text":"Copiar solo la entrevista porque alguien lo recuerda."},{"id":"2","text":"Revisar ambas fuentes y buscar registros que expliquen la diferencia."},{"id":"3","text":"Afirmar que ambas cuentan exactamente lo mismo."}],"correct":["2"]}},{"id":"s01-d0-diagnostico-q19","fase":"comprobar","areas":["l3"],"cnb":["l3:3.3"],"title":"Aplica una condición en inglés","prompt":"Lee la situación con atención y responde.","explain":"La tarjeta verde activa la segunda instrucción: sentarse junto a la ventana.","type":"reading","props":{"passage":"Read: **“If you have a blue card, stand next to the door. If you have a green card, sit by the window.”** You have a **green card**. What should you do?","questions":[{"q":"Elige tu respuesta.","options":[{"id":"0","text":"Stand next to the door."},{"id":"1","text":"Give the card to a friend."},{"id":"2","text":"Sit next to the door."},{"id":"3","text":"Sit by the window."}],"correct":"3"}]}},{"id":"s01-d0-diagnostico-q20","fase":"comprobar","areas":["fc"],"cnb":["fc:4.3"],"title":"Coopera con una dificultad","prompt":"Una compañera comprende las ideas, pero necesita más tiempo para leer las instrucciones. **¿Qué acuerdo combina participación y avance?**","explain":"Leer juntos y acordar roles y tiempo permite participar sin sustituir su aporte.","type":"choice","props":{"options":[{"id":"0","text":"Hacer su parte por ella para terminar pronto."},{"id":"1","text":"Leer juntos y acordar roles y tiempo para que también aporte."},{"id":"2","text":"Darle siempre la tarea más corta sin preguntarle."},{"id":"3","text":"Esperar en silencio sin revisar la organización del equipo."}],"correct":["1"]}},{"id":"s01-d0-diagnostico-reflexion-v2","fase":"reflexionar","ambito":"ser","areas":["fc"],"cnb":[],"prompt":"Piensa en cómo aprendes. **No hay respuestas correctas o incorrectas.** Tu docente usará esto para conversar contigo.","type":"reflection","props":{"statements":["Puedo explicar por qué elegí una respuesta","Cuando no entiendo una consigna, puedo decir qué parte me confunde y pedir ayuda","Puedo organizar mis materiales y empezar una tarea","Si una estrategia no funciona, puedo probar otra y revisar mi trabajo"],"commitments":["Quiero practicar cómo explicar mis ideas","Quiero apoyo para comprender las consignas","Quiero organizar mejor mis tiempos y materiales","Quiero desafíos nuevos y revisar mis estrategias"]}}]}},{"missionId":"s01","version":"cnb-sexto-cb33a9d7d92e26c0","lesson":{"id":"s01-cnt-1","title":"El origen del universo y de la Tierra","icon":"Sparkles","minutes":15,"gancho":"Una noche sin luna, en el campo, se ven miles de estrellas. ¿Alguna vez te has preguntado cómo empezó todo eso?","objetivos":["Narrar el relato judeocristiano de la creación en sus siete días","Reconocer otros relatos de origen, como el del Popol Vuh, y la explicación científica","Distinguir un relato de fe o cultural de una explicación científica, con respeto"],"resumen":["Una cosmovisión es la manera en que un pueblo entiende el mundo, su origen y el lugar del ser humano en él.","Según el relato judeocristiano del Génesis, Dios creó el mundo en seis días y descansó el séptimo: luz; cielo; tierra, mares y plantas; Sol, Luna y estrellas; peces y aves; animales terrestres y seres humanos.","El Popol Vuh, libro sagrado k'iche', narra que los creadores formaron a los primeros seres humanos de barro, luego de madera y por último de maíz.","La ciencia explica que el universo comenzó hace unos 13,800 millones de años (Gran Explosión) y que la Tierra se formó hace unos 4,500 millones de años. Los relatos y la ciencia responden preguntas distintas y se respetan."],"media":{"id":"s01-cnt-1-origenes","kind":"image","title":"Tres maneras de contar el origen","aspect":"16:9","alt":"Ilustración dividida en tres paneles: un paisaje luminoso que representa los días de la creación, una escena de maíz y montañas inspirada en el Popol Vuh, y una nube de gas y polvo que forma el Sol y los planetas.","brief":"Ilustración horizontal en tres paneles con el mismo estilo cálido de libro infantil. Panel 1 \\"Génesis\\": luz que se abre sobre aguas, luego tierra con plantas, Sol, Luna y estrellas, aves y peces (sin representar a Dios con rostro). Panel 2 \\"Popol Vuh\\": montañas de Guatemala, figuras sencillas de barro, de madera y de maíz amarillo y blanco, en colores tierra. Panel 3 \\"Ciencia\\": nube de gas y polvo girando que forma el Sol y planetas pequeños, con la Tierra aún roja y caliente. Rótulos breves en cada panel. Respeto total a cada tradición; nada caricaturesco. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:1.1.1"],"ambito":"conocer","title":"Relatos y explicaciones","prompt":"Antes de conocer los relatos, aprende tres palabras clave. Toca cada tarjeta.","type":"explain","props":{"icon":"Globe","body":"Preguntar **\\"¿de dónde venimos?\\"** es muy humano. Las respuestas dependen de **para qué** se hace la pregunta.","reveal":[{"icon":"Eye","front":"Cosmovisión","back":"La **manera en que un pueblo entiende el mundo**: su origen, la naturaleza, lo sagrado y el lugar del ser humano."},{"icon":"BookOpen","front":"Relato de origen","back":"Una narración de **fe o de cultura** que explica el comienzo del mundo y enseña **valores**: gratitud, respeto, cuidado de la vida. Se transmite de generación en generación."},{"icon":"Microscope","front":"Explicación científica","back":"Una explicación que se construye con **observaciones, mediciones y pruebas**, y que **cambia** si aparecen pruebas nuevas."}]},"id":"s01-cnt-1-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.1.1"],"ambito":"conocer","prompt":"Las personas se preguntan desde hace miles de años **cómo empezó el mundo**. ¿Cuántas explicaciones crees que existen?","explain":"Existen **muchas**: cada pueblo tiene su relato de origen, y además la ciencia tiene su propia explicación, basada en pruebas. Hoy conocerás tres.","type":"choice","props":{"options":[{"id":"a","text":"Una sola, la misma en todo el mundo","icon":"Circle","feedback":"Cada cultura ha contado el origen a su manera. ¡Hay muchas!"},{"id":"b","text":"Varias: cada pueblo tiene la suya, y la ciencia tiene otra","icon":"Layers"},{"id":"c","text":"Ninguna: nadie se lo ha preguntado","icon":"X","feedback":"Es una de las preguntas más antiguas de la humanidad."}],"correct":["b"]},"id":"s01-cnt-1-2"},{"fase":"construir","areas":["cnt","l1"],"cnb":["cnt:1.1.1"],"ambito":"conocer","title":"El relato judeocristiano","prompt":"Lee con atención el relato de la creación según el libro del **Génesis**, que comparten judíos y cristianos.","hint":"Si dudas, vuelve a leer el párrafo de cada día.","type":"reading","props":{"heading":"La creación en siete días","genre":"Relato de origen (resumen)","passage":"Según el primer libro de la Biblia, el Génesis, al principio todo estaba vacío y a oscuras, y el espíritu de Dios se movía sobre las aguas.\\n\\nEl **primer día**, Dios dijo: \\"Que exista la luz\\", y separó la luz de la oscuridad: así surgieron el día y la noche. El **segundo día** hizo el firmamento, el cielo, que separó unas aguas de otras. El **tercer día** juntó las aguas en mares, hizo aparecer la tierra seca y la cubrió de plantas y árboles con semilla.\\n\\nEl **cuarto día** colocó en el cielo el Sol, la Luna y las estrellas para marcar los días, las estaciones y los años. El **quinto día** creó los peces y los animales del agua, y las aves del cielo. El **sexto día** creó los animales de la tierra y, por último, al ser humano, hombre y mujer, y les encargó cuidar la creación.\\n\\nEl **séptimo día**, Dios descansó. Por eso, para muchas familias creyentes, hay un día de la semana dedicado al descanso y a la oración.","questions":[{"q":"¿Qué fue lo primero que se creó, según el relato?","options":[{"id":"a","text":"Los animales"},{"id":"b","text":"La luz"},{"id":"c","text":"El ser humano"}],"correct":"b","why":"El primer día: \\"Que exista la luz\\"."},{"q":"¿Qué día aparecen el Sol, la Luna y las estrellas?","options":[{"id":"a","text":"El cuarto día"},{"id":"b","text":"El primer día"},{"id":"c","text":"El séptimo día"}],"correct":"a"},{"q":"Según el relato, ¿qué encargo recibe el ser humano?","options":[{"id":"a","text":"Dominar a los demás pueblos"},{"id":"b","text":"Cuidar la creación"},{"id":"c","text":"Contar las estrellas"}],"correct":"b","why":"El relato enseña un valor: la naturaleza es un regalo que hay que cuidar."}]},"id":"s01-cnt-1-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.1.1"],"ambito":"conocer","prompt":"Ordena lo que se creó cada día, según el Génesis, del primero al sexto.","hint":"Primero lo que da luz y espacio, luego la tierra con plantas, después los astros y al final los animales y el ser humano.","explain":"Luz (1) → cielo (2) → tierra, mares y plantas (3) → Sol, Luna y estrellas (4) → peces y aves (5) → animales terrestres y seres humanos (6). El séptimo día es de descanso.","type":"order","props":{"labels":{"start":"Primer día","end":"Sexto día"},"items":[{"id":"d1","text":"La luz: el día y la noche","icon":"Sun"},{"id":"d2","text":"El firmamento o cielo","icon":"Cloud"},{"id":"d3","text":"La tierra seca, los mares y las plantas","icon":"Sprout"},{"id":"d4","text":"El Sol, la Luna y las estrellas","icon":"Moon"},{"id":"d5","text":"Los peces y las aves","icon":"Fish"},{"id":"d6","text":"Los animales terrestres y el ser humano","icon":"Users"}]},"id":"s01-cnt-1-4"},{"fase":"construir","areas":["cnt","ccss"],"cnb":["cnt:1.1.1"],"ambito":"conocer","title":"Otro relato de Guatemala: el Popol Vuh","prompt":"En Guatemala conviven varias cosmovisiones. El **Popol Vuh** es el libro sagrado del pueblo **maya k'iche'**. Toca las tarjetas.","type":"explain","props":{"icon":"Wheat","body":"En el Popol Vuh, los creadores **Tepeu** y **Gucumatz**, junto con el **Corazón del Cielo**, formaron la tierra, las montañas y los animales. Luego quisieron crear seres que pudieran hablar, recordar y agradecer.","reveal":[{"icon":"Droplets","front":"Seres de barro","back":"Se deshacían con el agua y no podían pensar. Los creadores los deshicieron."},{"icon":"TreeDeciduous","front":"Seres de madera","back":"Hablaban y se multiplicaban, pero **no tenían corazón ni memoria** y no agradecían. Fueron destruidos."},{"icon":"Wheat","front":"Seres de maíz","back":"Con masa de **maíz amarillo y blanco** se formaron los primeros seres humanos verdaderos, capaces de pensar y agradecer. Por eso el maíz es sagrado para muchos pueblos mayas."}]},"id":"s01-cnt-1-5"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.1.1"],"ambito":"conocer","prompt":"¿De qué relato es cada idea? Clasifícala.","hint":"Busca pistas: \\"siete días\\" es del Génesis; el barro, la madera y el maíz son del Popol Vuh.","explain":"Los dos relatos son distintos, pero comparten algo: explican el origen y enseñan a **agradecer y cuidar** la vida.","type":"sort","props":{"buckets":[{"id":"gen","label":"Génesis (judeocristiano)","icon":"BookOpen","color":"var(--area-cnt)"},{"id":"pop","label":"Popol Vuh (maya k'iche')","icon":"Wheat","color":"var(--c-maiz-strong)"},{"id":"amb","label":"Los dos","icon":"Copy","color":"var(--area-ccss)"}],"items":[{"id":"g1","text":"La creación ocurre en seis días y el séptimo es de descanso","bucket":"gen"},{"id":"g2","text":"Los primeros seres humanos verdaderos se forman de maíz","bucket":"pop"},{"id":"g3","text":"Hubo intentos con barro y con madera","bucket":"pop"},{"id":"g4","text":"El ser humano, hombre y mujer, se crea el sexto día","bucket":"gen"},{"id":"g5","text":"Explica el origen del mundo y enseña valores","bucket":"amb"},{"id":"g6","text":"Se transmite de generación en generación","bucket":"amb"}]},"id":"s01-cnt-1-6"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.1.1"],"ambito":"conocer","title":"La explicación de la ciencia","prompt":"Los científicos estudian la luz de las estrellas, las rocas y los meteoritos para reconstruir la historia del universo. Mira la animación y toca las tarjetas.","media":{"id":"s01-cnt-1-granexplosion","kind":"animation","title":"De la Gran Explosión a la Tierra","aspect":"16:9","duration":50,"alt":"Un punto de luz se expande y forma galaxias; en una de ellas una nube de gas y polvo gira y forma el Sol y los planetas; la Tierra pasa de roca ardiente a planeta azul con océanos.","brief":"Animación 2D de 50 s, estilo sencillo y colorido. (1) Un punto brillante se expande: rótulo \\"Gran Explosión, hace unos 13,800 millones de años\\". (2) Se forman estrellas y galaxias. (3) Acercamiento a una nube de gas y polvo que gira; en el centro nace el Sol y alrededor se juntan planetas: rótulo \\"hace unos 4,600 millones de años\\". (4) La Tierra: roca caliente con volcanes, se enfría, llueve durante mucho tiempo y se forman los océanos: \\"hace unos 4,500 millones de años\\". (5) Primeras formas de vida microscópicas en el agua. Narración en español, calmada, con subtítulos. No mezclar con imágenes religiosas."},"type":"explain","props":{"icon":"Rocket","body":"La ciencia **no** usa relatos: usa **pruebas**. Por ejemplo, los telescopios muestran que las galaxias se alejan unas de otras, como si todo hubiera empezado en un mismo punto.","reveal":[{"icon":"Sparkles","front":"Gran Explosión","back":"Hace unos **13,800 millones de años**, el universo era muy pequeño y caliente, y comenzó a **expandirse**. Así se formaron, con el tiempo, las galaxias y las estrellas."},{"icon":"Sun","front":"Nace el Sol","back":"Hace unos **4,600 millones de años**, una nube de gas y polvo se juntó por la gravedad: en el centro se formó el **Sol** y alrededor, los planetas."},{"icon":"Earth","front":"La Tierra","back":"Se formó hace unos **4,500 millones de años**. Primero era roca ardiente; al enfriarse, la lluvia formó los **océanos**, y allí surgieron los primeros seres vivos, **microscópicos**."}]},"id":"s01-cnt-1-7"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.1.1"],"ambito":"conocer","prompt":"Según la explicación científica, ordena estos sucesos del **más antiguo** al **más reciente**.","explain":"Primero el universo se expande; luego nacen galaxias y estrellas; después el Sol y la Tierra; la Tierra se enfría y forma océanos, y en el agua aparecen los primeros seres vivos.","type":"order","props":{"labels":{"start":"Más antiguo","end":"Más reciente"},"items":[{"id":"c1","text":"El universo comienza a expandirse (Gran Explosión)","icon":"Sparkles"},{"id":"c2","text":"Se forman las primeras galaxias y estrellas","icon":"Star"},{"id":"c3","text":"Una nube de gas y polvo forma el Sol y los planetas","icon":"Sun"},{"id":"c4","text":"La Tierra se enfría y se forman los océanos","icon":"Waves"},{"id":"c5","text":"Aparecen los primeros seres vivos, microscópicos, en el agua","icon":"Microscope"}]},"id":"s01-cnt-1-8"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.1.1"],"ambito":"conocer","prompt":"¿Es una característica de un **relato de fe o cultural** o de una **explicación científica**?","explain":"La ciencia pregunta **cómo** ocurrieron las cosas y lo comprueba con pruebas. Los relatos de fe y culturales responden sobre todo **por qué** y **para qué** existimos. Muchas personas valoran las dos cosas.","type":"sort","props":{"buckets":[{"id":"rel","label":"Relato de fe o cultural","icon":"BookOpen","color":"var(--c-maiz-strong)"},{"id":"cie","label":"Explicación científica","icon":"Microscope","color":"var(--area-cnt)"}],"items":[{"id":"r1","text":"Se basa en observaciones con telescopios y en mediciones","bucket":"cie"},{"id":"r2","text":"Enseña a agradecer la vida y a cuidar la naturaleza","bucket":"rel"},{"id":"r3","text":"Cambia si se descubren pruebas nuevas","bucket":"cie"},{"id":"r4","text":"Se cuenta en la familia y en las ceremonias de la comunidad","bucket":"rel"},{"id":"r5","text":"Calcula la edad de la Tierra midiendo rocas y meteoritos","bucket":"cie"},{"id":"r6","text":"Habla de la relación de las personas con lo sagrado","bucket":"rel"}]},"id":"s01-cnt-1-9"},{"fase":"aplicar","areas":["cnt","fc"],"cnb":["cnt:1.1.1"],"ambito":"convivir","prompt":"Conocer distintas cosmovisiones también es aprender a convivir. ¿Qué harías tú?","type":"dilemma","props":{"scene":{"icon":"MessagesSquare","text":"En clase, **Ixchel** cuenta que su abuelo le narra el Popol Vuh, y **Samuel** comparte que en su iglesia leen el Génesis. **Kevin** se ríe y dice: \\"Eso son cuentos; lo único que vale es la ciencia\\"."},"options":[{"id":"a","icon":"ThumbsUp","text":"Reírme con Kevin","consequence":"Ixchel y Samuel se sienten ofendidos y dejan de participar. Burlarse de las creencias de otras personas divide al grupo.","values":["Burla"],"constructive":false},{"id":"b","icon":"Handshake","text":"Decir que la ciencia y los relatos responden preguntas distintas, y que todos merecen respeto","consequence":"El grupo conversa con calma. Kevin entiende que puede valorar la ciencia sin despreciar la fe ni la cultura de los demás.","values":["Respeto","Diálogo"],"constructive":true},{"id":"c","icon":"MessageCircle","text":"Pedir a Ixchel y a Samuel que cuenten más, y a Kevin que explique la Gran Explosión","consequence":"Todos aprenden algo nuevo: el grupo descubre que escuchar distintas miradas enriquece.","values":["Curiosidad","Interculturalidad"],"constructive":true}]},"id":"s01-cnt-1-10"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:1.1.1"],"prompt":"Según el relato judeocristiano del Génesis, ¿qué fue creado el **quinto día**?","type":"choice","props":{"options":[{"id":"a","text":"Los peces y las aves"},{"id":"b","text":"La luz"},{"id":"c","text":"El Sol, la Luna y las estrellas"},{"id":"d","text":"El ser humano"}],"correct":["a"]},"id":"s01-cnt-1-11"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:1.1.1"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"En el Popol Vuh, los primeros seres humanos verdaderos fueron formados de maíz.","answer":true},{"text":"Según el Génesis, el séptimo día fue un día de descanso.","answer":true},{"text":"Según la ciencia, la Tierra se formó antes que el universo.","answer":false,"why":"El universo comenzó hace unos 13,800 millones de años; la Tierra se formó mucho después, hace unos 4,500 millones."},{"text":"Una explicación científica nunca cambia, aunque aparezcan pruebas nuevas.","answer":false,"why":"La ciencia se corrige y mejora cuando hay pruebas nuevas."}]},"id":"s01-cnt-1-12"}],"kind":"materia","area":"cnt","day":1}},{"missionId":"s01","version":"cnb-sexto-2836ea13d5362f41","lesson":{"id":"s01-ccss-1","title":"Latitud y longitud: la dirección de cada lugar","icon":"Globe","minutes":14,"gancho":"Tu casa tiene una dirección para que el cartero la encuentre. ¿Cómo le darías la \\"dirección\\" de Guatemala a alguien que está al otro lado del mundo?","objetivos":["Reconocer el ecuador, el meridiano de Greenwich, los paralelos y los meridianos","Explicar qué miden la latitud y la longitud","Ubicar un punto en un mapa cuadriculado con sus coordenadas geográficas"],"resumen":["Los paralelos son líneas imaginarias horizontales; el más importante es el ecuador (0°), que divide la Tierra en hemisferio norte y hemisferio sur.","Los meridianos son líneas imaginarias que van de polo a polo; el meridiano de Greenwich (0°) divide la Tierra en hemisferio este (oriente) y hemisferio oeste (occidente).","La latitud es la distancia en grados desde el ecuador hacia el norte o el sur (de 0° a 90°). La longitud es la distancia en grados desde Greenwich hacia el este o el oeste (de 0° a 180°).","Guatemala está aproximadamente entre los 13° y 18° de latitud norte y entre los 88° y 92° de longitud oeste."],"media":{"id":"s01-ccss-1-red","kind":"animation","title":"La red de líneas imaginarias","aspect":"16:9","duration":45,"alt":"Un globo terráqueo gira; aparecen el ecuador y los paralelos en azul, luego Greenwich y los meridianos en naranja, y finalmente un punto se ubica sobre Guatemala.","brief":"Animación 2D de 45 s. Un globo terráqueo gira despacio. (1) Aparece el ecuador en azul con la etiqueta \\"Ecuador 0°\\" y luego otros paralelos cada 30° (30° N, 60° N, 30° S, 60° S). (2) Aparece el meridiano de Greenwich en naranja \\"0°\\" y meridianos cada 30° hacia el este y el oeste. (3) Una lupa se acerca a Centroamérica y un punto marca Guatemala con la leyenda \\"aprox. 15° N, 90° O\\". Narración en español: \\"Latitud: cuánto al norte o al sur. Longitud: cuánto al este o al oeste.\\" Subtítulos. Colores planos, sin banderas."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:1.2.1"],"ambito":"conocer","title":"Líneas que no se ven, pero sirven","prompt":"Para ubicar lugares, los geógrafos dibujan sobre la Tierra una **red de líneas imaginarias**. No existen en el suelo: están en mapas y globos. Toca cada tarjeta.","media":{"id":"s01-ccss-1-hemisferios","kind":"diagram","title":"Cuatro hemisferios","aspect":"16:9","alt":"Dos globos: el primero cortado por el ecuador en norte y sur; el segundo cortado por el meridiano de Greenwich en este y oeste. Guatemala marcada en norte y oeste.","brief":"Diagrama con dos globos terráqueos lado a lado. Globo 1: el ecuador en azul grueso; mitad superior rotulada \\"Hemisferio norte\\" y mitad inferior \\"Hemisferio sur\\". Globo 2: el meridiano de Greenwich en naranja grueso; mitad izquierda \\"Hemisferio oeste (occidente)\\" y mitad derecha \\"Hemisferio este (oriente)\\". En ambos, un punto rojo pequeño sobre Guatemala con la etiqueta \\"Guatemala\\". Fondo blanco, textos grandes. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"type":"explain","props":{"icon":"Globe","body":"Guatemala está en el hemisferio **norte** (arriba del ecuador) y en el hemisferio **oeste** (a la izquierda de Greenwich).","reveal":[{"icon":"Minus","front":"Paralelos","back":"Círculos **horizontales** que rodean la Tierra. El más largo es el **ecuador (0°)**. Los paralelos llegan hasta 90° en cada polo."},{"icon":"Circle","front":"Ecuador","back":"Divide la Tierra en **hemisferio norte** y **hemisferio sur**. Pasa por países como Ecuador, Colombia y Brasil."},{"icon":"Slash","front":"Meridianos","back":"Semicírculos que van **de polo a polo**. Todos se juntan en el Polo Norte y en el Polo Sur."},{"icon":"MapPin","front":"Meridiano de Greenwich","back":"Es el meridiano **0°**. Pasa por Greenwich, en Londres (Inglaterra), y divide la Tierra en **este** y **oeste**."}]},"id":"s01-ccss-1-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:1.2.1"],"ambito":"conocer","prompt":"En una sala de cine, tu boleto dice **\\"Fila F, asiento 12\\"**. ¿Por qué necesitas **dos** datos para encontrar tu lugar?","explain":"Con un solo dato habría muchos lugares posibles. Con **dos datos que se cruzan** hay un solo lugar. La Tierra funciona igual: usamos **latitud** y **longitud**.","type":"choice","props":{"options":[{"id":"a","text":"Porque la fila dice qué tan adelante y el asiento dice qué tan a un lado: juntos marcan un solo lugar","icon":"Target"},{"id":"b","text":"Porque así el boleto se ve más bonito","icon":"Sparkles","feedback":"No es por adorno: con solo \\"fila F\\" habría muchos asientos posibles."},{"id":"c","text":"No hace falta: con la fila es suficiente","icon":"X","feedback":"En la fila F hay muchos asientos. Necesitas el número para saber cuál es el tuyo."}],"correct":["a"]},"id":"s01-ccss-1-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:1.2.1"],"prompt":"Clasifica cada descripción: ¿habla de un **paralelo** o de un **meridiano**?","hint":"Los paralelos son horizontales y nunca se tocan. Los meridianos van de un polo al otro y se juntan en los polos.","explain":"Paralelos: horizontales, miden la latitud, el principal es el ecuador. Meridianos: de polo a polo, miden la longitud, el principal es Greenwich.","type":"sort","props":{"buckets":[{"id":"par","label":"Paralelo","icon":"Minus","color":"var(--area-ccss)"},{"id":"mer","label":"Meridiano","icon":"Slash","color":"var(--c-maiz-strong)"}],"items":[{"id":"p1","text":"El ecuador","bucket":"par"},{"id":"p2","text":"Greenwich","bucket":"mer"},{"id":"p3","text":"Línea que va del Polo Norte al Polo Sur","bucket":"mer"},{"id":"p4","text":"Círculo horizontal que rodea la Tierra","bucket":"par"},{"id":"p5","text":"Se usa para medir la latitud","bucket":"par","feedback":"La latitud se cuenta desde el ecuador, recorriendo los paralelos hacia el norte o el sur."},{"id":"p6","text":"Se usa para medir la longitud","bucket":"mer"}]},"id":"s01-ccss-1-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:1.2.1"],"ambito":"conocer","title":"Latitud y longitud","prompt":"Las **coordenadas geográficas** son dos números en **grados (°)** que dicen dónde está un lugar. Toca cada tarjeta.","type":"explain","props":{"icon":"Compass","body":"Se escriben así: **15° N, 90° O**. Primero la latitud (con N o S) y luego la longitud (con E u O).","reveal":[{"icon":"ArrowUpDown","front":"Latitud","back":"Cuántos grados está un lugar **al norte (N) o al sur (S) del ecuador**. Va de 0° (ecuador) a 90° (polos)."},{"icon":"ArrowLeftRight","front":"Longitud","back":"Cuántos grados está un lugar **al este (E) o al oeste (O) de Greenwich**. Va de 0° a 180°."},{"icon":"MapPin","front":"Guatemala","back":"Está aproximadamente entre **13° y 18° N** y entre **88° y 92° O**. La capital queda cerca de **15° N, 90° O**."},{"icon":"AlertTriangle","front":"Error frecuente","back":"Escribir solo \\"15°\\" no basta: **15° N** y **15° S** son lugares muy lejanos. Siempre di la dirección."}]},"id":"s01-ccss-1-4"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:1.2.1"],"ambito":"hacer","title":"Ejemplo resuelto: leer un mapa cuadriculado","prompt":"En los mapas escolares a veces se usa una **cuadrícula**. Supongamos que en este mapa **cada cuadro mide 10°**: el eje horizontal es el ecuador y el vertical es Greenwich.","type":"worked-example","props":{"icon":"Map","problem":"Un barco está **3 cuadros a la izquierda** de Greenwich y **2 cuadros arriba** del ecuador. ¿Cuáles son sus coordenadas?","steps":[{"text":"Arriba del ecuador es **norte**. 2 cuadros × 10° = **20° N**.","why":"La latitud se cuenta hacia arriba (N) o hacia abajo (S) desde el ecuador."},{"text":"A la izquierda de Greenwich es **oeste**. 3 cuadros × 10° = **30° O**.","why":"La longitud se cuenta hacia la derecha (E) o la izquierda (O) desde Greenwich."},{"text":"Se escribe primero la latitud y luego la longitud: **20° N, 30° O**."},{"text":"En la cuadrícula del plano, ese punto es **(−3, 2)**: x negativa porque va al oeste, y positiva porque va al norte."}],"answer":"El barco está en **20° N, 30° O**.","tip":"Truco: norte y este son como los números positivos del plano; sur y oeste, como los negativos."},"id":"s01-ccss-1-5"},{"fase":"construir","areas":["ccss","mat"],"cnb":["ccss:1.2.1"],"ambito":"hacer","prompt":"Ahora tú, con ayuda. En este mapa cuadriculado **cada cuadro = 10°**. Coloca la lancha en **30° N, 20° E**.","hint":"Este = a la derecha (x positiva): 20° son 2 cuadros. Norte = arriba (y positiva): 30° son 3 cuadros.","explain":"20° E → x = 2; 30° N → y = 3. El punto es (2, 3).","type":"coordinate-map","props":{"range":{"xmin":-5,"xmax":5,"ymin":-4,"ymax":4},"task":{"kind":"place","x":2,"y":3,"emoji":"🚤","label":"la lancha"}},"id":"s01-ccss-1-6"},{"fase":"aplicar","areas":["ccss","mat"],"cnb":["ccss:1.2.1"],"ambito":"hacer","prompt":"Mismo mapa (cada cuadro = 10°). Una estación científica está en **20° S, 40° O**. Colócala.","explain":"40° O → 4 cuadros a la izquierda (x = −4). 20° S → 2 cuadros abajo (y = −2). El punto es (−4, −2).","type":"coordinate-map","props":{"range":{"xmin":-5,"xmax":5,"ymin":-4,"ymax":4},"task":{"kind":"place","x":-4,"y":-2,"emoji":"🏕️","label":"la estación"}},"id":"s01-ccss-1-7"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:1.2.1"],"ambito":"conocer","prompt":"Un lugar está en **0° de latitud**. ¿Qué sabemos seguro de él?","explain":"Latitud 0° significa que está **sobre el ecuador**. Su longitud puede ser cualquiera: por eso hay muchos lugares con latitud 0°.","type":"choice","props":{"options":[{"id":"a","text":"Está sobre el ecuador"},{"id":"b","text":"Está en el Polo Norte","feedback":"El Polo Norte está a 90° N, lo más lejos posible del ecuador."},{"id":"c","text":"Está en Greenwich","feedback":"Greenwich es la longitud 0°, no la latitud 0°."}],"correct":["a"]},"id":"s01-ccss-1-8"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:1.2.1"],"prompt":"¿Verdadero o falso? Piensa en dónde está Guatemala.","explain":"Guatemala está al norte del ecuador y al oeste de Greenwich; por eso sus coordenadas llevan N y O.","type":"true-false","props":{"statements":[{"text":"Guatemala está en el hemisferio norte.","answer":true},{"text":"Guatemala está en el hemisferio este.","answer":false,"why":"Está a la izquierda (al oeste) del meridiano de Greenwich."},{"text":"La longitud de Guatemala se escribe con la letra O (oeste).","answer":true},{"text":"Si un lugar está en 15° S, está al norte del ecuador.","answer":false,"why":"La S significa sur: está debajo del ecuador."}]},"id":"s01-ccss-1-9"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:1.2.1"],"prompt":"¿Qué mide la **longitud**?","type":"choice","props":{"options":[{"id":"a","text":"La distancia en grados al este o al oeste del meridiano de Greenwich"},{"id":"b","text":"La distancia en grados al norte o al sur del ecuador"},{"id":"c","text":"La altura de un lugar sobre el nivel del mar"}],"correct":["a"]},"id":"s01-ccss-1-10"},{"fase":"comprobar","areas":["ccss","mat"],"cnb":["ccss:1.2.1"],"prompt":"Cada cuadro = 10°. Coloca el avión en **10° N, 30° O**.","type":"coordinate-map","props":{"range":{"xmin":-5,"xmax":5,"ymin":-4,"ymax":4},"task":{"kind":"place","x":-3,"y":1,"emoji":"✈️","label":"el avión","at":"10° N, 30° O"}},"id":"s01-ccss-1-11"}],"kind":"materia","area":"ccss","day":1}},{"missionId":"s01","version":"cnb-sexto-7dc391ffab020f6e","lesson":{"id":"s01-art-1","title":"Sonidos largos y cortos: las figuras musicales","icon":"Music","minutes":14,"gancho":"Cuando alguien toca la marimba, algunas notas suenan cortitas y otras se quedan vibrando un buen rato. ¿Cómo se escribe eso para que otra persona lo pueda tocar igual?","objetivos":["Reconocer las cuatro cualidades del sonido","Identificar el pulso y la duración de la redonda, la blanca, la negra y la corchea","Leer y escribir ritmos sencillos contando tiempos"],"resumen":["El sonido tiene cuatro cualidades: altura (grave o agudo), duración (largo o corto), intensidad (fuerte o suave) y timbre (lo que hace que cada instrumento o voz suene distinto).","El pulso es el latido constante de la música, como el tic-tac de un reloj. Cada golpe de pulso es un tiempo.","Figuras musicales: redonda = 4 tiempos, blanca = 2 tiempos, negra = 1 tiempo, corchea = medio tiempo (dos corcheas duran lo mismo que una negra).","Para leer un ritmo, cuenta los tiempos de cada figura y súmalos; puedes decirlo con sílabas: negra \\"ta\\", dos corcheas \\"ti-ti\\", blanca \\"ta-a\\", redonda \\"ta-a-a-a\\"."],"media":{"id":"s01-art-1-figuras","kind":"animation","title":"Figuras que duran más o menos","aspect":"16:9","duration":50,"alt":"Una marimba toca un pulso constante mientras aparecen la redonda, la blanca, la negra y dos corcheas; cada figura se estira sobre una regla de 4 tiempos para mostrar cuánto dura.","brief":"Animación 2D de 50 s. Arriba, un metrónomo sencillo (sin marca) marca 4 pulsos con un punto que salta. Abajo, una \\"regla\\" de 4 casillas iguales rotuladas 1-2-3-4. Aparece la redonda y ocupa las 4 casillas mientras suena una nota larga de marimba; luego dos blancas (2 casillas cada una), cuatro negras (1 casilla) y ocho corcheas (media casilla). Cada figura se dibuja grande en negro sobre fondo crema, con su nombre y su duración (\\"4 tiempos\\", \\"2\\", \\"1\\", \\"½\\"). Narración en español neutro, voz cálida; subtítulos."},"steps":[{"fase":"explorar","areas":["art"],"cnb":["art:1.1.1"],"ambito":"conocer","title":"Las cuatro cualidades del sonido","prompt":"Todo sonido tiene cuatro **cualidades**. Toca cada tarjeta.","type":"explain","props":{"icon":"Ear","body":"Los músicos escriben **partituras** para que otras personas toquen una canción igual, aunque nunca la hayan escuchado. Para eso anotan las cualidades del sonido.","reveal":[{"icon":"ArrowUpDown","front":"Altura","back":"Si el sonido es **grave** (grueso, como un tambor grande) o **agudo** (delgado, como el canto de un pajarito)."},{"icon":"Hourglass","front":"Duración","back":"Si el sonido es **largo** o **corto**. Hoy aprenderás a escribirla con **figuras musicales**."},{"icon":"Volume2","front":"Intensidad","back":"Si el sonido es **fuerte** o **suave**. No es lo mismo que la altura: un sonido agudo puede ser suave."},{"icon":"Guitar","front":"Timbre","back":"La \\"voz\\" propia de cada instrumento o persona. Por el timbre distingues una marimba de una guitarra aunque toquen la misma nota."}]},"id":"s01-art-1-1"},{"fase":"construir","areas":["art"],"cnb":["art:1.1.1"],"ambito":"conocer","prompt":"Escucha los dos sonidos de marimba. Tienen la misma nota y el mismo volumen. ¿En qué se diferencian?","explain":"Uno **dura más** que el otro. La música se escribe con símbolos que dicen, entre otras cosas, **cuánto dura** cada sonido.","media":{"id":"s01-art-1-largo-corto","kind":"audio","title":"Dos sonidos: ¿cuál dura más?","duration":12,"alt":"Se escucha la nota Sol en marimba, primero muy corta y luego larga, dejando vibrar la tecla unos cuatro segundos.","brief":"Audio limpio de 12 s: nota Sol4 en marimba de concierto tocada con baqueta suave. (1) Golpe corto apagado con la mano (≈0.5 s). (2) Silencio de 2 s. (3) La misma nota con trémolo suave sostenido ≈4 s, mismo volumen. Sin música de fondo ni voz."},"type":"choice","props":{"options":[{"id":"a","text":"Uno es más agudo que el otro","icon":"ArrowUp","feedback":"Es la misma nota, así que tienen la misma altura. Escucha cuánto tiempo suena cada uno."},{"id":"b","text":"Uno dura más que el otro","icon":"Hourglass"},{"id":"c","text":"Uno es de otro instrumento","icon":"Guitar","feedback":"Los dos son de marimba: tienen el mismo timbre."}],"correct":["b"]},"id":"s01-art-1-2"},{"fase":"construir","areas":["art"],"cnb":["art:1.1.1"],"ambito":"conocer","title":"El pulso y las figuras","prompt":"La música tiene un **pulso**: un latido constante, como el tic-tac de un reloj o tu corazón en reposo. Cada golpe de pulso se llama **tiempo**. Las figuras dicen **cuántos tiempos** dura un sonido.","media":{"id":"s01-art-1-tabla-figuras","kind":"diagram","title":"Tabla de figuras musicales","aspect":"4:3","alt":"Tabla en forma de árbol: arriba una redonda; debajo dos blancas; debajo cuatro negras; debajo ocho corcheas. A la derecha de cada fila, su duración en tiempos.","brief":"Diagrama escolar en forma de pirámide invertida sobre fondo blanco. Fila 1: una redonda (óvalo hueco sin plica) — \\"Redonda: 4 tiempos\\". Fila 2: dos blancas (óvalo hueco con plica) — \\"Blanca: 2 tiempos\\". Fila 3: cuatro negras (óvalo relleno con plica) — \\"Negra: 1 tiempo\\". Fila 4: ocho corcheas (óvalo relleno con plica y banderita; se pueden unir de dos en dos con barra) — \\"Corchea: ½ tiempo\\". Todas las filas miden lo mismo de ancho para mostrar que suman igual. Trazo negro grueso, rótulos grandes legibles en celular. Dimensiones: 1200x900."},"type":"explain","props":{"icon":"Timer","body":"Una figura es un **símbolo de duración**. Mientras más \\"vacía\\" y sin adornos, más dura. Toca cada una.","reveal":[{"icon":"Circle","front":"Redonda","back":"Un óvalo **hueco, sin palito**. Dura **4 tiempos**. Se dice \\"ta-a-a-a\\"."},{"icon":"CircleDot","front":"Blanca","back":"Un óvalo **hueco con palito** (plica). Dura **2 tiempos**: la mitad de la redonda. Se dice \\"ta-a\\"."},{"icon":"Music2","front":"Negra","back":"Un óvalo **relleno con plica**. Dura **1 tiempo**: un pulso. Se dice \\"ta\\"."},{"icon":"Music","front":"Corchea","back":"Como la negra, pero con una **banderita**. Dura **medio tiempo**: dos corcheas llenan un pulso. Se dice \\"ti-ti\\"."}]},"id":"s01-art-1-3"},{"fase":"construir","areas":["art"],"cnb":["art:1.1.1"],"ambito":"conocer","prompt":"Une cada figura con su duración.","hint":"La redonda es la más larga. Cada figura siguiente dura la mitad de la anterior.","explain":"Redonda 4, blanca 2, negra 1 y corchea ½. Cada figura dura **la mitad** que la anterior.","type":"match","props":{"leftTitle":"Figura","rightTitle":"Duración","pairs":[{"id":"r","left":"Redonda","leftIcon":"Circle","right":"4 tiempos"},{"id":"b","left":"Blanca","leftIcon":"CircleDot","right":"2 tiempos"},{"id":"n","left":"Negra","leftIcon":"Music2","right":"1 tiempo"},{"id":"c","left":"Corchea","leftIcon":"Music","right":"Medio tiempo"}]},"id":"s01-art-1-4"},{"fase":"construir","areas":["art"],"cnb":["art:1.1.1"],"ambito":"hacer","title":"Ejemplo resuelto: leer un ritmo","prompt":"Mira cómo se lee un ritmo contando tiempos. Luego lo harás tú.","type":"worked-example","props":{"icon":"Music","problem":"En la pizarra hay este ritmo: **negra · negra · dos corcheas · blanca**. ¿Cuántos tiempos dura en total y cómo se palmea?","steps":[{"text":"Escribo el valor de cada figura: negra = 1, negra = 1, dos corcheas = ½ + ½ = 1, blanca = 2."},{"text":"Sumo: 1 + 1 + 1 + 2 = **5 tiempos**.","why":"Las duraciones se suman una tras otra, como pasos en un camino."},{"text":"Lo digo con sílabas mientras marco el pulso con el pie: **\\"ta · ta · ti-ti · ta-a\\"**.","why":"Las sílabas rítmicas ayudan a sentir la duración: \\"ta-a\\" se sostiene dos pulsos."},{"text":"Palmeo: un aplauso en cada \\"ta\\", dos aplausos rápidos en \\"ti-ti\\" y un aplauso que dejo \\"sonar\\" dos pulsos en \\"ta-a\\"."}],"answer":"El ritmo dura **5 tiempos** y se dice **\\"ta · ta · ti-ti · ta-a\\"**.","tip":"Mantén el pulso con el pie todo el tiempo: el pie no se apura ni se detiene, aunque las manos hagan figuras distintas."},"id":"s01-art-1-5"},{"fase":"construir","areas":["art","mat"],"cnb":["art:1.1.1"],"ambito":"hacer","prompt":"Ahora tú: ¿cuántos tiempos dura este ritmo? **blanca · negra · dos corcheas**","hint":"Blanca = 2, negra = 1 y dos corcheas juntas = 1.","explain":"2 + 1 + ½ + ½ = 4. El ritmo dura **4 tiempos**.","type":"number-input","props":{"answer":4,"unit":"tiempos","stimulus":"ta-a · ta · ti-ti","misconceptions":[{"value":5,"msg":"Contaste cada corchea como 1 tiempo. Recuerda: cada corchea dura medio tiempo."},{"value":3,"msg":"Revisa la blanca: dura 2 tiempos, no 1."}]},"id":"s01-art-1-6"},{"fase":"aplicar","areas":["art"],"cnb":["art:1.1.1"],"ambito":"hacer","prompt":"Compón un ritmo de **4 tiempos** en la marimba. Debe incluir al menos una **blanca** y una **corchea**. Tócalo y dilo con sílabas.","explain":"Una posibilidad: blanca (2) + negra (1) + dos corcheas (½ + ½) = 4 tiempos: \\"ta-a · ta · ti-ti\\". Si usas una corchea, necesitas otra para completar el pulso.","type":"rhythm","props":{"beats":4,"allowed":["redonda","blanca","negra","corchea"],"mustInclude":["blanca","corchea"],"showFractions":true},"id":"s01-art-1-7"},{"fase":"aplicar","areas":["art"],"cnb":["art:1.1.1"],"ambito":"conocer","prompt":"Una redonda dura 4 tiempos y cada corchea medio tiempo. ¿Cuántas **corcheas** duran lo mismo que **una redonda**?","explain":"En cada tiempo caben 2 corcheas. En 4 tiempos caben 4 × 2 = **8 corcheas**.","type":"number-input","props":{"answer":8,"unit":"corcheas","misconceptions":[{"value":4,"msg":"Cuatro negras llenan una redonda; las corcheas son más cortas, así que se necesitan más."},{"value":2,"msg":"Dos corcheas llenan solo una negra (1 tiempo). La redonda dura 4 tiempos."}]},"id":"s01-art-1-8"},{"fase":"aplicar","areas":["art"],"cnb":["art:1.1.1"],"ambito":"hacer","prompt":"**En casa:** fabrica una **sonaja** y úsala para tocar ritmos. Así practicarás las figuras toda la semana.","type":"project","props":{"goal":"Construir una sonaja con materiales sencillos y tocar con ella tres ritmos de 4 tiempos.","steps":[{"title":"Reúne materiales","detail":"Una botella plástica pequeña y limpia con tapa, y un puñito de frijoles, arroz o piedrecitas."},{"title":"Arma tu sonaja","detail":"Llena la botella hasta un cuarto y ciérrala bien. Prueba: frijoles suenan más grave; arroz, más agudo."},{"title":"Toca el pulso","detail":"Pon música tranquila o cuenta \\"1, 2, 3, 4\\" y agita la sonaja una vez en cada tiempo."},{"title":"Toca tres ritmos","detail":"Toca \\"ta · ta · ta · ta\\", \\"ta-a · ta-a\\" y \\"ti-ti · ta · ta-a\\". Enséñale uno a alguien de tu familia."}],"evidence":"Un dibujo de tu sonaja y los tres ritmos escritos en tu cuaderno con figuras.","rubric":["Mi sonaja suena y está bien cerrada","Mantengo el pulso sin apurarme","Toco los ritmos con la duración correcta"]},"id":"s01-art-1-9"},{"fase":"comprobar","areas":["art"],"cnb":["art:1.1.1"],"prompt":"¿Qué figura es un óvalo **hueco con plica** y dura **2 tiempos**?","type":"choice","props":{"options":[{"id":"r","text":"Redonda"},{"id":"b","text":"Blanca"},{"id":"n","text":"Negra"},{"id":"c","text":"Corchea"}],"correct":["b"]},"id":"s01-art-1-10"},{"fase":"comprobar","areas":["art"],"cnb":["art:1.1.1"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"El pulso es un latido constante de la música.","answer":true},{"text":"Una negra dura más que una blanca.","answer":false,"why":"La negra dura 1 tiempo y la blanca 2."},{"text":"Dos negras duran lo mismo que una blanca.","answer":true},{"text":"La intensidad dice si un sonido es grave o agudo.","answer":false,"why":"Eso es la altura. La intensidad dice si es fuerte o suave."}]},"id":"s01-art-1-11"}],"kind":"materia","area":"art","day":1}},{"missionId":"s01","version":"cnb-sexto-f2fcd6c03fc46271","lesson":{"id":"s01-fc-1","title":"Convivir con solidaridad y tolerancia","icon":"HeartHandshake","minutes":13,"gancho":"Llega a tu grado una compañera nueva que no conoce a nadie. ¿Qué te gustaría que hicieran por ti si fueras ella?","objetivos":["Explicar con tus palabras qué son la solidaridad y la tolerancia","Distinguir actitudes que favorecen la convivencia de las que la dañan","Elegir respuestas solidarias y tolerantes en situaciones reales"],"resumen":["Convivir es vivir junto a otras personas compartiendo espacios, reglas y responsabilidades: en la casa, la escuela y la comunidad.","Solidaridad: apoyar a otras personas, sobre todo a quien lo necesita, sin esperar nada a cambio.","Tolerancia: respetar a las personas y sus ideas, idiomas, costumbres o creencias aunque sean distintas de las mías. Ser tolerante no significa aceptar abusos.","Escuchar, incluir, compartir y reparar el daño favorecen la convivencia; la burla, la exclusión y la indiferencia la dañan."],"media":{"id":"s01-fc-1-convivencia","kind":"image","title":"Una escuela que convive","aspect":"16:9","alt":"Patio de una escuela rural guatemalteca: niñas y niños de distintos pueblos comparten la refacción, ayudan a un compañero con muletas y juegan juntos.","brief":"Ilustración plana y cálida de un patio escolar en Guatemala, a media mañana. Escenas pequeñas: (1) una niña con traje maya comparte su refacción con un niño nuevo; (2) dos niños ayudan a un compañero con muletas a subir un escalón; (3) un grupo mixto juega con una pelota; (4) una niña garífuna y un niño ladino conversan sonriendo. Paleta de colores vivos, sin textos ni marcas. Evitar estereotipos: niñas y niños en roles activos por igual. Dimensiones: 1600x900."},"steps":[{"fase":"explorar","areas":["fc"],"cnb":["fc:1.1.2"],"ambito":"conocer","title":"Dos valores para vivir juntos","prompt":"Todos los días **convivimos**: compartimos la casa, el aula, la camioneta, el mercado. Para que la convivencia sea buena necesitamos valores. Toca cada tarjeta.","type":"explain","props":{"icon":"Users","body":"La **solidaridad** mueve a ayudar; la **tolerancia** mueve a respetar. Las dos juntas hacen que todas las personas se sientan parte del grupo.","reveal":[{"icon":"Home","front":"Convivir","back":"Vivir **junto a otras personas** compartiendo espacios, reglas y responsabilidades."},{"icon":"HeartHandshake","front":"Solidaridad","back":"Apoyar a otros, **sobre todo a quien lo necesita**, sin esperar nada a cambio. Ejemplo: explicar la tarea a un compañero que faltó por enfermedad."},{"icon":"Handshake","front":"Tolerancia","back":"Respetar a las personas y sus **ideas, idiomas, costumbres o creencias** aunque sean distintas de las mías. Ejemplo: escuchar con atención a quien piensa diferente."},{"icon":"ShieldCheck","front":"Lo que la tolerancia NO es","back":"Tolerar **no** es aguantar golpes, insultos o abusos. Ante un abuso, lo correcto es pedir ayuda a una persona adulta de confianza."}]},"id":"s01-fc-1-1"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.1.2"],"ambito":"convivir","prompt":"Una tormenta tumbó la milpa de la familia de Tomás. Al día siguiente, varios vecinos llegaron con sus azadones a ayudar a resembrar, sin cobrar nada. ¿Cómo se llama esa actitud?","explain":"Ayudar a quien lo necesita, sin esperar pago, es **solidaridad**. Hoy aprenderás este valor y otro que lo acompaña: la **tolerancia**.","type":"choice","props":{"options":[{"id":"a","text":"Solidaridad","icon":"HeartHandshake"},{"id":"b","text":"Competencia","icon":"Trophy","feedback":"En una competencia cada quien busca ganar. Aquí los vecinos trabajan juntos para ayudar."},{"id":"c","text":"Indiferencia","icon":"EyeOff","feedback":"La indiferencia es no hacer nada ante el problema de otro. Los vecinos hicieron lo contrario."}],"correct":["a"]},"id":"s01-fc-1-2"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.1.2"],"prompt":"Clasifica cada acción: ¿muestra sobre todo **solidaridad** o **tolerancia**?","hint":"Pregúntate: ¿la persona está **ayudando** a alguien que lo necesita (solidaridad) o está **respetando** una diferencia (tolerancia)?","explain":"Solidaridad = ayudar a quien lo necesita. Tolerancia = respetar lo diferente. Muchas veces aparecen juntas.","type":"sort","props":{"buckets":[{"id":"sol","label":"Solidaridad (ayudar)","icon":"HeartHandshake","color":"var(--area-fc)"},{"id":"tol","label":"Tolerancia (respetar)","icon":"Handshake","color":"var(--c-ok)"}],"items":[{"id":"s1","text":"Juntar víveres para una familia que perdió su casa en un deslave","bucket":"sol"},{"id":"s2","text":"Escuchar sin burlarse a un compañero que reza de forma distinta a la tuya","bucket":"tol"},{"id":"s3","text":"Prestar tus colores a quien no pudo comprarlos","bucket":"sol"},{"id":"s4","text":"Respetar que tu amiga hable q’eqchi’ con su abuela durante el recreo","bucket":"tol","feedback":"Respetar el idioma de otra persona es tolerancia: su forma de comunicarse es tan valiosa como la tuya."},{"id":"s5","text":"Aceptar que tu equipo eligió otro nombre, aunque tú preferías el tuyo","bucket":"tol"},{"id":"s6","text":"Acompañar a casa a una compañera que se torció el tobillo","bucket":"sol"}]},"id":"s01-fc-1-3"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.1.2"],"ambito":"convivir","title":"Actitudes que construyen y actitudes que dañan","prompt":"Una **actitud** es nuestra forma habitual de reaccionar ante los demás. Algunas actitudes **construyen** la convivencia y otras la **dañan**. Toca cada tarjeta.","type":"explain","props":{"icon":"Blocks","body":"Las actitudes se **aprenden**. Por eso también se pueden **cambiar**: nadie nace burlándose, y todos podemos aprender a incluir.","reveal":[{"icon":"Ear","front":"Escuchar","back":"Dejar hablar al otro y tratar de entender lo que siente. **Construye**."},{"icon":"Users","front":"Incluir","back":"Invitar a quien está solo o es nuevo a jugar y a trabajar. **Construye**."},{"icon":"RefreshCw","front":"Reparar","back":"Pedir perdón y arreglar el daño cuando nos equivocamos. **Construye**."},{"icon":"Megaphone","front":"Burlarse","back":"Reírse del acento, el cuerpo, la ropa o la pobreza de alguien. **Daña**: la persona se siente humillada."},{"icon":"EyeOff","front":"Ser indiferente","back":"Ver que alguien sufre y no hacer nada. **Daña**: deja sola a la persona y permite que el problema siga."}]},"id":"s01-fc-1-4"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.1.2"],"prompt":"¿Esta actitud **favorece** o **daña** la convivencia?","hint":"Piensa cómo se sentiría la otra persona. Si se siente respetada o acompañada, la actitud favorece la convivencia.","explain":"Las actitudes que favorecen la convivencia hacen sentir a las personas respetadas e incluidas; las que la dañan las humillan o las dejan solas.","type":"sort","props":{"buckets":[{"id":"fav","label":"Favorece","icon":"ThumbsUp","color":"var(--c-ok)"},{"id":"dan","label":"Daña","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"a1","text":"Poner apodos por el color de piel","bucket":"dan"},{"id":"a2","text":"Pedir perdón después de empujar sin querer","bucket":"fav"},{"id":"a3","text":"Reenviar en el chat una foto para burlarse de alguien","bucket":"dan","feedback":"La burla en redes también daña, y puede llegar a muchas personas en segundos."},{"id":"a4","text":"Invitar a jugar a quien siempre se queda solo","bucket":"fav"},{"id":"a5","text":"Ver que molestan a alguien y reírse con los demás","bucket":"dan"},{"id":"a6","text":"Turnarse la pelota para que todos jueguen","bucket":"fav"}]},"id":"s01-fc-1-5"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.1.2"],"ambito":"convivir","title":"Ejemplo resuelto: analizar una situación","prompt":"Cuando algo pasa en el grupo, puedes analizarlo con **tres preguntas**. Mira cómo se hace.","type":"worked-example","props":{"icon":"Search","problem":"Llega al grado **Yolanda**, que viene de otra comunidad y habla un idioma distinto al de la mayoría. Algunos compañeros se burlan de su acento cuando lee en voz alta.","steps":[{"text":"**¿Qué está pasando?** Un grupo se burla de Yolanda por su acento.","why":"Primero describimos los hechos, sin exagerar ni juzgar todavía."},{"text":"**¿Cómo se siente cada persona?** Yolanda probablemente siente vergüenza y soledad; quizá ya no quiera leer en voz alta.","why":"Ponerse en el lugar del otro (empatía) nos ayuda a entender el daño."},{"text":"**¿Qué actitud ayudaría?** Tolerancia: respetar su forma de hablar. Solidaridad: acompañarla y pedir a los demás que dejen de burlarse."}],"answer":"La burla daña la convivencia. Una respuesta tolerante y solidaria sería **acompañar a Yolanda, valorar su idioma y pedir con respeto que paren las burlas**.","tip":"Hablar dos idiomas es una riqueza, no un defecto."},"id":"s01-fc-1-6"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.1.2"],"ambito":"convivir","prompt":"Ahora tú. ¿Qué harías?","type":"dilemma","props":{"scene":{"icon":"Users","text":"En la refacción, **Marvin** no trajo nada porque en su casa este mes alcanza poco. Dos compañeros empiezan a decir en voz alta: \\"Marvin siempre anda pidiendo\\". Él baja la cabeza."},"options":[{"id":"a","icon":"EyeOff","text":"Seguir comiendo como si nada","consequence":"Marvin se siente solo y avergonzado. Los comentarios siguen al día siguiente.","values":["Indiferencia"],"constructive":false},{"id":"b","icon":"HeartHandshake","text":"Compartir tu refacción con Marvin sin hacer escándalo","consequence":"Marvin come algo y se siente acompañado. Otros compañeros también comparten.","values":["Solidaridad","Discreción"],"constructive":true},{"id":"c","icon":"Megaphone","text":"Decir con calma: \\"No está bien burlarse de nadie por lo que tiene o no tiene\\"","consequence":"Los compañeros se quedan pensando y dejan de molestar. La maestra propone una refacción compartida los viernes.","values":["Respeto","Valentía"],"constructive":true}]},"id":"s01-fc-1-7"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.1.2"],"prompt":"Une cada situación con la actitud que **mejor** ayuda a convivir.","explain":"En cada caso, la mejor actitud es la que respeta la diferencia o apoya a quien lo necesita.","type":"match","props":{"leftTitle":"Situación","rightTitle":"Actitud que ayuda","pairs":[{"id":"m1","left":"Un compañero en silla de ruedas no puede llegar a la cancha","leftIcon":"PersonStanding","right":"Buscar juntos una rampa o un juego donde participe"},{"id":"m2","left":"Tu amiga es evangélica y en tu familia son católicos; ella no celebra una fiesta que tú sí","leftIcon":"BookOpen","right":"Respetar su creencia sin burlarte"},{"id":"m3","left":"Empujaste sin querer a alguien y se le cayó el cuaderno al charco","leftIcon":"Droplets","right":"Pedir perdón y ayudar a secarlo"},{"id":"m4","left":"En el trabajo en grupo, una niña callada no ha dado su opinión","leftIcon":"MessageCircle","right":"Preguntarle qué piensa y escucharla"}]},"id":"s01-fc-1-8"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:1.1.2"],"prompt":"En el partido, un niño garífuna mete gol y alguien grita un apodo por su color de piel. ¿Qué respuesta muestra **tolerancia y solidaridad**?","type":"choice","props":{"options":[{"id":"a","text":"Reírse, porque \\"es solo una broma\\""},{"id":"b","text":"Decir que ese apodo ofende, felicitar al compañero por su gol y avisar al docente si se repite"},{"id":"c","text":"No decir nada para no meterse en problemas"}],"correct":["b"]},"id":"s01-fc-1-9"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:1.1.2"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"La solidaridad es apoyar a quien lo necesita sin esperar nada a cambio.","answer":true},{"text":"Ser tolerante significa aguantar que alguien te golpee.","answer":false,"why":"La tolerancia es respetar diferencias, no aceptar abusos. Ante un abuso se pide ayuda."},{"text":"La indiferencia ante una burla daña la convivencia.","answer":true},{"text":"Las actitudes no se pueden cambiar: se nace con ellas.","answer":false,"why":"Las actitudes se aprenden, por eso también se pueden cambiar."}]},"id":"s01-fc-1-10"}],"kind":"materia","area":"fc","day":2}},{"missionId":"s01","version":"cnb-sexto-ffd922741216783f","lesson":{"id":"s01-l1-5","title":"Escribir un correo electrónico claro y respetuoso","icon":"Mail","minutes":14,"gancho":"Antes, para comunicarse con alguien lejos, las personas escribían cartas que tardaban semanas en llegar. Hoy un correo llega en segundos. ¿Se escribe igual?","objetivos":["Reconocer las partes de un correo electrónico","Escribir un asunto claro y un mensaje completo y cortés","Cuidar tus datos personales al usar el correo"],"resumen":["Partes de un correo: destinatario (Para), asunto, saludo, cuerpo del mensaje, despedida y firma. Se puede adjuntar un archivo con el ícono del clip.","El asunto dice en pocas palabras de qué trata el correo: \\"Solicitud de información sobre la biblioteca\\".","El cuerpo explica quién escribe, qué necesita y para qué, con palabras completas y cortesía.","Nunca compartas contraseñas ni datos personales con personas que no conoces. Si algo te incomoda, cuéntaselo a un adulto de confianza."],"media":{"id":"s01-l1-5-correo","kind":"diagram","title":"Las partes de un correo","aspect":"4:3","alt":"Ventana de correo electrónico con flechas que señalan: Para, Asunto, saludo, cuerpo, despedida, firma y el ícono del clip para adjuntar.","brief":"Diagrama de una ventana de correo genérica (sin marca real). Campos rotulados con flechas de colores: \\"Para\\" (correo inventado biblioteca@ejemplo.org), \\"Asunto: Solicitud de libros sobre volcanes\\", saludo \\"Buenos días:\\", cuerpo de tres líneas, despedida \\"Atentamente,\\", firma \\"Julio Tzoc, 6.º grado, Escuela Oficial Rural Mixta\\" y el ícono de clip con la etiqueta \\"Adjuntar\\". Estilo plano, colores suaves, letra grande legible en teléfono. Dimensiones: 1200x900."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":["l1:3.4.2"],"ambito":"conocer","title":"Las partes de un correo","prompt":"Observa el diagrama y toca cada tarjeta para conocer las partes de un correo electrónico.","type":"explain","props":{"icon":"Mail","body":"Un correo electrónico es parecido a una carta, pero viaja por internet. Tiene partes que ayudan a que llegue a la persona correcta y se entienda.","reveal":[{"icon":"AtSign","front":"Para (destinatario)","back":"La **dirección de correo** de quien lo recibe. Revísala letra por letra: un error y el correo no llega."},{"icon":"Tag","front":"Asunto","back":"El **tema** en pocas palabras. Ejemplo: \\"Consulta sobre la tarea de Ciencias\\"."},{"icon":"Hand","front":"Saludo","back":"Formal: \\"Buenos días, señora directora:\\" / \\"Estimado señor Pérez:\\". Informal (familia): \\"¡Hola, tía Rosa!\\"."},{"icon":"AlignJustify","front":"Cuerpo","back":"El mensaje: **quién eres**, **qué necesitas o quieres contar** y **para qué**. Párrafos cortos y palabras completas."},{"icon":"PenLine","front":"Despedida y firma","back":"Despedida: \\"Atentamente,\\" / \\"Muchas gracias,\\" / \\"Un abrazo,\\". Firma: tu nombre y, si es formal, tu grado y escuela."}]},"id":"s01-l1-5-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:3.4.2"],"ambito":"conocer","prompt":"La directora recibe muchos correos al día. ¿Cuál de estos **asuntos** le ayuda a saber de qué trata el mensaje antes de abrirlo?","explain":"Un buen asunto es corto y dice exactamente de qué trata el correo. Así la persona sabe si es urgente y lo encuentra fácilmente después.","type":"choice","props":{"options":[{"id":"a","text":"\\"Hola\\"","icon":"Mail","feedback":"\\"Hola\\" no dice nada sobre el tema del correo."},{"id":"b","text":"\\"Solicitud de permiso para la feria de ciencias\\"","icon":"MailCheck"},{"id":"c","text":"\\"URGENTE!!!!!\\"","icon":"Megaphone","feedback":"Las mayúsculas y los signos repetidos parecen gritos, y no dicen el tema."}],"correct":["b"]},"id":"s01-l1-5-2"},{"fase":"construir","areas":["l1"],"cnb":["l1:3.4.2"],"ambito":"hacer","prompt":"Ordena las partes del correo de Julio, de arriba hacia abajo.","hint":"Primero va a quién y sobre qué; luego el saludo, el mensaje y, al final, la despedida y la firma.","explain":"Este orden es el mismo en casi todos los correos: te ayuda a no olvidar ninguna parte.","type":"order","props":{"labels":{"start":"Arriba","end":"Abajo"},"items":[{"id":"p1","text":"Para: biblioteca.municipal@ejemplo.org"},{"id":"p2","text":"Asunto: Solicitud de libros sobre volcanes"},{"id":"p3","text":"Buenos días:"},{"id":"p4","text":"Soy estudiante de sexto grado y estoy preparando una exposición sobre los volcanes de Guatemala. ¿Tienen libros sobre el tema que pueda consultar?"},{"id":"p5","text":"Atentamente,"},{"id":"p6","text":"Julio Tzoc, 6.º grado"}]},"id":"s01-l1-5-3"},{"fase":"construir","areas":["l1"],"cnb":["l1:3.4.2"],"ambito":"hacer","title":"Ejemplo resuelto: de mensaje apurado a correo claro","prompt":"Mira cómo Andrea mejora su correo paso a paso.","type":"worked-example","props":{"icon":"MailCheck","problem":"Primer intento de Andrea al comité de la feria: Asunto: \\"hola\\". Cuerpo: \\"q dia es la feria y si puedo llevar mi proyecto de plantas\\".","steps":[{"text":"Escribe un **asunto** que diga el tema: \\"Consulta sobre la feria escolar\\"."},{"text":"Agrega un **saludo** formal: \\"Buenas tardes, estimado comité:\\".","why":"El comité no es su amigo cercano: el saludo formal muestra respeto."},{"text":"Se **presenta**: \\"Soy Andrea López, de sexto grado sección A.\\"","why":"Quien lee necesita saber quién escribe."},{"text":"Escribe su **pregunta completa** y con signos: \\"¿Qué día será la feria? ¿Puedo participar con mi proyecto sobre el cuidado de las plantas?\\"","why":"Palabras completas y signos de interrogación de apertura y cierre."},{"text":"Cierra con **despedida y firma**: \\"Muchas gracias. Atentamente, Andrea López.\\""}],"answer":"Un correo con asunto claro, saludo, presentación, preguntas completas, despedida y firma.","tip":"Antes de enviar, léelo como si fueras quien lo recibe: ¿se entiende sin que tengas que explicar nada más?"},"id":"s01-l1-5-4"},{"fase":"construir","areas":["l1"],"cnb":["l1:3.4.2"],"ambito":"hacer","prompt":"Este correo va dirigido a la señora alcaldesa auxiliar, pero tiene palabras **demasiado informales**. Tócalas.","hint":"Busca abreviaturas y expresiones que usarías solo con amigos.","explain":"\\"Q onda\\", \\"xq\\", \\"porfa\\" y \\"bye\\" son informales. En un correo formal se escribe: \\"Buenos días\\", \\"porque\\", \\"por favor\\" y \\"Atentamente\\".","type":"highlight","props":{"target":"palabras informales","text":"{Q onda}, señora alcaldesa auxiliar. Le escribimos {xq} queremos limpiar el parque de la aldea el sábado. ¿Nos podría prestar escobas y bolsas, {porfa}? {Bye}. Estudiantes de sexto grado."},"id":"s01-l1-5-5"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:3.4.2"],"ambito":"hacer","prompt":"Vas a mandar por correo tu tarea de Ciencias Sociales a tu maestro. ¿Qué **asunto** y qué **ícono** usas para enviar el archivo?","explain":"El asunto dice qué es y de quién; el clip sirve para adjuntar el archivo.","type":"choice","props":{"options":[{"id":"a","text":"Asunto: \\"Tarea de Ciencias Sociales – Luis Chávez, 6.º B\\" + ícono del clip","icon":"Paperclip"},{"id":"b","text":"Asunto: \\"aquí está\\" + ícono de la lupa","icon":"Search","feedback":"El asunto no dice qué es, y la lupa sirve para buscar, no para adjuntar."},{"id":"c","text":"Asunto: vacío + ícono del bote de basura","icon":"Trash2","feedback":"¡El bote de basura elimina! Y un asunto vacío confunde."}],"correct":["a"]},"id":"s01-l1-5-6"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:3.4.2"],"ambito":"ser","prompt":"Sobre el uso seguro del correo, ¿verdadero o falso?","explain":"Usar la tecnología también implica cuidarnos: nuestros datos son valiosos.","type":"true-false","props":{"statements":[{"text":"Si un desconocido te pide tu contraseña por correo, debes dársela para que no se enoje.","answer":false,"why":"Tu contraseña es solo tuya. Nadie que te quiera ayudar te la pedirá por correo."},{"text":"Si recibes un mensaje que te incomoda, es bueno contárselo a un adulto de confianza.","answer":true},{"text":"Revisar la dirección del destinatario antes de enviar evita que el correo llegue a otra persona.","answer":true}]},"id":"s01-l1-5-7"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:3.4.2"],"ambito":"hacer","prompt":"Escribe un correo a un familiar que viva en otro lugar (otro municipio, departamento o país). Invítalo a contarte **cómo es el lugar donde vive** para comparar con tu exposición \\"Nuestro lugar en mapas y palabras\\". Incluye asunto, saludo, cuerpo, despedida y firma.","type":"short-answer","props":{"minWords":45,"placeholder":"Asunto: …\\n\\nSaludo…\\n\\nCuerpo…\\n\\nDespedida y firma…","model":"Asunto: Quiero conocer tu lugar\\n\\n¡Hola, tío Mario!\\n\\nEstoy preparando una exposición en la escuela llamada \\"Nuestro lugar en mapas y palabras\\". Yo voy a hablar de Quetzaltenango, pero me gustaría compararlo con Petén, donde vives tú. ¿Me podrías contar cómo es el clima, qué se cultiva y qué te gusta más de ahí? Si tienes una foto, me ayudaría mucho.\\n\\nMuchas gracias. Un abrazo,\\nValeria","rubric":["Escribí un asunto que dice el tema","Tiene saludo, cuerpo, despedida y firma","Expliqué qué necesito y para qué","Escribí palabras completas, sin abreviaturas","Usé signos de interrogación de apertura y cierre (¿…?)"]},"id":"s01-l1-5-8"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:3.4.2"],"prompt":"Ordena las partes de un correo electrónico, de arriba hacia abajo.","type":"order","props":{"labels":{"start":"Arriba","end":"Abajo"},"items":[{"id":"q1","text":"Asunto"},{"id":"q2","text":"Saludo"},{"id":"q3","text":"Cuerpo del mensaje"},{"id":"q4","text":"Despedida y firma"}]},"id":"s01-l1-5-9"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:2.1.6"],"prompt":"Repaso de la semana: para empezar una exposición y **atrapar la atención**, ¿qué conviene más?","type":"choice","props":{"options":[{"id":"a","text":"Una pregunta o un dato curioso sobre el tema"},{"id":"b","text":"Pedir disculpas por los nervios"},{"id":"c","text":"Leer el título de la hoja"}],"correct":["a"]},"id":"s01-l1-5-10"},{"fase":"reflexionar","areas":["l1"],"cnb":[],"ambito":"ser","prompt":"Mira hacia atrás en tu semana de Comunicación y Lenguaje.","type":"reflection","props":{"statements":["Uso mi voz (volumen, pausas, cambios) para que me escuchen","Uso gestos y mirada que acompañan lo que digo","Interpreto íconos y elijo un lenguaje formal o informal según a quién escribo","Escribo un correo con todas sus partes"],"commitments":["Presentaré mi exposición \\"Nuestro lugar en mapas y palabras\\" a mi familia","Revisaré a quién escribo antes de enviar un mensaje","Evitaré escribir en mayúsculas para no \\"gritar\\" en los chats"]},"id":"s01-l1-5-11"}],"kind":"materia","area":"l1","day":5}},{"missionId":"s01","version":"cnb-sexto-43c206d2737e45b2","lesson":{"id":"s01-fc-2","title":"Los derechos humanos en los lugares donde vivimos","icon":"Scale","minutes":15,"gancho":"Agua, comida, escuela, un nombre… ¿Son solo cosas que necesitas o son también tus derechos?","objetivos":["Explicar qué son los derechos humanos y sus características","Relacionar las condiciones de un lugar (agua, escuela, salud) con los derechos que se cumplen o no","Proponer qué se puede hacer cuando un derecho no se cumple"],"resumen":["Los derechos humanos son lo que toda persona necesita y merece para vivir con dignidad, solo por ser persona.","Son universales (de todas las personas), inalienables (nadie te los puede quitar) e interdependientes (si falla uno, se afectan otros).","La Declaración Universal de los Derechos Humanos fue aprobada por las Naciones Unidas el 10 de diciembre de 1948. En Guatemala, la Constitución Política de la República también los protege.","Las condiciones de un lugar concreto (agua potable, escuela, centro de salud, trabajo, seguridad) muestran si los derechos se cumplen. El Estado es el principal responsable de garantizarlos; familias y comunidades también participan."],"media":{"id":"s01-fc-2-derechos-lugar","kind":"animation","title":"Un derecho, un lugar","aspect":"16:9","duration":50,"alt":"Un mapa ilustrado de una aldea donde se encienden íconos: un chorro de agua, una escuela, un centro de salud y una casa, cada uno con el derecho que representa.","brief":"Animación 2D de 50 s. Vista aérea ilustrada de una aldea guatemalteca con milpas, casas de block y lámina, un río y una carretera de terracería. Aparecen, uno a uno, íconos sobre lugares concretos: chorro de agua → \\"Derecho al agua y a la salud\\", escuela → \\"Derecho a la educación\\", centro de salud → \\"Derecho a la salud\\", mercado y parcela → \\"Derecho a la alimentación y al trabajo\\". Luego un lugar sin chorro se marca con un signo de pregunta: \\"¿Se cumple este derecho aquí?\\". Narración: \\"Los derechos humanos se viven en lugares concretos\\". Subtítulos. Colores planos, sin textos largos."},"steps":[{"fase":"explorar","areas":["fc"],"cnb":["fc:1.2.1"],"ambito":"conocer","title":"¿Qué son los derechos humanos?","prompt":"Los **derechos humanos** son lo que toda persona necesita y merece para vivir con **dignidad**, solo por ser persona. Toca cada tarjeta.","type":"explain","props":{"icon":"Scale","body":"No son favores ni premios: **te pertenecen desde que naces**, igual que a cualquier otra persona del mundo.","reveal":[{"icon":"Globe","front":"Universales","back":"Son de **todas** las personas, sin importar su pueblo, idioma, sexo, religión, edad o si tienen dinero o no."},{"icon":"Lock","front":"Inalienables","back":"**Nadie te los puede quitar**, ni tú los puedes vender o regalar."},{"icon":"Link","front":"Interdependientes","back":"Están conectados: si falla uno, se afectan otros. Sin alimentación, por ejemplo, cuesta aprender."},{"icon":"ScrollText","front":"Declaración Universal","back":"Las **Naciones Unidas** la aprobaron el **10 de diciembre de 1948**. Por eso ese día es el Día de los Derechos Humanos."},{"icon":"Landmark","front":"En Guatemala","back":"La **Constitución Política de la República** (1985) reconoce derechos como la vida, la libertad, la igualdad, la educación y la salud."}]},"id":"s01-fc-2-1"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.1"],"ambito":"conocer","prompt":"Supongamos que en una aldea las niñas y los niños caminan **dos horas** cada mañana para traer agua del río. ¿A qué más crees que afecta esa situación, además de la sed?","explain":"¡Muy bien pensado! La falta de agua afecta la salud, el tiempo para estudiar y hasta el juego. Hoy verás que detrás de cada condición de un lugar hay **derechos humanos**.","type":"choice","props":{"options":[{"id":"a","text":"A la salud, al tiempo para estudiar y al descanso","icon":"Droplets"},{"id":"b","text":"A nada más: solo es un poco de cansancio","icon":"X","feedback":"Piensa: si pasas dos horas acarreando agua, ¿a qué hora estudias o juegas? ¿Y si el agua del río no es limpia?"}],"correct":["a"]},"id":"s01-fc-2-2"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.1"],"prompt":"Comprueba lo que aprendiste. ¿Verdadero o falso?","hint":"Recuerda las tres características: universales, inalienables e interdependientes.","type":"true-false","props":{"statements":[{"text":"Los derechos humanos son solo para las personas adultas.","answer":false,"why":"Son universales: también son de las niñas y los niños."},{"text":"Una persona no pierde sus derechos por ser pobre o por hablar otro idioma.","answer":true},{"text":"Si alguien no tiene agua limpia, también puede verse afectada su salud.","answer":true,"why":"Los derechos son interdependientes: uno afecta a otro."},{"text":"Los derechos humanos se pueden vender.","answer":false,"why":"Son inalienables: no se venden, no se regalan, no se quitan."}]},"id":"s01-fc-2-3"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.1"],"ambito":"conocer","prompt":"Lee con atención. Este texto explica cómo se relacionan los derechos con los **lugares concretos** donde vive la gente.","type":"reading","props":{"genre":"Texto informativo","heading":"Los derechos se viven en un lugar","passage":"Los derechos humanos no se quedan en un papel: se viven, o no se viven, en lugares concretos. En la casa, en la escuela, en la calle, en el centro de salud y en el mercado podemos ver si se cumplen.\\n\\nPor ejemplo, el derecho a la **salud** se cumple mejor cuando hay agua potable, un **ambiente sano** (sin basura ni aguas contaminadas), un centro de salud cercano y alimentos suficientes. El derecho a la **educación** se cumple cuando hay una escuela a una distancia razonable, con maestros, materiales y un ambiente seguro. A esas cosas las llamamos **condiciones sociales**.\\n\\nCuando en un lugar faltan esas condiciones, las personas no pueden disfrutar plenamente de sus derechos, aunque estén escritos en la ley. El **Estado** es el principal responsable de garantizarlos: debe construir escuelas, llevar servicios de salud y proteger a la población. Las familias y las comunidades también ayudan: organizándose, cuidando lo que tienen y exigiendo con respeto lo que les corresponde.","questions":[{"q":"Según el texto, ¿qué son las \\"condiciones sociales\\"?","options":[{"id":"a","text":"Las cosas que hay en un lugar para que los derechos se cumplan, como agua, escuela o centro de salud"},{"id":"b","text":"Las reglas de un juego"},{"id":"c","text":"El clima de una región"}],"correct":"a"},{"q":"¿Quién es el principal responsable de garantizar los derechos?","options":[{"id":"a","text":"Cada niño por su cuenta"},{"id":"b","text":"El Estado"},{"id":"c","text":"Nadie"}],"correct":"b","why":"El texto dice que el Estado es el principal responsable; familias y comunidades también participan."},{"q":"Si un derecho está escrito en la ley pero en tu aldea no hay escuela, ¿qué puedes concluir?","options":[{"id":"a","text":"Que el derecho a la educación no se cumple plenamente en ese lugar"},{"id":"b","text":"Que ese derecho no existe"},{"id":"c","text":"Que no importa, porque ya está escrito"}],"correct":"a","why":"El derecho existe para todos; lo que falta son las condiciones para vivirlo."}]},"id":"s01-fc-2-4"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.1"],"prompt":"Une cada **condición** de un lugar con el **derecho** que ayuda a cumplir.","hint":"Pregúntate: si esa condición faltara, ¿qué necesidad de la persona quedaría sin atender?","explain":"Cada condición social concreta hace posible un derecho: el agua a la salud, la escuela a la educación, la inscripción a la identidad…","type":"match","props":{"leftTitle":"Condición","rightTitle":"Derecho","pairs":[{"id":"c1","left":"Agua potable en casa","leftIcon":"Droplets","right":"Derecho a la salud"},{"id":"c2","left":"Escuela con maestros y libros","leftIcon":"School","right":"Derecho a la educación"},{"id":"c3","left":"Inscripción en el RENAP al nacer","leftIcon":"FileText","right":"Derecho a un nombre y una identidad"},{"id":"c4","left":"Tortillas, frijol y verduras suficientes","leftIcon":"Wheat","right":"Derecho a la alimentación"},{"id":"c5","left":"Calles alumbradas y seguras","leftIcon":"Lightbulb","right":"Derecho a la seguridad"}]},"id":"s01-fc-2-5"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.1"],"ambito":"hacer","title":"Ejemplo resuelto: de la condición al derecho","prompt":"Así se analiza un **lugar concreto** para saber qué derechos se cumplen. Revela cada paso.","type":"worked-example","props":{"icon":"MapPin","problem":"Supongamos que en la Escuela de la aldea Los Pinos **no hay agua en los baños** desde hace tres meses. Las niñas y los niños no pueden lavarse las manos y varios se han enfermado del estómago.","steps":[{"text":"**Describo la condición:** no hay agua en los baños de la escuela."},{"text":"**Busco el derecho relacionado:** derecho a la **salud** (se enferman) y, de paso, a la **educación** (faltan a clases por enfermedad).","why":"Los derechos son interdependientes: uno arrastra a otro."},{"text":"**Identifico a los responsables:** el Estado, por medio del Ministerio de Educación y la municipalidad, debe resolver el servicio; la comunidad educativa puede organizarse para pedirlo."},{"text":"**Propongo una acción:** el gobierno escolar y la junta de padres escriben una carta respetuosa a la municipalidad, con fotos y fechas, pidiendo la reparación."}],"answer":"En ese lugar el derecho a la salud **no se cumple plenamente**. La comunidad puede **exigirlo con respeto y con datos**.","tip":"Condición → derecho → responsable → acción. Esas cuatro preguntas sirven para analizar cualquier lugar."},"id":"s01-fc-2-6"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.1"],"prompt":"En una colonia no pasa el camión de la basura y la gente la tira al río. Los niños que juegan en la orilla se enferman de la piel. ¿Qué **dos** derechos se ven afectados?","explain":"La basura en el río afecta la **salud** de las personas y su derecho a un **ambiente sano**. Votar o tener un nombre no dependen de la basura del río.","type":"choice","props":{"multiple":true,"options":[{"id":"a","text":"Derecho a la salud","icon":"HeartPulse"},{"id":"b","text":"Derecho a un ambiente sano","icon":"Leaf"},{"id":"c","text":"Derecho a votar","icon":"Vote","feedback":"Votar es un derecho de las personas adultas y no tiene relación directa con esta situación."},{"id":"d","text":"Derecho a tener un nombre","icon":"FileText","feedback":"El nombre y la identidad no dependen de la basura del río."}],"correct":["a","b"]},"id":"s01-fc-2-7"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.1"],"prompt":"Observa cada lugar. ¿El derecho **se cumple** o **no se cumple** plenamente?","explain":"Mira siempre la condición concreta: si falta lo necesario para vivir el derecho, no se cumple plenamente, aunque esté escrito en la ley.","type":"sort","props":{"buckets":[{"id":"si","label":"Se cumple","icon":"Check","color":"var(--c-ok)"},{"id":"no","label":"No se cumple plenamente","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"l1","text":"Un centro de salud abierto, con medicinas, a 15 minutos a pie","bucket":"si"},{"id":"l2","text":"Una escuela con una sola maestra para seis grados y sin libros","bucket":"no"},{"id":"l3","text":"Un niño de 11 años que trabaja todo el día y no va a la escuela","bucket":"no","feedback":"Se afecta su derecho a la educación, al descanso y al juego."},{"id":"l4","text":"Una familia inscribe a su bebé en el RENAP y recibe su certificado","bucket":"si"},{"id":"l5","text":"Un barrio sin alumbrado donde da miedo caminar de noche","bucket":"no"}]},"id":"s01-fc-2-8"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.1"],"ambito":"hacer","prompt":"Piensa en **un lugar de tu comunidad** (tu escuela, tu calle, el mercado, el centro de salud). Escribe: ¿qué condición observas?, ¿qué derecho se relaciona?, ¿se cumple o no? y ¿qué se podría hacer?","type":"short-answer","props":{"minWords":35,"placeholder":"En … observo que… Esto se relaciona con el derecho a…","model":"En mi escuela observo que el techo del aula de cuarto grado gotea cuando llueve y los niños tienen que moverse a una esquina. Esto se relaciona con el derecho a la educación en un ambiente seguro. No se cumple plenamente, porque se pierden clases. Podríamos contar las veces que pasa y pedir, con una carta del gobierno escolar, que la municipalidad repare el techo.","rubric":["Describí una condición concreta de un lugar real","Nombré el derecho relacionado","Dije si se cumple o no y por qué","Propuse una acción respetuosa y posible"]},"id":"s01-fc-2-9"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:1.2.1"],"prompt":"Una comunidad tiene escuela, pero no tiene centro de salud en 30 kilómetros. ¿Qué derecho **no** se cumple plenamente allí?","type":"choice","props":{"options":[{"id":"a","text":"El derecho a la educación"},{"id":"b","text":"El derecho a la salud"},{"id":"c","text":"El derecho a tener un nombre"}],"correct":["b"]},"id":"s01-fc-2-10"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:1.2.1"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"La Declaración Universal de los Derechos Humanos se aprobó en 1948.","answer":true},{"text":"Si un derecho está escrito en la ley, siempre se cumple en todos los lugares.","answer":false,"why":"Depende de que existan las condiciones: escuela, agua, salud, seguridad…"},{"text":"El Estado es el principal responsable de garantizar los derechos humanos.","answer":true}]},"id":"s01-fc-2-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["fc"],"cnb":["fc:1.1.2","fc:1.2.1"],"type":"reflection","props":{"statements":["Explico qué son la solidaridad y la tolerancia","Explico qué son los derechos humanos","Relaciono las condiciones de un lugar con los derechos que se cumplen o no"],"commitments":["Incluiré a alguien que esté solo en el recreo","Observaré un lugar de mi comunidad y pensaré qué derecho se cumple allí","Preguntaré en casa si conocen la Declaración de los Derechos Humanos"]},"id":"s01-fc-2-12"}],"kind":"materia","area":"fc","day":5}},{"missionId":"s01","version":"cnb-sexto-8f7ad7a47be7b7c8","lesson":{"id":"s01-ef-2","title":"Mi lado dominante y mi equilibrio","icon":"Hand","minutes":15,"gancho":"¿Con qué mano escribes, lanzas una pelota o te cepillas los dientes? ¿Y podrías hacerlo igual de bien con la otra?","objetivos":["Identificar tu mano dominante y ejercitarla, sin olvidar la otra mano","Diferenciar el equilibrio estático del dinámico","Mejorar tu equilibrio con una base amplia, el centro de gravedad bajo y la mirada fija"],"resumen":["La lateralidad es la preferencia por usar un lado del cuerpo. El lado dominante es el que usamos con más fuerza y precisión: la mayoría de personas son diestras; otras son zurdas. Ambas son normales.","Ejercitar la mano dominante mejora la precisión; practicar también con la otra mano da más habilidad y equilibrio al cuerpo.","Equilibrio estático: mantener una postura sin moverse (pararse en un pie). Equilibrio dinámico: mantenerlo mientras te mueves (caminar sobre una línea).","Para tener más equilibrio: base de apoyo amplia, centro de gravedad bajo (rodillas un poco dobladas), brazos abiertos y la mirada fija en un punto."],"media":{"id":"s01-ef-2-equilibrio","kind":"video","title":"Equilibrio quieto y en movimiento","aspect":"9:16","duration":45,"alt":"Una niña se para en un pie con los brazos abiertos y la mirada fija; luego camina sobre una línea en el suelo con un libro en la cabeza.","brief":"Video vertical de 45 s en un patio o salón. Parte 1 \\"Equilibrio estático\\": una niña (ropa deportiva, rostro no protagonista) se para en un pie, primero con brazos pegados (se tambalea) y luego con brazos abiertos y mirada fija en un punto (se estabiliza); rótulos \\"brazos abiertos\\", \\"mira un punto\\". Parte 2 \\"Equilibrio dinámico\\": camina sobre una línea de yeso o cinta, de talón a punta, con un cuaderno sobre la cabeza. Parte 3: un niño en silla de ruedas hace equilibrio del tronco con una pelota sobre las piernas. Aviso \\"Hazlo en suelo plano y despejado\\". Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:1.2.1"],"ambito":"conocer","title":"La lateralidad","prompt":"Nuestro cuerpo tiene dos lados, pero casi siempre **preferimos uno**. Toca cada tarjeta.","type":"explain","props":{"icon":"Hand","body":"La **lateralidad** es la preferencia por usar un lado del cuerpo: mano, pie, ojo y oído.","reveal":[{"icon":"Hand","front":"Lado dominante","back":"Es el que usas con **más fuerza y precisión**. Si es la derecha eres **diestro/a**; si es la izquierda, **zurdo/a**."},{"icon":"Users","front":"Todos somos distintos","back":"La mayoría de las personas son diestras, pero ser zurdo es **igual de normal**. Nadie debe obligarte a cambiar de mano."},{"icon":"Target","front":"Reforzar la dominante","back":"Practicar lanzamientos, botes y agarres con tu mano dominante mejora tu **precisión** en juegos y deportes."},{"icon":"RefreshCw","front":"Entrenar la otra","back":"Practicar también con la mano no dominante te da **más opciones** en el juego y equilibra tu cuerpo."}]},"id":"s01-ef-2-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.2.1"],"ambito":"conocer","prompt":"Haz una prueba rápida: **lanza una bolita de papel** a un bote con una mano y luego con la otra, 3 veces cada una. Casi todas las personas aciertan más con una mano. ¿Por qué crees que pasa?","explain":"Acertamos más con la mano **dominante**: la que el cerebro prefiere y ha entrenado más. Hoy vas a ejercitarla y también a darle práctica a la otra.","type":"choice","props":{"options":[{"id":"a","text":"Porque es la mano que preferimos y más hemos practicado","icon":"Target"},{"id":"b","text":"Porque esa mano tiene más huesos","icon":"Bone","feedback":"Las dos manos tienen los mismos huesos. La diferencia está en la práctica y en la preferencia del cerebro."},{"id":"c","text":"Por pura suerte","icon":"Sparkles","feedback":"Si repites la prueba muchas veces, casi siempre gana la misma mano: no es suerte."}],"correct":["a"]},"id":"s01-ef-2-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.2.4"],"ambito":"conocer","title":"Dos tipos de equilibrio","prompt":"El **equilibrio** es la capacidad de mantener el cuerpo estable sin caerse. Mira el video y toca cada tarjeta.","type":"explain","props":{"icon":"Scale","body":"Tu cuerpo tiene un **centro de gravedad** (un punto cerca del ombligo) que debe quedar **encima de tu base de apoyo** (los pies).","reveal":[{"icon":"PersonStanding","front":"Equilibrio estático","back":"Mantener una postura **sin desplazarte**: pararte en un pie, hacer \\"el avión\\", quedarte en cuclillas."},{"icon":"Footprints","front":"Equilibrio dinámico","back":"Mantener el equilibrio **mientras te mueves**: caminar sobre una línea o un tronco, saltar y caer firme, andar en bicicleta."},{"icon":"Maximize2","front":"Base amplia","back":"Con los pies **separados** tienes más base y más equilibrio que con los pies juntos o en un pie."},{"icon":"ArrowDown","front":"Centro bajo y mirada fija","back":"**Dobla un poco las rodillas**, **abre los brazos** y **mira un punto fijo**: te tambaleas menos."}]},"id":"s01-ef-2-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.2.4"],"ambito":"hacer","title":"Ejemplo resuelto: cruzar el tronco sobre el río","prompt":"Mira cómo Kevin aplica lo aprendido para no caerse.","type":"worked-example","props":{"icon":"Footprints","problem":"En un paseo, Kevin debe cruzar caminando sobre un tronco ancho y bajo, puesto como puente sobre un riachuelo poco profundo. ¿Qué hace para mantener el equilibrio?","steps":[{"text":"Revisa que el tronco esté **firme** y pide que una persona adulta esté cerca.","why":"La seguridad va primero."},{"text":"Abre los **brazos** hacia los lados.","why":"Los brazos abiertos ayudan a corregir el tambaleo."},{"text":"Dobla un poco las **rodillas**.","why":"Baja su centro de gravedad y queda más estable."},{"text":"Mira un **punto fijo** al final del tronco, no el agua.","why":"Mirar el agua que corre confunde al cerebro y hace tambalear."},{"text":"Avanza con **pasos cortos**, apoyando bien cada pie antes de mover el otro."}],"answer":"Kevin usa **equilibrio dinámico**: brazos abiertos, centro bajo, mirada fija y pasos cortos.","tip":"Si sientes que te caes, agáchate y apoya las manos: bajar el cuerpo te devuelve el equilibrio."},"id":"s01-ef-2-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.2.4"],"ambito":"conocer","prompt":"Clasifica cada actividad: ¿equilibrio **estático** o **dinámico**?","hint":"Pregúntate: ¿la persona se desplaza o se queda en su lugar?","explain":"Si mantienes una postura sin desplazarte, el equilibrio es estático; si te desplazas sin perderlo, es dinámico.","type":"sort","props":{"buckets":[{"id":"e","label":"Estático (quieto)","icon":"PersonStanding","color":"var(--area-ef)"},{"id":"d","label":"Dinámico (en movimiento)","icon":"Footprints","color":"var(--c-maiz-strong)"}],"items":[{"id":"x1","text":"Pararme en un pie 20 segundos","bucket":"e"},{"id":"x2","text":"Caminar sobre una línea pintada en el suelo","bucket":"d"},{"id":"x3","text":"Hacer \\"el avión\\" sin moverme","bucket":"e"},{"id":"x4","text":"Andar en bicicleta","bucket":"d"},{"id":"x5","text":"Saltar la cuerda","bucket":"d"},{"id":"x6","text":"Quedarme en cuclillas con los brazos al frente","bucket":"e"}]},"id":"s01-ef-2-5"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.2.1","ef:1.2.4"],"ambito":"hacer","prompt":"¡Circuito de mano y equilibrio! **Calentamiento:** rota muñecas, hombros y tobillos. **Estación 1 (mano):** lanza y atrapa una bolita de papel o un calcetín enrollado, 10 veces con la mano dominante y 10 con la otra; luego bota una pelota 10 veces con cada mano. **Estación 2 (equilibrio):** párate en un pie 20 s con cada pierna (estático) y camina 10 pasos sobre una línea de talón a punta, ida y vuelta (dinámico). **Poco espacio:** usa una línea de cinta de 2 m. **Adaptación:** puedes apoyarte en una pared o en una silla; en silla de ruedas, haz el equilibrio con el tronco sosteniendo un cuaderno sobre la cabeza.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después de la estación de la mano","exercise":{"name":"Lanzar, atrapar y botar con cada mano","icon":"Hand","seconds":60}},{"label":"Después de la estación de equilibrio","exercise":{"name":"Un pie y caminar sobre la línea","icon":"Footprints","seconds":60}}]},"id":"s01-ef-2-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.2.4"],"ambito":"hacer","prompt":"Ana se tambalea al pararse en un pie. Tiene los brazos pegados al cuerpo, las rodillas rígidas y mira hacia todos lados. ¿Qué le aconsejas?","explain":"Abrir los brazos, doblar un poco la rodilla de apoyo y fijar la mirada en un punto aumenta la estabilidad.","type":"choice","props":{"options":[{"id":"a","text":"Que abra los brazos, doble un poco la rodilla y mire un punto fijo"},{"id":"b","text":"Que cierre los ojos para concentrarse","feedback":"Con los ojos cerrados el equilibrio es mucho más difícil: la vista ayuda a estabilizarse."},{"id":"c","text":"Que se pare de puntillas para estar más alta","feedback":"De puntillas la base es más pequeña y el equilibrio es más difícil."}],"correct":["a"]},"id":"s01-ef-2-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.2.1"],"ambito":"convivir","prompt":"Luis es zurdo. En el recreo, un compañero le dice que \\"está mal\\" lanzar con la izquierda. ¿Qué es correcto?","explain":"Ser zurdo es una forma normal de lateralidad. Lo importante es ejercitar el lado dominante y, además, practicar con el otro.","type":"choice","props":{"options":[{"id":"a","text":"Luis debe cambiar a la mano derecha","feedback":"No: forzar a alguien a cambiar su mano dominante no tiene sentido y le quita precisión."},{"id":"b","text":"Ser zurdo es normal; Luis puede reforzar su mano izquierda y practicar también con la derecha"},{"id":"c","text":"Luis no debería jugar a lanzar","feedback":"Todas las personas pueden jugar, sin importar su mano dominante."}],"correct":["b"]},"id":"s01-ef-2-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.2.4"],"prompt":"Clasifica cada actividad: ¿equilibrio **estático** o **dinámico**?","type":"sort","props":{"buckets":[{"id":"e","label":"Estático (quieto)","icon":"PersonStanding","color":"var(--area-ef)"},{"id":"d","label":"Dinámico (en movimiento)","icon":"Footprints","color":"var(--c-maiz-strong)"}],"items":[{"id":"y1","text":"Caminar sobre una línea recta sin salirte","bucket":"d"},{"id":"y2","text":"Sostenerte en un pie con la otra rodilla arriba, sin moverte","bucket":"e"},{"id":"y3","text":"Cruzar un puente angosto caminando","bucket":"d"},{"id":"y4","text":"Quedarte de puntillas 10 segundos en tu lugar","bucket":"e"}]},"id":"s01-ef-2-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.2.1","ef:1.2.4"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"La mano dominante es la que usamos con más fuerza y precisión.","answer":true},{"text":"Con los pies juntos tienes más equilibrio que con los pies separados.","answer":false,"why":"Con los pies separados la base de apoyo es más amplia y hay más equilibrio."},{"text":"Doblar un poco las rodillas baja el centro de gravedad y ayuda al equilibrio.","answer":true}]},"id":"s01-ef-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["ef"],"cnb":["ef:1.2.4"],"type":"reflection","props":{"statements":["Explico qué hacen huesos, músculos, tendones y ligamentos","Hago flexión, extensión y rotación con control","Reconozco mi mano dominante y mejoro mi equilibrio"],"commitments":["Haré mi rutina de calentamiento antes de jugar","Practicaré lanzar y botar con las dos manos","Me pararé en un pie mientras me lavo los dientes"]},"id":"s01-ef-2-11"}],"kind":"materia","area":"ef","day":5}},{"missionId":"s01","version":"cnb-sexto-d43f9f5f50aae42f","lesson":{"id":"s01-l3-1","title":"In, on, under: ¿dónde está?","icon":"Backpack","minutes":13,"gancho":"Se te perdió el lápiz y tu compañera de intercambio solo habla inglés. ¿Cómo le preguntas dónde está?","objetivos":["Nombrar en inglés objetos del aula","Usar in, on y under para decir dónde está algo","Preguntar y responder: Where is the…? It is…"],"resumen":["Objetos del aula: book (libro), pencil (lápiz), notebook (cuaderno), backpack (mochila), table (mesa), chair (silla), box (caja).","in = dentro de · on = sobre, encima de (tocando) · under = debajo de.","Decimos \\"The book is on the table\\", not \\"in the table\\": in es dentro, on es encima.","Pregunta: Where is the pencil? Respuesta: It is in the box. (It is = It's)"],"media":{"id":"s01-l3-1-objetos","kind":"audio","title":"Classroom objects","duration":40,"alt":"Una voz en inglés dice objetos del aula y oraciones con in, on y under.","brief":"Audio de 40 s. Voz adulta con inglés claro y pausado (acento estadounidense o británico estándar), sin música. Cada palabra dos veces con 1 s de pausa: \\"book\\", \\"pencil\\", \\"notebook\\", \\"backpack\\", \\"table\\", \\"chair\\", \\"box\\". Luego, oraciones con 2 s de pausa: \\"The book is on the table.\\" \\"The pencil is in the box.\\" \\"The backpack is under the chair.\\" \\"Where is the notebook? It's in the backpack.\\""},"steps":[{"fase":"explorar","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"conocer","title":"Prepositions of place: in, on, under","prompt":"Las **preposiciones de lugar** dicen **dónde** está algo. Toca cada tarjeta.","type":"explain","props":{"icon":"MapPin","body":"Cuidado: en español decimos \\"en la mesa\\" y \\"en la caja\\" con la misma palabra, pero en inglés son **distintas**. We say: **\\"The book is on the table\\"**, not \\"in the table\\".","reveal":[{"icon":"Package","front":"in","back":"**Dentro de.** _The pencil is **in** the box._ (El lápiz está dentro de la caja.)"},{"icon":"ArrowUp","front":"on","back":"**Sobre, encima de** (tocando la superficie). _The book is **on** the table._ (El libro está sobre la mesa.)"},{"icon":"ArrowDown","front":"under","back":"**Debajo de.** _The backpack is **under** the chair._ (La mochila está debajo de la silla.)"}]},"id":"s01-l3-1-1"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"conocer","prompt":"Observa la imagen y lee: _\\"The cat is **on** the box.\\"_ ¿Dónde está el gato?","explain":"**On** significa \\"sobre\\" o \\"encima de\\". El gato está encima de la caja. Hoy aprenderás tres palabras para decir dónde están las cosas.","media":{"id":"s01-l3-1-gato","kind":"image","title":"The cat is on the box","aspect":"4:3","alt":"Un gato atigrado sentado encima de una caja de cartón cerrada, en un aula.","brief":"Ilustración sencilla y alegre: un gato atigrado sentado ENCIMA de una caja de cartón cerrada, en el piso de un aula con pupitres al fondo. Nada dentro ni debajo de la caja para que no haya confusión. Sin texto. Dimensiones: 1200x900."},"type":"choice","props":{"options":[{"id":"a","text":"Encima de la caja","icon":"ArrowUp"},{"id":"b","text":"Dentro de la caja","icon":"Package","feedback":"Dentro de la caja sería \\"in the box\\"."},{"id":"c","text":"Debajo de la caja","icon":"ArrowDown","feedback":"Debajo sería \\"under the box\\"."}],"correct":["a"]},"id":"s01-l3-1-2"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"conocer","title":"Classroom objects","prompt":"Escucha el audio de la lección y repite cada palabra en voz alta. Voltea la tarjeta para ver su significado y cómo se pronuncia aproximadamente.","type":"flashcards","props":{"cards":[{"icon":"Book","front":"book","back":"libro · se dice parecido a \\"buk\\""},{"icon":"Pencil","front":"pencil","back":"lápiz · \\"pén-sil\\""},{"icon":"Notebook","front":"notebook","back":"cuaderno · \\"nóut-buk\\""},{"icon":"Backpack","front":"backpack","back":"mochila · \\"bák-pak\\""},{"icon":"Table","front":"table","back":"mesa · \\"téi-bol\\""},{"icon":"Package","front":"box","back":"caja · \\"boks\\""},{"icon":"Armchair","front":"chair","back":"silla · \\"cher\\""}]},"id":"s01-l3-1-3"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"hacer","title":"Worked example","prompt":"Mira cómo se arma una respuesta completa en inglés.","type":"worked-example","props":{"icon":"MessageCircle","problem":"Tu amiga pregunta: _\\"Where is the notebook?\\"_ (¿Dónde está el cuaderno?). El cuaderno está **dentro de la mochila**. ¿Qué respondes?","steps":[{"text":"Empieza con **It is** (o su forma corta **It's**) = \\"Está\\".","why":"En inglés siempre se dice quién o qué: \\"it\\" (eso) reemplaza a \\"the notebook\\"."},{"text":"Elige la preposición: dentro de = **in**."},{"text":"Agrega el lugar con **the**: **the backpack**.","why":"\\"The\\" significa el, la, los o las."}],"answer":"**It's in the backpack.** (Está dentro de la mochila.)","tip":"Pregunta: Where is the…? → Respuesta: It's + in/on/under + the + lugar."},"id":"s01-l3-1-4"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"hacer","prompt":"Ahora tú, con ayuda: la pelota está **debajo** de la mesa. ¿Qué oración lo dice?","hint":"Debajo de = under. Encima de = on. Dentro de = in.","explain":"**Under** = debajo de. _The ball is under the table._","type":"choice","props":{"options":[{"id":"a","text":"The ball is on the table.","feedback":"On = encima. La pelota estaría sobre la mesa."},{"id":"b","text":"The ball is under the table."},{"id":"c","text":"The ball is in the table.","feedback":"Una pelota no puede estar dentro de una mesa. Busca \\"debajo de\\"."}],"correct":["b"]},"id":"s01-l3-1-5"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"hacer","prompt":"Lee cada situación en español y colócala en la preposición inglesa correcta.","hint":"Dentro → in. Encima, tocando → on. Debajo → under.","explain":"Dentro de la mochila, la caja o el vaso → in. Encima de la silla o el escritorio → on. Debajo de la cama o la silla → under.","type":"sort","props":{"buckets":[{"id":"in","label":"in","icon":"Package"},{"id":"on","label":"on","icon":"ArrowUp"},{"id":"un","label":"under","icon":"ArrowDown"}],"items":[{"id":"x1","text":"El cuaderno está dentro de la mochila.","bucket":"in"},{"id":"x2","text":"El gato duerme sobre la silla.","bucket":"on"},{"id":"x3","text":"Los zapatos están debajo de la cama.","bucket":"un"},{"id":"x4","text":"Los crayones están en la caja.","bucket":"in","feedback":"\\"En la caja\\" quiere decir dentro de ella: in."},{"id":"x5","text":"El libro está en el escritorio.","bucket":"on","feedback":"\\"En el escritorio\\" quiere decir encima de él: on. ¡Por eso decimos \\"on the table\\", not \\"in the table\\"!"},{"id":"x6","text":"El perro está debajo de la silla.","bucket":"un"}]},"id":"s01-l3-1-6"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"hacer","prompt":"Ordena las palabras para decir: \\"El lápiz está sobre el cuaderno\\".","explain":"The pencil (qué) + is (está) + on (sobre) + the notebook (dónde).","type":"order","props":{"labels":{"start":"Primera palabra","end":"Última palabra"},"items":[{"id":"o1","text":"The"},{"id":"o2","text":"pencil"},{"id":"o3","text":"is"},{"id":"o4","text":"on"},{"id":"o5","text":"the"},{"id":"o6","text":"notebook."}]},"id":"s01-l3-1-7"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"hacer","prompt":"Mira la escena del aula y completa con **in**, **on** o **under**.","explain":"El libro está encima de la mesa (on), la mochila debajo de la silla (under) y los lápices dentro de la caja (in).","media":{"id":"s01-l3-1-aula","kind":"image","title":"Our classroom","aspect":"4:3","alt":"Un aula: un libro encima de la mesa, una mochila debajo de la silla y lápices dentro de una caja.","brief":"Ilustración clara de un rincón de aula guatemalteca: una mesa de madera con un libro rojo ENCIMA; junto a ella, una silla con una mochila azul DEBAJO del asiento, en el piso; sobre la mesa, una caja abierta con varios lápices DENTRO. Objetos grandes y bien separados para que se vean las relaciones. Sin texto ni marcas. Dimensiones: 1200x900."},"type":"fill-blank","props":{"text":"The book is [[on]] the table. The backpack is [[under]] the chair. The pencils are [[in]] the box."},"id":"s01-l3-1-8"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"hacer","prompt":"Your friend asks: _\\"Where is my notebook?\\"_ Está debajo de tu silla. ¿Qué respondes?","explain":"**It's under your chair.** \\"Your\\" significa \\"tu\\": tu silla.","type":"choice","props":{"options":[{"id":"a","text":"It's under your chair."},{"id":"b","text":"It's in your chair.","feedback":"\\"In\\" sería dentro de la silla. Debajo es \\"under\\"."},{"id":"c","text":"Where is your chair?","feedback":"Eso es otra pregunta. Tu amiga necesita una respuesta."}],"correct":["a"]},"id":"s01-l3-1-9"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:1.1.1"],"prompt":"Boleto de salida: completa en inglés. (El libro está sobre la silla. La caja está debajo de la mesa.)","type":"fill-blank","props":{"text":"The book is [[on]] the chair. The box is [[under]] the table.","distractors":["in"]},"id":"s01-l3-1-10"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:1.1.1"],"prompt":"¿Cuál oración está **bien dicha** en inglés para \\"El cuaderno está en la mesa\\"?","type":"choice","props":{"options":[{"id":"a","text":"The notebook is in the table."},{"id":"b","text":"The notebook is on the table."},{"id":"c","text":"The notebook is under the table."}],"correct":["b"]},"id":"s01-l3-1-11"}],"kind":"materia","area":"l3","day":2}},{"missionId":"s01","version":"cnb-sexto-06e114b24e37136c","lesson":{"id":"s01-l1-3","title":"El cuerpo también habla: gestos, mirada y movimiento","icon":"PersonStanding","minutes":14,"gancho":"Sin decir una palabra, ¿puedes saber si alguien está nervioso, contento o aburrido? ¿Cómo lo sabes?","objetivos":["Preparar un guion breve que coordine palabras, voz, gestos y mirada"],"resumen":["Los gestos (manos y cara), la mirada, la postura y los movimientos también comunican.","Reparte la mirada entre todas las personas; párate firme; mueve las manos para mostrar tamaños, cantidades o direcciones.","El cuerpo y las palabras deben decir lo mismo: si dices \\"¡qué emoción!\\" con cara seria, el público se confunde.","Una exposición corta tiene inicio (atrapa), desarrollo (2 o 3 ideas) y cierre (una frase para recordar)."],"media":{"id":"s01-l1-3-cuerpo","kind":"image","title":"Lo que dice el cuerpo","aspect":"16:9","alt":"Dos ilustraciones de la misma niña exponiendo: a la izquierda, con los brazos cruzados, mirando al piso y balanceándose; a la derecha, parada firme, mirando al grupo y señalando un mapa.","brief":"Ilustración plana en dos paneles. Panel izquierdo con etiqueta \\"Distrae\\": niña de 12 años con brazos cruzados, vista al suelo, un pie cruzado detrás del otro, flechas que indican balanceo. Panel derecho con etiqueta \\"Comunica\\": la misma niña con postura erguida, pies separados al ancho de los hombros, mano abierta señalando un mapa de su municipio, mirada hacia el público; líneas punteadas desde sus ojos hacia distintos compañeros. Fondo de aula guatemalteca sencilla. Colores cálidos, sin texto adicional. Dimensiones: 1600x900."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":["l1:2.1.6"],"ambito":"conocer","title":"Cuatro formas en que habla tu cuerpo","prompt":"Toca cada tarjeta y descubre cómo usar tu cuerpo al exponer.","type":"explain","props":{"icon":"PersonStanding","body":"El lenguaje del cuerpo se llama **comunicación no verbal**: todo lo que comunicamos sin palabras. Después de la lección, compartir el guion con un familiar es opcional.","reveal":[{"icon":"Hand","front":"Gestos","back":"Con las **manos** puedes mostrar tamaños (\\"así de grande\\"), cantidades (tres dedos), direcciones (señalar el mapa). Con la **cara** muestras emociones: sorpresa, alegría, preocupación."},{"icon":"Eye","front":"Mirada","back":"**Reparte la mirada**: mira un momento a una persona de la izquierda, otra del centro y otra de la derecha. Así todos sienten que les hablas a ellos."},{"icon":"PersonStanding","front":"Postura","back":"Párate **firme**, con los pies separados al ancho de los hombros y la espalda recta. Evita balancearte o esconder las manos en los bolsillos."},{"icon":"Footprints","front":"Movimientos","back":"Muévete **con intención**: da un paso hacia el público para decir algo importante o acércate al cartel para señalarlo. No camines de un lado a otro sin razón."}]},"id":"s01-l1-3-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:2.1.6"],"ambito":"conocer","prompt":"Ana y Rosa dicen las mismas palabras. Ana tiene los brazos cruzados, mira al suelo y se balancea; Rosa está erguida y mira al público. ¿Qué **te comunica** el cuerpo de Ana?","explain":"Aunque las palabras sean iguales, los brazos cruzados, la vista al suelo y el balanceo transmiten nervios o desinterés. El cuerpo habla, ¡aunque no queramos!","type":"choice","props":{"options":[{"id":"a","text":"Que está segura y entusiasmada con su tema","feedback":"Fíjate en los brazos y en hacia dónde mira: dicen otra cosa."},{"id":"b","text":"Que está nerviosa o que no le interesa mucho su tema"},{"id":"c","text":"Nada: el cuerpo no comunica","feedback":"Siempre comunica. Por eso conviene usarlo a nuestro favor."}],"correct":["b"]},"id":"s01-l1-3-2"},{"fase":"construir","areas":["l1"],"cnb":["l1:2.1.6"],"ambito":"hacer","prompt":"¿Esto **ayuda** a comunicar o **distrae** al público?","hint":"Pregúntate si el gesto o movimiento acompaña lo que se está diciendo.","explain":"Lo que ayuda tiene una intención clara. Lo que distrae son hábitos de nervios que podemos corregir con práctica.","type":"sort","props":{"buckets":[{"id":"ay","label":"Ayuda","icon":"ThumbsUp","color":"var(--c-ok)"},{"id":"di","label":"Distrae","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"c1","text":"Abrir los brazos al decir \\"un lago enorme\\"","bucket":"ay"},{"id":"c2","text":"Jugar con el lapicero todo el tiempo","bucket":"di"},{"id":"c3","text":"Mirar a personas de distintos lados del salón","bucket":"ay"},{"id":"c4","text":"Mirar solo a la maestra","bucket":"di","feedback":"El resto del grupo siente que no le hablas. Reparte la mirada."},{"id":"c5","text":"Dar un paso al frente antes del dato más importante","bucket":"ay"},{"id":"c6","text":"Balancearse de un pie al otro","bucket":"di"}]},"id":"s01-l1-3-3"},{"id":"s01-l1-3-5","fase":"construir","areas":["l1"],"cnb":["l1:2.1.6"],"ambito":"hacer","title":"Ejemplo resuelto: el guion de una exposición de un minuto","prompt":"Ana preparó su exposición **\\"Nuestro lugar en mapas y palabras\\"**. Mira cómo organizó su guion y dónde decidió usar cada recurso.","type":"worked-example","props":{"icon":"ClipboardList","problem":"Ana vive en Livingston, Izabal. Tiene un minuto para presentar su lugar.","steps":[{"text":"**Inicio (atrapa):** \\"¿Se imaginan ir a la escuela… en lancha?\\" (Pausa. Sonríe. Mira a todo el grupo.)","why":"Pregunta + pausa + mirada: tres recursos en diez segundos."},{"text":"**Idea 1:** \\"Livingston está donde el río Dulce llega al mar Caribe.\\" (Señala el lugar en un mapa.)","why":"El gesto de señalar ayuda a ubicar."},{"text":"**Idea 2:** \\"Ahí vivimos familias garífunas, q'eqchi' y ladinas; por eso se oyen varios idiomas.\\" (Cuenta con los dedos: uno, dos, tres.)"},{"text":"**Idea 3:** \\"Mi comida favorita es el tapado, una sopa de mariscos con coco.\\" (Cara de \\"¡qué rico!\\".)"},{"text":"**Cierre (para recordar):** \\"Si algún día llegan en lancha, los espero con un tapado.\\" (Da un paso al frente y sonríe.)","why":"Un cierre amable y concreto se queda en la memoria."}],"answer":"Un guion claro: inicio que atrapa, tres ideas cortas y un cierre, cada parte con su recurso de voz o de cuerpo anotado entre paréntesis.","tip":"Escribe tus recursos entre paréntesis en el guion, como si fueras actor o actriz."}},{"id":"s01-l1-3-6","fase":"aplicar","areas":["l1"],"cnb":["l1:2.1.6"],"ambito":"hacer","prompt":"Ordena las partes de la exposición de Pedro sobre San Juan Comalapa.","explain":"Primero se atrapa la atención, luego se desarrollan las ideas y al final se cierra con algo memorable.","type":"order","props":{"labels":{"start":"Empieza","end":"Termina"},"items":[{"id":"o1","text":"\\"¿Sabían que en mi pueblo hay un muro pintado de colores que cuenta nuestra historia?\\" (Pausa.)"},{"id":"o2","text":"\\"Comalapa está en Chimaltenango y es conocida por sus pintores.\\" (Señala el mapa.)"},{"id":"o3","text":"\\"Mi tío pinta la cosecha del maíz; a veces yo le ayudo a mezclar colores.\\" (Muestra un dibujo.)"},{"id":"o4","text":"\\"Cuando vayan, busquen el muro: una parte de nuestra historia está pintada ahí.\\" (Paso al frente, sonrisa.)"}]}},{"id":"s01-l1-3-8","fase":"aplicar","areas":["l1"],"cnb":["l1:2.1.6"],"ambito":"hacer","prompt":"Dentro de los 6 minutos, **completa el inicio que ya escribiste en la lección 1** hasta formar un guion de al menos 50 palabras para **\\"Nuestro lugar en mapas y palabras\\"**: inicio, dos ideas y cierre. No copies de nuevo el inicio. Reserva los últimos **20 a 30 segundos** para un **autoensayo individual en solitario** del inicio: usa un recurso de voz, un gesto, una mirada intencional y un movimiento breve.","explain":"La representación breve es parte de esta misma tarea: no requiere otra persona, materiales ni grabación.","type":"short-answer","props":{"minWords":50,"placeholder":"Inicio: … (recurso)\\nIdea 1: … (recurso)\\nIdea 2: …\\nCierre: …","model":"Inicio: \\"¿Sabían que desde mi casa se ven tres volcanes?\\" (Pausa, señalo la ventana.)\\nIdea 1: \\"Vivo en Antigua Guatemala, una ciudad de calles empedradas.\\" (Muestro una foto.)\\nIdea 2: \\"Cada mañana miro el Volcán de Agua: si tiene nubes, mi abuela dice que va a llover.\\" (Cara de duda, sonrío.)\\nIdea 3: \\"En Semana Santa las calles se llenan de alfombras de aserrín de colores.\\" (Abro los brazos.)\\nCierre: \\"Mi lugar es pequeño, pero desde él se ven gigantes.\\" (Paso al frente, voz más lenta.)","rubric":["Tiene inicio, 2 o 3 ideas y cierre","Anoté al menos un recurso de voz (pausa, cambio de volumen)","Anoté al menos dos recursos de cuerpo (gesto, mirada, movimiento)","Los gestos acompañan lo que digo","Reutilicé el inicio previo sin copiarlo de nuevo","Representé en solitario el inicio durante 20 a 30 segundos usando voz, un gesto, una mirada intencional y un movimiento breve"]}},{"id":"s01-l1-3-9","fase":"comprobar","areas":["l1"],"cnb":["l1:2.1.6"],"prompt":"¿Qué es **repartir la mirada**?","type":"choice","props":{"options":[{"id":"a","text":"Mirar un momento a personas de distintos lados del grupo"},{"id":"b","text":"Mirar fijamente a una sola persona"},{"id":"c","text":"Cerrar los ojos para concentrarse"}],"correct":["a"]}},{"id":"s01-l1-3-10","fase":"comprobar","areas":["l1"],"cnb":["l1:2.1.6"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Mostrar tres dedos al decir \\"tres ríos\\" es un gesto que acompaña el mensaje.","answer":true},{"text":"Caminar de un lado a otro sin parar ayuda a mantener la atención.","answer":false,"why":"Los movimientos deben tener intención; si no, distraen."},{"text":"Si tus palabras dicen alegría, tu cara también debería mostrarla.","answer":true}]}}],"kind":"materia","area":"l1","day":3}},{"missionId":"s01","version":"cnb-sexto-f9966cb44615bdd2","lesson":{"id":"s01-cnt-2","title":"La célula animal y sus organelos","icon":"Microscope","minutes":15,"gancho":"Un jaguar, una hormiga y tú parecen muy distintos. Si los miraras con un microscopio muy potente, ¿qué encontrarías en los tres?","objetivos":["Explicar qué es la célula y por qué es la unidad de la vida","Nombrar las partes de la célula animal y describir la función de cada organelo"],"resumen":["La célula es la unidad más pequeña con vida. Todos los seres vivos están formados por células, y toda célula proviene de otra célula.","Partes principales: membrana celular (controla lo que entra y sale), citoplasma (medio donde están los organelos) y núcleo (guarda el ADN y dirige la célula).","Organelos: mitocondrias (producen energía), ribosomas (fabrican proteínas), retículo endoplasmático (transporta), aparato de Golgi (empaca y envía), lisosomas (digieren desechos), vacuolas (almacenan) y centriolos (ayudan a dividir la célula)."],"media":{"id":"s01-cnt-2-celula-animal","kind":"diagram","title":"La célula animal por dentro","aspect":"4:3","alt":"Esquema de una célula animal redondeada, cortada por la mitad, con el núcleo en el centro y los organelos rotulados en el citoplasma.","brief":"Diagrama escolar en colores planos de una célula animal de forma redondeada e irregular, vista en corte. Rotular con líneas guía y letra grande: membrana celular (borde fino azul), citoplasma (celeste claro), núcleo (morado, con nucléolo y ADN como hilos), mitocondrias (naranja, forma de frijol con pliegues), ribosomas (puntitos negros), retículo endoplasmático (pliegues rosados junto al núcleo), aparato de Golgi (sacos amarillos apilados), lisosomas (círculos verdes pequeños), vacuolas pequeñas y par de centriolos. Fondo blanco. Estilo de libro de texto de primaria, sin exceso de detalle. Dimensiones: 1200x900."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","title":"¿Qué es una célula?","prompt":"La **célula** es la unidad más pequeña que tiene vida: se alimenta, crece, responde y se reproduce. Toca cada tarjeta.","type":"explain","props":{"icon":"Microscope","body":"La mayoría de las células mide **menos de una décima de milímetro**: por eso necesitamos un **microscopio** para verlas. Tu cuerpo tiene **billones** de ellas (millones de millones).","reveal":[{"icon":"Blocks","front":"Unidad de la vida","back":"**Todos** los seres vivos están formados por células: algunos por una sola, otros, como tú, por billones."},{"icon":"Copy","front":"Viene de otra célula","back":"Toda célula nace de **otra célula** que se divide en dos. Así creces y así se reparan tus heridas."},{"icon":"Layers","front":"Tres partes principales","back":"**Membrana** (el borde), **citoplasma** (el interior) y **núcleo** (el centro de mando)."}]},"id":"s01-cnt-2-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","prompt":"¿Qué tienen en común un **jaguar**, una **hormiga** y **tú**?","explain":"Los tres están formados por **células**. La hormiga no tiene huesos y solo el jaguar tiene pelo, pero todos los seres vivos están hechos de células.","type":"choice","props":{"layout":"grid","options":[{"id":"a","text":"Todos tienen huesos","icon":"Bone","feedback":"La hormiga no tiene huesos: tiene un esqueleto externo, duro, por fuera del cuerpo."},{"id":"b","text":"Todos están formados por células","icon":"Microscope"},{"id":"c","text":"Todos tienen pelo","icon":"Cat","feedback":"Ni la hormiga ni tú tienen el cuerpo cubierto de pelo como el jaguar."}],"correct":["b"]},"id":"s01-cnt-2-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","title":"Las partes principales","prompt":"Imagina la célula como una **comunidad pequeña**: tiene un cerco con portón, un espacio donde se trabaja y una oficina que da las órdenes. Toca las tarjetas.","type":"explain","props":{"icon":"Home","body":"Cada parte tiene una **función** (un trabajo). Si una parte falla, toda la célula sufre.","reveal":[{"icon":"Shield","front":"Membrana celular","back":"Capa delgada y flexible que rodea la célula. **Controla qué entra y qué sale**: deja pasar agua y nutrientes y saca desechos. Es como el cerco con portón."},{"icon":"Droplets","front":"Citoplasma","back":"Sustancia parecida a una **gelatina** que llena la célula. En ella flotan los organelos y ocurren muchas reacciones."},{"icon":"Brain","front":"Núcleo","back":"Guarda el **ADN**, la información para construir y hacer funcionar la célula. **Dirige** todas sus actividades, como una oficina central."}]},"id":"s01-cnt-2-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","prompt":"Completa la descripción de la célula animal.","hint":"El borde controla el paso; la \\"gelatina\\" es el citoplasma; el centro de mando es el núcleo.","explain":"Membrana = controla el paso; citoplasma = medio interno; núcleo = guarda el ADN y dirige.","type":"fill-blank","props":{"text":"La [[membrana celular]] rodea la célula y controla lo que entra y sale. Adentro está el [[citoplasma]], una sustancia parecida a la gelatina donde flotan los organelos. El [[núcleo]] guarda el [[ADN]] y dirige las actividades de la célula.","distractors":["cloroplasto","pared celular"]},"id":"s01-cnt-2-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","title":"Los organelos: trabajadores de la célula","prompt":"En el citoplasma hay **organelos**: pequeñas estructuras, cada una con un trabajo. Toca cada tarjeta para conocer los principales.","type":"explain","props":{"icon":"Factory","body":"Los organelos trabajan en equipo, como las personas de una panadería: unas hacen la masa, otras hornean, otras empacan y otras limpian.","reveal":[{"icon":"Zap","front":"Mitocondrias","back":"Liberan la **energía** guardada en los nutrientes y la dejan lista para que la célula la use. Son su \\"planta de energía\\"."},{"icon":"CircleDot","front":"Ribosomas","back":"Puntitos que **fabrican proteínas**, siguiendo las instrucciones del núcleo."},{"icon":"Route","front":"Retículo endoplasmático","back":"Red de canales y pliegues que **transporta** sustancias dentro de la célula."},{"icon":"Package","front":"Aparato de Golgi","back":"Sacos apilados que **empacan y envían** las sustancias adonde se necesitan, dentro o fuera de la célula."},{"icon":"Recycle","front":"Lisosomas","back":"Bolsitas con jugos que **digieren** desechos y partes viejas. Son el \\"equipo de limpieza\\"."},{"icon":"Archive","front":"Vacuolas y centriolos","back":"Las **vacuolas** (pequeñas en la célula animal) **almacenan** agua y sustancias. Los **centriolos** ayudan a la célula a **dividirse** en dos."}]},"id":"s01-cnt-2-5"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","prompt":"Une cada organelo con su función.","hint":"Piensa en la comparación con la panadería: energía, fabricar, transportar, empacar, limpiar.","explain":"Mitocondria = energía; ribosoma = proteínas; retículo = transporte; Golgi = empaque y envío; lisosoma = digestión de desechos; centriolos = división.","type":"match","props":{"leftTitle":"Organelo","rightTitle":"Función","pairs":[{"id":"mi","left":"Mitocondria","leftIcon":"Zap","right":"Produce energía a partir de los nutrientes"},{"id":"ri","left":"Ribosoma","leftIcon":"CircleDot","right":"Fabrica proteínas"},{"id":"re","left":"Retículo endoplasmático","leftIcon":"Route","right":"Transporta sustancias por la célula"},{"id":"go","left":"Aparato de Golgi","leftIcon":"Package","right":"Empaca y envía sustancias"},{"id":"li","left":"Lisosoma","leftIcon":"Recycle","right":"Digiere desechos y partes viejas"},{"id":"ce","left":"Centriolos","leftIcon":"Copy","right":"Ayudan a la célula a dividirse"}]},"id":"s01-cnt-2-6"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","title":"Ejemplo: los organelos en equipo","prompt":"Mira cómo varios organelos trabajan juntos para que una célula fabrique y envíe una sustancia.","media":{"id":"s01-cnt-2-proteina","kind":"animation","title":"El viaje de una proteína","aspect":"16:9","duration":40,"alt":"Animación dentro de una célula animal: una instrucción sale del núcleo, un ribosoma arma una proteína, esta viaja por el retículo, el aparato de Golgi la empaca y una bolsita la saca por la membrana.","brief":"Animación 2D de 40 s con el mismo estilo del esquema de la célula animal. Un \\"mensaje\\" (cinta morada) sale del núcleo; un ribosoma sobre el retículo endoplasmático arma una cadena de cuentas (proteína); la cadena viaja por los canales del retículo hasta el aparato de Golgi, que la envuelve en una burbuja; la burbuja llega a la membrana y la proteína sale de la célula. Las mitocondrias brillan cada vez que dan energía. Rótulos grandes en cada organelo; narración en español con subtítulos."},"type":"worked-example","props":{"icon":"Factory","problem":"Las células del estómago fabrican **enzimas digestivas**: proteínas que salen de la célula y ayudan a deshacer la comida. ¿Qué organelos participan y en qué orden?","steps":[{"text":"El **núcleo** tiene en su ADN la instrucción para fabricar la sustancia y la envía al citoplasma.","why":"El núcleo dirige: sin su instrucción, no se fabrica nada."},{"text":"Los **ribosomas** fabrican la proteína siguiendo esa instrucción."},{"text":"El **retículo endoplasmático** la transporta por sus canales."},{"text":"El **aparato de Golgi** la empaca en una bolsita y la envía hacia la **membrana**, que la deja salir."},{"text":"Durante todo el proceso, las **mitocondrias** aportan la **energía** necesaria.","why":"Fabricar, transportar y empacar requiere energía."}],"answer":"Núcleo → ribosomas → retículo endoplasmático → aparato de Golgi → membrana, con energía de las mitocondrias.","tip":"Los organelos no trabajan solos: la célula funciona como un equipo."},"id":"s01-cnt-2-7"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","prompt":"Las células de los **músculos de las piernas** de una corredora de maratón necesitan muchísima energía. ¿Qué organelo tendrán en gran cantidad?","explain":"Las células que gastan mucha energía, como las musculares, tienen **muchas mitocondrias**.","type":"choice","props":{"options":[{"id":"a","text":"Mitocondrias","icon":"Zap"},{"id":"b","text":"Lisosomas","icon":"Recycle","feedback":"Los lisosomas digieren desechos; no producen energía."},{"id":"c","text":"Aparato de Golgi","icon":"Package","feedback":"El Golgi empaca y envía sustancias; la energía viene de otro organelo."}],"correct":["a"]},"id":"s01-cnt-2-8"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","prompt":"Una célula de tu piel fabrica una proteína que la protege. Ordena el recorrido, desde la instrucción hasta que la proteína sale.","explain":"La instrucción sale del núcleo, el ribosoma fabrica, el retículo transporta, el Golgi empaca y la membrana deja salir.","type":"order","props":{"labels":{"start":"Inicio","end":"Final"},"items":[{"id":"p1","text":"El núcleo envía la instrucción","icon":"Brain"},{"id":"p2","text":"Un ribosoma fabrica la proteína","icon":"CircleDot"},{"id":"p3","text":"El retículo endoplasmático la transporta","icon":"Route"},{"id":"p4","text":"El aparato de Golgi la empaca","icon":"Package"},{"id":"p5","text":"La membrana la deja salir de la célula","icon":"Shield"}]},"id":"s01-cnt-2-9"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.2.1"],"ambito":"conocer","prompt":"Supongamos que en una célula los **lisosomas** dejaran de funcionar. ¿Qué pasaría con más probabilidad?","explain":"Sin su \\"equipo de limpieza\\", los desechos y las partes viejas se acumularían y la célula se dañaría.","type":"choice","props":{"options":[{"id":"a","text":"Se acumularían desechos dentro de la célula","icon":"Trash2"},{"id":"b","text":"La célula dejaría de tener membrana","icon":"Shield","feedback":"La membrana no depende de los lisosomas."},{"id":"c","text":"La célula tendría más energía","icon":"Zap","feedback":"La energía la producen las mitocondrias."}],"correct":["a"]},"id":"s01-cnt-2-10"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:1.2.1"],"prompt":"¿Qué parte de la célula **guarda el ADN y dirige** sus actividades?","type":"choice","props":{"options":[{"id":"a","text":"La membrana celular"},{"id":"b","text":"El núcleo"},{"id":"c","text":"El citoplasma"},{"id":"d","text":"Los ribosomas"}],"correct":["b"]},"id":"s01-cnt-2-11"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:1.2.1"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"La membrana celular controla qué sustancias entran y salen de la célula.","answer":true},{"text":"Los ribosomas se encargan de digerir los desechos de la célula.","answer":false,"why":"Los ribosomas fabrican proteínas; los lisosomas digieren desechos."},{"text":"El aparato de Golgi empaca y envía sustancias.","answer":true},{"text":"Una célula puede aparecer de la nada, sin venir de otra célula.","answer":false,"why":"Toda célula proviene de otra célula que se divide."}]},"id":"s01-cnt-2-12"}],"kind":"materia","area":"cnt","day":3}},{"missionId":"s01","version":"cnb-sexto-858f8b4391adeba9","lesson":{"id":"s01-l3-2","title":"Next to, behind, in front of: my town","icon":"Map","minutes":14,"gancho":"Un turista te pregunta en el parque: \\"Where is the market?\\" ¿Podrías explicarle en inglés dónde queda?","objetivos":["Nombrar en inglés lugares de la comunidad","Usar next to, behind, in front of y between","Describir dónde están los lugares en un mapa sencillo"],"resumen":["Lugares: school (escuela), park (parque), market (mercado), church (iglesia), store (tienda), house (casa), bus stop (parada de bus).","next to = a la par de · behind = detrás de · in front of = enfrente de · between = entre (dos cosas).","Between siempre une dos lugares con and: The store is between the school and the park.","Seguimos usando in, on y under para objetos: The map is on the wall."],"media":{"id":"s01-l3-2-town","kind":"diagram","title":"Map of San Pedro","aspect":"16:9","alt":"Mapa sencillo de un pueblo con rótulos en inglés: church, park, school, store, market, bus stop y una casa.","brief":"Mapa ilustrado, vista desde arriba con edificios en perspectiva ligera, estilo amable. Una calle principal horizontal. Arriba de la calle, de izquierda a derecha: \\"school\\", \\"store\\", \\"park\\". El \\"park\\" tiene árboles y una fuente. Frente al parque, al otro lado de la calle (abajo): \\"church\\". Detrás de la escuela (más arriba): \\"market\\" con toldos de colores. A la par de la iglesia, a su derecha: \\"bus stop\\" con una camioneta. Una \\"house\\" pequeña a la izquierda de la iglesia. Rótulos grandes en inglés, en minúscula. Sin marcas comerciales. Dimensiones: 1600x900."},"steps":[{"fase":"explorar","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"conocer","title":"More prepositions of place","prompt":"Estas preposiciones sirven para ubicar lugares y personas. Toca cada tarjeta y compara con el mapa.","type":"explain","props":{"icon":"MapPin","body":"Fíjate: **in front of** y **next to** tienen varias palabras, pero funcionan como una sola.","reveal":[{"icon":"ArrowLeftRight","front":"next to","back":"**A la par de, al lado de.** _The bus stop is **next to** the church._"},{"icon":"ArrowUpFromLine","front":"behind","back":"**Detrás de.** _The market is **behind** the school._"},{"icon":"ArrowDownToLine","front":"in front of","back":"**Enfrente de.** _The church is **in front of** the park._"},{"icon":"Columns","front":"between","back":"**Entre** dos cosas, unidas con **and**. _The store is **between** the school **and** the park._"}]},"id":"s01-l3-2-1"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"conocer","prompt":"En una calle están, en este orden, la escuela, la tienda y el parque. Lee: _\\"The store is **between** the school and the park.\\"_ ¿Qué crees que significa **between**?","explain":"La tienda está en medio de la escuela y el parque: **between** = entre. Con el orden de la calle pudiste deducirlo. Hoy aprenderás más palabras para ubicar lugares.","type":"choice","props":{"options":[{"id":"a","text":"Entre (en medio de dos lugares)","icon":"ArrowLeftRight"},{"id":"b","text":"Dentro de","icon":"Package","feedback":"Dentro de es \\"in\\". Revisa el orden de la calle: la tienda está en medio de dos lugares."},{"id":"c","text":"Muy lejos de","icon":"Route","feedback":"En la calle, la tienda está justo en medio de la escuela y el parque, no lejos."}],"correct":["a"]},"id":"s01-l3-2-2"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"conocer","title":"Places in town","prompt":"Escucha y repite cada lugar en voz alta. Voltea la tarjeta para ver su significado.","media":{"id":"s01-l3-2-places","kind":"audio","title":"Places in town","duration":30,"alt":"Una voz en inglés dice nombres de lugares del pueblo.","brief":"Audio de 30 s. Voz adulta, inglés claro y pausado, sin música. Cada palabra dos veces con 1 s de pausa: \\"school\\", \\"park\\", \\"market\\", \\"church\\", \\"store\\", \\"house\\", \\"bus stop\\". Al final: \\"The store is between the school and the park.\\""},"type":"flashcards","props":{"cards":[{"icon":"School","front":"school","back":"escuela · \\"skul\\""},{"icon":"Trees","front":"park","back":"parque · \\"park\\""},{"icon":"Store","front":"market","back":"mercado · \\"már-ket\\""},{"icon":"Church","front":"church","back":"iglesia · \\"cherch\\""},{"icon":"ShoppingBasket","front":"store","back":"tienda · \\"stor\\""},{"icon":"Bus","front":"bus stop","back":"parada de bus · \\"bas stop\\""}]},"id":"s01-l3-2-3"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"hacer","title":"Worked example","prompt":"Mira cómo Carlos le explica a un turista dónde está la parada de bus.","type":"worked-example","props":{"icon":"Bus","problem":"A tourist asks: _\\"Excuse me, where is the bus stop?\\"_ En el mapa, la parada está **a la par de la iglesia**. ¿Qué responde Carlos?","steps":[{"text":"Empieza con **It's** (Está)."},{"text":"A la par de = **next to**.","why":"Se escriben dos palabras, pero es una sola idea."},{"text":"Agrega el lugar de referencia: **the church**."},{"text":"Junta todo en orden: It's + next to + the church. Carlos además señala la iglesia con la mano para ayudar más.","why":"Un gesto acompaña la respuesta y la hace más clara."}],"answer":"**It's next to the church.** (Está a la par de la iglesia.)","tip":"Siempre necesitas un lugar de referencia: next to the…, behind the…, between the… and the…"},"id":"s01-l3-2-4"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"hacer","prompt":"Ahora tú, con ayuda: en una calle están la escuela y el parque, y cerca hay tres casas sin nombre. Lee y elige la correcta: _\\"The **store** is **between** the school and the park.\\"_","hint":"Between = entre. Busca la casa que está en medio de la escuela y el parque.","explain":"La casa B está justo entre la escuela y el parque: esa es la tienda (store).","type":"choice","props":{"options":[{"id":"a","text":"Casa A: debajo de la escuela","icon":"House","feedback":"A está debajo de la escuela. Busca la casa en medio de la escuela y el parque."},{"id":"b","text":"Casa B: en medio de la escuela y el parque","icon":"House"},{"id":"c","text":"Casa C: debajo del parque","icon":"House","feedback":"C está debajo del parque. Busca la casa en medio de la escuela y el parque."}],"correct":["b"]},"id":"s01-l3-2-5"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"hacer","prompt":"Mira el mapa de la lección y completa las oraciones.","explain":"El mercado está detrás de la escuela (behind), la iglesia enfrente del parque (in front of) y la parada de bus a la par de la iglesia (next to).","type":"fill-blank","props":{"text":"The market is [[behind]] the school. The church is [[in front of]] the park. The bus stop is [[next to]] the church.","distractors":["under","between"]},"id":"s01-l3-2-6"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"hacer","prompt":"Mira el mapa de la lección. True or false?","type":"true-false","props":{"statements":[{"text":"The store is between the school and the park.","answer":true},{"text":"The market is in front of the church.","answer":false,"why":"The market is behind the school."},{"text":"The bus stop is next to the church.","answer":true},{"text":"The park is under the school.","answer":false,"why":"\\"Under\\" es debajo de. Un parque no puede estar debajo de una escuela: the park is next to the store."}]},"id":"s01-l3-2-7"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"hacer","title":"Reading","prompt":"Lee lo que escribió Ana sobre su comunidad y responde. Pistas: _my_ = mi, _near_ = cerca, _big_ = grande, _small_ = pequeño, _I like_ = me gusta.","type":"reading","props":{"genre":"Description","heading":"My town","passage":"Hello! My name is Ana. I live in San Pedro. My house is small. It is next to the bus stop.\\n\\nMy school is big. The store is between my school and the park. The market is behind my school.\\n\\nI like the park. It has many trees. On Sundays, I play in the park with my brother.","questions":[{"q":"Where is Ana's house?","options":[{"id":"a","text":"Next to the bus stop"},{"id":"b","text":"Behind the park"},{"id":"c","text":"In the market"}],"correct":"a"},{"q":"What is between the school and the park?","options":[{"id":"a","text":"The store"},{"id":"b","text":"The church"},{"id":"c","text":"Ana's house"}],"correct":"a"},{"q":"¿Qué hace Ana los domingos?","options":[{"id":"a","text":"Juega en el parque con su hermano"},{"id":"b","text":"Va al mercado con su mamá"},{"id":"c","text":"Estudia en la escuela"}],"correct":"a","why":"\\"On Sundays, I play in the park with my brother.\\" Play = jugar, brother = hermano."}]},"id":"s01-l3-2-8"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.1.1"],"ambito":"hacer","prompt":"Escribe **dos oraciones en inglés** sobre tu comunidad o tu casa. Usa dos preposiciones distintas (next to, behind, in front of, between, in, on, under).","type":"short-answer","props":{"minWords":10,"placeholder":"My school is next to…","model":"My house is behind the church. The store is next to my school.","rubric":["Escribí dos oraciones en inglés","Usé dos preposiciones de lugar distintas","Cada oración tiene un lugar de referencia (the church, my school…)"]},"id":"s01-l3-2-9"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:1.1.1"],"prompt":"Boleto de salida: ¿qué significa _\\"The park is **in front of** the church\\"_?","type":"choice","props":{"options":[{"id":"a","text":"El parque está enfrente de la iglesia."},{"id":"b","text":"El parque está detrás de la iglesia."},{"id":"c","text":"El parque está dentro de la iglesia."}],"correct":["a"]},"id":"s01-l3-2-10"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:1.1.1"],"prompt":"Completa en inglés: \\"La tienda está **entre** la escuela y el mercado. El perro está **detrás de** la casa.\\"","type":"fill-blank","props":{"text":"The store is [[between]] the school and the market. The dog is [[behind]] the house.","distractors":["next to","on"]},"id":"s01-l3-2-11"},{"fase":"reflexionar","areas":["l3"],"cnb":[],"ambito":"ser","prompt":"How are you? ¿Cómo te fue esta semana?","type":"reflection","props":{"statements":["Nombro objetos del aula y lugares del pueblo en inglés","Uso in, on y under correctamente","Uso next to, behind, in front of y between para ubicar lugares"],"commitments":["Diré en inglés dónde están tres cosas de mi casa","Enseñaré a alguien de mi familia la diferencia entre \\"in\\" y \\"on\\"","Dibujaré un mapa de mi comunidad con rótulos en inglés"]},"id":"s01-l3-2-12"}],"kind":"materia","area":"l3","day":4}},{"missionId":"s01","version":"cnb-sexto-91f532c19ff35854","lesson":{"id":"s01-cnt-1","title":"El origen del universo y de la Tierra","icon":"Sparkles","minutes":15,"gancho":"Una noche sin luna, en el campo, se ven miles de estrellas. ¿Alguna vez te has preguntado cómo empezó todo eso?","objetivos":["Narrar el relato judeocristiano de la creación en sus siete días","Reconocer otros relatos de origen, como el del Popol Vuh, y la explicación científica","Distinguir un relato de fe o cultural de una explicación científica, con respeto"],"resumen":["Una cosmovisión es la manera en que un pueblo entiende el mundo, su origen y el lugar del ser humano en él.","Según el relato judeocristiano del Génesis, Dios creó el mundo en seis días y descansó el séptimo: luz; cielo; tierra, mares y plantas; Sol, Luna y estrellas; peces y aves; animales terrestres y seres humanos.","El Popol Vuh, libro sagrado k'iche', narra que los creadores formaron a los primeros seres humanos de barro, luego de madera y por último de maíz.","La ciencia explica que el universo comenzó hace unos 13,800 millones de años (Gran Explosión) y que la Tierra se formó hace unos 4,500 millones de años. Los relatos y la ciencia responden preguntas distintas y se respetan."],"media":{"id":"s01-cnt-1-origenes","kind":"image","title":"Tres maneras de contar el origen","aspect":"16:9","alt":"Ilustración dividida en tres paneles: un paisaje luminoso que representa los días de la creación, una escena de maíz y montañas inspirada en el Popol Vuh, y una nube de gas y polvo que forma el Sol y los planetas.","brief":"Ilustración horizontal en tres paneles con el mismo estilo cálido de libro infantil. Panel 1 \\"Génesis\\": luz que se abre sobre aguas, luego tierra con plantas, Sol, Luna y estrellas, aves y peces (sin representar a Dios con rostro). Panel 2 \\"Popol Vuh\\": montañas de Guatemala, figuras sencillas de barro, de madera y de maíz amarillo y blanco, en colores tierra. Panel 3 \\"Ciencia\\": nube de gas y polvo girando que forma el Sol y planetas pequeños, con la Tierra aún roja y caliente. Rótulos breves en cada panel. Respeto total a cada tradición; nada caricaturesco. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:1.1.1"],"ambito":"conocer","title":"Relatos y explicaciones","prompt":"Antes de conocer los relatos, aprende tres palabras clave. Toca cada tarjeta.","type":"explain","props":{"icon":"Globe","body":"Preguntar **\\"¿de dónde venimos?\\"** es muy humano. Las respuestas dependen de **para qué** se hace la pregunta.","reveal":[{"icon":"Eye","front":"Cosmovisión","back":"La **manera en que un pueblo entiende el mundo**: su origen, la naturaleza, lo sagrado y el lugar del ser humano."},{"icon":"BookOpen","front":"Relato de origen","back":"Una narración de **fe o de cultura** que explica el comienzo del mundo y enseña **valores**: gratitud, respeto, cuidado de la vida. Se transmite de generación en generación."},{"icon":"Microscope","front":"Explicación científica","back":"Una explicación que se construye con **observaciones, mediciones y pruebas**, y que **cambia** si aparecen pruebas nuevas."}]},"id":"s01-cnt-1-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.1.1"],"ambito":"conocer","prompt":"Las personas se preguntan desde hace miles de años **cómo empezó el mundo**. ¿Cuántas explicaciones crees que existen?","explain":"Existen **muchas**: cada pueblo tiene su relato de origen, y además la ciencia tiene su propia explicación, basada en pruebas. Hoy conocerás tres.","type":"choice","props":{"options":[{"id":"a","text":"Una sola, la misma en todo el mundo","icon":"Circle","feedback":"Cada cultura ha contado el origen a su manera. ¡Hay muchas!"},{"id":"b","text":"Varias: cada pueblo tiene la suya, y la ciencia tiene otra","icon":"Layers"},{"id":"c","text":"Ninguna: nadie se lo ha preguntado","icon":"X","feedback":"Es una de las preguntas más antiguas de la humanidad."}],"correct":["b"]},"id":"s01-cnt-1-2"},{"fase":"construir","areas":["cnt","l1"],"cnb":["cnt:1.1.1"],"ambito":"conocer","title":"El relato judeocristiano","prompt":"Lee con atención el relato de la creación según el libro del **Génesis**, que comparten judíos y cristianos.","hint":"Si dudas, vuelve a leer el párrafo de cada día.","type":"reading","props":{"heading":"La creación en siete días","genre":"Relato de origen (resumen)","passage":"Según el primer libro de la Biblia, el Génesis, al principio todo estaba vacío y a oscuras, y el espíritu de Dios se movía sobre las aguas.\\n\\nEl **primer día**, Dios dijo: \\"Que exista la luz\\", y separó la luz de la oscuridad: así surgieron el día y la noche. El **segundo día** hizo el firmamento, el cielo, que separó unas aguas de otras. El **tercer día** juntó las aguas en mares, hizo aparecer la tierra seca y la cubrió de plantas y árboles con semilla.\\n\\nEl **cuarto día** colocó en el cielo el Sol, la Luna y las estrellas para marcar los días, las estaciones y los años. El **quinto día** creó los peces y los animales del agua, y las aves del cielo. El **sexto día** creó los animales de la tierra y, por último, al ser humano, hombre y mujer, y les encargó cuidar la creación.\\n\\nEl **séptimo día**, Dios descansó. Por eso, para muchas familias creyentes, hay un día de la semana dedicado al descanso y a la oración.","questions":[{"q":"¿Qué fue lo primero que se creó, según el relato?","options":[{"id":"a","text":"Los animales"},{"id":"b","text":"La luz"},{"id":"c","text":"El ser humano"}],"correct":"b","why":"El primer día: \\"Que exista la luz\\"."},{"q":"¿Qué día aparecen el Sol, la Luna y las estrellas?","options":[{"id":"a","text":"El cuarto día"},{"id":"b","text":"El primer día"},{"id":"c","text":"El séptimo día"}],"correct":"a"},{"q":"Según el relato, ¿qué encargo recibe el ser humano?","options":[{"id":"a","text":"Dominar a los demás pueblos"},{"id":"b","text":"Cuidar la creación"},{"id":"c","text":"Contar las estrellas"}],"correct":"b","why":"El relato enseña un valor: la naturaleza es un regalo que hay que cuidar."}]},"id":"s01-cnt-1-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.1.1"],"ambito":"conocer","prompt":"Ordena lo que se creó cada día, según el Génesis, del primero al sexto.","hint":"Primero lo que da luz y espacio, luego la tierra con plantas, después los astros y al final los animales y el ser humano.","explain":"Luz (1) → cielo (2) → tierra, mares y plantas (3) → Sol, Luna y estrellas (4) → peces y aves (5) → animales terrestres y seres humanos (6). El séptimo día es de descanso.","type":"order","props":{"labels":{"start":"Primer día","end":"Sexto día"},"items":[{"id":"d1","text":"La luz: el día y la noche","icon":"Sun"},{"id":"d2","text":"El firmamento o cielo","icon":"Cloud"},{"id":"d3","text":"La tierra seca, los mares y las plantas","icon":"Sprout"},{"id":"d4","text":"El Sol, la Luna y las estrellas","icon":"Moon"},{"id":"d5","text":"Los peces y las aves","icon":"Fish"},{"id":"d6","text":"Los animales terrestres y el ser humano","icon":"Users"}]},"id":"s01-cnt-1-4"},{"fase":"construir","areas":["cnt","ccss"],"cnb":["cnt:1.1.1"],"ambito":"conocer","title":"Otro relato de Guatemala: el Popol Vuh","prompt":"En Guatemala conviven varias cosmovisiones. El **Popol Vuh** es el libro sagrado del pueblo **maya k'iche'**. Toca las tarjetas.","type":"explain","props":{"icon":"Wheat","body":"En el Popol Vuh, los creadores **Tepeu** y **Gucumatz**, junto con el **Corazón del Cielo**, formaron la tierra, las montañas y los animales. Luego quisieron crear seres que pudieran hablar, recordar y agradecer.","reveal":[{"icon":"Droplets","front":"Seres de barro","back":"Se deshacían con el agua y no podían pensar. Los creadores los deshicieron."},{"icon":"TreeDeciduous","front":"Seres de madera","back":"Hablaban y se multiplicaban, pero **no tenían corazón ni memoria** y no agradecían. Fueron destruidos."},{"icon":"Wheat","front":"Seres de maíz","back":"Con masa de **maíz amarillo y blanco** se formaron los primeros seres humanos verdaderos, capaces de pensar y agradecer. Por eso el maíz es sagrado para muchos pueblos mayas."}]},"id":"s01-cnt-1-5"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.1.1"],"ambito":"conocer","prompt":"¿De qué relato es cada idea? Clasifícala.","hint":"Busca pistas: \\"siete días\\" es del Génesis; el barro, la madera y el maíz son del Popol Vuh.","explain":"Los dos relatos son distintos, pero comparten algo: explican el origen y enseñan a **agradecer y cuidar** la vida.","type":"sort","props":{"buckets":[{"id":"gen","label":"Génesis (judeocristiano)","icon":"BookOpen","color":"var(--area-cnt)"},{"id":"pop","label":"Popol Vuh (maya k'iche')","icon":"Wheat","color":"var(--c-maiz-strong)"},{"id":"amb","label":"Los dos","icon":"Copy","color":"var(--area-ccss)"}],"items":[{"id":"g1","text":"La creación ocurre en seis días y el séptimo es de descanso","bucket":"gen"},{"id":"g2","text":"Los primeros seres humanos verdaderos se forman de maíz","bucket":"pop"},{"id":"g3","text":"Hubo intentos con barro y con madera","bucket":"pop"},{"id":"g4","text":"El ser humano, hombre y mujer, se crea el sexto día","bucket":"gen"},{"id":"g5","text":"Explica el origen del mundo y enseña valores","bucket":"amb"},{"id":"g6","text":"Se transmite de generación en generación","bucket":"amb"}]},"id":"s01-cnt-1-6"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.1.1"],"ambito":"conocer","title":"La explicación de la ciencia","prompt":"Las personas que hacen ciencia estudian la luz de las estrellas, las rocas y los meteoritos para reconstruir la historia del universo. Mira la animación y toca las tarjetas.","media":{"id":"s01-cnt-1-granexplosion","kind":"animation","title":"De la Gran Explosión a la Tierra","aspect":"16:9","duration":50,"alt":"Un punto de luz se expande y forma galaxias; en una de ellas una nube de gas y polvo gira y forma el Sol y los planetas; la Tierra pasa de roca ardiente a planeta azul con océanos.","brief":"Animación 2D de 50 s, estilo sencillo y colorido. (1) Un punto brillante se expande: rótulo \\"Gran Explosión, hace unos 13,800 millones de años\\". (2) Se forman estrellas y galaxias. (3) Acercamiento a una nube de gas y polvo que gira; en el centro nace el Sol y alrededor se juntan planetas: rótulo \\"hace unos 4,600 millones de años\\". (4) La Tierra: roca caliente con volcanes, se enfría, llueve durante mucho tiempo y se forman los océanos: \\"hace unos 4,500 millones de años\\". (5) Primeras formas de vida microscópicas en el agua. Narración en español, calmada, con subtítulos. No mezclar con imágenes religiosas."},"type":"explain","props":{"icon":"Rocket","body":"La ciencia **no** usa relatos: usa **pruebas**. Por ejemplo, los telescopios muestran que las galaxias se alejan unas de otras, como si todo hubiera empezado en un mismo punto.","reveal":[{"icon":"Sparkles","front":"Gran Explosión","back":"Hace unos **13,800 millones de años**, el universo era muy pequeño y caliente, y comenzó a **expandirse**. Así se formaron, con el tiempo, las galaxias y las estrellas."},{"icon":"Sun","front":"Nace el Sol","back":"Hace unos **4,600 millones de años**, una nube de gas y polvo se juntó por la gravedad: en el centro se formó el **Sol** y alrededor, los planetas."},{"icon":"Earth","front":"La Tierra","back":"Se formó hace unos **4,500 millones de años**. Primero era roca ardiente; al enfriarse, la lluvia formó los **océanos**, y allí surgieron los primeros seres vivos, **microscópicos**."}]},"id":"s01-cnt-1-7"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.1.1"],"ambito":"conocer","prompt":"Según la explicación científica, ordena estos sucesos del **más antiguo** al **más reciente**.","explain":"Primero el universo se expande; luego nacen galaxias y estrellas; después el Sol y la Tierra; la Tierra se enfría y forma océanos, y en el agua aparecen los primeros seres vivos.","type":"order","props":{"labels":{"start":"Más antiguo","end":"Más reciente"},"items":[{"id":"c1","text":"El universo comienza a expandirse (Gran Explosión)","icon":"Sparkles"},{"id":"c2","text":"Se forman las primeras galaxias y estrellas","icon":"Star"},{"id":"c3","text":"Una nube de gas y polvo forma el Sol y los planetas","icon":"Sun"},{"id":"c4","text":"La Tierra se enfría y se forman los océanos","icon":"Waves"},{"id":"c5","text":"Aparecen los primeros seres vivos, microscópicos, en el agua","icon":"Microscope"}]},"id":"s01-cnt-1-8"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.1.1"],"ambito":"conocer","prompt":"¿Es una característica de un **relato de fe o cultural** o de una **explicación científica**?","explain":"La ciencia pregunta **cómo** ocurrieron las cosas y lo comprueba con pruebas. Los relatos de fe y culturales responden sobre todo **por qué** y **para qué** existimos. Muchas personas valoran las dos cosas.","type":"sort","props":{"buckets":[{"id":"rel","label":"Relato de fe o cultural","icon":"BookOpen","color":"var(--c-maiz-strong)"},{"id":"cie","label":"Explicación científica","icon":"Microscope","color":"var(--area-cnt)"}],"items":[{"id":"r1","text":"Se basa en observaciones con telescopios y en mediciones","bucket":"cie"},{"id":"r2","text":"Enseña a agradecer la vida y a cuidar la naturaleza","bucket":"rel"},{"id":"r3","text":"Cambia si se descubren pruebas nuevas","bucket":"cie"},{"id":"r4","text":"Se cuenta en la familia y en las ceremonias de la comunidad","bucket":"rel"},{"id":"r5","text":"Calcula la edad de la Tierra midiendo rocas y meteoritos","bucket":"cie"},{"id":"r6","text":"Habla de la relación de las personas con lo sagrado","bucket":"rel"}]},"id":"s01-cnt-1-9"},{"fase":"aplicar","areas":["cnt","fc"],"cnb":["cnt:1.1.1"],"ambito":"convivir","prompt":"Conocer distintas cosmovisiones también es aprender a convivir. ¿Qué harías tú?","type":"dilemma","props":{"scene":{"icon":"MessagesSquare","text":"En clase, **Ixchel** cuenta que su abuelo le narra el Popol Vuh, y **Samuel** comparte que en su iglesia leen el Génesis. **Kevin** se ríe y dice: \\"Eso son cuentos; lo único que vale es la ciencia\\"."},"options":[{"id":"a","icon":"ThumbsUp","text":"Reírme con Kevin","consequence":"Ixchel y Samuel se sienten ofendidos y dejan de participar. Burlarse de las creencias de otras personas divide al grupo.","values":["Burla"],"constructive":false},{"id":"b","icon":"Handshake","text":"Decir que la ciencia y los relatos responden preguntas distintas, y que todas las personas merecen respeto","consequence":"El grupo conversa con calma. Kevin entiende que puede valorar la ciencia sin despreciar la fe ni la cultura de los demás.","values":["Respeto","Diálogo"],"constructive":true},{"id":"c","icon":"MessageCircle","text":"Pedir a Ixchel y a Samuel que cuenten más, y a Kevin que explique la Gran Explosión","consequence":"Cada integrante aprende algo nuevo: el grupo descubre que escuchar distintas miradas enriquece.","values":["Curiosidad","Interculturalidad"],"constructive":true}]},"id":"s01-cnt-1-10"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:1.1.1"],"prompt":"Según el relato judeocristiano del Génesis, ¿qué fue creado el **quinto día**?","type":"choice","props":{"options":[{"id":"a","text":"Los peces y las aves"},{"id":"b","text":"La luz"},{"id":"c","text":"El Sol, la Luna y las estrellas"},{"id":"d","text":"El ser humano"}],"correct":["a"]},"id":"s01-cnt-1-11"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:1.1.1"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"En el Popol Vuh, los primeros seres humanos verdaderos fueron formados de maíz.","answer":true},{"text":"Según el Génesis, el séptimo día fue un día de descanso.","answer":true},{"text":"Según la ciencia, la Tierra se formó antes que el universo.","answer":false,"why":"El universo comenzó hace unos 13,800 millones de años; la Tierra se formó mucho después, hace unos 4,500 millones."},{"text":"Una explicación científica nunca cambia, aunque aparezcan pruebas nuevas.","answer":false,"why":"La ciencia se corrige y mejora cuando hay pruebas nuevas."}]},"id":"s01-cnt-1-12"}],"kind":"materia","area":"cnt","day":1}}]`),o={mission:e,lessons:a};export{o as default,a as lessons,e as mission};
